static int mir_match_byte_minmax(struct MirByteMinMax *plan)
{
    unsigned long long first;
    unsigned long long second;
    struct Sym *moves;
    struct Sym *winner_functions;
    struct Sym *board;
    struct Sym *self;
    int argument;

    memset(plan, 0, sizeof(*plan));
    if (mir.count != 253 || mir_cfg_block_count() != 31 ||
        mir.has_vla ||
        type_size(mir.return_type) != 1 ||
        type_ptr_depth(mir.return_type) != 0)
        return 0;
    mir_numeric_shape_hash(&first, &second);
    if (first != 0xfd2672fb1314f7a0ULL ||
        second != 0xd22eced2a2903e54ULL)
        return 0;

    moves = find_global(mir.insns[5].name);
    winner_functions = find_global(mir.insns[14].name);
    board = find_global(mir.insns[91].name);
    self = find_global(mir.insns[115].name);
    if (moves == NULL || winner_functions == NULL ||
        board == NULL || self == NULL ||
        strcmp(mir.insns[5].name, mir.insns[8].name) != 0 ||
        strcmp(mir.insns[91].name, mir.insns[98].name) != 0 ||
        strcmp(mir.insns[91].name, mir.insns[118].name) != 0 ||
        strcmp(mir.insns[115].name, mir.name) != 0 ||
        (moves->storage != SC_GLOBAL && moves->storage != SC_EXTERN) ||
        type_size(moves->type) != 4 || moves->is_volatile ||
        (winner_functions->storage != SC_GLOBAL &&
         winner_functions->storage != SC_EXTERN) ||
        !winner_functions->is_array ||
        winner_functions->elem_size != 2 ||
        winner_functions->is_volatile ||
        (board->storage != SC_GLOBAL && board->storage != SC_EXTERN) ||
        !board->is_array || board->elem_size != 1 ||
        board->is_volatile || board->pointee_is_volatile ||
        !self->is_defined || self->proto_nargs != 4 ||
        self->proto_variadic)
        return 0;
    for (argument = 0; argument < 4; ++argument)
        if (type_size(self->proto_types[argument]) != 1 ||
            type_ptr_depth(self->proto_types[argument]) != 0)
            return 0;
    if (!mir_same_scalar_memory_location(
            &mir.insns[5], &mir.insns[8]) ||
        mir.insns[5].memory_flags != 0 ||
        mir.insns[8].memory_flags != 0 ||
        !mir_minmax_byte_location(
            &mir.insns[1], SC_PARAM, &plan->alpha_offset) ||
        !mir_minmax_byte_location(
            &mir.insns[2], SC_PARAM, &plan->beta_offset) ||
        !mir_minmax_byte_location(
            &mir.insns[3], SC_PARAM, &plan->depth_offset) ||
        !mir_minmax_byte_location(
            &mir.insns[4], SC_PARAM, &plan->move_offset) ||
        !mir_minmax_byte_location(
            &mir.insns[62], SC_LOCAL, &plan->piece_offset) ||
        !mir_same_scalar_memory_location(
            &mir.insns[62], &mir.insns[71]))
        return 0;

    plan->moves = moves;
    plan->winner_functions = winner_functions;
    plan->board = board;
    plan->self = self;
    plan->depth_threshold = (int)mir.insns[10].immediate;
    plan->terminal_depth = (int)mir.insns[40].immediate;
    plan->loop_bound = (int)mir.insns[86].immediate;
    plan->blank = (int)mir.insns[90].immediate;
    plan->piece_x = (int)mir.insns[61].immediate;
    plan->piece_o = (int)mir.insns[70].immediate;
    plan->score_min = (int)mir.insns[58].immediate;
    plan->score_max = (int)mir.insns[67].immediate;
    plan->score_win = (int)mir.insns[32].immediate;
    plan->score_lose = (int)mir.insns[36].immediate;
    plan->score_tie = (int)mir.insns[46].immediate;
    return 1;
}

static int mir_conversion_from_value(
    int value, int source_value, int width)
{
    const struct MirInsn *conversion = mir_definition(value);

    return value == source_value ||
           (conversion != NULL &&
            conversion->opcode == MIR_UNARY &&
            conversion->immediate == 0 &&
            conversion->src1 == source_value &&
            type_size(conversion->type) == width &&
            mir_value_use_count(conversion->dst) == 1);
}

static int mir_byte_verify_location(
    const struct MirInsn *insn, int width, int *offset)
{
    int memory_type;
    int memory_storage;
    int memory_offset;

    if (insn == NULL ||
        !mir_scalar_memory_location(
            insn, &memory_type, &memory_storage, &memory_offset) ||
        type_size(memory_type) != width ||
        (memory_storage != SC_LOCAL && memory_storage != SC_PARAM) ||
        memory_offset < -128 ||
        memory_offset + width - 1 > 127)
        return 0;
    if (offset != NULL)
        *offset = memory_offset;
    return 1;
}

static int mir_match_byte_verify_loop(
    int instruction, struct MirByteVerifyLoop *plan)
{
    const struct MirInsn *initial;
    const struct MirInsn *initial_store;
    const struct MirInsn *header;
    const struct MirInsn *phi = NULL;
    const struct MirInsn *condition = NULL;
    const struct MirInsn *condition_branch = NULL;
    const struct MirInsn *pointer_load = NULL;
    const struct MirInsn *byte_load = NULL;
    const struct MirInsn *compare = NULL;
    const struct MirInsn *compare_branch = NULL;
    const struct MirInsn *value_store = NULL;
    const struct MirInsn *continuation;
    const struct MirInsn *pointer_reload;
    const struct MirInsn *pointer_one;
    const struct MirInsn *pointer_increment;
    const struct MirInsn *pointer_store;
    const struct MirInsn *latch;
    const struct MirInsn *index_one;
    const struct MirInsn *index_increment;
    const struct MirInsn *index_store;
    const struct MirInsn *jump;
    int initial_store_index;
    int header_index;
    int phi_index = -1;
    int condition_branch_index = -1;
    int byte_load_index = -1;
    int compare_branch_index = -1;
    int continuation_index;
    int pointer_reload_index;
    int pointer_one_index;
    int pointer_increment_index;
    int pointer_store_index;
    int latch_index;
    int index_one_index;
    int index_increment_index;
    int index_store_index;
    int jump_index;
    int exit_index;
    int count_offset;
    int pointer_offset;
    int value_offset;
    int value_store_index = -1;
    int left_value;
    int right_value;
    int stored_value;
    int scan;

    memset(plan, 0, sizeof(*plan));
    if (instruction < 0 || instruction >= mir.count)
        return 0;
    initial = &mir.insns[instruction];
    if (initial->opcode != MIR_CONST || initial->immediate != 0 ||
        type_size(initial->type) != 2)
        return 0;
    initial_store_index =
        mir_low_byte_loop_next_effective(instruction);
    if (initial_store_index >= mir.count)
        return 0;
    initial_store = &mir.insns[initial_store_index];
    if (initial_store->opcode != MIR_STORE ||
        initial_store->src1 != initial->dst ||
        initial_store->object < 0 ||
        initial_store->memory_size != 2)
        return 0;
    header_index =
        mir_low_byte_loop_next_effective(initial_store_index);
    if (header_index >= mir.count)
        return 0;
    header = &mir.insns[header_index];
    if (header->opcode != MIR_LABEL)
        return 0;
    for (scan = header_index + 1;
         scan < mir.count && scan <= header_index + 10; ++scan) {
        const struct MirInsn *candidate = &mir.insns[scan];

        if (candidate->opcode == MIR_PHI &&
            candidate->object == initial_store->object &&
            candidate->src1 == initial->dst) {
            phi = candidate;
            phi_index = scan;
            break;
        }
    }
    if (phi == NULL || type_size(phi->type) != 2)
        return 0;
    for (scan = phi_index + 1;
         scan < mir.count && scan <= phi_index + 10; ++scan) {
        const struct MirInsn *candidate = &mir.insns[scan];

        if (candidate->opcode != MIR_BINARY ||
            candidate->immediate != '<' ||
            candidate->src1 != phi->dst ||
            type_size(candidate->secondary_offset) != 2)
            continue;
        condition = candidate;
        condition_branch_index =
            mir_low_byte_loop_next_effective(scan);
        if (condition_branch_index < mir.count &&
            mir.insns[condition_branch_index].opcode ==
                MIR_BRANCH_FALSE &&
            mir.insns[condition_branch_index].src1 ==
                candidate->dst) {
            condition_branch =
                &mir.insns[condition_branch_index];
            break;
        }
    }
    if (condition == NULL || condition_branch == NULL ||
        !mir_byte_verify_location(
            mir_definition(condition->src2), 2, &count_offset))
        return 0;
    exit_index = mir_find_label(condition_branch->label);
    if (exit_index <= condition_branch_index ||
        !mir_phi_copies_are_empty(
            condition_branch_index, exit_index))
        return 0;

    for (scan = condition_branch_index + 1;
         scan < mir.count && scan <= condition_branch_index + 8; ++scan) {
        const struct MirInsn *candidate = &mir.insns[scan];

        if (candidate->opcode == MIR_LOAD &&
            type_ptr_depth(candidate->type) > 0 &&
            mir_byte_verify_location(
                candidate, 2, &pointer_offset)) {
            int next = mir_low_byte_loop_next_effective(scan);

            if (next < mir.count &&
                mir.insns[next].opcode == MIR_LOAD_INDIRECT &&
                mir.insns[next].src1 == candidate->dst &&
                mir.insns[next].memory_size == 1) {
                pointer_load = candidate;
                byte_load = &mir.insns[next];
                byte_load_index = next;
                break;
            }
        }
    }
    if (pointer_load == NULL || byte_load == NULL)
        return 0;
    for (scan = byte_load_index + 1;
         scan < mir.count && scan <= byte_load_index + 8; ++scan) {
        const struct MirInsn *candidate = &mir.insns[scan];

        if (candidate->opcode != MIR_BINARY ||
            candidate->immediate != TOK_NE ||
            type_size(candidate->secondary_offset) != 2)
            continue;
        left_value = candidate->src1;
        right_value = candidate->src2;
        if (!mir_conversion_from_value(
                left_value, byte_load->dst, 2)) {
            int swap = left_value;
            left_value = right_value;
            right_value = swap;
        }
        if (!mir_conversion_from_value(
                left_value, byte_load->dst, 2))
            continue;
        compare_branch_index =
            mir_low_byte_loop_next_effective(scan);
        if (compare_branch_index >= mir.count ||
            mir.insns[compare_branch_index].opcode !=
                MIR_BRANCH_FALSE ||
            mir.insns[compare_branch_index].src1 !=
                candidate->dst)
            continue;
        compare = candidate;
        compare_branch = &mir.insns[compare_branch_index];
        break;
    }
    if (compare == NULL || compare_branch == NULL)
        return 0;
    stored_value = right_value;
    {
        const struct MirInsn *conversion =
            mir_definition(stored_value);

        if (conversion != NULL &&
            conversion->opcode == MIR_UNARY &&
            conversion->immediate == 0)
            stored_value = conversion->src1;
    }
    {
        const struct MirInsn *conversion =
            mir_definition(stored_value);
        const struct MirInsn *mask;
        const struct MirInsn *mask_constant;
        const struct MirInsn *source;
        int source_value;
        int mask_index;
        int constant_index;

        if (conversion == NULL ||
            conversion->opcode != MIR_UNARY ||
            conversion->immediate != 0 ||
            type_size(conversion->type) != 1)
            return 0;
        mask = mir_definition(conversion->src1);
        if (mask == NULL || mask->opcode != MIR_BINARY ||
            mask->immediate != '&' ||
            type_size(mask->secondary_offset) != 2)
            return 0;
        mask_constant = mir_definition(mask->src2);
        source_value = mask->src1;
        if (mask_constant == NULL ||
            mask_constant->opcode != MIR_CONST ||
            (mask_constant->immediate & 0xffffL) != 255) {
            mask_constant = mir_definition(mask->src1);
            source_value = mask->src2;
        }
        source = mir_definition(source_value);
        if (mask_constant == NULL ||
            mask_constant->opcode != MIR_CONST ||
            (mask_constant->immediate & 0xffffL) != 255 ||
            source == NULL ||
            !mir_byte_verify_location(
                source, 2, &value_offset))
            return 0;
        for (scan = 0; scan < instruction; ++scan)
            if (mir.insns[scan].opcode == MIR_STORE &&
                mir.insns[scan].src1 == stored_value &&
                mir.insns[scan].memory_size == 1) {
                value_store = &mir.insns[scan];
                value_store_index = scan;
                break;
            }
        if (value_store == NULL)
            return 0;
        mask_index = (int)(mask - mir.insns);
        constant_index =
            (int)(mask_constant - mir.insns);
        plan->value_start =
            mask_index < constant_index ? mask_index : constant_index;
        plan->value_end = value_store_index;
        plan->value_source_offset = value_offset;
        for (scan = plan->value_start;
             scan <= plan->value_end; ++scan) {
            const struct MirInsn *candidate = &mir.insns[scan];

            if (candidate->opcode == MIR_NOP ||
                candidate == mask ||
                candidate == mask_constant ||
                candidate == conversion ||
                candidate == value_store)
                continue;
            return 0;
        }
    }
    continuation_index =
        mir_find_label(compare_branch->label);
    if (continuation_index <= compare_branch_index ||
        continuation_index >= exit_index)
        return 0;
    continuation = &mir.insns[continuation_index];
    if (continuation->opcode != MIR_LABEL)
        return 0;
    for (scan = compare_branch_index + 1;
         scan < continuation_index; ++scan)
        if (((mir.insns[scan].opcode == MIR_LOAD ||
              mir.insns[scan].opcode == MIR_STORE) &&
             mir.insns[scan].object == initial_store->object) ||
            mir.insns[scan].opcode == MIR_LABEL ||
            mir.insns[scan].opcode == MIR_JUMP ||
            mir.insns[scan].opcode == MIR_BRANCH_FALSE ||
            mir.insns[scan].opcode == MIR_RETURN)
            return 0;

    pointer_reload_index =
        mir_low_byte_loop_next_effective(continuation_index);
    pointer_one_index =
        mir_low_byte_loop_next_effective(pointer_reload_index);
    pointer_increment_index =
        mir_low_byte_loop_next_effective(pointer_one_index);
    pointer_store_index =
        mir_low_byte_loop_next_effective(pointer_increment_index);
    latch_index =
        mir_low_byte_loop_next_effective(pointer_store_index);
    index_one_index =
        mir_low_byte_loop_next_effective(latch_index);
    index_increment_index =
        mir_low_byte_loop_next_effective(index_one_index);
    index_store_index =
        mir_low_byte_loop_next_effective(index_increment_index);
    jump_index =
        mir_low_byte_loop_next_effective(index_store_index);
    if (jump_index >= exit_index)
        return 0;
    pointer_reload = &mir.insns[pointer_reload_index];
    pointer_one = &mir.insns[pointer_one_index];
    pointer_increment = &mir.insns[pointer_increment_index];
    pointer_store = &mir.insns[pointer_store_index];
    latch = &mir.insns[latch_index];
    index_one = &mir.insns[index_one_index];
    index_increment = &mir.insns[index_increment_index];
    index_store = &mir.insns[index_store_index];
    jump = &mir.insns[jump_index];
    if (pointer_reload->opcode != MIR_LOAD ||
        !mir_same_scalar_memory_location(
            pointer_load, pointer_reload) ||
        pointer_one->opcode != MIR_CONST ||
        pointer_one->immediate != 1 ||
        pointer_increment->opcode != MIR_BINARY ||
        pointer_increment->immediate != '+' ||
        pointer_increment->src1 != pointer_reload->dst ||
        pointer_increment->src2 != pointer_one->dst ||
        pointer_store->opcode != MIR_STORE ||
        pointer_store->src1 != pointer_increment->dst ||
        !mir_same_scalar_memory_location(
            pointer_load, pointer_store) ||
        latch->opcode != MIR_LABEL ||
        latch->label != phi->phi_pred2 ||
        index_one->opcode != MIR_CONST ||
        index_one->immediate != 1 ||
        index_increment->opcode != MIR_BINARY ||
        index_increment->immediate != '+' ||
        index_increment->src1 != phi->dst ||
        index_increment->src2 != index_one->dst ||
        index_increment->dst != phi->src2 ||
        index_store->opcode != MIR_STORE ||
        index_store->src1 != index_increment->dst ||
        index_store->object != initial_store->object ||
        jump->opcode != MIR_JUMP ||
        jump->label != header->label)
        return 0;
    for (scan = exit_index + 1; scan < mir.count; ++scan) {
        const struct MirInsn *candidate = &mir.insns[scan];

        if ((candidate->opcode == MIR_LOAD ||
             candidate->opcode == MIR_STORE) &&
            (candidate->object == initial_store->object ||
             mir_same_scalar_memory_location(
                 pointer_load, candidate)))
            return 0;
    }
    plan->skip_through = compare_branch_index;
    plan->header_label = header->label;
    plan->exit_label = condition_branch->label;
    plan->phi_value = phi->dst;
    plan->count_offset = count_offset;
    plan->pointer_offset = pointer_offset;
    plan->index_object = initial_store->object;
    return 1;
}

static int mir_match_byte_verify_value_prefix(
    int instruction, struct MirByteVerifyLoop *plan)
{
    int candidate;
    int end = instruction + 64;

    if (instruction < 0 || instruction >= mir.count ||
        mir.insns[instruction].opcode != MIR_CONST ||
        (mir.insns[instruction].immediate & 0xffffL) != 255)
        return 0;
    if (end > mir.count)
        end = mir.count;
    for (candidate = instruction + 1;
         candidate < end; ++candidate) {
        if (mir.insns[candidate].opcode != MIR_CONST ||
            mir.insns[candidate].immediate != 0)
            continue;
        if (mir_match_byte_verify_loop(candidate, plan) &&
            plan->value_start == instruction)
            return 1;
    }
    return 0;
}

static int mir_match_word_pointer_increment(
    int first, int last, const struct MirInsn *pointer,
    int header_label, int *increment_start, int *jump_index)
{
    int instruction;

    for (instruction = first; instruction < last; ++instruction) {
        const struct MirInsn *load = &mir.insns[instruction];
        const struct MirInsn *amount;
        const struct MirInsn *increment;
        const struct MirInsn *store;
        const struct MirInsn *jump;
        int amount_index;
        int increment_index;
        int store_index;
        int candidate_jump;

        if (load->opcode != MIR_LOAD ||
            !mir_same_scalar_memory_location(pointer, load))
            continue;
        amount_index =
            mir_low_byte_loop_next_effective(instruction);
        increment_index =
            mir_low_byte_loop_next_effective(amount_index);
        store_index =
            mir_low_byte_loop_next_effective(increment_index);
        if (store_index >= last)
            continue;
        amount = &mir.insns[amount_index];
        increment = &mir.insns[increment_index];
        store = &mir.insns[store_index];
        if (amount->opcode != MIR_CONST ||
            amount->immediate != 2 ||
            increment->opcode != MIR_BINARY ||
            increment->immediate != '+' ||
            increment->src1 != load->dst ||
            increment->src2 != amount->dst ||
            store->opcode != MIR_STORE ||
            store->src1 != increment->dst ||
            !mir_same_scalar_memory_location(pointer, store))
            continue;
        candidate_jump =
            mir_low_byte_loop_next_effective(store_index);
        while (candidate_jump < last &&
               mir.insns[candidate_jump].opcode == MIR_LABEL)
            candidate_jump =
                mir_low_byte_loop_next_effective(candidate_jump);
        if (candidate_jump >= last)
            continue;
        jump = &mir.insns[candidate_jump];
        if (jump->opcode != MIR_JUMP ||
            jump->label != header_label)
            continue;
        if (increment_start != NULL)
            *increment_start = instruction;
        if (jump_index != NULL)
            *jump_index = candidate_jump;
        return 1;
    }
    return 0;
}

static int mir_match_word_scan_loop(
    int instruction, struct MirWordScanLoop *plan)
{
    const struct MirInsn *header;
    const struct MirInsn *pointer = NULL;
    const struct MirInsn *word_load = NULL;
    const struct MirInsn *zero_compare = NULL;
    const struct MirInsn *exit_branch = NULL;
    int word_load_index = -1;
    int exit_branch_index = -1;
    int exit_index;
    int increment_start;
    int jump_index;
    int pointer_offset;
    int scan;

    memset(plan, 0, sizeof(*plan));
    if (instruction < 0 || instruction >= mir.count)
        return 0;
    header = &mir.insns[instruction];
    if (header->opcode != MIR_LABEL)
        return 0;
    for (scan = instruction + 1;
         scan < mir.count && scan <= instruction + 10; ++scan) {
        const struct MirInsn *candidate = &mir.insns[scan];
        int next;

        if (candidate->opcode != MIR_LOAD ||
            type_ptr_depth(candidate->type) == 0 ||
            !mir_byte_verify_location(
                candidate, 2, &pointer_offset))
            continue;
        next = mir_low_byte_loop_next_effective(scan);
        if (next < mir.count &&
            mir.insns[next].opcode == MIR_LOAD_INDIRECT &&
            mir.insns[next].src1 == candidate->dst &&
            mir.insns[next].memory_size == 2) {
            pointer = candidate;
            word_load = &mir.insns[next];
            word_load_index = next;
            break;
        }
    }
    if (pointer == NULL || word_load == NULL)
        return 0;
    for (scan = word_load_index + 1;
         scan < mir.count && scan <= word_load_index + 8; ++scan) {
        const struct MirInsn *candidate = &mir.insns[scan];
        int other;
        const struct MirInsn *constant;
        int branch_index;

        if (candidate->opcode != MIR_BINARY ||
            candidate->immediate != TOK_NE ||
            type_size(candidate->secondary_offset) != 2)
            continue;
        if (candidate->src1 == word_load->dst)
            other = candidate->src2;
        else if (candidate->src2 == word_load->dst)
            other = candidate->src1;
        else
            continue;
        constant = mir_definition(other);
        if (constant == NULL || constant->opcode != MIR_CONST ||
            (constant->immediate & 0xffffL) != 0)
            continue;
        branch_index =
            mir_low_byte_loop_next_effective(scan);
        if (branch_index >= mir.count ||
            mir.insns[branch_index].opcode != MIR_BRANCH_FALSE ||
            mir.insns[branch_index].src1 != candidate->dst)
            continue;
        zero_compare = candidate;
        exit_branch = &mir.insns[branch_index];
        exit_branch_index = branch_index;
        break;
    }
    if (zero_compare == NULL || exit_branch == NULL)
        return 0;
    exit_index = mir_find_label(exit_branch->label);
    if (exit_index <= exit_branch_index ||
        !mir_phi_copies_are_empty(
            exit_branch_index, exit_index) ||
        !mir_match_word_pointer_increment(
            exit_branch_index + 1, exit_index, pointer,
            header->label, &increment_start, &jump_index))
        return 0;

    plan->kind = MIR_WORD_SCAN_LENGTH;
    for (scan = exit_branch_index + 1;
         scan < increment_start; ++scan)
        if (mir.insns[scan].opcode != MIR_NOP) {
            plan->kind = MIR_WORD_SCAN_LAST_MATCH;
            break;
        }
    if (plan->kind == MIR_WORD_SCAN_LAST_MATCH) {
        const struct MirInsn *match_pointer = NULL;
        const struct MirInsn *match_word = NULL;
        const struct MirInsn *match_compare = NULL;
        const struct MirInsn *match_branch = NULL;
        const struct MirInsn *saved_pointer = NULL;
        const struct MirInsn *save = NULL;
        int match_pointer_index = -1;
        int match_word_index = -1;
        int match_compare_index = -1;
        int match_branch_index = -1;
        int save_index = -1;
        int comparison_offset;
        int last_match_offset;

        for (scan = exit_branch_index + 1;
             scan < increment_start; ++scan) {
            const struct MirInsn *candidate = &mir.insns[scan];
            int next;

            if (candidate->opcode != MIR_LOAD ||
                !mir_same_scalar_memory_location(
                    pointer, candidate))
                continue;
            next = mir_low_byte_loop_next_effective(scan);
            if (next < increment_start &&
                mir.insns[next].opcode == MIR_LOAD_INDIRECT &&
                mir.insns[next].src1 == candidate->dst &&
                mir.insns[next].memory_size == 2) {
                match_pointer = candidate;
                match_pointer_index = scan;
                match_word = &mir.insns[next];
                match_word_index = next;
                break;
            }
        }
        if (match_pointer == NULL || match_word == NULL)
            return 0;
        for (scan = match_word_index + 1;
             scan < increment_start; ++scan) {
            const struct MirInsn *candidate = &mir.insns[scan];
            int other;
            int branch_index;

            if (candidate->opcode != MIR_BINARY ||
                candidate->immediate != TOK_EQ ||
                type_size(candidate->secondary_offset) != 2)
                continue;
            if (candidate->src1 == match_word->dst)
                other = candidate->src2;
            else if (candidate->src2 == match_word->dst)
                other = candidate->src1;
            else
                continue;
            if (!mir_byte_verify_location(
                    mir_definition(other), 2,
                    &comparison_offset))
                continue;
            branch_index =
                mir_low_byte_loop_next_effective(scan);
            if (branch_index >= increment_start ||
                mir.insns[branch_index].opcode != MIR_BRANCH_FALSE ||
                mir.insns[branch_index].src1 != candidate->dst)
                continue;
            match_compare = candidate;
            match_compare_index = scan;
            match_branch = &mir.insns[branch_index];
            match_branch_index = branch_index;
            break;
        }
        if (match_compare == NULL || match_branch == NULL)
            return 0;
        for (scan = match_branch_index + 1;
             scan < increment_start; ++scan) {
            const struct MirInsn *candidate = &mir.insns[scan];
            int next;

            if (candidate->opcode != MIR_LOAD ||
                !mir_same_scalar_memory_location(
                    pointer, candidate))
                continue;
            next = mir_low_byte_loop_next_effective(scan);
            if (next < increment_start &&
                mir.insns[next].opcode == MIR_STORE &&
                mir.insns[next].src1 == candidate->dst &&
                mir_byte_verify_location(
                    &mir.insns[next], 2,
                    &last_match_offset)) {
                saved_pointer = candidate;
                save = &mir.insns[next];
                save_index = next;
                break;
            }
        }
        if (saved_pointer == NULL || save == NULL ||
            mir_find_label(match_branch->label) < save_index ||
            mir_find_label(match_branch->label) > increment_start)
            return 0;
        for (scan = exit_branch_index + 1;
             scan < increment_start; ++scan) {
            const struct MirInsn *candidate = &mir.insns[scan];

            if (candidate->opcode == MIR_NOP ||
                candidate->opcode == MIR_LABEL ||
                scan == match_pointer_index ||
                scan == match_word_index ||
                scan == match_compare_index ||
                scan == match_branch_index ||
                candidate == saved_pointer ||
                candidate == save)
                continue;
            return 0;
        }
        plan->comparison_offset = comparison_offset;
        plan->last_match_offset = last_match_offset;
    }
    if (plan->kind == MIR_WORD_SCAN_LENGTH) {
        for (scan = exit_branch_index + 1;
             scan < increment_start; ++scan)
            if (mir.insns[scan].opcode != MIR_NOP)
                return 0;
    }
    plan->skip_through = jump_index;
    plan->header_label = header->label;
    plan->exit_label = exit_branch->label;
    plan->pointer_offset = pointer_offset;
    return 1;
}

static int mir_wide_mask_zero_add_component(
    struct MirWideMaskZeroBranch *plan, int instruction)
{
    int component;

    if (instruction < 0 || instruction >= mir.count)
        return 0;
    for (component = 0; component < plan->component_count; ++component)
        if (plan->components[component] == instruction)
            return 1;
    if (plan->component_count >=
        (int)(sizeof(plan->components) / sizeof(plan->components[0])))
        return 0;
    plan->components[plan->component_count++] = instruction;
    return 1;
}

static int mir_wide_mask_zero_has_component(
    const struct MirWideMaskZeroBranch *plan, int instruction)
{
    int component;

    for (component = 0; component < plan->component_count; ++component)
        if (plan->components[component] == instruction)
            return 1;
    return 0;
}

static int mir_match_wide_mask_zero_branch(
    int instruction, struct MirWideMaskZeroBranch *plan)
{
    const struct MirInsn *first;
    const struct MirInsn *mask = NULL;
    const struct MirInsn *mask_constant;
    const struct MirInsn *compare;
    const struct MirInsn *zero;
    const struct MirInsn *branch;
    const struct MirInsn *source;
    int mask_instruction = -1;
    int compare_instruction;
    int branch_instruction;
    int source_value;
    int scan;
    int first_instruction;

    memset(plan, 0, sizeof(*plan));
    if (instruction < 0 || instruction >= mir.count)
        return 0;
    first = &mir.insns[instruction];
    if (first->opcode != MIR_CONST || type_size(first->type) != 4)
        return 0;
    for (scan = instruction + 1;
         scan < mir.count && scan <= instruction + 8; ++scan)
        if (mir.insns[scan].opcode == MIR_BINARY &&
            mir.insns[scan].immediate == '&' &&
            type_size(mir.insns[scan].secondary_offset) == 4) {
            mask = &mir.insns[scan];
            mask_instruction = scan;
            break;
        }
    if (mask == NULL || mir_value_use_count(mask->dst) != 1)
        return 0;
    mask_constant = mir_definition(mask->src2);
    source_value = mask->src1;
    if (mask_constant == NULL ||
        mask_constant->opcode != MIR_CONST) {
        mask_constant = mir_definition(mask->src1);
        source_value = mask->src2;
    }
    if (mask_constant == NULL ||
        mask_constant->opcode != MIR_CONST ||
        type_size(mask_constant->type) != 4 ||
        ((unsigned long)mask_constant->immediate & 0xffffffffUL) == 0 ||
        mir_value_use_count(mask_constant->dst) != 1 ||
        mir_definition(source_value) == NULL ||
        type_size(mir_definition(source_value)->type) != 4)
        return 0;
    compare_instruction =
        mir_low_byte_loop_next_effective(mask_instruction);
    if (compare_instruction >= mir.count)
        return 0;
    compare = &mir.insns[compare_instruction];
    if (compare->opcode != MIR_BINARY ||
        (compare->immediate != TOK_EQ &&
         compare->immediate != TOK_NE) ||
        mir_value_use_count(compare->dst) != 1)
        return 0;
    zero = mir_definition(compare->src1);
    if (compare->src2 == mask->dst) {
        /* zero remains src1 */
    } else if (compare->src1 == mask->dst) {
        zero = mir_definition(compare->src2);
    } else {
        return 0;
    }
    if (zero == NULL || zero->opcode != MIR_CONST ||
        type_size(zero->type) != 4 ||
        ((unsigned long)zero->immediate & 0xffffffffUL) != 0 ||
        mir_value_use_count(zero->dst) != 1)
        return 0;
    branch_instruction =
        mir_low_byte_loop_next_effective(compare_instruction);
    if (branch_instruction >= mir.count)
        return 0;
    branch = &mir.insns[branch_instruction];
    if (branch->opcode != MIR_BRANCH_FALSE ||
        branch->src1 != compare->dst ||
        mir_find_label(branch->label) < 0)
        return 0;
    first_instruction = (int)(mask_constant - mir.insns);
    if ((int)(zero - mir.insns) < first_instruction)
        first_instruction = (int)(zero - mir.insns);
    if (first_instruction != instruction)
        return 0;

    plan->source_value = source_value;
    source = mir_definition(source_value);
    if (source != NULL &&
        (int)(source - mir.insns) >= instruction &&
        (int)(source - mir.insns) <= branch_instruction) {
        int source_type;
        int source_storage;
        int source_offset;

        if (source->opcode != MIR_LOAD ||
            mir_value_use_count(source->dst) != 1 ||
            !mir_scalar_memory_location(
                source, &source_type, &source_storage, &source_offset) ||
            type_size(source_type) != 4 ||
            (source_storage != SC_LOCAL &&
             source_storage != SC_PARAM) ||
            source_offset < -128 || source_offset + 3 > 127 ||
            !mir_wide_mask_zero_add_component(
                plan, (int)(source - mir.insns)))
            return 0;
        plan->source_is_direct = 1;
        plan->source_offset = source_offset;
    }
    plan->mask =
        (unsigned long)mask_constant->immediate & 0xffffffffUL;
    plan->comparison = (int)compare->immediate;
    plan->branch_instruction = branch_instruction;
    if (!mir_wide_mask_zero_add_component(
            plan, (int)(mask_constant - mir.insns)) ||
        !mir_wide_mask_zero_add_component(
            plan, (int)(zero - mir.insns)) ||
        !mir_wide_mask_zero_add_component(plan, mask_instruction) ||
        !mir_wide_mask_zero_add_component(plan, compare_instruction) ||
        !mir_wide_mask_zero_add_component(plan, branch_instruction))
        return 0;
    for (scan = instruction; scan <= branch_instruction; ++scan)
        if (!mir_wide_mask_zero_has_component(plan, scan) &&
            mir.insns[scan].opcode != MIR_NOP)
            return 0;
    return 1;
}

static int mir_function_has_wide_mask_zero_branch(void)
{
    int instruction;

    for (instruction = 0; instruction < mir.count; ++instruction) {
        struct MirWideMaskZeroBranch plan;

        if (mir_match_wide_mask_zero_branch(instruction, &plan))
            return 1;
    }
    return 0;
}

static int mir_wide_byte_pack_add_component(
    struct MirWideBytePackReturn *plan, int instruction)
{
    int component;

    if (instruction < 0 || instruction >= mir.count)
        return 0;
    for (component = 0; component < plan->component_count; ++component)
        if (plan->components[component] == instruction)
            return 1;
    if (plan->component_count >=
        (int)(sizeof(plan->components) / sizeof(plan->components[0])))
        return 0;
    plan->components[plan->component_count++] = instruction;
    return 1;
}

static int mir_wide_byte_pack_has_component(
    const struct MirWideBytePackReturn *plan, int instruction)
{
    int component;

    for (component = 0; component < plan->component_count; ++component)
        if (plan->components[component] == instruction)
            return 1;
    return 0;
}

static int mir_collect_wide_byte_pack_terms(
    int value, struct MirWideBytePackReturn *plan, int depth)
{
    const struct MirInsn *definition = mir_definition(value);
    const struct MirInsn *shift_count = NULL;
    const struct MirInsn *mask;
    const struct MirInsn *mask_constant;
    const struct MirInsn *widen;
    const struct MirInsn *load;
    const struct MirInsn *index;
    const struct MirInsn *index_constant;
    const struct MirInsn *base;
    int shift = 0;
    int masked_value;
    int byte_offset;
    int base_type;
    int base_storage;
    int base_offset;

    if (definition == NULL || depth > 8)
        return 0;
    if (definition->opcode == MIR_BINARY &&
        definition->immediate == '|' &&
        type_size(definition->secondary_offset) == 4) {
        if (!mir_wide_byte_pack_add_component(
                plan, (int)(definition - mir.insns)))
            return 0;
        return mir_collect_wide_byte_pack_terms(
                   definition->src1, plan, depth + 1) &&
               mir_collect_wide_byte_pack_terms(
                   definition->src2, plan, depth + 1);
    }
    if (definition->opcode == MIR_BINARY &&
        definition->immediate == TOK_SHL &&
        type_size(definition->secondary_offset) == 4) {
        shift_count = mir_definition(definition->src2);
        if (shift_count == NULL || shift_count->opcode != MIR_CONST ||
            (shift_count->immediate != 8 &&
             shift_count->immediate != 16 &&
             shift_count->immediate != 24))
            return 0;
        shift = (int)shift_count->immediate;
        masked_value = definition->src1;
        if (!mir_wide_byte_pack_add_component(
                plan, (int)(definition - mir.insns)) ||
            !mir_wide_byte_pack_add_component(
                plan, (int)(shift_count - mir.insns)))
            return 0;
    } else {
        masked_value = value;
    }
    mask = mir_definition(masked_value);
    if (mask == NULL || mask->opcode != MIR_BINARY ||
        mask->immediate != '&' || type_size(mask->secondary_offset) != 4)
        return 0;
    mask_constant = mir_definition(mask->src1);
    value = mask->src2;
    if (mask_constant == NULL || mask_constant->opcode != MIR_CONST ||
        ((unsigned long)mask_constant->immediate & 0xffffffffUL) != 255UL) {
        mask_constant = mir_definition(mask->src2);
        value = mask->src1;
    }
    if (mask_constant == NULL || mask_constant->opcode != MIR_CONST ||
        ((unsigned long)mask_constant->immediate & 0xffffffffUL) != 255UL)
        return 0;
    widen = mir_definition(value);
    if (widen == NULL || widen->opcode != MIR_UNARY ||
        widen->immediate != 0 || type_size(widen->type) != 4)
        return 0;
    load = mir_definition(widen->src1);
    if (load == NULL || load->opcode != MIR_LOAD_INDIRECT ||
        load->memory_size != 1 || load->bit_width != 0)
        return 0;
    index = mir_definition(load->src1);
    if (index == NULL || index->opcode != MIR_INDEX_ADDRESS ||
        index->immediate != 1)
        return 0;
    index_constant = mir_definition(index->src2);
    base = mir_definition(index->src1);
    if (index_constant == NULL ||
        index_constant->opcode != MIR_CONST ||
        index_constant->immediate < 0 ||
        index_constant->immediate > 3 ||
        base == NULL ||
        !mir_scalar_memory_location(base, &base_type, &base_storage,
                                    &base_offset) ||
        type_ptr_depth(base_type) == 0 || type_size(base_type) != 2 ||
        (base_storage != SC_LOCAL && base_storage != SC_PARAM) ||
        base_offset < -128 || base_offset + 1 > 127)
        return 0;
    byte_offset = (int)index_constant->immediate;
    if (plan->shifts[byte_offset] >= 0 ||
        (plan->base_offset != 32767 &&
         plan->base_offset != base_offset))
        return 0;
    plan->base_offset = base_offset;
    plan->shifts[byte_offset] = shift;
    return mir_wide_byte_pack_add_component(
               plan, (int)(mask - mir.insns)) &&
           mir_wide_byte_pack_add_component(
               plan, (int)(mask_constant - mir.insns)) &&
           mir_wide_byte_pack_add_component(
               plan, (int)(widen - mir.insns)) &&
           mir_wide_byte_pack_add_component(
               plan, (int)(load - mir.insns)) &&
           mir_wide_byte_pack_add_component(
               plan, (int)(index - mir.insns)) &&
           mir_wide_byte_pack_add_component(
               plan, (int)(index_constant - mir.insns));
}

static int mir_match_wide_byte_pack_return(
    int instruction, struct MirWideBytePackReturn *plan)
{
    const struct MirInsn *first;
    const struct MirInsn *ret = NULL;
    int return_instruction = -1;
    int scan;
    int offset;

    memset(plan, 0, sizeof(*plan));
    plan->base_offset = 32767;
    for (offset = 0; offset < 4; ++offset)
        plan->shifts[offset] = -1;
    if (instruction < 0 || instruction >= mir.count)
        return 0;
    first = &mir.insns[instruction];
    if (first->opcode != MIR_INDEX_ADDRESS)
        return 0;
    for (scan = instruction + 1; scan < mir.count; ++scan) {
        if (mir.insns[scan].opcode == MIR_LABEL ||
            mir.insns[scan].opcode == MIR_JUMP ||
            mir.insns[scan].opcode == MIR_BRANCH_FALSE)
            return 0;
        if (mir.insns[scan].opcode == MIR_RETURN) {
            ret = &mir.insns[scan];
            return_instruction = scan;
            break;
        }
    }
    if (ret == NULL || ret->src1 < 0 ||
        !mir_collect_wide_byte_pack_terms(ret->src1, plan, 0))
        return 0;
    for (offset = 0; offset < 4; ++offset)
        if (plan->shifts[offset] != 24 - 8 * offset)
            return 0;
    if (!mir_wide_byte_pack_has_component(plan, instruction) ||
        !mir_wide_byte_pack_add_component(plan, return_instruction))
        return 0;
    plan->skip_through = return_instruction;
    for (scan = instruction; scan <= return_instruction; ++scan) {
        const struct MirInsn *insn = &mir.insns[scan];

        if (mir_wide_byte_pack_has_component(plan, scan) ||
            insn->opcode == MIR_NOP)
            continue;
        if (insn->opcode == MIR_STORE &&
            insn->src1 >= 0 &&
            mir_object_is_fully_promoted(insn->object)) {
            const struct MirInsn *source = mir_definition(insn->src1);

            if (source != NULL &&
                mir_wide_byte_pack_has_component(
                    plan, (int)(source - mir.insns))) {
                if (!mir_wide_byte_pack_add_component(plan, scan))
                    return 0;
                continue;
            }
        }
        return 0;
    }
    for (scan = 0; scan < plan->component_count; ++scan) {
        const struct MirInsn *component =
            &mir.insns[plan->components[scan]];

        if (component->dst >= 0 &&
            mir_low_byte_loop_value_used_outside(
                component->dst, instruction, return_instruction))
            return 0;
    }
    return 1;
}

static int mir_wide_byte_store_add_component(
    struct MirWideByteStore *plan, int instruction)
{
    int component;

    if (instruction < 0 || instruction >= mir.count)
        return 0;
    for (component = 0; component < plan->component_count; ++component)
        if (plan->components[component] == instruction)
            return 1;
    if (plan->component_count >=
        (int)(sizeof(plan->components) / sizeof(plan->components[0])))
        return 0;
    plan->components[plan->component_count++] = instruction;
    return 1;
}

static int mir_wide_byte_store_has_component(
    const struct MirWideByteStore *plan, int instruction)
{
    int component;

    for (component = 0; component < plan->component_count; ++component)
        if (plan->components[component] == instruction)
            return 1;
    return 0;
}

static int mir_match_wide_byte_store(
    int instruction, struct MirWideByteStore *plan)
{
    const struct MirInsn *index;
    const struct MirInsn *index_constant;
    const struct MirInsn *base;
    const struct MirInsn *store = NULL;
    const struct MirInsn *conversion;
    const struct MirInsn *mask;
    const struct MirInsn *mask_constant;
    const struct MirInsn *lane;
    const struct MirInsn *shift_count = NULL;
    const struct MirInsn *source;
    int base_type;
    int base_storage;
    int base_offset;
    int source_type;
    int source_storage;
    int source_offset;
    int store_instruction = -1;
    int lane_value;
    int source_value;
    int shift = 0;
    int scan;

    memset(plan, 0, sizeof(*plan));
    if (instruction < 0 || instruction >= mir.count)
        return 0;
    index = &mir.insns[instruction];
    if (index->opcode != MIR_INDEX_ADDRESS || index->immediate != 1 ||
        mir_value_use_count(index->dst) != 1)
        return 0;
    index_constant = mir_definition(index->src2);
    base = mir_definition(index->src1);
    if (index_constant == NULL ||
        index_constant->opcode != MIR_CONST ||
        index_constant->immediate < 0 ||
        index_constant->immediate > 3 ||
        mir_value_use_count(index_constant->dst) != 1 ||
        base == NULL ||
        !mir_scalar_memory_location(base, &base_type, &base_storage,
                                    &base_offset) ||
        type_ptr_depth(base_type) == 0 || type_size(base_type) != 2 ||
        (base_storage != SC_LOCAL && base_storage != SC_PARAM) ||
        base_offset < -128 || base_offset + 1 > 127)
        return 0;
    for (scan = instruction + 1; scan < mir.count; ++scan) {
        if (mir.insns[scan].opcode == MIR_LABEL ||
            mir.insns[scan].opcode == MIR_JUMP ||
            mir.insns[scan].opcode == MIR_BRANCH_FALSE ||
            mir.insns[scan].opcode == MIR_RETURN)
            break;
        if (mir.insns[scan].opcode == MIR_STORE_INDIRECT &&
            mir.insns[scan].src1 == index->dst) {
            store = &mir.insns[scan];
            store_instruction = scan;
            break;
        }
    }
    if (store == NULL || store->memory_size != 1 ||
        store->bit_width != 0)
        return 0;
    conversion = mir_definition(store->src2);
    if (conversion == NULL || conversion->opcode != MIR_UNARY ||
        conversion->immediate != 0 || type_size(conversion->type) != 1 ||
        mir_value_use_count(conversion->dst) != 1)
        return 0;
    mask = mir_definition(conversion->src1);
    if (mask == NULL || mask->opcode != MIR_BINARY ||
        mask->immediate != '&' || type_size(mask->secondary_offset) != 4 ||
        mir_value_use_count(mask->dst) != 1)
        return 0;
    mask_constant = mir_definition(mask->src1);
    lane_value = mask->src2;
    if (mask_constant == NULL || mask_constant->opcode != MIR_CONST ||
        ((unsigned long)mask_constant->immediate & 0xffffffffUL) != 255UL) {
        mask_constant = mir_definition(mask->src2);
        lane_value = mask->src1;
    }
    if (mask_constant == NULL || mask_constant->opcode != MIR_CONST ||
        ((unsigned long)mask_constant->immediate & 0xffffffffUL) != 255UL ||
        mir_value_use_count(mask_constant->dst) != 1)
        return 0;
    lane = mir_definition(lane_value);
    source_value = lane_value;
    if (lane != NULL && lane->opcode == MIR_BINARY &&
        lane->immediate == TOK_SHR &&
        type_size(lane->secondary_offset) == 4 &&
        mir_value_use_count(lane->dst) == 1) {
        shift_count = mir_definition(lane->src2);
        if (shift_count == NULL || shift_count->opcode != MIR_CONST ||
            (shift_count->immediate != 8 &&
             shift_count->immediate != 16 &&
             shift_count->immediate != 24) ||
            mir_value_use_count(shift_count->dst) != 1)
            return 0;
        shift = (int)shift_count->immediate;
        source_value = lane->src1;
    } else {
        lane = NULL;
    }
    source = mir_definition(source_value);
    if (source == NULL || type_size(source->type) != 4 ||
        !mir_scalar_memory_location(source, &source_type, &source_storage,
                                    &source_offset) ||
        type_size(source_type) != 4 ||
        (source_storage != SC_LOCAL && source_storage != SC_PARAM) ||
        source_offset < -128 || source_offset + shift / 8 > 127)
        return 0;

    plan->skip_through = store_instruction;
    plan->base_offset = base_offset;
    plan->source_offset = source_offset + shift / 8;
    plan->byte_offset = (int)index_constant->immediate;
    if (!mir_wide_byte_store_add_component(plan, instruction) ||
        !mir_wide_byte_store_add_component(
            plan, (int)(conversion - mir.insns)) ||
        !mir_wide_byte_store_add_component(
            plan, (int)(mask - mir.insns)) ||
        !mir_wide_byte_store_add_component(
            plan, (int)(mask_constant - mir.insns)) ||
        !mir_wide_byte_store_add_component(plan, store_instruction))
        return 0;
    if (lane != NULL &&
        (!mir_wide_byte_store_add_component(
             plan, (int)(lane - mir.insns)) ||
         !mir_wide_byte_store_add_component(
             plan, (int)(shift_count - mir.insns))))
        return 0;
    for (scan = instruction; scan <= store_instruction; ++scan) {
        const struct MirInsn *insn = &mir.insns[scan];

        if (mir_wide_byte_store_has_component(plan, scan) ||
            insn->opcode == MIR_NOP)
            continue;
        return 0;
    }
    for (scan = 0; scan < plan->component_count; ++scan) {
        const struct MirInsn *component =
            &mir.insns[plan->components[scan]];

        if (component->dst >= 0 &&
            mir_low_byte_loop_value_used_outside(
                component->dst, instruction, store_instruction))
            return 0;
    }
    return 1;
}

static int mir_low_byte_loop_add_component(
    struct MirLowByteIndexLoop *plan, int instruction)
{
    int component;

    if (instruction < 0 || instruction >= mir.count)
        return 0;
    for (component = 0; component < plan->component_count; ++component)
        if (plan->components[component] == instruction)
            return 1;
    if (plan->component_count >=
        (int)(sizeof(plan->components) / sizeof(plan->components[0])))
        return 0;
    plan->components[plan->component_count++] = instruction;
    return 1;
}

static int mir_low_byte_loop_has_component(
    const struct MirLowByteIndexLoop *plan, int instruction)
{
    int component;

    for (component = 0; component < plan->component_count; ++component)
        if (plan->components[component] == instruction)
            return 1;
    return 0;
}

static int mir_low_byte_loop_next_effective(int instruction)
{
    int next = instruction + 1;

    while (next < mir.count) {
        const struct MirInsn *insn = &mir.insns[next];

        if (insn->opcode == MIR_NOP) {
            ++next;
            continue;
        }
        if (insn->opcode == MIR_LOAD && insn->memory_flags == 0 &&
            insn->dst >= 0 && !mir_value_has_use(insn->dst)) {
            ++next;
            continue;
        }
        break;
    }
    return next;
}

static int mir_low_byte_loop_value_used_outside(
    int value, int first, int last)
{
    int instruction;

    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];

        if (instruction >= first && instruction <= last)
            continue;
        if (insn->src1 == value || insn->src2 == value)
            return 1;
        if ((insn->opcode == MIR_CALL ||
             insn->opcode == MIR_CALL_AGGREGATE) &&
            mir_call_uses_value(insn, value))
            return 1;
    }
    return 0;
}

static int mir_low_byte_loop_add_projection(
    int value, int index_value, struct MirLowByteIndexLoop *plan)
{
    const struct MirInsn *conversion = mir_definition(value);
    const struct MirInsn *byte_conversion;
    const struct MirInsn *mask;
    const struct MirInsn *mask_constant;
    const struct MirInsn *addition;
    const struct MirInsn *widen;
    const struct MirInsn *invariant;
    int conversion_index = -1;
    int byte_conversion_index;
    int mask_index;
    int constant_index;
    int addition_index;
    int widen_index;
    int invariant_type;
    int invariant_storage;
    int invariant_offset;
    int addition_value;
    int widen_value;
    int invariant_value;

    if (conversion != NULL && conversion->opcode == MIR_UNARY &&
        conversion->immediate == 0 && type_size(conversion->type) == 2) {
        const struct MirInsn *source = mir_definition(conversion->src1);

        if (source == NULL || type_size(source->type) != 1 ||
            mir_value_use_count(conversion->dst) != 1)
            return 0;
        conversion_index = (int)(conversion - mir.insns);
        value = conversion->src1;
        conversion = source;
    }
    byte_conversion = conversion;
    if (byte_conversion == NULL ||
        byte_conversion->opcode != MIR_UNARY ||
        byte_conversion->immediate != 0 ||
        type_size(byte_conversion->type) != 1 ||
        mir_value_use_count(byte_conversion->dst) != 1)
        return 0;
    mask = mir_definition(byte_conversion->src1);
    if (mask == NULL || mask->opcode != MIR_BINARY ||
        mask->immediate != '&' || type_size(mask->secondary_offset) != 4 ||
        mir_value_use_count(mask->dst) != 1)
        return 0;
    mask_constant = mir_definition(mask->src1);
    addition_value = mask->src2;
    if (mask_constant == NULL || mask_constant->opcode != MIR_CONST ||
        ((unsigned long)mask_constant->immediate & 0xffffffffUL) != 255UL) {
        mask_constant = mir_definition(mask->src2);
        addition_value = mask->src1;
    }
    if (mask_constant == NULL || mask_constant->opcode != MIR_CONST ||
        ((unsigned long)mask_constant->immediate & 0xffffffffUL) != 255UL ||
        mir_value_use_count(mask_constant->dst) != 1)
        return 0;
    addition = mir_definition(addition_value);
    if (addition == NULL || addition->opcode != MIR_BINARY ||
        addition->immediate != '+' ||
        type_size(addition->secondary_offset) != 4 ||
        mir_value_use_count(addition->dst) != 1)
        return 0;
    widen_value = addition->src1;
    invariant_value = addition->src2;
    widen = mir_definition(widen_value);
    if (widen == NULL || widen->opcode != MIR_UNARY ||
        widen->immediate != 0 || type_size(widen->type) != 4 ||
        widen->src1 != index_value) {
        widen_value = addition->src2;
        invariant_value = addition->src1;
        widen = mir_definition(widen_value);
    }
    if (widen == NULL || widen->opcode != MIR_UNARY ||
        widen->immediate != 0 || type_size(widen->type) != 4 ||
        widen->src1 != index_value ||
        mir_value_use_count(widen->dst) != 1)
        return 0;
    invariant = mir_definition(invariant_value);
    if (invariant == NULL || type_size(invariant->type) != 4 ||
        !mir_scalar_memory_location(invariant, &invariant_type,
                                    &invariant_storage,
                                    &invariant_offset) ||
        type_size(invariant_type) != 4 ||
        (invariant_storage != SC_LOCAL &&
         invariant_storage != SC_PARAM) ||
        invariant_offset < -128 || invariant_offset > 127)
        return 0;

    byte_conversion_index = (int)(byte_conversion - mir.insns);
    mask_index = (int)(mask - mir.insns);
    constant_index = (int)(mask_constant - mir.insns);
    addition_index = (int)(addition - mir.insns);
    widen_index = (int)(widen - mir.insns);
    if ((conversion_index >= 0 &&
         !mir_low_byte_loop_add_component(plan, conversion_index)) ||
        !mir_low_byte_loop_add_component(plan, byte_conversion_index) ||
        !mir_low_byte_loop_add_component(plan, mask_index) ||
        !mir_low_byte_loop_add_component(plan, constant_index) ||
        !mir_low_byte_loop_add_component(plan, addition_index) ||
        !mir_low_byte_loop_add_component(plan, widen_index))
        return 0;
    plan->invariant_offset = invariant_offset;
    return 1;
}

static int mir_low_byte_loop_promotes_value(
    int value, int source_value, struct MirLowByteIndexLoop *plan)
{
    const struct MirInsn *conversion;

    if (value == source_value)
        return 1;
    conversion = mir_definition(value);
    if (conversion == NULL || conversion->opcode != MIR_UNARY ||
        conversion->immediate != 0 || conversion->src1 != source_value ||
        type_size(conversion->type) != 2 ||
        mir_value_use_count(conversion->dst) != 1)
        return 0;
    return mir_low_byte_loop_add_component(
        plan, (int)(conversion - mir.insns));
}

static int mir_low_byte_loop_match_body(
    int first, int latch, int index_value, struct MirLowByteIndexLoop *plan)
{
    int instruction;

    for (instruction = first; instruction < latch; ++instruction) {
        const struct MirInsn *index = &mir.insns[instruction];
        const struct MirInsn *base;
        int base_type;
        int base_storage;
        int base_offset;
        int use;

        if (index->opcode != MIR_INDEX_ADDRESS ||
            index->src2 != index_value || index->immediate != 1 ||
            mir_value_use_count(index->dst) != 1)
            continue;
        base = mir_definition(index->src1);
        if (base == NULL ||
            !mir_scalar_memory_location(base, &base_type, &base_storage,
                                        &base_offset) ||
            type_ptr_depth(base_type) == 0 ||
            type_size(base_type) != 2 ||
            (base_storage != SC_LOCAL && base_storage != SC_PARAM) ||
            base_offset < -128 || base_offset + 1 > 127)
            continue;

        use = instruction + 1;
        while (use < latch && mir.insns[use].opcode == MIR_NOP)
            ++use;
        if (use >= latch ||
            mir.insns[use].opcode != MIR_STORE_INDIRECT ||
            mir.insns[use].src1 != index->dst)
            for (use = instruction + 1; use < latch; ++use)
                if (mir.insns[use].opcode == MIR_STORE_INDIRECT &&
                    mir.insns[use].src1 == index->dst)
                    break;
        if (use < latch && mir.insns[use].opcode == MIR_STORE_INDIRECT &&
            mir.insns[use].src1 == index->dst &&
            mir.insns[use].memory_size == 1 &&
            mir.insns[use].bit_width == 0) {
            struct MirLowByteIndexLoop candidate = *plan;

            if (!mir_low_byte_loop_add_projection(
                    mir.insns[use].src2, index_value, &candidate))
                continue;
            candidate.kind = MIR_LOW_BYTE_INDEX_STORE;
            candidate.base_offset = base_offset;
            if (!mir_low_byte_loop_add_component(&candidate, instruction) ||
                !mir_low_byte_loop_add_component(&candidate, use))
                continue;
            if ((int)(base - mir.insns) >= first &&
                !mir_low_byte_loop_add_component(
                    &candidate, (int)(base - mir.insns)))
                continue;
            *plan = candidate;
            return 1;
        }
        use = instruction + 1;
        while (use < latch && mir.insns[use].opcode == MIR_NOP)
            ++use;
        if (use >= latch ||
            mir.insns[use].opcode != MIR_LOAD_INDIRECT ||
            mir.insns[use].src1 != index->dst)
            for (use = instruction + 1; use < latch; ++use)
                if (mir.insns[use].opcode == MIR_LOAD_INDIRECT &&
                    mir.insns[use].src1 == index->dst)
                    break;
        if (use < latch && mir.insns[use].opcode == MIR_LOAD_INDIRECT &&
            mir.insns[use].src1 == index->dst &&
            mir.insns[use].memory_size == 1 &&
            mir.insns[use].bit_width == 0 &&
            mir_value_use_count(mir.insns[use].dst) == 1) {
            int compare_index;

            for (compare_index = use + 1;
                 compare_index < latch; ++compare_index) {
                const struct MirInsn *compare =
                    &mir.insns[compare_index];
                int projection_value;
                int loaded_value;
                int branch_index;
                int continue_instruction;
                int mismatch_const;
                int mismatch_return;
                struct MirLowByteIndexLoop candidate = *plan;

                if (compare->opcode != MIR_BINARY ||
                    compare->immediate != TOK_NE ||
                    mir_value_use_count(compare->dst) != 1)
                    continue;
                loaded_value = compare->src1;
                projection_value = compare->src2;
                if (!mir_low_byte_loop_promotes_value(
                        loaded_value, mir.insns[use].dst, &candidate)) {
                    loaded_value = compare->src2;
                    projection_value = compare->src1;
                    candidate = *plan;
                    if (!mir_low_byte_loop_promotes_value(
                            loaded_value, mir.insns[use].dst, &candidate))
                        continue;
                }
                if (!mir_low_byte_loop_add_projection(
                        projection_value, index_value, &candidate))
                    continue;
                branch_index = mir_low_byte_loop_next_effective(
                    compare_index);
                if (branch_index >= latch ||
                    mir.insns[branch_index].opcode != MIR_BRANCH_FALSE ||
                    mir.insns[branch_index].src1 != compare->dst)
                    continue;
                continue_instruction =
                    mir_find_label(mir.insns[branch_index].label);
                if (continue_instruction <= branch_index ||
                    continue_instruction > latch ||
                    !mir_phi_copies_are_empty(
                        branch_index, continue_instruction))
                    continue;
                mismatch_const =
                    mir_low_byte_loop_next_effective(branch_index);
                mismatch_return =
                    mir_low_byte_loop_next_effective(mismatch_const);
                if (mismatch_const >= continue_instruction ||
                    mismatch_return >= continue_instruction ||
                    type_size(mir.return_type) != 2 ||
                    mir.insns[mismatch_const].opcode != MIR_CONST ||
                    type_size(mir.insns[mismatch_const].type) != 2 ||
                    mir.insns[mismatch_const].immediate != 0 ||
                    mir.insns[mismatch_return].opcode != MIR_RETURN ||
                    mir.insns[mismatch_return].src1 !=
                        mir.insns[mismatch_const].dst)
                    continue;
                while (continue_instruction < latch &&
                       (mir.insns[continue_instruction].opcode == MIR_LABEL ||
                        mir.insns[continue_instruction].opcode == MIR_NOP)) {
                    if (mir.insns[continue_instruction].opcode == MIR_LABEL &&
                        !mir_low_byte_loop_add_component(
                            &candidate, continue_instruction))
                        break;
                    ++continue_instruction;
                }
                if (continue_instruction != latch)
                    continue;
                candidate.kind = MIR_LOW_BYTE_INDEX_COMPARE;
                candidate.base_offset = base_offset;
                candidate.continue_label =
                    mir.insns[branch_index].label;
                if (!mir_low_byte_loop_add_component(
                        &candidate, instruction) ||
                    !mir_low_byte_loop_add_component(&candidate, use) ||
                    !mir_low_byte_loop_add_component(
                        &candidate, compare_index) ||
                    !mir_low_byte_loop_add_component(
                        &candidate, branch_index) ||
                    !mir_low_byte_loop_add_component(
                        &candidate, mismatch_const) ||
                    !mir_low_byte_loop_add_component(
                        &candidate, mismatch_return))
                    continue;
                if ((int)(base - mir.insns) >= first &&
                    !mir_low_byte_loop_add_component(
                        &candidate, (int)(base - mir.insns)))
                    continue;
                *plan = candidate;
                return 1;
            }
        }
    }
    return 0;
}

static int mir_match_low_byte_index_loop(
    int instruction, struct MirLowByteIndexLoop *plan)
{
    const struct MirInsn *initial;
    const struct MirInsn *store;
    const struct MirInsn *header;
    const struct MirInsn *phi = NULL;
    const struct MirInsn *condition;
    const struct MirInsn *limit;
    const struct MirInsn *promote;
    const struct MirInsn *branch;
    const struct MirInsn *one;
    const struct MirInsn *increment;
    const struct MirInsn *update_store;
    const struct MirInsn *jump;
    int store_instruction;
    int header_instruction;
    int phi_instruction = -1;
    int condition_instruction;
    int branch_instruction;
    int latch_instruction;
    int one_instruction;
    int increment_instruction;
    int update_store_instruction;
    int jump_instruction;
    int exit_instruction;
    int index_type;
    int index_storage;
    int index_offset;
    int scan;

    memset(plan, 0, sizeof(*plan));
    plan->continue_label = -1;
    plan->invariant_offset = 0;
    if (instruction < 0 || instruction >= mir.count)
        return 0;
    initial = &mir.insns[instruction];
    if (initial->opcode != MIR_CONST || initial->dst < 0 ||
        mir_value_use_count(initial->dst) != 2 ||
        initial->immediate < 0 || initial->immediate > 254)
        return 0;
    store_instruction = mir_low_byte_loop_next_effective(instruction);
    if (store_instruction >= mir.count)
        return 0;
    store = &mir.insns[store_instruction];
    if (store->opcode != MIR_STORE || store->src1 != initial->dst ||
        store->object < 0 || store->memory_size != 1)
        return 0;
    header_instruction =
        mir_low_byte_loop_next_effective(store_instruction);
    if (header_instruction >= mir.count)
        return 0;
    header = &mir.insns[header_instruction];
    if (header->opcode != MIR_LABEL)
        return 0;
    for (scan = header_instruction + 1;
         scan < mir.count && scan <= header_instruction + 8; ++scan)
        if (mir.insns[scan].opcode == MIR_PHI &&
            mir.insns[scan].object == store->object &&
            mir.insns[scan].src1 == initial->dst) {
            phi = &mir.insns[scan];
            phi_instruction = scan;
            break;
        }
    if (phi == NULL || type_size(phi->type) != 1 ||
        !mir_scalar_memory_location(phi, &index_type, &index_storage,
                                    &index_offset) ||
        type_size(index_type) != 1 ||
        (index_storage != SC_LOCAL && index_storage != SC_PARAM) ||
        index_offset < -128 || index_offset > 127)
        return 0;

    branch_instruction = -1;
    for (scan = phi_instruction + 1;
         scan < mir.count && scan <= phi_instruction + 8; ++scan)
        if (mir.insns[scan].opcode == MIR_BRANCH_FALSE) {
            branch_instruction = scan;
            break;
        }
    if (branch_instruction < 0)
        return 0;
    branch = &mir.insns[branch_instruction];
    condition = mir_definition(branch->src1);
    if (condition == NULL || condition->opcode != MIR_BINARY ||
        condition->immediate != '<' ||
        mir_value_use_count(condition->dst) != 1)
        return 0;
    condition_instruction = (int)(condition - mir.insns);
    promote = mir_definition(condition->src1);
    limit = mir_definition(condition->src2);
    if (promote == NULL || promote->opcode != MIR_UNARY ||
        promote->immediate != 0 || promote->src1 != phi->dst ||
        type_size(promote->type) != 2 ||
        mir_value_use_count(promote->dst) != 1 ||
        limit == NULL || limit->opcode != MIR_CONST ||
        limit->immediate <= initial->immediate ||
        limit->immediate > 255 ||
        (((index_type & TYPE_UNSIGNED) == 0) &&
         limit->immediate > 127) ||
        mir_value_use_count(limit->dst) != 1)
        return 0;
    exit_instruction = mir_find_label(branch->label);
    latch_instruction = mir_find_label(phi->phi_pred2);
    if (exit_instruction <= branch_instruction ||
        latch_instruction <= branch_instruction ||
        latch_instruction >= exit_instruction ||
        !mir_phi_copies_are_empty(branch_instruction, exit_instruction))
        return 0;

    one_instruction = mir_low_byte_loop_next_effective(latch_instruction);
    increment_instruction =
        mir_low_byte_loop_next_effective(one_instruction);
    update_store_instruction =
        mir_low_byte_loop_next_effective(increment_instruction);
    jump_instruction =
        mir_low_byte_loop_next_effective(update_store_instruction);
    if (jump_instruction >= exit_instruction)
        return 0;
    one = &mir.insns[one_instruction];
    increment = &mir.insns[increment_instruction];
    update_store = &mir.insns[update_store_instruction];
    jump = &mir.insns[jump_instruction];
    if (one->opcode != MIR_CONST || one->immediate != 1 ||
        mir_value_use_count(one->dst) != 1 ||
        increment->opcode != MIR_BINARY || increment->immediate != '+' ||
        increment->src1 != phi->dst || increment->src2 != one->dst ||
        increment->dst != phi->src2 ||
        type_size(increment->secondary_offset) != 1 ||
        update_store->opcode != MIR_STORE ||
        update_store->src1 != increment->dst ||
        update_store->object != store->object ||
        jump->opcode != MIR_JUMP || jump->label != header->label)
        return 0;
    for (scan = phi_instruction + 1;
         scan < branch_instruction; ++scan)
        if (mir.insns[scan].opcode == MIR_PHI)
            return 0;

    plan->skip_through = jump_instruction;
    plan->header_label = header->label;
    plan->initial = (int)initial->immediate;
    plan->limit = (int)limit->immediate;
    plan->index_object = store->object;
    if (!mir_low_byte_loop_add_component(plan, instruction) ||
        !mir_low_byte_loop_add_component(plan, store_instruction) ||
        !mir_low_byte_loop_add_component(plan, header_instruction) ||
        !mir_low_byte_loop_add_component(plan, phi_instruction) ||
        !mir_low_byte_loop_add_component(
            plan, (int)(promote - mir.insns)) ||
        !mir_low_byte_loop_add_component(
            plan, (int)(limit - mir.insns)) ||
        !mir_low_byte_loop_add_component(plan, condition_instruction) ||
        !mir_low_byte_loop_add_component(plan, branch_instruction) ||
        !mir_low_byte_loop_add_component(plan, latch_instruction) ||
        !mir_low_byte_loop_add_component(plan, one_instruction) ||
        !mir_low_byte_loop_add_component(plan, increment_instruction) ||
        !mir_low_byte_loop_add_component(plan, update_store_instruction) ||
        !mir_low_byte_loop_add_component(plan, jump_instruction) ||
        !mir_low_byte_loop_match_body(
            branch_instruction + 1, latch_instruction, phi->dst, plan))
        return 0;

    for (scan = instruction; scan <= plan->skip_through; ++scan) {
        const struct MirInsn *insn = &mir.insns[scan];

        if (mir_low_byte_loop_has_component(plan, scan) ||
            insn->opcode == MIR_NOP)
            continue;
        if (insn->opcode == MIR_LOAD && insn->memory_flags == 0 &&
            insn->dst >= 0 && !mir_value_has_use(insn->dst))
            continue;
        return 0;
    }
    for (scan = 0; scan < mir.count; ++scan) {
        const struct MirInsn *insn = &mir.insns[scan];

        if (scan >= instruction && scan <= plan->skip_through)
            continue;
        if (insn->object == plan->index_object &&
            (insn->opcode == MIR_LOAD || insn->opcode == MIR_STORE ||
             insn->opcode == MIR_PARAM ||
             insn->opcode == MIR_OBJECT_MERGE ||
             insn->opcode == MIR_PHI))
            return 0;
    }
    for (scan = 0; scan < plan->component_count; ++scan) {
        const struct MirInsn *component =
            &mir.insns[plan->components[scan]];

        if (component->dst >= 0 &&
            mir_low_byte_loop_value_used_outside(
                component->dst, instruction, plan->skip_through))
            return 0;
    }
    return 1;
}

static int mir_match_indirect_incdec(
    int instruction, struct MirIndirectIncDec *plan)
{
    const struct MirInsn *load;
    const struct MirInsn *constant;
    const struct MirInsn *binary;
    const struct MirInsn *store;
    const struct MirInsn *ret;
    int returns_adjusted;
    int scan;

    /*
     * First rollout: isolated update helpers only. Multi-block functions can
     * execute this shape in very hot paths where the surrounding MIR register
     * schedule outweighs its local instruction saving (cint/cobint emit).
     */
    if (mir_cfg_block_count() != 1 ||
        instruction < 0 || instruction + 4 >= mir.count)
        return 0;
    load = &mir.insns[instruction];
    constant = &mir.insns[instruction + 1];
    binary = &mir.insns[instruction + 2];
    store = &mir.insns[instruction + 3];
    ret = &mir.insns[instruction + 4];
    if (load->opcode != MIR_LOAD_INDIRECT ||
        load->bit_width != 0 ||
        (load->memory_size != 1 &&
         load->memory_size != 2 &&
         load->memory_size != 4) ||
        type_size(load->type) != load->memory_size ||
        type_is_bool(load->type) ||
        constant->opcode != MIR_CONST ||
        constant->immediate != 1 ||
        constant->dst < 0 ||
        binary->opcode != MIR_BINARY ||
        (binary->immediate != '+' && binary->immediate != '-') ||
        binary->src1 != load->dst ||
        binary->src2 != constant->dst ||
        (binary->secondary_offset != 0 &&
         type_size(binary->secondary_offset) != load->memory_size) ||
        store->opcode != MIR_STORE_INDIRECT ||
        store->src1 != load->src1 ||
        store->src2 != binary->dst ||
        store->bit_width != 0 ||
        store->memory_size != load->memory_size ||
        ret->opcode != MIR_RETURN ||
        (ret->src1 != load->dst && ret->src1 != binary->dst))
        return 0;
    returns_adjusted = ret->src1 == binary->dst;
    if (load->memory_size == 4 && returns_adjusted)
        return 0;
    for (scan = 0; scan < mir.count; ++scan) {
        const struct MirInsn *use = &mir.insns[scan];

        if (use->src1 == load->dst || use->src2 == load->dst ||
            mir_call_uses_value(use, load->dst)) {
            if (!((scan == instruction + 2 &&
                   use->src1 == load->dst) ||
                  (!returns_adjusted &&
                   scan == instruction + 4 &&
                   use->src1 == load->dst)))
                return 0;
        }
        if (use->src1 == constant->dst ||
            use->src2 == constant->dst ||
            mir_call_uses_value(use, constant->dst))
            if (!(scan == instruction + 2 &&
                  use->src2 == constant->dst))
                return 0;
        if (use->src1 == binary->dst || use->src2 == binary->dst ||
            mir_call_uses_value(use, binary->dst)) {
            if (!((scan == instruction + 3 &&
                   use->src2 == binary->dst) ||
                  (returns_adjusted &&
                   scan == instruction + 4 &&
                   use->src1 == binary->dst)))
                return 0;
        }
        if (use->src1 == load->src1 || use->src2 == load->src1 ||
            mir_call_uses_value(use, load->src1)) {
            if (!((scan == instruction &&
                   use->src1 == load->src1) ||
                  (scan == instruction + 3 &&
                   use->src1 == load->src1)))
                return 0;
        }
    }
    plan->load_instruction = instruction;
    plan->constant_instruction = instruction + 1;
    plan->binary_instruction = instruction + 2;
    plan->store_instruction = instruction + 3;
    plan->return_instruction = instruction + 4;
    plan->address_value = load->src1;
    plan->old_value = load->dst;
    plan->adjusted_value = binary->dst;
    plan->memory_size = load->memory_size;
    plan->type = load->type;
    plan->decrement = binary->immediate == '-';
    plan->returns_adjusted = returns_adjusted;
    return 1;
}

static void mir_emit_indirect_incdec_normalize(FILE *out, int type)
{
    if (type_size(type) != 1)
        return;
    if ((type & TYPE_UNSIGNED) != 0)
        fputs("\tld h,0\n", out);
    else
        mir_emit_signed_byte_extend(out);
}

static void mir_emit_indirect_incdec(
    FILE *out, const struct MirIndirectIncDec *plan)
{
    int adjust_label;

    mir_spilled_cfg_used_indirect_incdec = 1;
    mir_emit_virtual_load(out, plan->address_value);
    if (plan->memory_size == 4) {
        fputs("\tld b,h\n\tld c,l\n"
              "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
              "\tinc hl\n\tld a,(hl)\n\tinc hl\n"
              "\tld h,(hl)\n\tld l,a\n\tex de,hl\n",
              out);
        if (!plan->returns_adjusted)
            fputs("\tpush de\n\tpush hl\n", out);
        adjust_label = new_label();
        if (plan->decrement)
            fprintf(out,
                    "\tld a,h\n\tor l\n\tdec hl\n"
                    "\tjp nz, L%d\n\tdec de\nL%d:\n",
                    adjust_label, adjust_label);
        else
            fprintf(out,
                    "\tinc hl\n\tld a,h\n\tor l\n"
                    "\tjp nz, L%d\n\tinc de\nL%d:\n",
                    adjust_label, adjust_label);
        fputs("\tpush hl\n\tld h,b\n\tld l,c\n\tpop bc\n"
              "\tld (hl),c\n\tinc hl\n\tld (hl),b\n"
              "\tinc hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
              out);
        if (!plan->returns_adjusted)
            fputs("\tpop hl\n\tpop de\n", out);
        else
            fputs("\tld h,b\n\tld l,c\n", out);
        mir_emit_instruction_index = plan->store_instruction;
        mir_forwarded_wide_value = plan->returns_adjusted
            ? plan->adjusted_value : plan->old_value;
        mir_forwarded_wide_instruction = plan->store_instruction;
        return;
    }
    fputs("\tpush hl\n", out);
    if (plan->memory_size == 1) {
        fputs("\tld l,(hl)\n", out);
        mir_emit_indirect_incdec_normalize(out, plan->type);
    } else {
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n",
              out);
    }
    if (!plan->returns_adjusted)
        fputs("\tpush hl\n", out);
    fputs(plan->decrement ? "\tdec hl\n" : "\tinc hl\n", out);
    if (plan->returns_adjusted)
        mir_emit_indirect_incdec_normalize(out, plan->type);
    fputs("\tex de,hl\n", out);
    if (!plan->returns_adjusted)
        fputs("\tpop hl\n\tex (sp),hl\n", out);
    else
        fputs("\tpop hl\n", out);
    if (plan->memory_size == 1)
        fputs("\tld (hl),e\n", out);
    else
        fputs("\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
    if (!plan->returns_adjusted)
        fputs("\tpop hl\n", out);
    else
        fputs("\tex de,hl\n", out);
    mir_emit_instruction_index = plan->store_instruction;
    mir_forwarded_hl_value = plan->returns_adjusted
        ? plan->adjusted_value : plan->old_value;
    mir_forwarded_hl_instruction = plan->store_instruction;
}

static int mir_prepare_backend_slots(void)
{
    int *first;
    int *last;
    int *slot_end;
    char *fused_away = NULL;
    unsigned char *stack_interval_occupied = NULL;
    int planned_narrow_cache_call = -1;
    int planned_wide_cache_call = -1;
    int slot_capacity;
    int value;
    int i;

    if (mir.next_value <= 0) {
        mir.backend_slot_count = 0;
        return 0;
    }

    if (mir.backend_slot_capacity < mir.next_value) {
        int *new_slots = (int *)realloc(
            mir.backend_slots, (size_t)mir.next_value * sizeof(*new_slots));
        if (new_slots == NULL)
            fatal("out of memory allocating MIR backend slots");
        mir.backend_slots = new_slots;
        mir.backend_slot_capacity = mir.next_value;
    }
    if (mir.planned_stack_consumer_capacity < mir.next_value) {
        int *new_consumers = (int *)realloc(
            mir.planned_stack_consumers,
            (size_t)mir.next_value * sizeof(*new_consumers));
        if (new_consumers == NULL)
            fatal("out of memory allocating MIR planned stack consumers");
        mir.planned_stack_consumers = new_consumers;
        mir.planned_stack_consumer_capacity = mir.next_value;
    }
    if (mir.planned_stack_value_capacity < mir.count) {
        int *new_values = (int *)realloc(
            mir.planned_stack_values,
            (size_t)mir.count * sizeof(*new_values));
        if (new_values == NULL)
            fatal("out of memory allocating MIR planned stack values");
        mir.planned_stack_values = new_values;
        mir.planned_stack_value_capacity = mir.count;
    }
    if (mir.planned_stack_emitted_capacity < mir.next_value) {
        unsigned char *new_emitted = (unsigned char *)realloc(
            mir.planned_stack_emitted,
            (size_t)mir.next_value * sizeof(*new_emitted));
        if (new_emitted == NULL)
            fatal("out of memory allocating MIR planned stack state");
        mir.planned_stack_emitted = new_emitted;
        mir.planned_stack_emitted_capacity = mir.next_value;
    }
    for (value = 0; value < mir.next_value; ++value)
        mir.planned_stack_consumers[value] = -1;
    memset(mir.planned_stack_emitted, 0,
           (size_t)mir.next_value * sizeof(*mir.planned_stack_emitted));
    for (i = 0; i < mir.count; ++i)
        mir.planned_stack_values[i] = -1;
    first = (int *)malloc((size_t)mir.next_value * sizeof(*first));
    last = (int *)malloc((size_t)mir.next_value * sizeof(*last));
    slot_capacity = mir.next_value * 2 + mir.object_count * 2;
    slot_end = (int *)malloc((size_t)slot_capacity * sizeof(*slot_end));
    if (first == NULL || last == NULL || slot_end == NULL)
        fatal("out of memory computing MIR backend intervals");
    if (mir_backend_slot_offset_capacity < slot_capacity) {
        int *new_offsets = (int *)realloc(
            mir_backend_slot_offsets,
            (size_t)slot_capacity * sizeof(*new_offsets));
        if (new_offsets == NULL)
            fatal("out of memory computing MIR backend slot offsets");
        mir_backend_slot_offsets = new_offsets;
        mir_backend_slot_offset_capacity = slot_capacity;
    }
    if (mir_planned_stack_handoffs_enabled) {
        stack_interval_occupied =
            (unsigned char *)calloc((size_t)mir.count, 1);
        if (stack_interval_occupied == NULL)
            fatal("out of memory planning MIR stack handoffs");
    }
    fused_away = (char *)calloc((size_t)mir.next_value, 1);
    if (fused_away == NULL)
        fatal("out of memory computing MIR fused-value set");
    if (mir_backend_slots_skip_fused_comparisons) {
        for (i = 0; i < mir.count; ++i) {
            int skip = mir_binary_is_fusable_comparison(i);
            if (skip > 0)
                fused_away[mir.insns[i].dst] = 1;
            if (skip == 2)
                fused_away[mir.insns[i + 1].dst] = 1;
            if (mir_unary_is_fusable_not_branch(i))
                fused_away[mir.insns[i].dst] = 1;
            {
                int multiply_index;
                if (mir_float_madd_match(i, &multiply_index, NULL))
                    fused_away[mir.insns[multiply_index].dst] = 1;
            }
        }
    }
    for (i = 0; i < mir.count; ++i) {
        struct MirLowByteIndexLoop loop;
        int component;

        if (!mir_match_low_byte_index_loop(i, &loop))
            continue;
        for (component = 0; component < loop.component_count; ++component) {
            int value = mir.insns[loop.components[component]].dst;

            if (value >= 0)
                fused_away[value] = 2;
        }
    }
    for (i = 0; i < mir.count; ++i) {
        struct MirWideByteStore store;
        int component;

        if (!mir_match_wide_byte_store(i, &store))
            continue;
        for (component = 0; component < store.component_count; ++component) {
            int value = mir.insns[store.components[component]].dst;

            if (value >= 0)
                fused_away[value] = 2;
        }
    }
    for (i = 0; i < mir.count; ++i) {
        struct MirWideBytePackReturn pack;
        int component;

        if (!mir_match_wide_byte_pack_return(i, &pack))
            continue;
        for (component = 0; component < pack.component_count; ++component) {
            int value = mir.insns[pack.components[component]].dst;

            if (value >= 0)
                fused_away[value] = 2;
        }
    }
    for (i = 0; i < mir.count; ++i) {
        struct MirWideMaskZeroBranch branch;
        int component;

        if (!mir_match_wide_mask_zero_branch(i, &branch))
            continue;
        for (component = 0; component < branch.component_count;
             ++component) {
            int value = mir.insns[branch.components[component]].dst;

            if (value >= 0)
                fused_away[value] = 2;
        }
    }
    for (i = 0; i < mir.count; ++i) {
        struct MirIndirectIncDec incdec;

        if (!mir_match_indirect_incdec(i, &incdec))
            continue;
        fused_away[incdec.old_value] = 2;
        fused_away[mir.insns[incdec.constant_instruction].dst] = 2;
        fused_away[incdec.adjusted_value] = 2;
        fused_away[incdec.address_value] = 2;
    }
    for (value = 0; value < mir.next_value; ++value) {
        first[value] = mir.count;
        last[value] = -1;
        mir.backend_slots[value] = -1;
    }
    for (value = 0; value < slot_capacity; ++value)
        slot_end[value] = -1;
    for (i = 0; i < mir.count; ++i) {
        const struct MirInsn *insn = &mir.insns[i];
        if (insn->dst >= 0) {
            first[insn->dst] = i;
            last[insn->dst] = i;
        }
        if (insn->src1 >= 0 && last[insn->src1] < i)
            last[insn->src1] = i;
        if (insn->src2 >= 0 && last[insn->src2] < i)
            last[insn->src2] = i;
        if (insn->opcode == MIR_CALL ||
            insn->opcode == MIR_CALL_AGGREGATE) {
            int argument;
            for (argument = 0; argument < mir.next_value; ++argument)
                if (mir_call_uses_value(insn, argument) &&
                    last[argument] < i)
                    last[argument] = i;
        }
    }
    for (i = 0; i < mir.count; ++i)
        if (mir.insns[i].opcode == MIR_PHI) {
            int phi_start = i;
            int predecessor;
            while (phi_start > 0 &&
               (mir.insns[phi_start - 1].opcode == MIR_PHI ||
                mir.insns[phi_start - 1].opcode == MIR_NOP))
                --phi_start;
            while (phi_start < i &&
               mir.insns[phi_start].opcode == MIR_NOP)
            ++phi_start;
            for (predecessor = 0; predecessor < mir.count; ++predecessor) {
                int successor;
                int predecessor_label = mir_block_label_before(predecessor);
                for (successor = 0;
                     successor < mir.insns[predecessor].successor_count;
                     ++successor) {
                    int target = mir_first_phi_or_block_end(
                        mir.insns[predecessor].successors[successor]);
                    if (target != phi_start)
                        continue;
                    if (predecessor_label == mir.insns[i].phi_pred1 &&
                        last[mir.insns[i].src1] < predecessor)
                        last[mir.insns[i].src1] = predecessor;
                    if (predecessor_label == mir.insns[i].phi_pred2 &&
                        last[mir.insns[i].src2] < predecessor)
                        last[mir.insns[i].src2] = predecessor;
                }
            }
        }
    for (i = 0; i < mir.count; ++i)
        if (mir.insns[i].opcode == MIR_JUMP) {
            int target = mir_find_label(mir.insns[i].label);
            if (target >= 0 && target < i)
                for (value = 0; value < mir.next_value; ++value)
                    if (first[value] < target && last[value] >= target &&
                        last[value] < i)
                        last[value] = i;
        }
    /* mir-migration-plan-next10 (param-direct follow-up): a fused
     * divmod pair (mir_divmod_partner, emission ~9000) writes BOTH the
     * modulo and division result values eagerly at whichever of the two
     * MIR_BINARY instructions is encountered first in program order, not
     * at each result's own defining instruction - the second instruction
     * only "break"s without emitting anything, trusting the earlier
     * store. first[]/last[] computed above only account for each value's
     * own instruction index, so a result written early this way was
     * still reported as first-live only at its own (later) instruction,
     * understating its true live range by the gap between the two
     * instructions. Any other value's slot reused across exactly that
     * gap can then alias and clobber the early-written result before its
     * real use - a latent hazard nothing forced into the open until the
     * parameter-rehoming change (below) perturbed slot numbering enough
     * for two such values to collide (surfaced as tmuldiv's ui16_test
     * modulo/division mixups). Extend both partners' first[] to the
     * earlier instruction so slot reuse across that gap is impossible. */
    for (i = 0; i < mir.count; ++i) {
        const struct MirInsn *insn = &mir.insns[i];
        int partner;
        if (insn->opcode != MIR_BINARY ||
            (insn->immediate != '/' && insn->immediate != '%'))
            continue;
        partner = mir_divmod_partner(i);
        if (partner > i) {
            if (first[insn->dst] > i)
                first[insn->dst] = i;
            if (first[mir.insns[partner].dst] > i)
                first[mir.insns[partner].dst] = i;
        }
    }
    /* Item T51 (mir-text-size-plan.md): mir_binary_only_constant and
     * mir_index_only_constant already make the MIR_CONST case (above,
     * where the value is defined) and the MIR_BINARY/MIR_INDEX_ADDRESS
     * consumer sites (below, in the emitter) both emit zero code for a
     * constant whose sole use qualifies - the definition site skips its
     * own "ld hl,<const>"/store entirely, and the consumer materializes
     * the constant directly as an immediate (e.g. "ld de,<const>")
     * instead of ever calling mir_emit_virtual_load/mir_emit_virtual_store
     * for it. Despite this, mir_prepare_backend_slots never excluded
     * these two predicates from slot assignment - unlike the structurally
     * identical mir_call_only_constant (a sibling predicate for the
     * MIR_CALL-argument case, already excluded here) - so such a value
     * still got a live backend slot reserved for it: 2 bytes of dead
     * frame space nothing ever stores to or reads from. Found via
     * tests/t2darr.c's check() (`failures = failures + 1;`): the
     * constant 1's sole use is the ADD's right-hand operand, qualifying
     * for mir_binary_only_constant, yet a slot was still reserved. This
     * pattern recurs across the whole `check`/`chk`/`okb`/`fail`
     * assertion-helper family (50+ functions sharing the same shape) and
     * is the same class of dead-slot waste as the already-known,
     * narrower Item T33 (wumpus.c's rndix). */
    /* Batch 11 extends the same one-predicate discipline to two more
     * emission/reservation mismatches. Deferred metadata can leave values
     * defined by analysis-only MIR_NOP instructions, which emit no access,
     * and mir_address_is_single_call_argument makes both the MIR_ADDRESS
     * definition and its MIR_ARG consumer rematerialize without a slot.
     * Reuse those existing structural facts here rather than reserving
     * frame space that neither emission path can reference. */
    mir.backend_slot_count =
        mir_seed_promoted_local_slots(slot_end, slot_capacity);
    mir_backend_local_slot_count = mir.backend_slot_count;
    mir_backend_slot_pool_count = mir.backend_slot_count;
    mir_backend_frame_slot_count = 0;
    mir_slot_report_requested_count = 0;
    mir_slot_report_assigned_count = 0;
    mir_slot_report_param_assigned_count = 0;
    for (i = 0; i < mir.count; ++i) {
        if (planned_narrow_cache_call == i)
            planned_narrow_cache_call = -1;
        if (planned_wide_cache_call == i)
            planned_wide_cache_call = -1;
        for (value = 0; value < mir.next_value; ++value)
            if (first[value] == i) {
                int cache_target;
                int stack_consumer;
                int slot;
                const struct MirInsn *definition = mir_definition(value);
                int units = mir_definition_is_wide(definition) ? 2 : 1;
                int reusable_source = -1;
                int wide_phi_source = -1;
                int narrow_phi_source = -1;
                int phi_argument_call =
                    mir_phi_first_call_argument_target(value);
                int force_slot =
                    mir_value_requires_phi_slot(value) ||
                    mir_value_requires_divmod_slot(value) ||
                    mir_value_requires_odd_call_cleanup_slot(value);
                ++mir_slot_report_requested_count;
                if (fused_away[value] == 2)
                    continue;
                if (phi_argument_call >= 0) {
                    mir.backend_slots[value] =
                        MIR_BACKEND_SLOT_PHI_ARGUMENT_STACK;
                    continue;
                }
                if (units == 2 && definition != NULL &&
                    definition->opcode == MIR_BINARY &&
                    mir_binary_is_wide_phi_increment(
                        i, &wide_phi_source, NULL) &&
                    wide_phi_source >= 0 &&
                    mir.backend_slots[wide_phi_source] >= 0) {
                    int unit;

                    slot = mir.backend_slots[wide_phi_source];
                    mir.backend_slots[value] = slot;
                    for (unit = 0; unit < units; ++unit)
                        slot_end[slot + unit] = last[value];
                    continue;
                }
                if (units == 1 && definition != NULL &&
                    definition->opcode == MIR_BINARY &&
                    mir_binary_is_narrow_phi_adjust(
                        i, &narrow_phi_source, NULL) &&
                    narrow_phi_source >= 0 &&
                    mir.backend_slots[narrow_phi_source] >= 0) {
                    slot = mir.backend_slots[narrow_phi_source];
                    mir.backend_slots[value] = slot;
                    slot_end[slot] = last[value];
                    continue;
                }
                if (!force_slot &&
                    (last[value] <= first[value] ||
                                        (definition != NULL &&
                                         definition->opcode == MIR_NOP) ||
                                        mir_scalar_constant_is_rematerializable(
                                            value) ||
                                        mir_string_address_is_rematerializable(
                                            value) ||
                                        mir_wide_constant_is_rematerializable(
                                            value) ||
                                        mir_wide_constant_is_signed_relational_immediate(
                                            value) ||
                                        mir_value_is_wide_narrow_multiply_widen(
                                            value) ||
                                        mir_address_is_rematerializable(value) ||
                                        mir_call_only_constant(value) ||
                                        mir_binary_only_constant(value) ||
                                        mir_index_only_constant(value) ||
                                        mir_value_only_used_by_constant_absolute_address(value) ||
                                        mir_value_only_used_by_dynamic_absolute_index(value) ||
                                        mir_multiply_by_small_constant(value) ||
                                        fused_away[value] == 1 ||
                                        mir_value_is_selfstore_incdec(value) ||
                                        mir_value_is_selfstore_incdec_source(value) ||
                                        mir_value_only_used_by_selfstore_adjust_amount(
                                            value) ||
                                        mir_value_is_dense_byte_switch_condition(
                                            value) ||
                                        ((type_size(definition->type) == 2 ||
                                            type_size(definition->type) == 4) &&
                                         mir_load_is_single_call_argument(value,
                                                                                                            type_size(definition->type))) ||
                                        mir_value_only_used_by_stable_pointer_argument(
                                            value) ||
                                        (type_size(definition->type) == 2 &&
                                         mir_indirect_load_is_single_stable_pointer_call_argument(
                                             value, 2)) ||
                                        (type_size(definition->type) == 2 &&
                                         mir_global_load_is_single_call_argument(
                                             value, 2)) ||
                                        (type_size(definition->type) == 2 &&
                                         mir_load_is_single_indirect_call_target(value, 2)) ||
                                        mir_address_is_single_call_argument(value) ||
                                        mir_backend_slot_forwardable(value, units, i) ||
                                        mir_wide_backend_slot_forwardable(value, units, i) ||
                                        mir_wide_signed_const_lhs_slot_forwardable(
                                            value, units, i) ||
                                        mir_wide_helper_lhs_slot_forwardable(value, units, i) ||
                                        mir_call_argument_slot_forwardable(value, units, i) ||
                                        mir_stack_backend_slot_forwardable(value, units, i) ||
                                        mir_value_is_nested_truth_comparison_input(value) ||
                                        mir_value_only_used_by_dead_stores(value) ||
                                        mir_value_only_used_by_dead_unary(value)))
                    continue;
                if (!force_slot &&
                    mir_value_has_direct_named_home(value)) {
                    int home_storage;
                    int home_offset;
                    if (mir_direct_named_home_location(
                            definition, &home_storage, &home_offset) &&
                        home_storage == SC_LOCAL) {
                        mir_spilled_cfg_used_stable_pointer_local_home = 1;
                        mir_spilled_cfg_used_stable_pointer_local_slot = 1;
                    }
                    continue;
                }
                stack_consumer = force_slot ? -1 :
                    mir_planned_stack_consumer(
                        value, i, stack_interval_occupied);
                if (stack_consumer >= 0) {
                    int instruction;

                    mir.planned_stack_consumers[value] = stack_consumer;
                    mir.planned_stack_values[stack_consumer] = value;
                    for (instruction = i;
                         instruction <= stack_consumer; ++instruction)
                        stack_interval_occupied[instruction] = 1;
                    continue;
                }
                /*
                 * The emitters can retain one pending call argument in BC
                 * or the alternate register set instead of touching its
                 * assigned slot. Plan that choice in the same definition
                 * order as emission so cache occupancy is exact. A
                 * cacheable definition-to-call span
                 * permits no other value-producing instruction, so narrow
                 * and wide cache lifetimes cannot overlap.
                 */
                cache_target = force_slot ? -1 :
                    mir_call_argument_cache_target_for_state(
                        value, i, planned_narrow_cache_call >= 0,
                        planned_wide_cache_call >= 0);
                if (cache_target >= 0) {
                    if (units == 2 &&
                        mir_wide_call_argument_is_first_pushed(
                            value, cache_target))
                        mir.backend_slots[value] =
                            MIR_BACKEND_SLOT_WIDE_ARGUMENT_STACK_CACHE;
                    else if (units == 1 &&
                             mir_narrow_argument_direct_push_enabled)
                        mir.backend_slots[value] =
                            MIR_BACKEND_SLOT_NARROW_ARGUMENT_DIRECT_PUSH;
                    else
                        mir.backend_slots[value] =
                            MIR_BACKEND_SLOT_CALL_CACHE;
                    if (units == 2)
                        planned_wide_cache_call = cache_target;
                    else
                        planned_narrow_cache_call = cache_target;
                    continue;
                }
                ++mir_slot_report_assigned_count;
                if (definition != NULL && definition->opcode == MIR_PARAM)
                    ++mir_slot_report_param_assigned_count;
                if (definition != NULL && definition->opcode == MIR_BINARY &&
                    ((units == 1 && type_size(definition->secondary_offset) == 2) ||
                     (units == 2 && type_size(definition->secondary_offset) == 4) ||
                     (units == 1 && type_size(definition->secondary_offset) == 4))) {
                    /* A narrow (16-bit) boolean result from a wide (32-bit)
                     * comparison still has two dying 32-bit operand units
                     * available; match reuse against the operand width, not
                     * the (narrower) result width, and take only the first
                     * unit of a wide operand's slot for the result. */
                    int operand_units =
                        type_size(definition->secondary_offset) == 4 ? 2 : 1;
                    if (definition->src1 >= 0 && last[definition->src1] == i &&
                        mir.backend_slots[definition->src1] >= 0 &&
                        (mir_definition_is_wide(mir_definition(
                             definition->src1)) ? 2 : 1) == operand_units)
                        reusable_source = definition->src1;
                    else if (definition->src2 >= 0 && last[definition->src2] == i &&
                             mir.backend_slots[definition->src2] >= 0 &&
                             (mir_definition_is_wide(mir_definition(
                                  definition->src2)) ? 2 : 1) == operand_units)
                        reusable_source = definition->src2;
                } else if (definition != NULL && definition->opcode == MIR_UNARY &&
                    definition->src1 >= 0 &&
                    (mir_definition_is_wide(mir_definition(
                         definition->src1)) ? 2 : 1) == units &&
                    last[definition->src1] == i &&
                    mir.backend_slots[definition->src1] >= 0) {
                    reusable_source = definition->src1;
                }
                if (reusable_source >= 0) {
                    int unit;
                    slot = mir.backend_slots[reusable_source];
                    mir.backend_slots[value] = slot;
                    if (slot < mir_backend_local_slot_count)
                        mir_spilled_cfg_used_promoted_local_slot = 1;
                    for (unit = 0; unit < units; ++unit)
                        slot_end[slot + unit] = last[value];
                    continue;
                }
                for (slot = 0; slot + units <= mir.backend_slot_count; ++slot) {
                    int unit;
                    int available = 1;
                    if (units == 2 &&
                        mir_backend_slot_offsets[slot + 1] !=
                            mir_backend_slot_offsets[slot] - 2)
                        continue;
                    for (unit = 0; unit < units; ++unit)
                        if (slot_end[slot + unit] >= i) {
                            available = 0;
                            break;
                        }
                    if (available)
                        break;
                }
                if (slot + units > mir.backend_slot_count) {
                    int unit;
                    slot = mir.backend_slot_count;
                    for (unit = 0; unit < units; ++unit)
                        mir_backend_slot_offsets[slot + unit] =
                            -mir_effective_local_bytes() -
                            mir.aggregate_temp_bytes -
                            2 * (mir_backend_frame_slot_count + unit + 1);
                    mir.backend_slot_count += units;
                    mir_backend_frame_slot_count += units;
                    mir_backend_slot_pool_count = mir.backend_slot_count;
                }
                mir.backend_slots[value] = slot;
                if (slot < mir_backend_local_slot_count)
                    mir_spilled_cfg_used_promoted_local_slot = 1;
                {
                    int unit;
                    for (unit = 0; unit < units; ++unit)
                        slot_end[slot + unit] = last[value];
                }
            }
    }
    mir_verify_planned_stack_handoffs();
    if (getenv("DCC_MIR_WIDE_HELPER_REPORT") != NULL)
        for (value = 0; value < mir.next_value; ++value) {
            const struct MirInsn *definition = mir_definition(value);
            int definition_index;
            int consumer;
            const char *helper;

            if (definition == NULL)
                continue;
            definition_index = (int)(definition - mir.insns);
            if (!mir_wide_helper_lhs_consumer(
                    value, definition_index, &consumer))
                continue;
            helper = mir_wide_runtime_helper(&mir.insns[consumer]);
            fprintf(stderr,
                    "; MIR wide-helper function=%s value=%d producer=%s "
                    "consumer=%d helper=%s distance=%d safe=%d "
                    "handoff=%d slot=%d slots=%d\n",
                    mir.name, value, mir_opcode_name(definition->opcode),
                    consumer, helper != NULL ? helper : "none",
                    consumer - definition_index,
                    mir_wide_helper_lhs_span_is_safe(
                        definition_index, consumer),
                    mir_wide_helper_handoff_supported(
                        &mir.insns[consumer]),
                    mir.backend_slots[value], mir.backend_slot_count);
        }
    if (getenv("DCC_MIR_BACKEND_SLOT_REPORT") != NULL)
        for (value = 0; value < mir.next_value; ++value)
            if (mir.backend_slots[value] >= mir_backend_local_slot_count) {
                const struct MirInsn *definition = mir_definition(value);

                fprintf(stderr,
                        "; MIR backend-slot function=%s value=%d opcode=%s "
                        "type=%d first=%d last=%d slot=%d uses=%d\n",
                        mir.name, value,
                        definition != NULL
                            ? mir_opcode_name(definition->opcode) : "none",
                        definition != NULL ? definition->type : 0,
                        first[value], last[value], mir.backend_slots[value],
                        mir_value_use_count(value));
            }
    free(fused_away);
    free(stack_interval_occupied);
    free(slot_end);
    free(last);
    free(first);
    if (getenv("DCC_MIR_SLOT_REPORT") != NULL &&
        mir_slot_report_requested_count > 0)
        fprintf(stderr,
                "; MIR slot-report function=%s requested=%d assigned=%d "
                "param_assigned=%d\n",
                mir.name, mir_slot_report_requested_count,
                mir_slot_report_assigned_count,
                mir_slot_report_param_assigned_count);
    return mir_backend_frame_slot_count;
}

void mir_emit_virtual_load(FILE *out, int value)
{
    const struct MirInsn *definition = mir_definition(value);
    int offset;
    int iy_offset;
    if (mir_forwarded_hl_value == value &&
        mir_forwarded_hl_instruction + 1 == mir_emit_instruction_index) {
        /* This check must precede the param-direct branch below: the
         * register-forwarding optimization elides the reload entirely
         * when the value is already resident in HL from the immediately
         * preceding instruction, regardless of whether this value is
         * slot-based or param-direct. Skipping it here regressed
         * tvla's vla_sizeof_c99_type_bytes (a param read many times in
         * a loop) by re-emitting a full ix-relative reload on every use
         * instead of reusing HL when available. */
        mir_forwarded_hl_value = -1;
        mir_forwarded_hl_instruction = -1;
        return;
    }
    if (mir_scalar_constant_is_rematerializable(value)) {
        fprintf(out, "\tld hl,%ld\n", definition->immediate & 0xffffL);
        return;
    }
    if (mir_string_address_is_rematerializable(value)) {
        fprintf(out, "\tld hl,S%ld\n", definition->immediate);
        return;
    }
    if (mir_address_is_rematerializable(value)) {
        if (!mir_emit_address_value_to_hl(out, value))
            fatal("cannot rematerialize MIR address");
        return;
    }
    if (mir_value_has_direct_named_home(value)) {
        /* Read straight from the value's stable named IX-relative home instead
         * of a duplicated backend slot. Mirrors exactly the
         * in-range/out-of-range forms the original MIR_PARAM binding site
         * uses for a narrow scalar, including the IY-relative fast path
         * hot loops rely on (skipping it caused a measurable, if tiny,
         * cycle regression in tsnprtf's call_vsnprintf). */
        const struct MirInsn *definition = mir_definition(value);
        int value_type = definition->type;
        int value_size = type_size(value_type);
        int object_offset;
        int object_storage;
        int object_iy_offset;
        if (!mir_direct_named_home_location(
                definition, &object_storage, &object_offset))
            fatal("missing direct MIR named-home offset");
        object_iy_offset = object_offset + mir_effective_local_bytes() +
                           mir.aggregate_temp_bytes;
        if (mir_virtual_iy_base && object_iy_offset >= -128 &&
            object_iy_offset + value_size - 1 <= 127) {
            fprintf(out, "\tld l,(iy%+d)\n", object_iy_offset);
            if (value_size == 2)
                fprintf(out, "\tld h,(iy%+d)\n", object_iy_offset + 1);
        } else if (object_offset >= -128 &&
                   object_offset + value_size - 1 <= 127) {
            fprintf(out, "\tld l,(ix%+d)\n", object_offset);
            if (value_size == 2)
                fprintf(out, "\tld h,(ix%+d)\n", object_offset + 1);
        } else {
            fputs("\tpush ix\n\tpop hl\n", out);
            fprintf(out, "\tld de,%d\n\tadd hl,de\n\tld a,(hl)\n",
                    object_offset);
            if (value_size == 2)
                fputs("\tinc hl\n\tld h,(hl)\n\tld l,a\n", out);
            else
                fputs("\tld l,a\n", out);
        }
        if (value_size == 1) {
            if (type_is_bool(value_type)) {
                int bool_label = new_label();
                fputs("\tld a,l\n\tor a\n\tld hl,0\n", out);
                fprintf(out, "\tjp z, L%d\n\tinc hl\nL%d:\n",
                        bool_label, bool_label);
            } else if ((value_type & TYPE_UNSIGNED) != 0) {
                fputs("\tld h,0\n", out);
            } else {
                mir_emit_signed_byte_extend(out);
            }
        }
        return;
    }
    offset = mir_virtual_offset(value);
    iy_offset = mir_virtual_iy_offset(value);
    if (mir_virtual_iy_base && iy_offset >= -128 && iy_offset + 1 <= 127) {
        fprintf(out, "\tld l,(iy%+d)\n\tld h,(iy%+d)\n",
                iy_offset, iy_offset + 1);
        return;
    }
    if (offset >= -128 && offset + 1 <= 127) {
        fprintf(out, "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
                offset, offset + 1);
    } else {
        fputs("\tpush ix\n\tpop hl\n", out);
        fprintf(out, "\tld de,%d\n\tadd hl,de\n"
                     "\tld a,(hl)\n\tinc hl\n\tld h,(hl)\n\tld l,a\n",
                offset);
    }
}

/* Item T15 (mir-text-size-plan.md): a value's definition immediately
 * followed by a MIR_CONST that itself feeds the very next MIR_BINARY as
 * that binary's right-hand operand (value; const; binary(value, const))
 * currently loses mir_can_forward_hl_to_next's forwarding entirely,
 * because the CONST sits between the value's definition and its one real
 * use - mir_can_forward_hl_to_next only recognizes a handful of consumer
 * opcodes as the literal next instruction, and MIR_CONST isn't one of
 * them, so the value is unconditionally stored to its backend slot and
 * immediately reloaded one "logical" instruction later even though
 * nothing between the store and reload could have clobbered it (a
 * MIR_CONST used only as an immediate operand emits no code of its own
 * at that point - see mir_binary_only_constant's callers below). This
 * mirrors mir_can_forward_stack_to_index's existing const-in-the-middle
 * shape (push the value, let the consumer pop it back after evaluating
 * the constant) but for a binary operator's constant right-hand operand
 * instead of an array index's constant stride.
 *
 * Deliberately excludes any shape that takes a different code path for
 * the constant: divmod pairing and the multiply-by-constant fast path
 * bypass the plain "push left, evaluate right, pop, combine" sequence
 * this optimization targets, so forwarding across them is out of scope
 * here (a separate item, not folded in).
 *
 * Item T17 (mir-text-size-plan.md): originally also excluded fused-
 * comparison branches, on the assumption they took a different code
 * path entirely - investigation showed mir_emit_fused_comparison_branch
 * only consumes HL/DE however they got there (the src1/src2-loading
 * code above, including this forwarding mechanism, is shared with the
 * fused-comparison case; only the final action after loading - branch
 * directly vs. materialize+store - differs). The exclusion is removed:
 * a fusable comparison's left operand can be forwarded exactly the same
 * as any other binary operator's. */
static int mir_can_forward_stack_to_binary_const(int value)
{
    const struct MirInsn *middle;
    const struct MirInsn *binary;
    int binary_instruction;
    int instruction;

    if (mir_emit_instruction_index < 0 ||
        mir_emit_instruction_index + 2 >= mir.count)
        return 0;
    middle = &mir.insns[mir_emit_instruction_index + 1];
    binary_instruction = mir_emit_instruction_index + 2;
    binary = &mir.insns[binary_instruction];
    if (middle->opcode != MIR_CONST || binary->opcode != MIR_BINARY ||
        binary->src1 != value || binary->src2 != middle->dst)
        return 0;
    if (type_size(binary->secondary_offset) == 4)
        return 0;
    if (mir_divmod_partner(binary_instruction) >= 0)
        return 0;
    if (binary->immediate == '*' &&
        mir_mul_const_fast_path_eligible(
            (unsigned long)middle->immediate & 0xffffUL, binary->dst))
        return 0;
    /* Item T17 (mir-text-size-plan.md): a fusable comparison whose
     * constant right-hand operand is exactly 0 takes the Item 25/27
     * shortcut, which skips materializing DE (and, critically, skips
     * the pop that would otherwise retrieve this forwarded value) -
     * forwarding here would leave an unbalanced push on the stack.
     * Every other fusable comparison (non-zero-RHS) goes through the
     * ordinary const-materialize-to-DE path below, which does perform
     * the pop, so only this specific pair of shapes needs excluding. */
    if (mir_binary_is_fusable_comparison(binary_instruction) > 0 &&
        (mir_fused_compare_is_const_zero_rhs(binary_instruction) ||
         mir_fused_compare_is_signed_zero_sign_test(binary_instruction)))
        return 0;
    for (instruction = binary_instruction + 1;
         instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];
        if (insn->src1 == value || insn->src2 == value)
            return 0;
        if ((insn->opcode == MIR_CALL ||
             insn->opcode == MIR_CALL_AGGREGATE) &&
            mir_call_uses_value(insn, value))
            return 0;
    }
    return 1;
}

static int mir_can_forward_stack_to_binary_lhs(int value)
{
    const struct MirInsn *middle;
    const struct MirInsn *binary;
    int binary_instruction;

    if (!mir_general_rhs_stack_forwarding_enabled ||
        mir_emit_instruction_index < 0 ||
        mir_emit_instruction_index + 2 >= mir.count ||
        mir_value_use_count(value) != 1)
        return 0;
    middle = &mir.insns[mir_emit_instruction_index + 1];
    binary_instruction = mir_emit_instruction_index + 2;
    binary = &mir.insns[binary_instruction];
    if ((middle->opcode != MIR_LOAD && middle->opcode != MIR_PARAM) ||
        type_size(middle->type) > 2 ||
        binary->opcode != MIR_BINARY || binary->src1 != value ||
        binary->src2 != middle->dst ||
        type_size(binary->secondary_offset) == 4 ||
        mir_value_use_count(middle->dst) != 1 ||
        mir_divmod_partner(binary_instruction) >= 0)
        return 0;
    mir_spilled_cfg_used_binary_load_pair_forwarding = 1;
    return 1;
}

/* Item T16 (mir-text-size-plan.md): mir_can_forward_hl_to_next's
 * MIR_BINARY case only ever matches `value` against the binary's src1
 * (left operand) - a value that is instead the very next MIR_BINARY's
* *right*-hand operand (src2) gets no forwarding at all. Push the value
* immediately after computing it and let the binary's emission pop it
* into DE after loading the left operand.
*
* T203 generalizes the original constant-left implementation to any
* single-use narrow right operand. Loading src1 is stack-balanced, so it
* cannot disturb the pending right value. If src1 is itself a planned
* stack handoff, the right value is newer and is popped first, followed by
* the planned left value. The fix is symmetric to
* mir_can_forward_stack_to_index/_binary_const above. It remains
* restricted to the immediately-following instruction only (no intervening
* MIR_CONST skip - that shape is a distinct, not yet needed case) and
* excludes divmod pairing, which uses a different code path entirely.
 *
 * Item T17 (mir-text-size-plan.md): like
 * mir_can_forward_stack_to_binary_const above, this originally also
 * excluded fused-comparison branches - removed for the same reason:
 * mir_emit_fused_comparison_branch only consumes whatever HL/DE already
 * hold, regardless of how they got there. */
static int mir_can_forward_stack_to_binary_rhs(int value)
{
    const struct MirInsn *binary;
    int binary_instruction;
    int instruction;

    if (mir_emit_instruction_index < 0 ||
        mir_emit_instruction_index + 1 >= mir.count)
        return 0;
    binary_instruction = mir_emit_instruction_index + 1;
    binary = &mir.insns[binary_instruction];
    if (binary->opcode != MIR_BINARY || binary->src2 != value)
        return 0;
    if (type_size(binary->secondary_offset) == 4)
        return 0;
    if (mir_value_use_count(value) != 1)
        return 0;
    if (!mir_binary_only_constant(binary->src1) &&
        !mir_general_rhs_stack_forwarding_enabled)
        return 0;
    if (mir_divmod_partner(binary_instruction) >= 0)
        return 0;
    /* Defensive: mirrors the same Item T17 zero-RHS guard as
     * mir_can_forward_stack_to_binary_const above. src2 (the forwarded
     * value here) is not expected to itself be a plain constant in
     * practice, but if it ever were, the Item 25/27 shortcuts would
     * skip the pop this predicate promises the caller will perform. */
    if (mir_binary_is_fusable_comparison(binary_instruction) > 0 &&
        (mir_fused_compare_is_const_zero_rhs(binary_instruction) ||
         mir_fused_compare_is_signed_zero_sign_test(binary_instruction)))
        return 0;
    for (instruction = binary_instruction + 1;
         instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];
        if (insn->src1 == value || insn->src2 == value)
            return 0;
        if ((insn->opcode == MIR_CALL ||
             insn->opcode == MIR_CALL_AGGREGATE) &&
            mir_call_uses_value(insn, value))
            return 0;
    }
    return 1;
}

static int mir_can_forward_stack_to_indirect_store_value(int value)
{
    const struct MirInsn *store;

    if (!mir_indirect_store_value_forwarding_enabled ||
        mir_emit_instruction_index < 0 ||
        mir_emit_instruction_index + 1 >= mir.count ||
        mir_value_use_count(value) != 1)
        return 0;
    store = &mir.insns[mir_emit_instruction_index + 1];
    return store->opcode == MIR_STORE_INDIRECT &&
           store->src2 == value && store->bit_width == 0 &&
           store->memory_size > 0 && store->memory_size <= 2 &&
           !mir_constant_absolute_access_supported(store);
}

static int mir_stack_forward_target(int value, int *dynamic_index)
{
    int target;

    if (dynamic_index != NULL)
        *dynamic_index = 0;
    if (mir_emit_instruction_index >= 0 &&
        mir_emit_instruction_index < mir.count &&
        mir.insns[mir_emit_instruction_index].opcode == MIR_PHI)
        return -1;
    target = mir_dynamic_index_base_forward_target(value);
    if (target >= 0) {
        if (dynamic_index != NULL)
            *dynamic_index = 1;
        return target;
    }
    target = mir_stack_index_forward_target(value);
    if (target >= 0)
        return target;
    if (mir_can_forward_stack_to_indirect_store_value(value))
        return mir_emit_instruction_index + 1;
    if (mir_can_forward_stack_to_binary_lhs(value))
        return mir_emit_instruction_index + 2;
    if (mir_can_forward_stack_to_binary_const(value))
        return mir_emit_instruction_index + 2;
    if (mir_can_forward_stack_to_binary_rhs(value))
        return mir_emit_instruction_index + 1;
    return -1;
}

static int mir_stack_backend_slot_forwardable(
    int value, int units, int instruction)
{
    int saved_index;
    int forwardable;

    if (units != 1)
        return 0;
    saved_index = mir_emit_instruction_index;
    mir_emit_instruction_index = instruction;
    forwardable = mir_stack_forward_target(value, NULL) >= 0;
    mir_emit_instruction_index = saved_index;
    return forwardable;
}

static int mir_planned_stack_target(int value)
{
    if (value < 0 || value >= mir.next_value ||
        mir.planned_stack_consumers == NULL)
        return -1;
    return mir.planned_stack_consumers[value];
}

static int mir_planned_stack_matches_consumer(int value, int instruction)
{
    return mir_planned_stack_target(value) == instruction &&
           instruction >= 0 && instruction < mir.count &&
           mir.planned_stack_values != NULL &&
           mir.planned_stack_values[instruction] == value;
}

static int mir_planned_stack_is_emitted(int value)
{
    return value >= 0 && value < mir.next_value &&
           mir.planned_stack_emitted != NULL &&
           mir.planned_stack_emitted[value] != 0;
}

static int mir_pending_planned_stack_consumer(void)
{
    int value;

    for (value = 0; value < mir.next_value; ++value)
        if (mir_planned_stack_is_emitted(value))
            return mir_planned_stack_target(value);
    return -1;
}

static int mir_stack_forward_nests_with_planned_left(
    int value, int consumer)
{
    const struct MirInsn *insn;

    if (consumer < 0 || consumer >= mir.count)
        return 0;
    insn = &mir.insns[consumer];
    if (!mir_planned_stack_matches_consumer(insn->src1, consumer))
        return 0;
    return mir_is_general_rhs_stack_forward(value, consumer) ||
           mir_is_indirect_store_value_stack_forward(value, consumer);
}

static int mir_value_currently_uses_stack_handoff(
    int value, int instruction)
{
    return (mir_planned_stack_matches_consumer(value, instruction) &&
            mir_planned_stack_is_emitted(value)) ||
           (mir_forwarded_stack_value == value &&
            mir_forwarded_stack_target_instruction == instruction);
}

static int mir_consume_planned_stack(FILE *out, int value, int instruction,
                                     const char *destination)
{
    if (!mir_planned_stack_matches_consumer(value, instruction) ||
        !mir_planned_stack_is_emitted(value))
        return 0;
    fprintf(out, "\tpop %s\n", destination);
    mir.planned_stack_emitted[value] = 0;
    ++mir_planned_stack_consume_count;
    return 1;
}

static void mir_emit_virtual_store(FILE *out, int value)
{
    const struct MirInsn *definition = mir_definition(value);
    int force_slot_store = definition != NULL &&
                           definition->opcode == MIR_PHI;
    int dynamic_index_forward;
    int direct_reload_storeind_target;
    int forward_to_store;
    int has_slot;
    int forward_instruction;
    int offset;
    int iy_offset;
    int pending_planned_consumer;
    if (mir_value_requires_phi_slot(value))
        force_slot_store = 1;
    if (mir_value_has_direct_named_home(value))
        /* Nothing to store: later uses re-read the stable named home (see
         * mir_emit_virtual_load); the loaded HL is simply not persisted. */
        return;
    if (value == mir_prepacked_result_value) {
        fputs("\tpush hl\n", out);
        return;
    }
    if (value >= 0 && value < mir.next_value &&
        mir.backend_slots != NULL &&
        (mir.backend_slots[value] == MIR_BACKEND_SLOT_CALL_CACHE ||
         mir.backend_slots[value] ==
             MIR_BACKEND_SLOT_NARROW_ARGUMENT_DIRECT_PUSH)) {
        int call_instruction =
            mir_planned_call_argument_cache_target(value, 0);
        fputs("\tld c,l\n\tld b,h\n", out);
        mir_cached_call_value = value;
        mir_cached_call_instruction = call_instruction;
        return;
    }
    direct_reload_storeind_target =
        mir_call_result_direct_reload_indirect_store_target(value);
    if (!force_slot_store &&
        direct_reload_storeind_target >= 0) {
        mir_forwarded_hl_value = value;
        mir_forwarded_hl_instruction = direct_reload_storeind_target - 1;
        return;
    }
    forward_instruction = mir_planned_stack_target(value);
    if (!force_slot_store && forward_instruction >= 0) {
        if (mir_forwarded_stack_value >= 0 &&
            mir_forwarded_stack_target_instruction <
                mir_emit_instruction_index) {
            mir_forwarded_stack_value = -1;
            mir_forwarded_stack_instruction = -1;
            mir_forwarded_stack_target_instruction = -1;
        }
        if (mir_forwarded_stack_value >= 0) {
            if (getenv("DCC_MIR_SELECT_REPORT") != NULL)
                fprintf(stderr,
                        "; MIR planned-stack overlap function=%s "
                        "existing-value=%d existing-consumer=%d "
                        "value=%d producer=%d consumer=%d\n",
                        mir.name, mir_forwarded_stack_value,
                        mir_forwarded_stack_target_instruction,
                        value, mir_emit_instruction_index,
                        forward_instruction);
            mir_planned_stack_invalid = 1;
        }
        if (mir_forwarded_wide_stack_value >= 0 &&
            forward_instruction >= mir_forwarded_wide_stack_consumer)
            mir_planned_stack_invalid = 1;
        fputs("\tpush hl\n", out);
        mir_spilled_cfg_used_planned_stack_handoff = 1;
        if (mir.insns[forward_instruction].opcode == MIR_INDEX_ADDRESS)
            mir_spilled_cfg_used_planned_index_base_handoff = 1;
        mir.planned_stack_emitted[value] = 1;
        ++mir_planned_stack_emit_count;
        return;
    }
    has_slot = value >= 0 && value < mir.next_value &&
                   mir.backend_slots != NULL && mir.backend_slots[value] >= 0;
    forward_instruction = mir_forward_skip_target(mir_emit_instruction_index);
    if (!has_slot) {
        /* Item 13 (mir-migration-plan-100): mir_prepare_backend_slots skips
         * allocating a slot for a value it already proved via
         * mir_backend_slot_forwardable() can only ever be consumed through
         * this same HL-forwarding path (never stored to memory) - still set
         * up the forwarding handoff so the immediately-following use skips
         * its own reload; anything else with no slot is genuinely dead. */
        if (!force_slot_store && mir_can_forward_hl_to_next(value)) {
            mir_forwarded_hl_value = value;
            mir_forwarded_hl_instruction = forward_instruction - 1;
            if (mir_is_branch_condition_forward(value, forward_instruction))
                ++mir_spilled_cfg_branch_condition_forwarding_count;
        } else if (!force_slot_store &&
                   mir_can_forward_hl_to_call_argument(value)) {
            /* Item T59 (mir-text-size-plan.md): mir_prepare_backend_slots'
             * reservation pass now also skips allocating a slot for values
             * mir_can_forward_hl_to_call_argument alone proves (the
             * has_slot branch below already relied on this same predicate
             * to avoid ever *writing* to an already-reserved slot; this
             * mirrors that for the no-slot case). Without this branch the
             * value has has_slot == 0, mir_can_forward_hl_to_next doesn't
             * recognize an ARG+CALL consumer, no forwarding handoff is
             * armed at all, and the later load falls through to reading
             * mir.backend_slots[value] - an address that was never
             * reserved for this value. Found via tests/tstrcmpi.c's main
             * (nested `sgn(stricmp(...))` calls) once mir_prepare_backend_
             * slots' own skip-list started recognizing this predicate. */
            mir_forwarded_hl_value = value;
            mir_forwarded_hl_instruction =
                mir_call_argument_after_nops(mir_emit_instruction_index);
        } else if (!force_slot_store &&
                   (forward_instruction =
                    mir_stack_forward_target(
                        value, &dynamic_index_forward)) >= 0) {
            pending_planned_consumer =
                mir_pending_planned_stack_consumer();
            if (pending_planned_consumer >= 0 &&
                forward_instruction >= pending_planned_consumer &&
                !mir_stack_forward_nests_with_planned_left(
                    value, forward_instruction))
                mir_planned_stack_invalid = 1;
            fputs("\tpush hl\n", out);
            mir_forwarded_stack_value = value;
            mir_forwarded_stack_instruction = mir_emit_instruction_index;
            mir_forwarded_stack_target_instruction = forward_instruction;
            if (mir_is_general_rhs_stack_forward(value, forward_instruction))
                mir_spilled_cfg_used_general_rhs_stack_forwarding = 1;
            if (mir_is_indirect_store_value_stack_forward(
                    value, forward_instruction))
                ++mir_spilled_cfg_indirect_store_value_forwarding_count;
            if (dynamic_index_forward)
                mir_spilled_cfg_used_dynamic_index_base_forwarding = 1;
        }
        return;
    }
    forward_to_store = !force_slot_store &&
        mir_can_forward_hl_to_next(value) &&
        forward_instruction < mir.count &&
        mir.insns[forward_instruction].opcode == MIR_STORE;
    if (!force_slot_store &&
        !forward_to_store && mir_can_forward_hl_to_next(value)) {
        mir_forwarded_hl_value = value;
        mir_forwarded_hl_instruction = forward_instruction - 1;
        if (mir_is_branch_condition_forward(value, forward_instruction))
            ++mir_spilled_cfg_branch_condition_forwarding_count;
        return;
    }
    if (!force_slot_store &&
        mir_can_forward_hl_to_call_argument(value)) {
        mir_forwarded_hl_value = value;
        mir_forwarded_hl_instruction =
            mir_call_argument_after_nops(mir_emit_instruction_index);
        return;
    }
    if (!force_slot_store &&
        (forward_instruction = mir_stack_forward_target(
             value, &dynamic_index_forward)) >= 0) {
        pending_planned_consumer = mir_pending_planned_stack_consumer();
        if (pending_planned_consumer >= 0 &&
            forward_instruction >= pending_planned_consumer &&
            !mir_stack_forward_nests_with_planned_left(
                value, forward_instruction))
            mir_planned_stack_invalid = 1;
        fputs("\tpush hl\n", out);
        mir_forwarded_stack_value = value;
        mir_forwarded_stack_instruction = mir_emit_instruction_index;
        mir_forwarded_stack_target_instruction = forward_instruction;
        if (mir_is_general_rhs_stack_forward(value, forward_instruction))
            mir_spilled_cfg_used_general_rhs_stack_forwarding = 1;
        if (mir_is_indirect_store_value_stack_forward(
                value, forward_instruction))
            ++mir_spilled_cfg_indirect_store_value_forwarding_count;
        if (dynamic_index_forward)
            mir_spilled_cfg_used_dynamic_index_base_forwarding = 1;
        return;
    }
    if (!force_slot_store) {
        int call_instruction = mir_call_argument_cache_target(value);
        if (call_instruction >= 0) {
            fputs("\tld c,l\n\tld b,h\n", out);
            mir_cached_call_value = value;
            mir_cached_call_instruction = call_instruction;
            return;
        }
    }
    offset = mir_virtual_offset(value);
    iy_offset = mir_virtual_iy_offset(value);
    mir_forwarded_hl_value = -1;
    mir_forwarded_hl_instruction = -1;
    {
    int forward_to_narrow_store = forward_to_store &&
        mir_forward_store_target_is_narrow(forward_instruction);
    if (mir_virtual_iy_base && iy_offset >= -128 && iy_offset + 1 <= 127) {
        fprintf(out, "\tld (iy%+d),l\n", iy_offset);
        if (!forward_to_narrow_store)
            fprintf(out, "\tld (iy%+d),h\n", iy_offset + 1);
        if (forward_to_store) {
            mir_forwarded_hl_value = value;
            mir_forwarded_hl_instruction = forward_instruction - 1;
        } else if (mir_can_forward_hl_to_call_argument_first_use(value)) {
            mir_forwarded_hl_value = value;
            mir_forwarded_hl_instruction =
                mir_call_argument_after_nops(mir_emit_instruction_index);
        }
        return;
    }
    if (offset >= -128 && offset + 1 <= 127) {
        fprintf(out, "\tld (ix%+d),l\n", offset);
        if (!forward_to_narrow_store)
            fprintf(out, "\tld (ix%+d),h\n", offset + 1);
        if (forward_to_store) {
            mir_forwarded_hl_value = value;
            mir_forwarded_hl_instruction = forward_instruction - 1;
        } else if (mir_can_forward_hl_to_call_argument_first_use(value)) {
            /* Item T82 (mir-text-size-plan.md): safe only for this
             * in-range form - the out-of-range branch below moves the
             * value out of HL (into DE via `ex de,hl`) to compute the
             * store address, so HL no longer holds it afterward. */
            mir_forwarded_hl_value = value;
            mir_forwarded_hl_instruction =
                mir_call_argument_after_nops(mir_emit_instruction_index);
        }
    } else {
        fputs("\tex de,hl\n\tpush ix\n\tpop hl\n", out);
        fprintf(out, "\tld bc,%d\n\tadd hl,bc\n"
                     "\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
                offset);
        if (forward_to_store) {
            mir_forwarded_hl_value = value;
            mir_forwarded_hl_instruction = forward_instruction - 1;
        }
    }
    }
}

int mir_value_is_wide(int value)
{
    return mir_definition_is_wide(mir_definition(value));
}

static int mir_wide_constant_uses_new_rematerialization(int value)
{
    const struct MirInsn *definition = mir_definition(value);
    int instruction = definition != NULL
        ? (int)(definition - mir.insns) : -1;

    return mir_wide_constant_is_rematerializable(value) &&
           !mir_call_only_constant(value) &&
           !mir_binary_only_constant(value) &&
           !mir_index_only_constant(value) &&
           !mir_backend_slot_forwardable(value, 2, instruction) &&
           !mir_wide_backend_slot_forwardable(value, 2, instruction) &&
           !mir_wide_helper_lhs_slot_forwardable(value, 2, instruction) &&
           !mir_call_argument_slot_forwardable(value, 2, instruction) &&
           !mir_stack_backend_slot_forwardable(value, 2, instruction) &&
           !mir_value_only_used_by_dead_stores(value) &&
           !mir_value_only_used_by_dead_unary(value);
}

static int mir_call_result_direct_reload_indirect_store_target(int value)
{
    const struct MirInsn *definition = mir_definition(value);
    const struct MirInsn *store;
    int skipped_label;
    int target;
    int instruction;

    if (definition == NULL || definition->opcode != MIR_CALL ||
        mir_emit_instruction_index < 0 ||
        mir_emit_instruction_index + 1 >= mir.count)
        return -1;
    target = mir_forward_skip_target_ex(mir_emit_instruction_index,
                                        &skipped_label);
    if (skipped_label || target < 0 || target >= mir.count)
        return -1;
    store = &mir.insns[target];
    if (store->opcode != MIR_STORE_INDIRECT || store->src2 != value ||
        mir_constant_absolute_access_supported(store) ||
        (!mir_indirect_store_address_has_direct_reload(store) &&
         !(mir_planned_stack_matches_consumer(store->src1, target) &&
           mir_planned_stack_is_emitted(store->src1))) ||
        (mir_value_currently_uses_stack_handoff(store->src1, target) &&
         !(mir_planned_stack_matches_consumer(store->src1, target) &&
           mir_planned_stack_is_emitted(store->src1))))
        return -1;
    for (instruction = target + 1;
         instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];
        if (insn->src1 == value || insn->src2 == value)
            return -1;
        if ((insn->opcode == MIR_CALL ||
             insn->opcode == MIR_CALL_AGGREGATE) &&
            mir_call_uses_value(insn, value))
            return -1;
    }
    return target;
}

static int mir_divmod_partner(int instruction)
{
    const struct MirInsn *candidate;
    int partner;

    if (instruction < 0 || instruction >= mir.count)
        return -1;
    candidate = &mir.insns[instruction];
    if (candidate->opcode != MIR_BINARY ||
        (candidate->immediate != '/' && candidate->immediate != '%') ||
        type_size(candidate->secondary_offset) > 2)
        return -1;
    for (partner = 0; partner < mir.count; ++partner) {
        const struct MirInsn *other = &mir.insns[partner];
        if (partner == instruction || other->opcode != MIR_BINARY ||
            other->src1 != candidate->src1 || other->src2 != candidate->src2 ||
            other->secondary_offset != candidate->secondary_offset)
            continue;
        if ((candidate->immediate == '/' && other->immediate == '%') ||
            (candidate->immediate == '%' && other->immediate == '/'))
            return partner;
    }
    return -1;
}

int mir_spilled_cfg_has_divmod_pair(void)
{
    int instruction;

    for (instruction = 0; instruction < mir.count; ++instruction)
        if (mir_divmod_partner(instruction) > instruction)
            return 1;
    return 0;
}

int mir_spilled_cfg_divmod_has_dead_result(void)
{
    int instruction;

    for (instruction = 0; instruction < mir.count; ++instruction) {
        int partner = mir_divmod_partner(instruction);

        if (partner > instruction &&
            (mir_value_only_used_by_dead_stores(
                 mir.insns[instruction].dst) ||
             mir_value_only_used_by_dead_stores(
                 mir.insns[partner].dst)))
            return 1;
    }
    return 0;
}

static void mir_emit_virtual_load_wide(FILE *out, int value)
{
    const struct MirInsn *definition = mir_definition(value);
    int offset;
    int iy_offset;

    /* Item T40 (mir-text-size-plan.md): consume a value mir_emit_virtual_
     * store_wide already forwarded straight from its producing
     * instruction, exactly mirroring mir_emit_virtual_load's own
     * mir_forwarded_hl_value check - the value is already resident in
     * HL:DE from the immediately preceding instruction, so no reload is
     * needed at all. Must precede every other case below (matching the
     * scalar version's own ordering) since this applies regardless of
     * whether the value is slot-based, param-direct, or anything else. */
    if (mir_forwarded_wide_value == value &&
        mir_forwarded_wide_instruction + 1 == mir_emit_instruction_index) {
        mir_forwarded_wide_value = -1;
        mir_forwarded_wide_instruction = -1;
        return;
    }
    if (mir_wide_constant_is_rematerializable(value) ||
        (definition != NULL &&
         (definition->opcode == MIR_CONST ||
          definition->opcode == MIR_FLOAT_CONST) &&
         type_size(definition->type) == 4 &&
         mir.backend_slots != NULL &&
         mir.backend_slots[value] < 0)) {
        /*
         * Slot planning can classify a constant as binary-only before
         * multiply-add fusion turns it into a direct helper operand. Such a
         * value intentionally has no slot; materialize it here rather than
         * deriving an IX offset from its SSA number.
         */
        if (mir_wide_constant_uses_new_rematerialization(value)) {
            mir_spilled_cfg_used_wide_constant_rematerialization = 1;
        }
        fprintf(out, "\tld hl,%lu\n\tld de,%lu\n",
                (unsigned long)definition->immediate & 0xffffUL,
                ((unsigned long)definition->immediate >> 16) & 0xffffUL);
        return;
    }
    if (!mir_definition_is_wide(definition)) {
        mir_emit_virtual_load(out, value);
        if (definition != NULL &&
            ((definition->type & TYPE_UNSIGNED) != 0 ||
             type_ptr_depth(definition->type) > 0 ||
             type_is_bool(definition->type)))
            fputs("\tld de,0\n", out);
        else
            fputs("\tld a,h\n\trlca\n\tsbc a,a\n\tld d,a\n\tld e,a\n",
                  out);
        return;
    }
    if (mir_value_has_direct_named_home(value)) {
        /* mir-migration-plan-next10: wide (4-byte) parameter counterpart
         * of mir_emit_virtual_load - object storage for a wide parameter is
         * ascending (offset..offset+3), unlike the descending backend-slot
         * convention below, so this mirrors the original MIR_PARAM binding
         * site's load form exactly rather than reusing mir_virtual_offset.
         * Also mirrors the IY-relative fast path hot loops rely on. */
        int object_offset;
        int object_storage;
        int selfstore_store_index;
        if (getenv("DCC_MIR_PERF_RECOVERY_REPORT") != NULL &&
            mir_wide_load_is_immediate_binary_rhs(value))
            fprintf(stderr,
                    "; MIR perf-recovery function=%s feature=wide-rhs-load\n",
                    mir.name);
        if (!mir_direct_named_home_location(
                definition, &object_storage, &object_offset) &&
            !mir_binary_is_selfstore_wide_increment(
                (int)(definition - mir.insns),
                &selfstore_store_index, &object_offset))
            fatal("missing direct wide MIR named-home offset");
        int object_iy_offset = object_offset + mir_effective_local_bytes() +
                                mir.aggregate_temp_bytes;
        if (mir_virtual_iy_base && object_iy_offset >= -128 &&
            object_iy_offset + 3 <= 127) {
            fprintf(out,
                    "\tld l,(iy%+d)\n\tld h,(iy%+d)\n"
                    "\tld e,(iy%+d)\n\tld d,(iy%+d)\n",
                    object_iy_offset, object_iy_offset + 1,
                    object_iy_offset + 2, object_iy_offset + 3);
        } else if (object_offset >= -128 && object_offset + 3 <= 127) {
            fprintf(out,
                    "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
                    "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
                    object_offset, object_offset + 1,
                    object_offset + 2, object_offset + 3);
        } else {
            fputs("\tpush ix\n\tpop hl\n", out);
            fprintf(out, "\tld de,%d\n\tadd hl,de\n", object_offset);
            fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
                  "\tinc hl\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
                  "\tld h,b\n\tld l,c\n", out);
        }
        return;
    }
    offset = mir_virtual_offset(value);
    iy_offset = mir_virtual_iy_offset(value);
    if (mir_virtual_iy_base && iy_offset - 2 >= -128 &&
        iy_offset + 1 <= 127) {
        fprintf(out,
                "\tld l,(iy%+d)\n\tld h,(iy%+d)\n"
                "\tld e,(iy%+d)\n\tld d,(iy%+d)\n",
                iy_offset, iy_offset + 1, iy_offset - 2, iy_offset - 1);
        return;
    }
    if (offset - 2 >= -128 && offset + 1 <= 127) {
        fprintf(out,
                "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
                "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
                offset, offset + 1, offset - 2, offset - 1);
    } else {
        fputs("\tpush ix\n\tpop hl\n", out);
        fprintf(out, "\tld de,%d\n\tadd hl,de\n", offset);
        fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
              "\tdec hl\n\tdec hl\n\tdec hl\n"
              "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
              "\tld h,b\n\tld l,c\n", out);
    }
}

static void mir_emit_virtual_store_wide(FILE *out, int value)
{
    const struct MirInsn *definition = mir_definition(value);
    int force_slot_store = definition != NULL &&
                           definition->opcode == MIR_PHI;
    int has_slot;
    int helper_consumer;
    int offset;
    int iy_offset;
    /* Item T35 (mir-text-size-plan.md): mirrors mir_emit_virtual_store's
     * own first-line check, now that Item T35's mir_object_eligible
     * relaxation lets a wide (4-byte) parameter actually have an object
     * at all - nothing to store here, later reads simply re-load
     * directly from the parameter's own stable home (see
     * mir_emit_virtual_load_wide, which already checks this same
     * predicate on the load side). Without this check a direct-eligible
     * wide parameter would still pay a full spill even though nothing
     * downstream would ever read the slot this store writes. */
    if (mir_value_has_direct_named_home(value))
        return;
    if (value == mir_prepacked_result_value) {
        fputs("\tpush de\n\tpush hl\n", out);
        return;
    }
    if (value >= 0 && value < mir.next_value &&
        mir.backend_slots != NULL &&
        (mir.backend_slots[value] == MIR_BACKEND_SLOT_CALL_CACHE ||
         mir.backend_slots[value] ==
             MIR_BACKEND_SLOT_WIDE_ARGUMENT_STACK_CACHE)) {
        int call_instruction =
            mir_planned_call_argument_cache_target(value, 1);
        if (mir.backend_slots[value] ==
            MIR_BACKEND_SLOT_WIDE_ARGUMENT_STACK_CACHE)
            fputs("\tpush de\n\tpush hl\n", out);
        else
            fputs("\texx\n", out);
        mir_cached_wide_call_value = value;
        mir_cached_wide_call_instruction = call_instruction;
        return;
    }
    if (!force_slot_store &&
        mir_wide_signed_const_lhs_slot_forwardable(
            value, 2, mir_emit_instruction_index)) {
        mir_forwarded_wide_value = value;
        mir_forwarded_wide_instruction = mir_emit_instruction_index;
        return;
    }
    if (!force_slot_store &&
        mir_wide_helper_lhs_consumer(
            value, mir_emit_instruction_index, &helper_consumer) &&
        mir_wide_helper_handoff_supported(&mir.insns[helper_consumer]) &&
        mir_wide_helper_lhs_span_is_safe(
            mir_emit_instruction_index, helper_consumer)) {
        if (mir_forwarded_wide_stack_value >= 0) {
            const struct MirInsn *consumer = &mir.insns[helper_consumer];

            if (mir_forwarded_wide_stack_consumer == helper_consumer &&
                consumer->src1 == value &&
                consumer->src2 == mir_forwarded_wide_stack_value &&
                mir_forward_skip_target(mir_emit_instruction_index) ==
                    helper_consumer) {
                mir_forwarded_wide_value = value;
                mir_forwarded_wide_instruction = helper_consumer - 1;
                return;
            }
            mir_planned_stack_invalid = 1;
            return;
        }
        int pending_consumer = mir_pending_planned_stack_consumer();
        if (pending_consumer >= 0 && helper_consumer >= pending_consumer)
            mir_planned_stack_invalid = 1;
        fputs("\tpush de\n\tpush hl\n", out);
        mir_forwarded_wide_stack_value = value;
        mir_forwarded_wide_stack_consumer = helper_consumer;
        return;
    }
    if (!force_slot_store &&
        mir_wide_binary_rhs_forwarding_enabled &&
        mir_emit_instruction_index + 1 < mir.count &&
        mir_wide_binary_rhs_pair_supported(
            value, &mir.insns[mir_emit_instruction_index + 1]) &&
        mir.insns[mir_emit_instruction_index + 1].src2 == value &&
        mir_value_use_count(value) == 1) {
        if (mir_pending_planned_stack_consumer() >= 0 ||
            mir_forwarded_wide_stack_value >= 0) {
            mir_planned_stack_invalid = 1;
            return;
        }
        fputs("\tpush de\n\tpush hl\n", out);
        mir_forwarded_wide_stack_value = value;
        mir_forwarded_wide_stack_consumer = mir_emit_instruction_index + 1;
        ++mir_wide_binary_rhs_forwarding_uses;
        return;
    }
    /* Item T40 (mir-text-size-plan.md): forward a computed wide value
     * straight to its sole next use (currently only a MIR_RETURN, see
     * mir_can_forward_hl_de_to_next) instead of always spilling it to a
     * backend slot first - mirrors mir_emit_virtual_store's own
     * forwarding check, just for HL:DE instead of HL alone. The slot
     * mir_prepare_backend_slots already assigned (it has no wide-
     * forwarding awareness yet) is simply left unused in this case,
     * the same acceptable tradeoff Item 13 documented for the scalar
     * path before mir_prepare_backend_slots grew its own forwarding
     * awareness. */
    if (!force_slot_store &&
        mir_can_forward_hl_de_to_next(value)) {
        int forward_instruction =
            mir_forward_skip_target(mir_emit_instruction_index);
        mir_forwarded_wide_value = value;
        mir_forwarded_wide_instruction = forward_instruction - 1;
        return;
    }
    has_slot = value >= 0 && value < mir.next_value &&
                   mir.backend_slots != NULL && mir.backend_slots[value] >= 0;
    if (!has_slot)
        return;
    int call_instruction = mir_call_argument_cache_target(value);
    if (!force_slot_store && call_instruction >= 0) {
        fputs("\texx\n", out);
        mir_cached_wide_call_value = value;
        mir_cached_wide_call_instruction = call_instruction;
        return;
    }
    offset = mir_virtual_offset(value);
    iy_offset = mir_virtual_iy_offset(value);
    mir_forwarded_hl_value = -1;
    mir_forwarded_hl_instruction = -1;
    mir_forwarded_wide_value = -1;
    mir_forwarded_wide_instruction = -1;
    if (mir_virtual_iy_base && iy_offset - 2 >= -128 &&
        iy_offset + 1 <= 127) {
        fprintf(out,
                "\tld (iy%+d),l\n\tld (iy%+d),h\n"
                "\tld (iy%+d),e\n\tld (iy%+d),d\n",
                iy_offset, iy_offset + 1, iy_offset - 2, iy_offset - 1);
        return;
    }
    if (offset - 2 >= -128 && offset + 1 <= 127) {
        fprintf(out,
                "\tld (ix%+d),l\n\tld (ix%+d),h\n"
                "\tld (ix%+d),e\n\tld (ix%+d),d\n",
                offset, offset + 1, offset - 2, offset - 1);
    } else {
        fputs("\tpush de\n\tpush hl\n\tpush ix\n\tpop hl\n", out);
        fprintf(out, "\tld de,%d\n\tadd hl,de\n", offset);
        fputs("\tpop bc\n\tld (hl),c\n\tinc hl\n\tld (hl),b\n"
              "\tdec hl\n\tdec hl\n\tdec hl\n"
              "\tpop bc\n\tld (hl),c\n\tinc hl\n\tld (hl),b\n", out);
    }
}

static void mir_emit_virtual_iy_epilogue(FILE *out)
{
    if (!mir_virtual_iy_base) {
        fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
        return;
    }
    fputs("\texx\n\tpush ix\n\tpop hl\n", out);
    fprintf(out, "\tld de,-%d\n\tadd hl,de\n\tld sp,hl\n",
            mir_virtual_iy_frame_bytes + 2);
    fputs("\tpop iy\n\tld sp,ix\n\tpop ix\n\texx\n\tret\n", out);
}

static void mir_emit_low_byte_index_loop(
    FILE *out, const int *labels, const struct MirLowByteIndexLoop *loop)
{
    if (getenv("DCC_MIR_LOW_BYTE_INDEX_LOOP_REPORT") != NULL)
        fprintf(stderr,
                "; MIR low-byte-index-loop function=%s kind=%s "
                "initial=%d limit=%d\n",
                mir.name,
                loop->kind == MIR_LOW_BYTE_INDEX_STORE
                    ? "store" : "compare",
                loop->initial, loop->limit);
    fprintf(out,
            "\tld c,(ix%+d)\n\tld b,(ix%+d)\n",
            loop->base_offset, loop->base_offset + 1);
    if (loop->initial != 0)
        fprintf(out,
                "\tld hl,%d\n\tadd hl,bc\n\tld b,h\n\tld c,l\n",
                loop->initial);
    fprintf(out,
            "\tld e,%d\n\tld h,(ix%+d)\nL%d:\n"
            "\tld a,h\n\tadd a,e\n",
            loop->initial, loop->invariant_offset,
            labels[loop->header_label]);
    if (loop->kind == MIR_LOW_BYTE_INDEX_STORE) {
        fputs("\tld (bc),a\n\tinc bc\n", out);
    } else {
        fprintf(out,
                "\tld d,a\n\tld a,(bc)\n\tcp d\n\tinc bc\n"
                "\tjp z, L%d\n\tld hl,0\n",
                labels[loop->continue_label]);
        mir_emit_virtual_iy_epilogue(out);
        fprintf(out, "L%d:\n", labels[loop->continue_label]);
    }
    fprintf(out,
            "\tinc e\n\tld a,e\n\tcp %d\n\tjp c, L%d\n",
            loop->limit, labels[loop->header_label]);
}

static void mir_emit_phi_value_store(FILE *out, int value)
{
    int saved_instruction = mir_emit_instruction_index;

    mir_emit_instruction_index = -1;
    mir_emit_virtual_store(out, value);
    mir_emit_instruction_index = saved_instruction;
}

static void mir_emit_phi_value_load(FILE *out, int value)
{
    int saved_instruction = mir_emit_instruction_index;

    mir_emit_instruction_index = -1;
    mir_emit_virtual_load(out, value);
    mir_emit_instruction_index = saved_instruction;
}

static void mir_emit_byte_verify_loop(
    FILE *out, const int *labels, const struct MirByteVerifyLoop *loop)
{
    int body_label = new_label();
    int mismatch_label = new_label();
    int mismatch_fallthrough_label = new_label();

    fprintf(out,
            "\tld c,(ix%+d)\n\tld b,(ix%+d)\n"
            "\tld a,b\n\tor c\n\tjp z, L%d\n",
            loop->count_offset, loop->count_offset + 1,
            labels[loop->exit_label]);
    fprintf(out,
            "\tld a,(ix%+d)\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "L%d:\n\tcpi\n\tjp nz, L%d\n"
            "\tjp pe, L%d\n\tjp L%d\n"
            "L%d:\n\tdec hl\n"
            "\tld (ix%+d),l\n\tld (ix%+d),h\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tor a\n\tsbc hl,bc\n\tdec hl\n",
            loop->value_source_offset,
            loop->pointer_offset, loop->pointer_offset + 1,
            body_label, mismatch_label, body_label,
            labels[loop->exit_label],
            mismatch_label,
            loop->pointer_offset, loop->pointer_offset + 1,
            loop->count_offset, loop->count_offset + 1);
    mir_emit_phi_value_store(out, loop->phi_value);
    fprintf(out, "\tjp L%d\nL%d:\n",
            mismatch_fallthrough_label,
            labels[loop->header_label]);
    mir_emit_phi_value_load(out, loop->phi_value);
    fputs("\tex de,hl\n", out);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tor a\n\tsbc hl,de\n\tld c,l\n\tld b,h\n"
            "\tld a,b\n\tor c\n\tjp z, L%d\n",
            loop->count_offset, loop->count_offset + 1,
            labels[loop->exit_label]);
    fprintf(out,
            "\tld a,(ix%+d)\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tjp L%d\nL%d:\n",
            loop->value_source_offset,
            loop->pointer_offset, loop->pointer_offset + 1,
            body_label, mismatch_fallthrough_label);
}

static void mir_emit_word_scan_loop(
    FILE *out, const int *labels, const struct MirWordScanLoop *loop)
{
    int done_label = new_label();
    int next_label = new_label();

    fprintf(out,
            "\tld c,(ix%+d)\n\tld b,(ix%+d)\n"
            "L%d:\n"
            "\tld l,c\n\tld h,b\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n\tld a,h\n\tor l\n"
            "\tjp z, L%d\n",
            loop->pointer_offset, loop->pointer_offset + 1,
            labels[loop->header_label], done_label);
    if (loop->kind == MIR_WORD_SCAN_LAST_MATCH) {
        fprintf(out,
                "\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
                "\tor a\n\tsbc hl,de\n\tjp nz, L%d\n"
                "\tld (ix%+d),c\n\tld (ix%+d),b\n"
                "L%d:\n",
                loop->comparison_offset,
                loop->comparison_offset + 1,
                next_label,
                loop->last_match_offset,
                loop->last_match_offset + 1,
                next_label);
    }
    fprintf(out,
            "\tinc bc\n\tinc bc\n\tjp L%d\n"
            "L%d:\n",
            labels[loop->header_label], done_label);
    if (loop->kind == MIR_WORD_SCAN_LENGTH)
        fprintf(out,
                "\tld (ix%+d),c\n\tld (ix%+d),b\n",
                loop->pointer_offset, loop->pointer_offset + 1);
    fprintf(out, "\tjp L%d\n", labels[loop->exit_label]);
}

static void mir_emit_byte_minmax(
    FILE *out, const struct MirByteMinMax *plan)
{
    const char *moves_name =
        asm_name_for(sym_asm_name(plan->moves));
    const char *winner_name =
        asm_name_for(sym_asm_name(plan->winner_functions));
    const char *board_name =
        asm_name_for(sym_asm_name(plan->board));
    const char *self_name =
        asm_name_for(sym_asm_name(plan->self));
    int moves_done = new_label();
    int no_terminal = new_label();
    int no_winner = new_label();
    int winner_lose = new_label();
    int even_depth = new_label();
    int init_done = new_label();
    int loop = new_label();
    int tail = new_label();
    int minimizing = new_label();
    int max_not_win = new_label();
    int max_alpha = new_label();
    int min_not_lose = new_label();
    int return_value = new_label();
    int exit = new_label();

    if ((plan->moves->storage == SC_EXTERN ||
         plan->moves->needs_extrn) &&
        mir_extrn_should_emit(plan->moves))
        fprintf(out, "\textrn %s\n", moves_name);
    if ((plan->winner_functions->storage == SC_EXTERN ||
         plan->winner_functions->needs_extrn) &&
        mir_extrn_should_emit(plan->winner_functions))
        fprintf(out, "\textrn %s\n", winner_name);
    if ((plan->board->storage == SC_EXTERN ||
         plan->board->needs_extrn) &&
        mir_extrn_should_emit(plan->board))
        fprintf(out, "\textrn %s\n", board_name);

    fprintf(out,
            "\tld hl,%s\n"
            "\tinc (hl)\n\tjp nz, L%d\n"
            "\tinc hl\n\tinc (hl)\n\tjp nz, L%d\n"
            "\tinc hl\n\tinc (hl)\n\tjp nz, L%d\n"
            "\tinc hl\n\tinc (hl)\n"
            "L%d:\n",
            moves_name, moves_done, moves_done, moves_done, moves_done);

    fprintf(out,
            "\tld a,(ix%+d)\n\tcp %d\n\tjp c, L%d\n"
            "\tld l,(ix%+d)\n\tld h,0\n\tadd hl,hl\n"
            "\tld de,%s\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n",
            plan->depth_offset, plan->depth_threshold, no_terminal,
            plan->move_offset, winner_name);
    mir_emit_runtime_call(out, "__call_hl");
    fprintf(out,
            "\tld a,l\n\tor a\n\tjp z, L%d\n"
            "\tcp %d\n\tjp nz, L%d\n"
            "\tld l,%d\n\tjp L%d\n"
            "L%d:\n\tld l,%d\n\tjp L%d\n"
            "L%d:\n"
            "\tld a,(ix%+d)\n\tcp %d\n\tjp nz, L%d\n"
            "\tld l,%d\n\tjp L%d\n"
            "L%d:\n",
            no_winner, plan->piece_x, winner_lose,
            plan->score_win, exit,
            winner_lose, plan->score_lose, exit,
            no_winner,
            plan->depth_offset, plan->terminal_depth, no_terminal,
            plan->score_tie, exit,
            no_terminal);

    fprintf(out,
            "\tbit 0,(ix%+d)\n\tjp z, L%d\n"
            "\tld c,%d\n\tld a,%d\n\tld (ix%+d),a\n"
            "\tjp L%d\n"
            "L%d:\n"
            "\tld c,%d\n\tld a,%d\n\tld (ix%+d),a\n"
            "L%d:\n"
            "\tld b,0\n\tld hl,%s\n"
            "L%d:\n"
            "\tld a,(hl)\n\tor a\n\tjp nz, L%d\n"
            "\tld a,(ix%+d)\n\tld (hl),a\n"
            "\tpush hl\n\tpush bc\n"
            "\tld l,b\n\tld h,0\n\tpush hl\n"
            "\tld l,(ix%+d)\n\tld h,0\n\tinc hl\n\tpush hl\n"
            "\tld l,(ix%+d)\n\tld h,0\n\tpush hl\n"
            "\tld l,(ix%+d)\n\tld h,0\n\tpush hl\n"
            "\tcall %s\n"
            "\tpop bc\n\tpop bc\n\tpop bc\n\tpop bc\n"
            "\tld e,l\n\tpop bc\n\tpop hl\n"
            "\tld (hl),%d\n"
            "\tbit 0,(ix%+d)\n\tjp z, L%d\n",
            plan->depth_offset, even_depth,
            plan->score_min, plan->piece_x, plan->piece_offset,
            init_done,
            even_depth,
            plan->score_max, plan->piece_o, plan->piece_offset,
            init_done,
            board_name,
            loop,
            tail,
            plan->piece_offset,
            plan->depth_offset,
            plan->beta_offset,
            plan->alpha_offset,
            self_name,
            plan->blank,
            plan->depth_offset, minimizing);

    fprintf(out,
            "\tld a,e\n\tcp %d\n\tjp nz, L%d\n"
            "\tld l,%d\n\tjp L%d\n"
            "L%d:\n"
            "\tcp c\n\tjp c, L%d\n\tjp z, L%d\n"
            "\tld c,a\n\tcp (ix%+d)\n\tjp c, L%d\n"
            "\tjp L%d\n"
            "L%d:\n"
            "\tcp (ix%+d)\n\tjp c, L%d\n\tjp z, L%d\n"
            "\tld (ix%+d),a\n\tjp L%d\n",
            plan->score_win, max_not_win,
            plan->score_win, exit,
            max_not_win,
            tail, tail,
            plan->beta_offset, max_alpha,
            return_value,
            max_alpha,
            plan->alpha_offset, tail, tail,
            plan->alpha_offset, tail);

    fprintf(out,
            "L%d:\n"
            "\tld a,e\n\tcp %d\n\tjp nz, L%d\n"
            "\tld l,%d\n\tjp L%d\n"
            "L%d:\n"
            "\tcp c\n\tjp nc, L%d\n"
            "\tld c,a\n\tcp (ix%+d)\n"
            "\tjp c, L%d\n\tjp z, L%d\n"
            "\tcp (ix%+d)\n\tjp nc, L%d\n"
            "\tld (ix%+d),a\n\tjp L%d\n"
            "L%d:\n\tld l,c\n\tjp L%d\n",
            minimizing,
            plan->score_lose, min_not_lose,
            plan->score_lose, exit,
            min_not_lose,
            tail,
            plan->alpha_offset,
            return_value, return_value,
            plan->beta_offset, tail,
            plan->beta_offset, tail,
            return_value, exit);

    fprintf(out,
            "L%d:\n"
            "\tinc hl\n\tinc b\n\tld a,b\n\tcp %d\n"
            "\tjp c, L%d\n"
            "\tld l,c\n"
            "L%d:\n"
            "\tld h,0\n",
            tail, plan->loop_bound, loop,
            exit);
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_fixed_byte_winner(
    FILE *out, const struct MirFixedByteWinner *plan)
{
    const char *board_name =
        asm_name_for(sym_asm_name(plan->board));
    int success = new_label();
    int line;

    if ((plan->board->storage == SC_EXTERN ||
         plan->board->needs_extrn) &&
        mir_extrn_should_emit(plan->board))
        fprintf(out, "\textrn %s\n", board_name);
    fprintf(out, "\tld a,(%s%+d)\n\tld b,a\n",
            board_name, plan->source_offset);
    for (line = 0; line < plan->line_count; ++line) {
        int next = new_label();

        fprintf(out,
                "\tld a,(%s%+d)\n\tcp b\n\tjp nz, L%d\n"
                "\tld a,(%s%+d)\n\tcp b\n\tjp z, L%d\n"
                "L%d:\n",
                board_name, plan->line_offsets[line][0], next,
                board_name, plan->line_offsets[line][1], success,
                next);
    }
    fprintf(out,
            "\tld hl,0\n\tret\n"
            "L%d:\n\tld l,b\n\tld h,0\n\tret\n",
            success);
}

static void mir_emit_word_powermod(
    FILE *out, const struct MirWordPowermod *plan)
{
    int exponent_nonzero = new_label();
    int initialize = new_label();
    int loop = new_label();
    int after_product = new_label();
    int return_result = new_label();
    int exit = new_label();

    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tdec hl\n"
            "\tld a,h\n\tor l\n\tjp nz, L%d\n"
            "\tld hl,0\n\tjp L%d\n"
            "L%d:\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld a,h\n\tor l\n\tjp nz, L%d\n"
            "\tld hl,1\n\tjp L%d\n"
            "L%d:\n"
            "\tld hl,1\n\tld (ix%+d),l\n\tld (ix%+d),h\n"
            "\tld hl,%d\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
            plan->modulus_offset, plan->modulus_offset + 1,
            exponent_nonzero,
            exit,
            exponent_nonzero,
            plan->exponent_offset, plan->exponent_offset + 1,
            initialize,
            exit,
            initialize,
            plan->result_offset, plan->result_offset + 1,
            plan->initial_base,
            plan->modulus_offset, plan->modulus_offset + 1);
    mir_emit_runtime_call(out, "__modu");
    fprintf(out,
            "\tld (ix%+d),l\n\tld (ix%+d),h\n"
            "L%d:\n"
            "\tbit 0,(ix%+d)\n\tjp z, L%d\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "\tld c,(ix%+d)\n\tld b,(ix%+d)\n",
            plan->base_offset, plan->base_offset + 1,
            loop,
            plan->exponent_offset, after_product,
            plan->result_offset, plan->result_offset + 1,
            plan->base_offset, plan->base_offset + 1,
            plan->modulus_offset, plan->modulus_offset + 1);
    mir_emit_runtime_call(out, "__m1mu");
    fprintf(out,
            "\tld (ix%+d),l\n\tld (ix%+d),h\n"
            "L%d:\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tsrl h\n\trr l\n"
            "\tld (ix%+d),l\n\tld (ix%+d),h\n"
            "\tld a,h\n\tor l\n\tjp z, L%d\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld e,l\n\tld d,h\n"
            "\tld c,(ix%+d)\n\tld b,(ix%+d)\n",
            plan->result_offset, plan->result_offset + 1,
            after_product,
            plan->exponent_offset, plan->exponent_offset + 1,
            plan->exponent_offset, plan->exponent_offset + 1,
            return_result,
            plan->base_offset, plan->base_offset + 1,
            plan->modulus_offset, plan->modulus_offset + 1);
    mir_emit_runtime_call(out, "__m1mu");
    fprintf(out,
            "\tld (ix%+d),l\n\tld (ix%+d),h\n\tjp L%d\n"
            "L%d:\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "L%d:\n"
            "\tld sp,ix\n\tpop ix\n\tret\n",
            plan->base_offset, plan->base_offset + 1, loop,
            return_result,
            plan->result_offset, plan->result_offset + 1,
            exit);
}

static void mir_emit_float_parameter(
    FILE *out, int offset)
{
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
            offset, offset + 1, offset + 2, offset + 3);
}

static void mir_emit_float_bits(
    FILE *out, unsigned long bits)
{
    fprintf(out, "\tld hl,%lu\n\tld de,%lu\n",
            bits & 0xffffUL, (bits >> 16) & 0xffffUL);
}

static void mir_emit_float_parameter_left(
    FILE *out, int offset, unsigned long right_bits,
    const char *helper)
{
    mir_emit_float_parameter(out, offset);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_float_bits(out, right_bits);
    mir_emit_runtime_call(out, helper);
    fputs("\tpop bc\n\tpop bc\n", out);
}

static void mir_emit_float_unit_fraction(
    FILE *out, const struct MirFloatUnitFraction *plan)
{
    const char *assert_name =
        asm_name_for(sym_asm_name(plan->assert_function));
    int upper_ok = new_label();
    int lower_ok = new_label();
    int return_parameter = new_label();
    int exit = new_label();

    if ((plan->assert_function->storage == SC_EXTERN ||
         plan->assert_function->needs_extrn) &&
        mir_extrn_should_emit(plan->assert_function))
        fprintf(out, "\textrn %s\n", assert_name);
    mir_emit_float_parameter_left(
        out, plan->parameter_offset,
        plan->upper_bits, "__fgtf");
    fprintf(out,
            "\tld a,h\n\tor l\n\tjp nz, L%d\n"
            "\tld hl,S%d\n\tpush hl\n\tcall %s\n\tpop bc\n"
            "L%d:\n",
            upper_ok, plan->upper_assert_string,
            assert_name, upper_ok);
    mir_emit_float_parameter_left(
        out, plan->parameter_offset,
        plan->lower_bits, "__flef");
    fprintf(out,
            "\tld a,h\n\tor l\n\tjp nz, L%d\n"
            "\tld hl,S%d\n\tpush hl\n\tcall %s\n\tpop bc\n"
            "L%d:\n",
            lower_ok, plan->lower_assert_string,
            assert_name, lower_ok);
    mir_emit_float_parameter_left(
        out, plan->parameter_offset,
        plan->unit_bits, "__flef");
    fprintf(out,
            "\tld a,h\n\tor l\n\tjp z, L%d\n",
            return_parameter);
    mir_emit_float_parameter(out, plan->parameter_offset);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_float_bits(out, plan->unit_bits);
    mir_emit_runtime_call(out, "__fsf");
    fputs("\tpop bc\n\tpop bc\n", out);
    fprintf(out,
            "\tjp L%d\n"
            "L%d:\n",
            exit, return_parameter);
    mir_emit_float_parameter(out, plan->parameter_offset);
    fprintf(out,
            "L%d:\n"
            "\tld sp,ix\n\tpop ix\n\tret\n",
            exit);
}

static void mir_emit_frameless_byte_parameter(
    FILE *out, int sp_offset)
{
    fprintf(out, "\tld hl,%d\n\tadd hl,sp\n\tld a,(hl)\n",
            sp_offset);
}

static void mir_emit_ascii_piece_side(
    FILE *out, const struct MirAsciiPieceSide *plan)
{
    int lower = new_label();
    int upper_result = new_label();
    int lower_result = new_label();
    int other_result = new_label();

    mir_emit_frameless_byte_parameter(out, plan->parameter_sp_offset);
    fprintf(out,
            "\tcp %d\n\tjp c, L%d\n"
            "\tcp %d\n\tjp c, L%d\n"
            "L%d:\n"
            "\tcp %d\n\tjp c, L%d\n"
            "\tcp %d\n\tjp c, L%d\n"
            "\tjp L%d\n"
            "L%d:\n\tld hl,%d\n\tret\n"
            "L%d:\n\tld hl,%d\n\tret\n"
            "L%d:\n\tld hl,%d\n\tret\n",
            plan->upper_first, lower,
            plan->upper_last + 1, upper_result,
            lower,
            plan->lower_first, other_result,
            plan->lower_last + 1, lower_result,
            other_result,
            upper_result, plan->upper_result & 0xffff,
            lower_result, plan->lower_result & 0xffff,
            other_result, plan->other_result & 0xffff);
}

static void mir_emit_ascii_piece_value(
    FILE *out, const struct MirAsciiPieceValue *plan)
{
    int folded = new_label();
    int labels[6];
    int item;

    mir_emit_frameless_byte_parameter(out, plan->parameter_sp_offset);
    fprintf(out,
            "\tcp %d\n\tjp c, L%d\n"
            "\tcp %d\n\tjp nc, L%d\n"
            "\tsub %d\n"
            "L%d:\n",
            plan->lower_first, folded,
            plan->lower_last + 1, folded,
            plan->fold_amount, folded);
    for (item = 0; item < 6; ++item) {
        labels[item] = new_label();
        fprintf(out, "\tcp %d\n\tjp z, L%d\n",
                plan->piece[item], labels[item]);
    }
    fprintf(out, "\tld hl,%d\n\tret\n",
            plan->default_value & 0xffff);
    for (item = 0; item < 6; ++item)
        fprintf(out, "L%d:\n\tld hl,%d\n\tret\n",
                labels[item], plan->value[item] & 0xffff);
}

static void mir_emit_sign_extend_a(FILE *out)
{
    fputs("\tld l,a\n\trlca\n\tsbc a,a\n\tld h,a\n", out);
}

static void mir_emit_evaluate_board_reload(
    FILE *out, const char *board_name)
{
    fprintf(out,
            "\tld l,(ix-3)\n\tld h,0\n"
            "\tld de,%s\n\tadd hl,de\n"
            "\tld a,(hl)\n\tld (ix-4),a\n",
            board_name);
}

static void mir_emit_board_evaluate(
    FILE *out, const struct MirBoardEvaluate *plan)
{
    const char *board_name =
        asm_name_for(sym_asm_name(plan->board));
    const char *side_name =
        asm_name_for(sym_asm_name(plan->side));
    const char *value_name =
        asm_name_for(sym_asm_name(plan->value_function));
    const char *position_name =
        asm_name_for(sym_asm_name(plan->position_function));
    const char *piece_side_name =
        asm_name_for(sym_asm_name(plan->side_function));
    int loop = new_label();
    int tail = new_label();
    int black = new_label();
    int update_done = new_label();
    int positive = new_label();
    int exit = new_label();

    if ((plan->board->storage == SC_EXTERN ||
         plan->board->needs_extrn) &&
        mir_extrn_should_emit(plan->board))
        fprintf(out, "\textrn %s\n", board_name);
    if ((plan->side->storage == SC_EXTERN ||
         plan->side->needs_extrn) &&
        mir_extrn_should_emit(plan->side))
        fprintf(out, "\textrn %s\n", side_name);
    fputs("\tld hl,0\n\tld (ix-2),l\n\tld (ix-1),h\n"
          "\tld (ix-3),0\n", out);
    fprintf(out,
            "L%d:\n"
            "\tld l,(ix-3)\n\tld h,0\n\tld de,%s\n\tadd hl,de\n"
            "\tld a,(hl)\n\tcp %d\n\tjp z, L%d\n"
            "\tld (ix-4),a\n",
            loop, board_name, plan->blank, tail);

    mir_emit_evaluate_board_reload(out, board_name);
    mir_emit_sign_extend_a(out);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tcall %s\n\tpop bc\n", value_name);
    fputs("\tld (ix-6),l\n\tld (ix-5),h\n", out);

    fputs("\tld l,(ix-3)\n\tld h,0\n\tpush hl\n", out);
    mir_emit_evaluate_board_reload(out, board_name);
    fputs("\tld a,(ix-4)\n", out);
    mir_emit_sign_extend_a(out);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tcall %s\n\tpop bc\n\tpop bc\n",
            position_name);
    fputs("\tld e,(ix-6)\n\tld d,(ix-5)\n\tadd hl,de\n"
          "\tld (ix-6),l\n\tld (ix-5),h\n", out);

    mir_emit_evaluate_board_reload(out, board_name);
    fputs("\tld a,(ix-4)\n", out);
    mir_emit_sign_extend_a(out);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tcall %s\n\tpop bc\n", piece_side_name);
    fprintf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n\tjp nz, L%d\n"
            "\tld l,(ix-2)\n\tld h,(ix-1)\n"
            "\tld e,(ix-6)\n\tld d,(ix-5)\n\tadd hl,de\n"
            "\tld (ix-2),l\n\tld (ix-1),h\n\tjp L%d\n"
            "L%d:\n",
            plan->white, black,
            update_done,
            black);
    mir_emit_evaluate_board_reload(out, board_name);
    fputs("\tld a,(ix-4)\n", out);
    mir_emit_sign_extend_a(out);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tcall %s\n\tpop bc\n", piece_side_name);
    fprintf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n\tjp nz, L%d\n"
            "\tld l,(ix-2)\n\tld h,(ix-1)\n"
            "\tld e,(ix-6)\n\tld d,(ix-5)\n"
            "\tor a\n\tsbc hl,de\n"
            "\tld (ix-2),l\n\tld (ix-1),h\n"
            "L%d:\n",
            plan->black, update_done,
            update_done);
    fprintf(out,
            "L%d:\n"
            "\tinc (ix-3)\n\tld a,(ix-3)\n\tcp %d\n\tjp c, L%d\n"
            "\tld hl,(%s)\n\tld de,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp z, L%d\n"
            "\tld l,(ix-2)\n\tld h,(ix-1)\n"
            "\txor a\n\tsub l\n\tld l,a\n"
            "\tld a,0\n\tsbc a,h\n\tld h,a\n\tjp L%d\n"
            "L%d:\n\tld l,(ix-2)\n\tld h,(ix-1)\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            tail, plan->bound, loop,
            side_name, plan->white, positive,
            exit,
            positive,
            exit);
}

static void mir_emit_center_score(
    FILE *out, const struct MirCenterScore *plan)
{
    int file_nonnegative = new_label();
    int rank_nonnegative = new_label();

    fprintf(out,
            "\tld hl,%d\n\tadd hl,sp\n"
            "\tld a,(hl)\n\tinc hl\n\tld h,(hl)\n\tld l,a\n"
            "\tpush hl\n"
            "\tld a,l\n\tand %d\n",
            plan->parameter_sp_offset, plan->file_mask);
    if (plan->scale == 2)
        fputs("\tadd a,a\n", out);
    else
        fprintf(out, "\tld e,%d\n\tcall __mulu\n\tld a,l\n",
                plan->scale);
    fprintf(out,
            "\tsub %d\n\tjp nc, L%d\n\tneg\n"
            "L%d:\n\tld b,a\n"
            "\tpop hl\n",
            plan->midpoint, file_nonnegative, file_nonnegative);
    if (plan->rank_shift > 0)
        mir_emit_scalar_shift_by_constant(
            out, TOK_SHR, 0, plan->rank_shift);
    if (plan->scale == 2)
        fputs("\tadd hl,hl\n", out);
    else
        mir_emit_mul_hl_const(out, (unsigned long)plan->scale);
    fprintf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n"
            "\tbit 7,h\n\tjp z, L%d\n"
            "\txor a\n\tsub l\n\tld l,a\n"
            "\tld a,0\n\tsbc a,h\n\tld h,a\n"
            "L%d:\n"
            "\tex de,hl\n\tld hl,%d\n\tld a,l\n\tsub b\n\tld l,a\n"
            "\tor a\n\tsbc hl,de\n\tret\n",
            plan->midpoint, rank_nonnegative, rank_nonnegative,
            plan->total);
}

static void mir_emit_king_scan(
    FILE *out, const struct MirKingScan *plan)
{
    const char *board_name =
        asm_name_for(sym_asm_name(plan->board));
    const char *attack_name =
        asm_name_for(sym_asm_name(plan->attack_function));
    int black = new_label();
    int initialized = new_label();
    int loop = new_label();
    int found = new_label();
    int exit = new_label();

    if ((plan->board->storage == SC_EXTERN ||
         plan->board->needs_extrn) &&
        mir_extrn_should_emit(plan->board))
        fprintf(out, "\textrn %s\n", board_name);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld de,%d\n\tor a\n\tsbc hl,de\n\tjp nz, L%d\n"
            "\tld c,%d\n\tjp L%d\n"
            "L%d:\n\tld c,%d\n"
            "L%d:\n\tld b,0\n\tld hl,%s\n"
            "L%d:\n\tld a,(hl)\n\tcp c\n\tjp z, L%d\n"
            "\tinc hl\n\tinc b\n\tld a,b\n\tcp %d\n\tjp c, L%d\n"
            "\tld hl,%d\n\tjp L%d\n"
            "L%d:\n",
            plan->side_offset, plan->side_offset + 1,
            plan->white, black,
            plan->white_king, initialized,
            black, plan->black_king,
            initialized, board_name,
            loop, found,
            plan->bound, loop,
            plan->missing_result, exit,
            found);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\txor a\n\tsub l\n\tld l,a\n"
            "\tld a,0\n\tsbc a,h\n\tld h,a\n\tpush hl\n"
            "\tld l,b\n\tld h,0\n\tpush hl\n"
            "\tcall %s\n\tpop bc\n\tpop bc\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            plan->side_offset, plan->side_offset + 1,
            attack_name, exit);
}

static void mir_emit_piece_position(
    FILE *out, const struct MirPiecePosition *plan)
{
    const char *center_name =
        asm_name_for(sym_asm_name(plan->center_function));
    int folded = new_label();
    int rank_ready = new_label();
    int pawn = new_label();
    int knight = new_label();
    int bishop = new_label();
    int queen = new_label();
    int rook = new_label();
    int king = new_label();
    int knight_done = new_label();
    int bishop_done = new_label();
    int king_done = new_label();
    int exit = new_label();

    fprintf(out,
            "\tld a,(ix%+d)\n"
            "\tcp 97\n\tjp c, L%d\n\tcp 123\n\tjp nc, L%d\n"
            "\tsub 32\n"
            "L%d:\n\tld (ix-1),a\n",
            plan->piece_offset, folded, folded, folded);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
            plan->square_offset, plan->square_offset + 1);
    mir_emit_scalar_shift_by_constant(out, TOK_SHR, 0, 3);
    fputs("\tld (ix-3),l\n\tld (ix-2),h\n", out);
    fprintf(out,
            "\tld a,(ix%+d)\n\tcp 97\n\tjp c, L%d\n"
            "\tcp 123\n\tjp nc, L%d\n"
            "\tld hl,7\n\tld e,(ix-3)\n\tld d,(ix-2)\n"
            "\tor a\n\tsbc hl,de\n"
            "\tld (ix-3),l\n\tld (ix-2),h\n"
            "L%d:\n",
            plan->piece_offset, rank_ready,
            rank_ready, rank_ready);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tpush hl\n"
            "\tcall %s\n\tpop bc\n"
            "\tld (ix-5),l\n\tld (ix-4),h\n"
            "\tld a,(ix-1)\n"
            "\tcp 80\n\tjp z, L%d\n"
            "\tcp 78\n\tjp z, L%d\n"
            "\tcp 66\n\tjp z, L%d\n"
            "\tcp 81\n\tjp z, L%d\n"
            "\tcp 82\n\tjp z, L%d\n"
            "\tcp 75\n\tjp z, L%d\n"
            "\tld hl,0\n\tjp L%d\n",
            plan->square_offset, plan->square_offset + 1,
            center_name,
            pawn, knight, bishop, queen, rook, king, exit);

    fprintf(out,
            "L%d:\n"
            "\tld l,(ix-3)\n\tld h,(ix-2)\n"
            "\tld e,l\n\tld d,h\n\tadd hl,hl\n\tadd hl,hl\n\tadd hl,de\n"
            "\tld e,(ix-5)\n\tld d,(ix-4)\n\tadd hl,de\n\tjp L%d\n",
            pawn, exit);

    fprintf(out,
            "L%d:\n"
            "\tld l,(ix-5)\n\tld h,(ix-4)\n"
            "\tadd hl,hl\n\tadd hl,hl\n\tadd hl,hl\n"
            "\tbit 7,(ix-2)\n\tjp nz, L%d\n"
            "\tld a,(ix-3)\n\tor (ix-2)\n\tjp z, L%d\n"
            "\tld de,20\n\tadd hl,de\n"
            "L%d:\n\tjp L%d\n",
            knight, knight_done, knight_done, knight_done, exit);

    fprintf(out,
            "L%d:\n"
            "\tld l,(ix-5)\n\tld h,(ix-4)\n"
            "\tadd hl,hl\n\tadd hl,hl\n"
            "\tbit 7,(ix-2)\n\tjp nz, L%d\n"
            "\tld a,(ix-3)\n\tor (ix-2)\n\tjp z, L%d\n"
            "\tld de,15\n\tadd hl,de\n"
            "L%d:\n\tjp L%d\n",
            bishop, bishop_done, bishop_done, bishop_done, exit);

    fprintf(out,
            "L%d:\n\tld l,(ix-5)\n\tld h,(ix-4)\n\tjp L%d\n"
            "L%d:\n\tld hl,0\n\tjp L%d\n",
            queen, exit, rook, exit);

    fprintf(out,
            "L%d:\n"
            "\tld l,(ix-5)\n\tld h,(ix-4)\n"
            "\tadd hl,hl\n\tadd hl,hl\n"
            "\txor a\n\tsub l\n\tld l,a\n"
            "\tld a,0\n\tsbc a,h\n\tld h,a\n"
            "\tbit 7,(ix-2)\n\tjp nz, L%d\n"
            "\tld a,(ix-3)\n\tor (ix-2)\n\tjp z, L%d\n"
            "\tld de,80\n\tor a\n\tsbc hl,de\n"
            "L%d:\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            king, king_done, king_done, king_done, exit);
}

static void mir_emit_slider_attack(
    FILE *out, const struct MirSliderAttack *plan)
{
    const char *board_name =
        asm_name_for(sym_asm_name(plan->board));
    int loop = new_label();
    int distance_ok = new_label();
    int occupied = new_label();
    int lowercase = new_label();
    int compare_side = new_label();
    int side_ready = new_label();
    int matching_side = new_label();
    int folded = new_label();
    int hit = new_label();
    int advance = new_label();
    int miss = new_label();
    int exit = new_label();

    if ((plan->board->storage == SC_EXTERN ||
         plan->board->needs_extrn) &&
        mir_extrn_should_emit(plan->board))
        fprintf(out, "\textrn %s\n", board_name);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n\tadd hl,de\n"
            "\tld c,l\n\tld b,h\n"
            "L%d:\n"
            "\tbit 7,b\n\tjp nz, L%d\n"
            "\tld a,b\n\tor a\n\tjp nz, L%d\n"
            "\tld a,c\n\tcp 64\n\tjp nc, L%d\n"
            "\tld l,c\n\tld h,b\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "\tor a\n\tsbc hl,de\n"
            "\tld a,l\n\tand 7\n\tld (ix-1),a\n"
            "\tld a,c\n\tand 7\n\tsub (ix-1)\n"
            "\tjp nc, L%d\n\tneg\n"
            "L%d:\n\tcp 2\n\tjp nc, L%d\n"
            "\tld hl,%s\n\tld e,c\n\tld d,b\n\tadd hl,de\n"
            "\tld a,(hl)\n\tcp 46\n\tjp nz, L%d\n\tjp L%d\n",
            plan->square_offset, plan->square_offset + 1,
            plan->direction_offset, plan->direction_offset + 1,
            loop,
            miss, miss, miss,
            plan->direction_offset, plan->direction_offset + 1,
            distance_ok, distance_ok, miss,
            board_name,
            occupied, advance);
    fprintf(out,
            "L%d:\n\tld (ix-2),a\n"
            "\tcp 65\n\tjp c, L%d\n\tcp 91\n\tjp nc, L%d\n"
            "\tld hl,1\n\tjp L%d\n"
            "L%d:\n\tcp 97\n\tjp c, L%d\n"
            "\tcp 123\n\tjp nc, L%d\n"
            "\tld hl,65535\n\tjp L%d\n"
            "L%d:\n\tld hl,0\n"
            "L%d:\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "\tor a\n\tsbc hl,de\n\tjp nz, L%d\n"
            "L%d:\n"
            "\tld a,(ix-2)\n\tcp 97\n\tjp c, L%d\n"
            "\tcp 123\n\tjp nc, L%d\n\tsub 32\n"
            "L%d:\n"
            "\tcp (ix%+d)\n\tjp z, L%d\n"
            "\tcp (ix%+d)\n\tjp z, L%d\n\tjp L%d\n",
            occupied,
            lowercase, lowercase,
            side_ready,
            lowercase, compare_side, compare_side,
            side_ready,
            compare_side,
            side_ready,
            plan->side_offset, plan->side_offset + 1,
            miss,
            matching_side,
            folded, folded, folded,
            plan->first_piece_offset, hit,
            plan->second_piece_offset, hit, miss);
    fprintf(out,
            "L%d:\n\tld hl,1\n\tjp L%d\n"
            "L%d:\n"
            "\tld l,c\n\tld h,b\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n\tadd hl,de\n"
            "\tld c,l\n\tld b,h\n\tjp L%d\n"
            "L%d:\n\tld hl,0\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            hit, exit,
            advance,
            plan->direction_offset, plan->direction_offset + 1,
            loop,
            miss,
            exit);
}

static void mir_emit_frame_long_load(
    FILE *out, int offset)
{
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
            offset, offset + 1, offset + 2, offset + 3);
}

static void mir_emit_frame_long_store(
    FILE *out, int offset)
{
    fprintf(out,
            "\tld (ix%+d),l\n\tld (ix%+d),h\n"
            "\tld (ix%+d),e\n\tld (ix%+d),d\n",
            offset, offset + 1, offset + 2, offset + 3);
}

static void mir_emit_pointer_long_load(
    FILE *out, int pointer_offset)
{
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n\tinc hl\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tld l,c\n\tld h,b\n",
            pointer_offset, pointer_offset + 1);
}

static void mir_emit_pointer_long_store(
    FILE *out, int pointer_offset)
{
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
            pointer_offset, pointer_offset + 1);
    fputs("\tpop bc\n\tld (hl),c\n\tinc hl\n\tld (hl),b\n\tinc hl\n"
          "\tpop bc\n\tld (hl),c\n\tinc hl\n\tld (hl),b\n", out);
}

static void mir_emit_frame_pointer_adjust(
    FILE *out, int offset, int amount)
{
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tld de,%d\n",
            offset, offset + 1,
            amount < 0 ? -amount : amount);
    if (amount < 0)
        fputs("\tor a\n\tsbc hl,de\n", out);
    else
        fputs("\tadd hl,de\n", out);
    fprintf(out, "\tld (ix%+d),l\n\tld (ix%+d),h\n",
            offset, offset + 1);
}

static void mir_emit_symbol_extrn(FILE *out, struct Sym *symbol)
{
    const char *name = asm_name_for(sym_asm_name(symbol));

    if ((symbol->storage == SC_EXTERN || symbol->needs_extrn) &&
        mir_extrn_should_emit(symbol))
        fprintf(out, "\textrn %s\n", name);
}

static void mir_emit_symbol_call(FILE *out, struct Sym *symbol)
{
    const char *name = asm_name_for(sym_asm_name(symbol));

    mir_emit_symbol_extrn(out, symbol);
    fprintf(out, "\tcall %s\n", name);
}

static void mir_emit_resolved_symbol_call(
    FILE *out, struct Sym *symbol, const char *name)
{
    if ((symbol == NULL || symbol->needs_extrn) &&
        mir_extrn_should_emit_name(name))
        fprintf(out, "\textrn %s\n", name);
    fprintf(out, "\tcall %s\n", name);
}

static void mir_emit_copy_frame_word(
    FILE *out, int destination_offset, int source_offset)
{
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld (ix%+d),l\n\tld (ix%+d),h\n",
            source_offset, source_offset + 1,
            destination_offset, destination_offset + 1);
}

static void mir_emit_sign_extend_hl_to_de(FILE *out)
{
    fputs("\tld a,h\n\trlca\n\tsbc a,a\n\tld d,a\n\tld e,a\n",
          out);
}

static void mir_emit_signed_long_constant_branch(
    FILE *out, int offset, unsigned long constant_bits,
    int branch_if_less, int true_label, int false_label)
{
    int byte;

    fprintf(out,
            "\tld a,(ix%+d)\n\txor 128\n\tcp %lu\n",
            offset + 3,
            ((constant_bits >> 24) & 0xffUL) ^ 0x80UL);
    if (branch_if_less)
        fprintf(out, "\tjp c, L%d\n\tjp nz, L%d\n",
                true_label, false_label);
    else
        fprintf(out, "\tjp c, L%d\n\tjp nz, L%d\n",
                false_label, true_label);
    for (byte = 2; byte >= 0; --byte) {
        fprintf(out,
                "\tld a,(ix%+d)\n\tcp %lu\n",
                offset + byte,
                (constant_bits >> (byte * 8)) & 0xffUL);
        if (byte != 0) {
            if (branch_if_less)
                fprintf(out, "\tjp c, L%d\n\tjp nz, L%d\n",
                        true_label, false_label);
            else
                fprintf(out, "\tjp c, L%d\n\tjp nz, L%d\n",
                        false_label, true_label);
        } else if (branch_if_less) {
            fprintf(out, "\tjp c, L%d\n\tjp L%d\n",
                    true_label, false_label);
        } else {
            fprintf(out, "\tjp c, L%d\n\tjp nz, L%d\n\tjp L%d\n",
                    false_label, true_label, false_label);
        }
    }
}

static void mir_emit_long_clamp(
    FILE *out, const struct MirLongClamp *plan)
{
    int below_maximum = new_label();
    int above_minimum = new_label();
    int maximum = new_label();
    int minimum = new_label();
    int done = new_label();

    mir_emit_signed_long_constant_branch(
        out, plan->parameter_offset, plan->maximum_bits,
        0, maximum, below_maximum);
    fprintf(out, "L%d:\n", below_maximum);
    mir_emit_signed_long_constant_branch(
        out, plan->parameter_offset, plan->minimum_bits,
        1, minimum, above_minimum);
    fprintf(out,
            "L%d:\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tjp L%d\n"
            "L%d:\n\tld hl,%d\n\tjp L%d\n"
            "L%d:\n\tld hl,%d\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            above_minimum,
            plan->parameter_offset, plan->parameter_offset + 1,
            done,
            maximum, plan->maximum_result, done,
            minimum, plan->minimum_result,
            done);
}

static void mir_emit_long_q8_value(
    FILE *out, int offset, const struct MirLongQ8Spec *conversion)
{
    int below_upper = new_label();
    int above_lower = new_label();
    int nonnegative = new_label();
    int no_carry = new_label();
    int upper = new_label();
    int lower = new_label();
    int done = new_label();

    mir_emit_signed_long_constant_branch(
        out, offset, conversion->upper_bits,
        0, upper, below_upper);
    fprintf(out, "L%d:\n", below_upper);
    mir_emit_signed_long_constant_branch(
        out, offset, conversion->lower_bits,
        1, lower, above_lower);
    fprintf(out,
            "L%d:\n\tbit 7,(ix%+d)\n\tjp z, L%d\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld e,(ix%+d)\n"
            "\tld bc,%d\n\tadd hl,bc\n\tjp nc, L%d\n\tinc e\n"
            "L%d:\n\tld l,h\n\tld h,e\n\tjp L%d\n"
            "L%d:\n\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tjp L%d\n"
            "L%d:\n\tld hl,%d\n\tjp L%d\n"
            "L%d:\n\tld hl,%d\n"
            "L%d:\n",
            above_lower, offset + 3, nonnegative,
            offset, offset + 1, offset + 2,
            (1 << conversion->shift) - 1, no_carry,
            no_carry, done,
            nonnegative, offset + conversion->shift / 8,
            offset + conversion->shift / 8 + 1, done,
            upper, conversion->upper_result, done,
            lower, conversion->lower_result,
            done);
}

static void mir_emit_long_q8(
    FILE *out, const struct MirLongQ8 *plan)
{
    mir_emit_long_q8_value(
        out, plan->parameter_offset, &plan->conversion);
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_pointer_word_and_advance(
    FILE *out, int pointer_offset)
{
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n\tinc hl\n"
            "\tld (ix%+d),l\n\tld (ix%+d),h\n"
            "\tld l,c\n\tld h,b\n",
            pointer_offset, pointer_offset + 1,
            pointer_offset, pointer_offset + 1);
}

static void mir_emit_signed_pointer_product(
    FILE *out, int left_pointer_offset, int right_pointer_offset)
{
    mir_emit_pointer_word_and_advance(out, left_pointer_offset);
    mir_emit_sign_extend_hl_to_de(out);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_pointer_word_and_advance(out, right_pointer_offset);
    mir_emit_sign_extend_hl_to_de(out);
    fputs("\tpop bc\n\tpop de\n", out);
    mir_emit_runtime_call(out, "__m1s");
}

static void mir_emit_q8_accumulate(
    FILE *out, int matrix_pointer_offset, int scalar_offset,
    int output_pointer_offset, struct Sym *q16_function,
    struct Sym *clamp_function)
{
    mir_emit_pointer_word_and_advance(out, matrix_pointer_offset);
    mir_emit_sign_extend_hl_to_de(out);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
            scalar_offset, scalar_offset + 1);
    mir_emit_sign_extend_hl_to_de(out);
    fputs("\tpop bc\n\tpop de\n", out);
    mir_emit_runtime_call(out, "__m1s");
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_symbol_call(out, q16_function);
    fputs("\tpop bc\n\tpop bc\n", out);

    mir_emit_sign_extend_hl_to_de(out);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
            "\tld l,c\n\tld h,b\n",
            output_pointer_offset, output_pointer_offset + 1);
    mir_emit_sign_extend_hl_to_de(out);
    fputs("\tpop bc\n\tadd hl,bc\n\tex de,hl\n"
          "\tpop bc\n\tadc hl,bc\n\tex de,hl\n"
          "\tpush de\n\tpush hl\n", out);
    mir_emit_symbol_call(out, clamp_function);
    fputs("\tpop bc\n\tpop bc\n\tex de,hl\n", out);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld (hl),e\n\tinc hl\n\tld (hl),d\n\tinc hl\n"
            "\tld (ix%+d),l\n\tld (ix%+d),h\n",
            output_pointer_offset, output_pointer_offset + 1,
            output_pointer_offset, output_pointer_offset + 1);
}

static void mir_emit_fixed_q8_multiply(
    FILE *out, const struct MirFixedQ8Multiply *plan)
{
    enum {
        MATRIX_POINTER = -2,
        INPUT_POINTER = -4,
        OUTPUT_BASE = -6,
        SCALAR_VALUE = -8,
        OUTPUT_POINTER = -10,
        OUTER_COUNT = -11,
        INNER_COUNT = -12
    };
    int zero_loop = new_label();
    int outer_loop = new_label();
    int inner_loop = new_label();

    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld (ix%d),l\n\tld (ix%d),h\n",
            plan->matrix_offset, plan->matrix_offset + 1,
            MATRIX_POINTER, MATRIX_POINTER + 1);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld (ix%d),l\n\tld (ix%d),h\n",
            plan->input_offset, plan->input_offset + 1,
            INPUT_POINTER, INPUT_POINTER + 1);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld (ix%d),l\n\tld (ix%d),h\n"
            "\tld b,%d\n\txor a\n"
            "L%d:\n\tld (hl),a\n\tinc hl\n\tdjnz L%d\n"
            "\tld (ix%d),%d\n"
            "L%d:\n",
            plan->output_offset, plan->output_offset + 1,
            OUTPUT_BASE, OUTPUT_BASE + 1,
            plan->columns * 2,
            zero_loop, zero_loop,
            OUTER_COUNT, plan->rows,
            outer_loop);
    mir_emit_pointer_word_and_advance(out, INPUT_POINTER);
    fprintf(out,
            "\tld (ix%d),l\n\tld (ix%d),h\n",
            SCALAR_VALUE, SCALAR_VALUE + 1);
    mir_emit_copy_frame_word(out, OUTPUT_POINTER, OUTPUT_BASE);
    fprintf(out,
            "\tld (ix%d),%d\n"
            "L%d:\n",
            INNER_COUNT, plan->columns,
            inner_loop);
    mir_emit_q8_accumulate(
        out, MATRIX_POINTER, SCALAR_VALUE, OUTPUT_POINTER,
        plan->q16_function, plan->clamp_function);
    fprintf(out,
            "\tdec (ix%d)\n\tjp nz, L%d\n"
            "\tdec (ix%d)\n\tjp nz, L%d\n"
            "\tld sp,ix\n\tpop ix\n\tret\n",
            INNER_COUNT, inner_loop,
            OUTER_COUNT, outer_loop);
}

static void mir_emit_attention_score(
    FILE *out, const struct MirAttentionScore *plan)
{
    enum {
        QUERY_POINTER = -2,
        KEY_POINTER = -4,
        ACCUMULATOR = -8,
        LOOP_COUNT = -9
    };
    int loop = new_label();

    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld (ix%d),l\n\tld (ix%d),h\n",
            plan->query_offset, plan->query_offset + 1,
            QUERY_POINTER, QUERY_POINTER + 1);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld (ix%d),l\n\tld (ix%d),h\n"
            "\tld hl,0\n\tld de,0\n",
            plan->key_offset, plan->key_offset + 1,
            KEY_POINTER, KEY_POINTER + 1);
    mir_emit_frame_long_store(out, ACCUMULATOR);
    fprintf(out,
            "\tld (ix%d),%d\n"
            "L%d:\n",
            LOOP_COUNT, plan->dimension, loop);
    mir_emit_signed_pointer_product(
        out, QUERY_POINTER, KEY_POINTER);
    fprintf(out,
            "\tld c,(ix%d)\n\tld b,(ix%d)\n\tadd hl,bc\n"
            "\tex de,hl\n"
            "\tld c,(ix%d)\n\tld b,(ix%d)\n\tadc hl,bc\n"
            "\tex de,hl\n",
            ACCUMULATOR, ACCUMULATOR + 1,
            ACCUMULATOR + 2, ACCUMULATOR + 3);
    mir_emit_frame_long_store(out, ACCUMULATOR);
    fprintf(out,
            "\tdec (ix%d)\n\tjp nz, L%d\n",
            LOOP_COUNT, loop);
    mir_emit_long_q8_value(
        out, ACCUMULATOR, &plan->conversion);
    mir_emit_scalar_shift_by_constant(
        out, TOK_SHR, 0, plan->output_shift);
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_symbol_address_to_frame(
    FILE *out, struct Sym *symbol, int byte_offset, int frame_offset)
{
    const char *name = asm_name_for(sym_asm_name(symbol));

    mir_emit_symbol_extrn(out, symbol);
    if (byte_offset == 0)
        fprintf(out, "\tld hl,%s\n", name);
    else
        fprintf(out, "\tld hl,%s+%d\n", name, byte_offset);
    fprintf(out,
            "\tld (ix%+d),l\n\tld (ix%+d),h\n",
            frame_offset, frame_offset + 1);
}

static void mir_emit_project_all_qkv(
    FILE *out, const struct MirProjectAllQkv *plan)
{
    enum {
        INPUT_POINTER = -2,
        QUERY_OUTPUT = -4,
        KEY_OUTPUT = -6,
        VALUE_OUTPUT = -8,
        QUERY_MATRIX = -10,
        KEY_MATRIX = -12,
        VALUE_MATRIX = -14,
        SCALAR_VALUE = -16,
        QUERY_CURSOR = -18,
        KEY_CURSOR = -20,
        VALUE_CURSOR = -22,
        ROW_COUNT = -23,
        INPUT_COUNT = -24,
        OUTPUT_COUNT = -25
    };
    const char *workspace_name =
        asm_name_for(sym_asm_name(plan->workspace));
    int zero_bytes = plan->zero_elements * 2;
    int row_loop = new_label();
    int input_loop = new_label();
    int output_loop = new_label();

    mir_emit_symbol_extrn(out, plan->workspace);
    fprintf(out, "\tld hl,%s\n\tld (hl),0\n", workspace_name);
    if (zero_bytes > 1)
        fprintf(out,
                "\tld de,%s+1\n\tld bc,%d\n\tldir\n",
                workspace_name, zero_bytes - 1);

    mir_emit_symbol_address_to_frame(
        out, plan->embeddings, 0, INPUT_POINTER);
    mir_emit_symbol_address_to_frame(
        out, plan->workspace, plan->query_offset * 2, QUERY_OUTPUT);
    mir_emit_symbol_address_to_frame(
        out, plan->workspace, plan->key_offset * 2, KEY_OUTPUT);
    mir_emit_symbol_address_to_frame(
        out, plan->workspace, plan->value_offset * 2, VALUE_OUTPUT);
    fprintf(out,
            "\tld (ix%d),%d\n"
            "L%d:\n",
            ROW_COUNT, plan->rows, row_loop);
    mir_emit_symbol_address_to_frame(
        out, plan->query_weights, 0, QUERY_MATRIX);
    mir_emit_symbol_address_to_frame(
        out, plan->key_weights, 0, KEY_MATRIX);
    mir_emit_symbol_address_to_frame(
        out, plan->value_weights, 0, VALUE_MATRIX);
    fprintf(out,
            "\tld (ix%d),%d\n"
            "L%d:\n",
            INPUT_COUNT, plan->dimension, input_loop);
    mir_emit_pointer_word_and_advance(out, INPUT_POINTER);
    fprintf(out,
            "\tld (ix%d),l\n\tld (ix%d),h\n",
            SCALAR_VALUE, SCALAR_VALUE + 1);
    mir_emit_copy_frame_word(out, QUERY_CURSOR, QUERY_OUTPUT);
    mir_emit_copy_frame_word(out, KEY_CURSOR, KEY_OUTPUT);
    mir_emit_copy_frame_word(out, VALUE_CURSOR, VALUE_OUTPUT);
    fprintf(out,
            "\tld (ix%d),%d\n"
            "L%d:\n",
            OUTPUT_COUNT, plan->dimension, output_loop);
    mir_emit_q8_accumulate(
        out, QUERY_MATRIX, SCALAR_VALUE, QUERY_CURSOR,
        plan->q16_function, plan->clamp_function);
    mir_emit_q8_accumulate(
        out, KEY_MATRIX, SCALAR_VALUE, KEY_CURSOR,
        plan->q16_function, plan->clamp_function);
    mir_emit_q8_accumulate(
        out, VALUE_MATRIX, SCALAR_VALUE, VALUE_CURSOR,
        plan->q16_function, plan->clamp_function);
    fprintf(out,
            "\tdec (ix%d)\n\tjp nz, L%d\n"
            "\tdec (ix%d)\n\tjp nz, L%d\n",
            OUTPUT_COUNT, output_loop,
            INPUT_COUNT, input_loop);
    mir_emit_frame_pointer_adjust(
        out, QUERY_OUTPUT, plan->dimension * 2);
    mir_emit_frame_pointer_adjust(
        out, KEY_OUTPUT, plan->dimension * 2);
    mir_emit_frame_pointer_adjust(
        out, VALUE_OUTPUT, plan->dimension * 2);
    fprintf(out,
            "\tdec (ix%d)\n\tjp nz, L%d\n"
            "\tld sp,ix\n\tpop ix\n\tret\n",
            ROW_COUNT, row_loop);
}

static void mir_emit_assign_pre_offset(
    FILE *out, const struct MirAssignPre *plan,
    int symbol_pointer_offset, int index_offset, int scale)
{
    int indexed = new_label();
    int ready = new_label();

    fprintf(out,
            "\tld l,(ix%d)\n\tld h,(ix%d)\n"
            "\tld de,%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tld hl,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp nz, L%d\n"
            "\tld hl,0\n\tjp L%d\n"
            "L%d:\n\tld l,(ix%d)\n\tld h,(ix%d)\n"
            "L%d:\n",
            symbol_pointer_offset, symbol_pointer_offset + 1,
            plan->kind_offset,
            plan->scalar_kind,
            indexed,
            ready,
            indexed, index_offset, index_offset + 1,
            ready);
    if (scale == 2)
        fputs("\tadd hl,hl\n", out);
    fputs("\tex de,hl\n", out);
    fprintf(out,
            "\tld l,(ix%d)\n\tld h,(ix%d)\n"
            "\tld bc,%d\n\tadd hl,bc\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
            "\tld h,b\n\tld l,c\n\tadd hl,de\n",
            symbol_pointer_offset, symbol_pointer_offset + 1,
            plan->base_offset);
}

static void mir_emit_assign_pre(
    FILE *out, const struct MirAssignPre *plan)
{
    enum {
        SYMBOL_INDEX = -2,
        RESOLVED_INDEX = -4,
        VALUE = -6,
        SYMBOL_POINTER = -8,
        MEMORY_OFFSET = -10
    };
    const char *symbols_name =
        asm_name_for(sym_asm_name(plan->symbols));
    const char *memory_name =
        asm_name_for(sym_asm_name(plan->memory));
    const char *capacity_name =
        asm_name_for(sym_asm_name(plan->memory_capacity));
    int zero_index = new_label();
    int index_ready = new_label();
    int word_store = new_label();
    int bounds_error = new_label();
    int done = new_label();

    mir_emit_symbol_extrn(out, plan->symbols);
    mir_emit_symbol_extrn(out, plan->memory);
    mir_emit_symbol_extrn(out, plan->memory_capacity);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld (ix%d),l\n\tld (ix%d),h\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tbit 7,h\n\tjp nz, L%d\n\tpush hl\n",
            plan->symbol_index_offset,
            plan->symbol_index_offset + 1,
            SYMBOL_INDEX, SYMBOL_INDEX + 1,
            plan->expression_index_offset,
            plan->expression_index_offset + 1,
            zero_index);
    mir_emit_symbol_call(out, plan->evaluate_function);
    fprintf(out,
            "\tpop bc\n\tjp L%d\n"
            "L%d:\n\tld hl,0\n"
            "L%d:\n\tld (ix%d),l\n\tld (ix%d),h\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tpush hl\n",
            index_ready,
            zero_index,
            index_ready, RESOLVED_INDEX, RESOLVED_INDEX + 1,
            plan->rhs_expression_offset,
            plan->rhs_expression_offset + 1);
    mir_emit_symbol_call(out, plan->evaluate_function);
    fprintf(out,
            "\tpop bc\n\tld (ix%d),l\n\tld (ix%d),h\n"
            "\tld l,(ix%d)\n\tld h,(ix%d)\n",
            VALUE, VALUE + 1,
            SYMBOL_INDEX, SYMBOL_INDEX + 1);
    mir_emit_mul_hl_const(out, (unsigned long)plan->symbol_stride);
    fprintf(out,
            "\tex de,hl\n\tld hl,(%s)\n\tadd hl,de\n"
            "\tld (ix%d),l\n\tld (ix%d),h\n"
            "\tld de,%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tld hl,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp nz, L%d\n",
            symbols_name,
            SYMBOL_POINTER, SYMBOL_POINTER + 1,
            plan->type_offset,
            plan->byte_type,
            word_store);

    mir_emit_assign_pre_offset(
        out, plan, SYMBOL_POINTER, RESOLVED_INDEX, 1);
    fprintf(out,
            "\tex de,hl\n\tld hl,(%s)\n\tadd hl,de\n"
            "\tld a,(ix%d)\n\tld (hl),a\n\tjp L%d\n"
            "L%d:\n",
            memory_name, VALUE, done,
            word_store);

    mir_emit_assign_pre_offset(
        out, plan, SYMBOL_POINTER, RESOLVED_INDEX, plan->cell_size);
    fprintf(out,
            "\tld (ix%d),l\n\tld (ix%d),h\n"
            "\tbit 7,h\n\tjp nz, L%d\n"
            "\tinc hl\n\tld de,(%s)\n"
            "\tor a\n\tsbc hl,de\n\tjp nc, L%d\n"
            "\tld e,(ix%d)\n\tld d,(ix%d)\n"
            "\tld hl,(%s)\n\tadd hl,de\n"
            "\tld e,(ix%d)\n\tld d,(ix%d)\n"
            "\tld (hl),e\n\tinc hl\n\tld (hl),d\n"
            "\tjp L%d\n"
            "L%d:\n\tld hl,S%d\n\tpush hl\n",
            MEMORY_OFFSET, MEMORY_OFFSET + 1,
            bounds_error,
            capacity_name,
            bounds_error,
            MEMORY_OFFSET, MEMORY_OFFSET + 1,
            memory_name,
            VALUE, VALUE + 1,
            done,
            bounds_error, plan->bounds_string);
    mir_emit_symbol_call(out, plan->die_function);
    fprintf(out,
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            done);
}

enum MirForthFrameOffset {
    MIR_FORTH_CODE = -2,
    MIR_FORTH_MEMORY = -4,
    MIR_FORTH_STACK = -6,
    MIR_FORTH_CALL_STACK = -8,
    MIR_FORTH_LOOP_INDEX = -10,
    MIR_FORTH_LOOP_LIMIT = -12,
    MIR_FORTH_LOOP_PREVIOUS = -14,
    MIR_FORTH_SP = -16,
    MIR_FORTH_CRP = -18,
    MIR_FORTH_LRP = -20,
    MIR_FORTH_LOOP_TOP = -22,
    MIR_FORTH_MEMORY_CAPACITY = -24,
    MIR_FORTH_TEMP_A = -26,
    MIR_FORTH_TEMP_B = -28,
    MIR_FORTH_TEMP_C = -30,
    MIR_FORTH_TEMP_N = -32
};

static void mir_emit_forth_frame_load(FILE *out, int offset)
{
    fprintf(out,
            "\tld l,(ix%d)\n\tld h,(ix%d)\n",
            offset, offset + 1);
}

static void mir_emit_forth_frame_store(FILE *out, int offset)
{
    fprintf(out,
            "\tld (ix%d),l\n\tld (ix%d),h\n",
            offset, offset + 1);
}

static void mir_emit_forth_state_member_load(
    FILE *out, const char *state_name, int member_offset, int frame_offset)
{
    fprintf(out,
            "\tld hl,(%s)\n\tld de,%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tld (ix%d),e\n\tld (ix%d),d\n",
            state_name, member_offset,
            frame_offset, frame_offset + 1);
}

static void mir_emit_forth_state_member_store(
    FILE *out, const char *state_name, int member_offset, int frame_offset)
{
    fprintf(out,
            "\tld hl,(%s)\n\tld de,%d\n\tadd hl,de\n"
            "\tld c,(ix%d)\n\tld b,(ix%d)\n"
            "\tld (hl),c\n\tinc hl\n\tld (hl),b\n",
            state_name, member_offset,
            frame_offset, frame_offset + 1);
}

static void mir_emit_forth_sync_state(
    FILE *out, const struct MirForthRun *plan, const char *state_name)
{
    mir_emit_forth_state_member_store(
        out, state_name, plan->stack_pointer_offset, MIR_FORTH_SP);
    mir_emit_forth_state_member_store(
        out, state_name, plan->call_pointer_offset, MIR_FORTH_CRP);
    mir_emit_forth_state_member_store(
        out, state_name, plan->loop_pointer_offset, MIR_FORTH_LRP);
    mir_emit_forth_state_member_store(
        out, state_name, plan->loop_top_offset, MIR_FORTH_LOOP_TOP);
}

static void mir_emit_forth_reload_state(
    FILE *out, const struct MirForthRun *plan, const char *state_name)
{
    mir_emit_forth_state_member_load(
        out, state_name, plan->stack_pointer_offset, MIR_FORTH_SP);
    mir_emit_forth_state_member_load(
        out, state_name, plan->call_pointer_offset, MIR_FORTH_CRP);
    mir_emit_forth_state_member_load(
        out, state_name, plan->loop_pointer_offset, MIR_FORTH_LRP);
    mir_emit_forth_state_member_load(
        out, state_name, plan->loop_top_offset, MIR_FORTH_LOOP_TOP);
}

static void mir_emit_forth_stack_address(
    FILE *out, int stack_offset, int stack_pointer_offset, int adjustment)
{
    int step;

    mir_emit_forth_frame_load(out, stack_pointer_offset);
    for (step = 0; step < adjustment; ++step)
        fputs("\tinc hl\n", out);
    for (step = 0; step > adjustment; --step)
        fputs("\tdec hl\n", out);
    fputs("\tadd hl,hl\n\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, stack_offset);
    fputs("\tadd hl,de\n", out);
}

static void mir_emit_forth_push_hl(FILE *out)
{
    fputs("\tpush hl\n", out);
    mir_emit_forth_stack_address(
        out, MIR_FORTH_STACK, MIR_FORTH_SP, 0);
    fputs("\tpop de\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_SP);
    fputs("\tinc hl\n", out);
    mir_emit_forth_frame_store(out, MIR_FORTH_SP);
}

static void mir_emit_forth_pop_hl(FILE *out)
{
    mir_emit_forth_frame_load(out, MIR_FORTH_SP);
    fputs("\tdec hl\n", out);
    mir_emit_forth_frame_store(out, MIR_FORTH_SP);
    fputs("\tadd hl,hl\n\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_STACK);
    fputs("\tadd hl,de\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tex de,hl\n", out);
}

static void mir_emit_forth_load_stack_hl(FILE *out, int adjustment)
{
    mir_emit_forth_stack_address(
        out, MIR_FORTH_STACK, MIR_FORTH_SP, adjustment);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n", out);
}

static void mir_emit_forth_store_stack_hl(FILE *out, int adjustment)
{
    fputs("\tpush hl\n", out);
    mir_emit_forth_stack_address(
        out, MIR_FORTH_STACK, MIR_FORTH_SP, adjustment);
    fputs("\tpop de\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
}

static void mir_emit_forth_local_array_address(
    FILE *out, int base_offset, int index_offset, int adjustment)
{
    mir_emit_forth_frame_load(out, index_offset);
    if (adjustment < 0)
        while (adjustment++ < 0)
            fputs("\tdec hl\n", out);
    else
        while (adjustment-- > 0)
            fputs("\tinc hl\n", out);
    fputs("\tadd hl,hl\n\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, base_offset);
    fputs("\tadd hl,de\n", out);
}

static void mir_emit_forth_instruction_argument(
    FILE *out, const struct MirForthRun *plan)
{
    fprintf(out,
            "\tld l,(iy%+d)\n\tld h,(iy%+d)\n",
            plan->instruction_argument_offset,
            plan->instruction_argument_offset + 1);
}

static void mir_emit_forth_signed_less_branch(
    FILE *out, int true_label, int false_label)
{
    int high_equal = new_label();

    fprintf(out,
            "\tld a,h\n\txor 128\n\tld b,a\n"
            "\tld a,d\n\txor 128\n\tcp b\n"
            "\tjp z, L%d\n\tjp c, L%d\n\tjp L%d\n"
            "L%d:\n\tld a,l\n\tcp e\n\tjp c, L%d\n\tjp L%d\n",
            high_equal, false_label, true_label,
            high_equal, true_label, false_label);
}

static void mir_emit_forth_die(
    FILE *out, const struct MirForthRun *plan, int string_id)
{
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", string_id);
    mir_emit_symbol_call(out, plan->die_function);
}

static void mir_emit_forth_run(
    FILE *out, const struct MirForthRun *plan)
{
    const char *state_name =
        asm_name_for(sym_asm_name(plan->state));
    int cases[42];
    int dispatch = new_label();
    int table = new_label();
    int next = new_label();
    int set_pc = new_label();
    int sync_exit = new_label();
    int return_stack_error = new_label();
    int loop_stack_error = new_label();
    int bad_address = new_label();
    int bad_fill = new_label();
    int bad_opcode = new_label();
    int item;

    for (item = 0; item < plan->opcode_count; ++item)
        cases[item] = new_label();
    mir_emit_symbol_extrn(out, plan->state);
    mir_emit_symbol_extrn(out, plan->print_function);
    mir_emit_symbol_extrn(out, plan->putchar_function);

    mir_emit_forth_state_member_load(
        out, state_name, plan->code_offset, MIR_FORTH_CODE);
    mir_emit_forth_state_member_load(
        out, state_name, plan->memory_offset, MIR_FORTH_MEMORY);
    mir_emit_forth_state_member_load(
        out, state_name, plan->stack_offset, MIR_FORTH_STACK);
    mir_emit_forth_state_member_load(
        out, state_name, plan->call_stack_offset, MIR_FORTH_CALL_STACK);
    mir_emit_forth_state_member_load(
        out, state_name, plan->loop_index_offset, MIR_FORTH_LOOP_INDEX);
    mir_emit_forth_state_member_load(
        out, state_name, plan->loop_limit_offset, MIR_FORTH_LOOP_LIMIT);
    mir_emit_forth_state_member_load(
        out, state_name, plan->loop_previous_offset,
        MIR_FORTH_LOOP_PREVIOUS);
    mir_emit_forth_state_member_load(
        out, state_name, plan->stack_pointer_offset, MIR_FORTH_SP);
    mir_emit_forth_state_member_load(
        out, state_name, plan->call_pointer_offset, MIR_FORTH_CRP);
    mir_emit_forth_state_member_load(
        out, state_name, plan->loop_pointer_offset, MIR_FORTH_LRP);
    mir_emit_forth_state_member_load(
        out, state_name, plan->loop_top_offset, MIR_FORTH_LOOP_TOP);
    mir_emit_forth_state_member_load(
        out, state_name, plan->memory_capacity_offset,
        MIR_FORTH_MEMORY_CAPACITY);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tadd hl,hl\n\tadd hl,hl\n\tex de,hl\n",
            plan->pc_offset + 2, plan->pc_offset + 3);
    mir_emit_forth_frame_load(out, MIR_FORTH_CODE);
    fprintf(out,
            "\tadd hl,de\n\tpush hl\n\tpop iy\n"
            "L%d:\n"
            "\tld a,(iy%+d)\n\tor a\n\tjp nz, L%d\n"
            "\tld a,(iy%+d)\n\tcp %d\n\tjp nc, L%d\n"
            "\tld l,a\n\tld h,0\n\tadd hl,hl\n"
            "\tld de,L%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n\tjp (hl)\n"
            "L%d:\n",
            dispatch,
            plan->instruction_op_offset + 1, bad_opcode,
            plan->instruction_op_offset, plan->opcode_count, bad_opcode,
            table, table);
    for (item = 0; item < plan->opcode_count; ++item)
        fprintf(out, "\tdw L%d\n", cases[item]);

    /* OP_HALT */
    fprintf(out, "L%d:\n\tjp L%d\n", cases[0], sync_exit);

    /* OP_LIT */
    fprintf(out, "L%d:\n", cases[1]);
    mir_emit_forth_instruction_argument(out, plan);
    mir_emit_forth_push_hl(out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_CALL */
    fprintf(out, "L%d:\n", cases[2]);
    mir_emit_forth_frame_load(out, MIR_FORTH_CRP);
    fprintf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp nc, L%d\n"
            "\tpush iy\n\tpop hl\n\tld de,%d\n\tadd hl,de\n\tpush hl\n",
            plan->return_stack_limit, return_stack_error,
            plan->instruction_size);
    mir_emit_forth_local_array_address(
        out, MIR_FORTH_CALL_STACK, MIR_FORTH_CRP, 0);
    fputs("\tpop de\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_CRP);
    fputs("\tinc hl\n", out);
    mir_emit_forth_frame_store(out, MIR_FORTH_CRP);
    mir_emit_forth_instruction_argument(out, plan);
    fprintf(out, "\tjp L%d\n", set_pc);

    /* OP_RET */
    fprintf(out, "L%d:\n", cases[3]);
    mir_emit_forth_frame_load(out, MIR_FORTH_CRP);
    fprintf(out,
            "\tld a,h\n\tor a\n\tjp m, L%d\n"
            "\tor l\n\tjp z, L%d\n\tdec hl\n",
            sync_exit, sync_exit);
    mir_emit_forth_frame_store(out, MIR_FORTH_CRP);
    mir_emit_forth_local_array_address(
        out, MIR_FORTH_CALL_STACK, MIR_FORTH_CRP, 0);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tpush de\n\tpop iy\n", out);
    fprintf(out, "\tjp L%d\n", dispatch);

    /* OP_JMP */
    fprintf(out, "L%d:\n", cases[4]);
    mir_emit_forth_instruction_argument(out, plan);
    fprintf(out, "\tjp L%d\n", set_pc);

    /* OP_JZ */
    fprintf(out, "L%d:\n", cases[5]);
    mir_emit_forth_pop_hl(out);
    fprintf(out,
            "\tld a,h\n\tor l\n\tjp nz, L%d\n",
            next);
    mir_emit_forth_instruction_argument(out, plan);
    fprintf(out, "\tjp L%d\n", set_pc);

    /* OP_DO */
    fprintf(out, "L%d:\n", cases[6]);
    mir_emit_forth_pop_hl(out);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
    mir_emit_forth_pop_hl(out);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_B);
    mir_emit_forth_frame_load(out, MIR_FORTH_LRP);
    fprintf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n\tjp nc, L%d\n",
            plan->return_stack_limit, loop_stack_error);
    mir_emit_forth_local_array_address(
        out, MIR_FORTH_LOOP_INDEX, MIR_FORTH_LRP, 0);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
    fputs("\tex de,hl\n\tpop hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
          out);
    mir_emit_forth_local_array_address(
        out, MIR_FORTH_LOOP_LIMIT, MIR_FORTH_LRP, 0);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_B);
    fputs("\tex de,hl\n\tpop hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
          out);
    mir_emit_forth_local_array_address(
        out, MIR_FORTH_LOOP_PREVIOUS, MIR_FORTH_LRP, 0);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_LOOP_TOP);
    fputs("\tex de,hl\n\tpop hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
          out);
    mir_emit_forth_frame_load(out, MIR_FORTH_LRP);
    mir_emit_forth_frame_store(out, MIR_FORTH_LOOP_TOP);
    fputs("\tinc hl\n", out);
    mir_emit_forth_frame_store(out, MIR_FORTH_LRP);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_LOOP */
    {
        int loop_continue = new_label();
        int loop_done = new_label();

        fprintf(out, "L%d:\n", cases[7]);
        mir_emit_forth_frame_load(out, MIR_FORTH_LRP);
        fputs("\tdec hl\n", out);
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
        mir_emit_forth_local_array_address(
            out, MIR_FORTH_LOOP_INDEX, MIR_FORTH_TEMP_A, 0);
        fputs("\tpush hl\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
              "\tex de,hl\n\tinc hl\n\tex de,hl\n"
              "\tpop hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n"
              "\tex de,hl\n", out);
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_B);
        mir_emit_forth_local_array_address(
            out, MIR_FORTH_LOOP_LIMIT, MIR_FORTH_TEMP_A, 0);
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n", out);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_B);
        mir_emit_forth_signed_less_branch(
            out, loop_continue, loop_done);
        fprintf(out, "L%d:\n", loop_continue);
        mir_emit_forth_instruction_argument(out, plan);
        fprintf(out, "\tjp L%d\n", set_pc);
        fprintf(out, "L%d:\n", loop_done);
        mir_emit_forth_local_array_address(
            out, MIR_FORTH_LOOP_PREVIOUS, MIR_FORTH_TEMP_A, 0);
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n", out);
        mir_emit_forth_frame_store(out, MIR_FORTH_LOOP_TOP);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
        mir_emit_forth_frame_store(out, MIR_FORTH_LRP);
        fprintf(out, "\tjp L%d\n", next);
    }

    /* OP_I */
    fprintf(out, "L%d:\n", cases[8]);
    mir_emit_forth_local_array_address(
        out, MIR_FORTH_LOOP_INDEX, MIR_FORTH_LOOP_TOP, 0);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n", out);
    mir_emit_forth_push_hl(out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_PSTR is emitted with the I/O cases below. */

    /* OP_PRIM */
    fprintf(out, "L%d:\n", cases[10]);
    mir_emit_forth_sync_state(out, plan, state_name);
    fputs("\tpush iy\n", out);
    mir_emit_forth_instruction_argument(out, plan);
    fputs("\tpush hl\n", out);
    mir_emit_symbol_call(out, plan->primitive_function);
    fputs("\tpop bc\n\tpop iy\n", out);
    mir_emit_forth_reload_state(out, plan, state_name);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_FETCHA */
    fprintf(out, "L%d:\n", cases[11]);
    mir_emit_forth_instruction_argument(out, plan);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY);
    fputs("\tadd hl,de\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tex de,hl\n", out);
    mir_emit_forth_push_hl(out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_STOREA */
    fprintf(out, "L%d:\n", cases[12]);
    mir_emit_forth_pop_hl(out);
    fputs("\tpush hl\n", out);
    mir_emit_forth_instruction_argument(out, plan);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY);
    fputs("\tadd hl,de\n\tpop de\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
          out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_CFETCHA */
    fprintf(out, "L%d:\n", cases[13]);
    mir_emit_forth_instruction_argument(out, plan);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY);
    fputs("\tadd hl,de\n\tld l,(hl)\n\tld h,0\n", out);
    mir_emit_forth_push_hl(out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_CSTOREA */
    fprintf(out, "L%d:\n", cases[14]);
    mir_emit_forth_pop_hl(out);
    fputs("\tpush hl\n", out);
    mir_emit_forth_instruction_argument(out, plan);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY);
    fputs("\tadd hl,de\n\tpop de\n\tld (hl),e\n", out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_ADDSTOREA */
    fprintf(out, "L%d:\n", cases[15]);
    mir_emit_forth_pop_hl(out);
    fputs("\tpush hl\n", out);
    mir_emit_forth_instruction_argument(out, plan);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY);
    fputs("\tadd hl,de\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tex de,hl\n\tpop de\n\tadd hl,de\n\tpush hl\n", out);
    mir_emit_forth_instruction_argument(out, plan);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY);
    fputs("\tadd hl,de\n\tpop de\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
          out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_DUP */
    fprintf(out, "L%d:\n", cases[16]);
    mir_emit_forth_load_stack_hl(out, -1);
    mir_emit_forth_push_hl(out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_DROP */
    fprintf(out, "L%d:\n", cases[17]);
    mir_emit_forth_frame_load(out, MIR_FORTH_SP);
    fputs("\tdec hl\n", out);
    mir_emit_forth_frame_store(out, MIR_FORTH_SP);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_SWAP */
    fprintf(out, "L%d:\n", cases[18]);
    mir_emit_forth_load_stack_hl(out, -1);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
    mir_emit_forth_load_stack_hl(out, -2);
    mir_emit_forth_store_stack_hl(out, -1);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
    mir_emit_forth_store_stack_hl(out, -2);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_OVER */
    fprintf(out, "L%d:\n", cases[19]);
    mir_emit_forth_load_stack_hl(out, -2);
    mir_emit_forth_push_hl(out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_ROT */
    fprintf(out, "L%d:\n", cases[20]);
    mir_emit_forth_load_stack_hl(out, -3);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
    mir_emit_forth_load_stack_hl(out, -2);
    mir_emit_forth_store_stack_hl(out, -3);
    mir_emit_forth_load_stack_hl(out, -1);
    mir_emit_forth_store_stack_hl(out, -2);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
    mir_emit_forth_store_stack_hl(out, -1);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_ADD */
    fprintf(out, "L%d:\n", cases[21]);
    mir_emit_forth_pop_hl(out);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_B);
    mir_emit_forth_load_stack_hl(out, -1);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_B);
    fputs("\tex de,hl\n\tpop hl\n", out);
    fputs("\tadd hl,de\n", out);
    mir_emit_forth_store_stack_hl(out, -1);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_SUB */
    fprintf(out, "L%d:\n", cases[22]);
    mir_emit_forth_pop_hl(out);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_B);
    mir_emit_forth_load_stack_hl(out, -1);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_B);
    fputs("\tex de,hl\n\tpop hl\n", out);
    fputs("\tor a\n\tsbc hl,de\n", out);
    mir_emit_forth_store_stack_hl(out, -1);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_MUL */
    fprintf(out, "L%d:\n", cases[23]);
    mir_emit_forth_pop_hl(out);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_B);
    mir_emit_forth_load_stack_hl(out, -1);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_B);
    fputs("\tex de,hl\n\tpop hl\n", out);
    mir_emit_runtime_call(out, "__mulu");
    mir_emit_forth_store_stack_hl(out, -1);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_DIVMOD */
    {
        int divide = new_label();
        int finish = new_label();

        fprintf(out, "L%d:\n", cases[24]);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_B);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_B);
        fprintf(out,
                "\tld a,h\n\tor l\n\tjp nz, L%d\n"
                "\tld hl,0\n",
                divide);
        mir_emit_forth_push_hl(out);
        fputs("\tld hl,0\n", out);
        mir_emit_forth_push_hl(out);
        fprintf(out, "\tjp L%d\nL%d:\n", finish, divide);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_B);
        fputs("\tex de,hl\n", out);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
        mir_emit_runtime_call(out, "__sdivmod");
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
        fputs("\tex de,hl\n", out);
        mir_emit_forth_push_hl(out);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
        mir_emit_forth_push_hl(out);
        fprintf(out, "L%d:\n\tjp L%d\n", finish, next);
    }

    /* OP_MOD */
    {
        int modulo = new_label();
        int finish = new_label();

        fprintf(out, "L%d:\n", cases[25]);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_B);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_B);
        fprintf(out,
                "\tld a,h\n\tor l\n\tjp nz, L%d\n"
                "\tld hl,0\n\tjp L%d\n"
                "L%d:\n\tex de,hl\n",
                modulo, finish, modulo);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
        mir_emit_runtime_call(out, "__mods");
        fprintf(out, "L%d:\n", finish);
        mir_emit_forth_push_hl(out);
        fprintf(out, "\tjp L%d\n", next);
    }

    /* OP_EQ / OP_NE */
    for (item = 26; item <= 27; ++item) {
        int true_label = new_label();
        int done_label = new_label();

        fprintf(out, "L%d:\n", cases[item]);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_B);
        mir_emit_forth_load_stack_hl(out, -1);
        fputs("\tpush hl\n", out);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_B);
        fputs("\tex de,hl\n\tpop hl\n", out);
        fputs("\tor a\n\tsbc hl,de\n", out);
        fprintf(out,
                "\tjp %s, L%d\n\tld hl,0\n\tjp L%d\n"
                "L%d:\n\tld hl,1\nL%d:\n",
                item == 26 ? "z" : "nz", true_label,
                done_label, true_label, done_label);
        mir_emit_forth_store_stack_hl(out, -1);
        fprintf(out, "\tjp L%d\n", next);
    }

    /* OP_LT / OP_GT */
    for (item = 28; item <= 29; ++item) {
        int true_label = new_label();
        int false_label = new_label();
        int done_label = new_label();

        fprintf(out, "L%d:\n", cases[item]);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_B);
        mir_emit_forth_load_stack_hl(out, -1);
        fputs("\tpush hl\n", out);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_B);
        if (item == 28) {
            fputs("\tex de,hl\n\tpop hl\n", out);
        } else {
            fputs("\tpop de\n", out);
        }
        mir_emit_forth_signed_less_branch(
            out, true_label, false_label);
        fprintf(out,
                "L%d:\n\tld hl,1\n\tjp L%d\n"
                "L%d:\n\tld hl,0\n"
                "L%d:\n",
                true_label, done_label,
                false_label, done_label);
        mir_emit_forth_store_stack_hl(out, -1);
        fprintf(out, "\tjp L%d\n", next);
    }

    /* OP_AND / OP_OR */
    for (item = 30; item <= 31; ++item) {
        fprintf(out, "L%d:\n", cases[item]);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_B);
        mir_emit_forth_load_stack_hl(out, -1);
        fputs("\tpush hl\n", out);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_B);
        fputs("\tex de,hl\n\tpop hl\n", out);
        if (item == 30)
            fputs("\tld a,l\n\tand e\n\tld l,a\n"
                  "\tld a,h\n\tand d\n\tld h,a\n", out);
        else
            fputs("\tld a,l\n\tor e\n\tld l,a\n"
                  "\tld a,h\n\tor d\n\tld h,a\n", out);
        mir_emit_forth_store_stack_hl(out, -1);
        fprintf(out, "\tjp L%d\n", next);
    }

    /* OP_INVERT */
    {
        int zero = new_label();
        int done_label = new_label();

        fprintf(out, "L%d:\n", cases[32]);
        mir_emit_forth_load_stack_hl(out, -1);
        fprintf(out,
                "\tld a,h\n\tor l\n\tjp z, L%d\n"
                "\tld hl,0\n\tjp L%d\n"
                "L%d:\n\tld hl,1\nL%d:\n",
                zero, done_label, zero, done_label);
        mir_emit_forth_store_stack_hl(out, -1);
        fprintf(out, "\tjp L%d\n", next);
    }

    /* OP_FETCH */
    fprintf(out, "L%d:\n", cases[33]);
    mir_emit_forth_load_stack_hl(out, -1);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
    fprintf(out, "\tbit 7,h\n\tjp nz, L%d\n\tinc hl\n", bad_address);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY_CAPACITY);
    fputs("\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp c, L%d\n\tjp z, L%d\n",
            bad_address, bad_address);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY);
    fputs("\tadd hl,de\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tex de,hl\n", out);
    mir_emit_forth_store_stack_hl(out, -1);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_STORE */
    fprintf(out, "L%d:\n", cases[34]);
    mir_emit_forth_pop_hl(out);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
    fprintf(out, "\tbit 7,h\n\tjp nz, L%d\n\tinc hl\n", bad_address);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY_CAPACITY);
    fputs("\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp c, L%d\n\tjp z, L%d\n",
            bad_address, bad_address);
    mir_emit_forth_pop_hl(out);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY);
    fputs("\tadd hl,de\n\tpop de\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
          out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_CFETCH */
    fprintf(out, "L%d:\n", cases[35]);
    mir_emit_forth_load_stack_hl(out, -1);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
    fprintf(out, "\tbit 7,h\n\tjp nz, L%d\n", bad_address);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY_CAPACITY);
    fputs("\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp c, L%d\n\tjp z, L%d\n", bad_address, bad_address);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY);
    fputs("\tadd hl,de\n\tld l,(hl)\n\tld h,0\n", out);
    mir_emit_forth_store_stack_hl(out, -1);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_CSTORE */
    fprintf(out, "L%d:\n", cases[36]);
    mir_emit_forth_pop_hl(out);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
    fprintf(out, "\tbit 7,h\n\tjp nz, L%d\n", bad_address);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY_CAPACITY);
    fputs("\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp c, L%d\n\tjp z, L%d\n", bad_address, bad_address);
    mir_emit_forth_pop_hl(out);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY);
    fputs("\tadd hl,de\n\tpop de\n\tld (hl),e\n", out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_ADDSTORE */
    fprintf(out, "L%d:\n", cases[37]);
    mir_emit_forth_pop_hl(out);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
    fprintf(out, "\tbit 7,h\n\tjp nz, L%d\n\tinc hl\n", bad_address);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY_CAPACITY);
    fputs("\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp c, L%d\n\tjp z, L%d\n",
            bad_address, bad_address);
    mir_emit_forth_pop_hl(out);
    mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_B);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY);
    fputs("\tadd hl,de\n\tpush hl\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tex de,hl\n", out);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_B);
    fputs("\tadd hl,de\n\tex de,hl\n\tpop hl\n"
          "\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_FILL */
    {
        int fill_bounds_ok = new_label();

        fprintf(out, "L%d:\n", cases[38]);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_C);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_N);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, MIR_FORTH_TEMP_A);
        fprintf(out, "\tbit 7,h\n\tjp nz, L%d\n", bad_fill);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_N);
        fprintf(out, "\tbit 7,h\n\tjp nz, L%d\n", bad_fill);
        fputs("\tex de,hl\n", out);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
        fputs("\tadd hl,de\n", out);
        fprintf(out, "\tjp c, L%d\n", bad_fill);
        fputs("\tex de,hl\n", out);
        mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY_CAPACITY);
        fputs("\tor a\n\tsbc hl,de\n", out);
        fprintf(out,
                "\tjp c, L%d\n"
                "L%d:\n",
                bad_fill, fill_bounds_ok);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_A);
        fputs("\tex de,hl\n", out);
        mir_emit_forth_frame_load(out, MIR_FORTH_MEMORY);
        fputs("\tadd hl,de\n\tpush hl\n", out);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_C);
        fputs("\tld e,l\n\tld d,0\n", out);
        mir_emit_forth_frame_load(out, MIR_FORTH_TEMP_N);
        fputs("\tld b,h\n\tld c,l\n\tpop hl\n", out);
        mir_emit_runtime_call(out, "__msf");
        fprintf(out, "\tjp L%d\n", next);
    }

    /* OP_DOT */
    fprintf(out, "L%d:\n", cases[39]);
    mir_emit_forth_pop_hl(out);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", plan->number_format_string);
    mir_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n\tpop bc\n", out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_CR */
    fprintf(out,
            "L%d:\n\tld hl,S%d\n\tpush hl\n",
            cases[40], plan->newline_string);
    mir_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n", out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_EMIT */
    fprintf(out, "L%d:\n", cases[41]);
    mir_emit_forth_pop_hl(out);
    fputs("\tpush hl\n", out);
    mir_emit_symbol_call(out, plan->putchar_function);
    fputs("\tpop bc\n", out);
    fprintf(out, "\tjp L%d\n", next);

    /* OP_PSTR */
    fprintf(out,
            "L%d:\n\tld hl,(%s)\n\tld de,%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n\tpush hl\n",
            cases[9], state_name, plan->strings_offset);
    mir_emit_forth_instruction_argument(out, plan);
    fputs("\tadd hl,hl\n\tex de,hl\n\tpop hl\n\tadd hl,de\n"
          "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tpush de\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", plan->string_format_string);
    mir_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n\tpop bc\n", out);
    fprintf(out, "\tjp L%d\n", next);

    fprintf(out,
            "L%d:\n",
            next);
    for (item = 0; item < plan->instruction_size; ++item)
        fputs("\tinc iy\n", out);
    fprintf(out,
            "\tjp L%d\n"
            "L%d:\n"
            "\tadd hl,hl\n\tadd hl,hl\n\tex de,hl\n",
            dispatch,
            set_pc);
    mir_emit_forth_frame_load(out, MIR_FORTH_CODE);
    fprintf(out,
            "\tadd hl,de\n\tpush hl\n\tpop iy\n\tjp L%d\n"
            "L%d:\n",
            dispatch,
            sync_exit);
    mir_emit_forth_sync_state(out, plan, state_name);
    fputs("\tld sp,ix\n\tpop ix\n\tpop iy\n\tret\n", out);

    fprintf(out, "L%d:\n", return_stack_error);
    mir_emit_forth_die(out, plan, plan->return_stack_string);
    fprintf(out, "\tjp L%d\nL%d:\n", sync_exit, loop_stack_error);
    mir_emit_forth_die(out, plan, plan->loop_stack_string);
    fprintf(out, "\tjp L%d\nL%d:\n", sync_exit, bad_address);
    mir_emit_forth_die(out, plan, plan->bad_address_string);
    fprintf(out, "\tjp L%d\nL%d:\n", sync_exit, bad_fill);
    mir_emit_forth_die(out, plan, plan->bad_fill_string);
    fprintf(out, "\tjp L%d\nL%d:\n", sync_exit, bad_opcode);
    mir_emit_forth_die(out, plan, plan->bad_opcode_string);
    fprintf(out, "\tjp L%d\n", sync_exit);
}

static void mir_emit_global_byte_verify(
    FILE *out, const struct MirGlobalByteVerify *plan)
{
    const char *buffer_name =
        asm_name_for(sym_asm_name(plan->buffer));
    int loop = new_label();
    int mismatch = new_label();
    int done = new_label();

    mir_emit_symbol_extrn(out, plan->buffer);
    fprintf(out,
            "\tld c,(ix%+d)\n\tld b,(ix%+d)\n"
            "\tbit 7,b\n\tjp nz, L%d\n"
            "\tld a,b\n\tor c\n\tjp z, L%d\n"
            "\tld a,(ix%+d)\n\tld hl,%s\n"
            "L%d:\n\tcpi\n\tjp nz, L%d\n\tjp pe, L%d\n\tjp L%d\n"
            "L%d:\n\tdec hl\n\tld l,(hl)\n\tld h,0\n\tpush hl\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tor a\n\tsbc hl,bc\n\tdec hl\n\tpush hl\n"
            "\tld l,(ix%+d)\n\tld h,0\n\tpush hl\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tpush hl\n"
            "\tld hl,S%d\n\tpush hl\n",
            plan->size_offset, plan->size_offset + 1,
            done, done,
            plan->value_offset, buffer_name,
            loop, mismatch, loop, done,
            mismatch,
            plan->size_offset, plan->size_offset + 1,
            plan->value_offset,
            plan->size_offset, plan->size_offset + 1,
            plan->format_string);
    mir_emit_runtime_call(out, "__pfehx");
    mir_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n\tpop bc\n\tpop bc\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", plan->failure_string);
    mir_emit_symbol_call(out, plan->fail_function);
    fprintf(out,
            "\tpop bc\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            done);
}

static void mir_emit_e_digits(FILE *out, const struct MirEDigits *plan)
{
    enum {
        ARRAY_POINTER = -2,
        OUTER_COUNT = -4,
        ACCUMULATOR = -6,
        INNER_INDEX = -8,
        REMAINDER = -10
    };
    int frame_bytes = plan->digits + 10;
    int outer = new_label();
    int inner = new_label();
    int print_digit = new_label();
    int done = new_label();

    fputs("\tpush ix\n\tpop hl\n", out);
    fprintf(out,
            "\tld de,-%d\n\tadd hl,de\n"
            "\tld (ix%d),l\n\tld (ix%d),h\n"
            "\tinc hl\n\tld (hl),1\n"
            "\tld d,h\n\tld e,l\n\tinc de\n\tld bc,%d\n\tldir\n",
            frame_bytes,
            ARRAY_POINTER, ARRAY_POINTER + 1,
            plan->digits - 2);
    mir_emit_forth_frame_load(out, ARRAY_POINTER);
    fputs("\tld (hl),0\n\tinc hl\n\tld (hl),2\n", out);
    fprintf(out,
            "\tld hl,%d\n", plan->digits);
    mir_emit_forth_frame_store(out, OUTER_COUNT);
    fputs("\tld hl,0\n", out);
    mir_emit_forth_frame_store(out, ACCUMULATOR);
    fprintf(out, "L%d:\n", outer);
    mir_emit_forth_frame_load(out, OUTER_COUNT);
    fprintf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp c, L%d\n\tjp z, L%d\n",
            plan->outer_limit, done, done);
    mir_emit_forth_frame_load(out, OUTER_COUNT);
    mir_emit_forth_frame_store(out, INNER_INDEX);
    fputs("\tdec hl\n", out);
    mir_emit_forth_frame_store(out, OUTER_COUNT);
    fprintf(out, "L%d:\n", inner);
    mir_emit_forth_frame_load(out, INNER_INDEX);
    fputs("\tdec hl\n", out);
    mir_emit_forth_frame_store(out, INNER_INDEX);
    fprintf(out,
            "\tld a,h\n\tor l\n\tjp z, L%d\n"
            "\tex de,hl\n",
            print_digit);
    mir_emit_forth_frame_load(out, ACCUMULATOR);
    mir_emit_runtime_call(out, "__udivmod");
    mir_emit_forth_frame_store(out, ACCUMULATOR);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_store(out, REMAINDER);

    mir_emit_forth_frame_load(out, INNER_INDEX);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, ARRAY_POINTER);
    fputs("\tadd hl,de\n\tpush hl\n", out);
    mir_emit_forth_frame_load(out, REMAINDER);
    fputs("\tld a,l\n\tpop hl\n\tld (hl),a\n", out);

    mir_emit_forth_frame_load(out, INNER_INDEX);
    fputs("\tdec hl\n\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, ARRAY_POINTER);
    fputs("\tadd hl,de\n\tld l,(hl)\n\tld h,0\n", out);
    mir_emit_mul_hl_const(out, (unsigned long)plan->radix);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, ACCUMULATOR);
    fputs("\tex de,hl\n\tpop hl\n\tadd hl,de\n", out);
    mir_emit_forth_frame_store(out, ACCUMULATOR);
    fprintf(out, "\tjp L%d\n", inner);

    fprintf(out, "L%d:\n", print_digit);
    mir_emit_forth_frame_load(out, ACCUMULATOR);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", plan->digit_format_string);
    mir_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n\tpop bc\n", out);
    fprintf(out, "\tjp L%d\nL%d:\n", outer, done);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", plan->done_string);
    mir_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n\tld hl,0\n\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_float_matrix_multiply(
    FILE *out, const struct MirFloatMatrixMultiply *plan)
{
    enum {
        LEFT_ROW = -2,
        RESULT_ROW = -4,
        RESULT_POINTER = -6,
        LEFT_POINTER = -8,
        RIGHT_COLUMN = -12,
        ROW_COUNT = -13,
        COLUMN_COUNT = -14,
        INNER_COUNT = -15
    };
    const char *left_name =
        asm_name_for(sym_asm_name(plan->left));
    const char *right_name =
        asm_name_for(sym_asm_name(plan->right));
    const char *result_name =
        asm_name_for(sym_asm_name(plan->result));
    int row_loop = new_label();
    int column_loop = new_label();
    int inner_loop = new_label();

    mir_emit_symbol_extrn(out, plan->left);
    mir_emit_symbol_extrn(out, plan->right);
    mir_emit_symbol_extrn(out, plan->result);
    fprintf(out,
            "\tld hl,%s\n", left_name);
    mir_emit_forth_frame_store(out, LEFT_ROW);
    fprintf(out, "\tld hl,%s\n", result_name);
    mir_emit_forth_frame_store(out, RESULT_ROW);
    fprintf(out,
            "\tld (ix%d),%d\n"
            "L%d:\n",
            ROW_COUNT, plan->dimension,
            row_loop);
    mir_emit_copy_frame_word(out, RESULT_POINTER, RESULT_ROW);
    fprintf(out, "\tld hl,%s\n", right_name);
    mir_emit_forth_frame_store(out, RIGHT_COLUMN);
    fprintf(out,
            "\tld (ix%d),%d\n"
            "L%d:\n",
            COLUMN_COUNT, plan->dimension,
            column_loop);
    mir_emit_copy_frame_word(out, LEFT_POINTER, LEFT_ROW);
    mir_emit_forth_frame_load(out, RIGHT_COLUMN);
    fputs("\tpush hl\n\tpop iy\n", out);
    fprintf(out,
            "\tld (ix%d),%d\n"
            "L%d:\n",
            INNER_COUNT, plan->dimension,
            inner_loop);
    mir_emit_pointer_long_load(out, RESULT_POINTER);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out,
            "\tld l,(ix%d)\n\tld h,(ix%d)\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n\tinc hl\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tinc hl\n"
            "\tld (ix%d),l\n\tld (ix%d),h\n"
            "\tld l,c\n\tld h,b\n",
            LEFT_POINTER, LEFT_POINTER + 1,
            LEFT_POINTER, LEFT_POINTER + 1);
    fputs("\tpush de\n\tpush hl\n", out);
    fputs("\tld l,(iy+0)\n\tld h,(iy+1)\n"
          "\tld e,(iy+2)\n\tld d,(iy+3)\n", out);
    mir_emit_runtime_call(out, "__fmaf");
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n\tpop bc\n", out);
    mir_emit_pointer_long_store(out, RESULT_POINTER);
    fprintf(out, "\tld de,%d\n\tadd iy,de\n", plan->row_stride);
    fprintf(out,
            "\tdec (ix%d)\n\tjp nz, L%d\n",
            INNER_COUNT, inner_loop);
    mir_emit_frame_pointer_adjust(
        out, RESULT_POINTER, plan->element_size);
    mir_emit_frame_pointer_adjust(
        out, RIGHT_COLUMN, plan->element_size);
    fprintf(out,
            "\tdec (ix%d)\n\tjp nz, L%d\n",
            COLUMN_COUNT, column_loop);
    mir_emit_frame_pointer_adjust(
        out, LEFT_ROW, plan->row_stride);
    mir_emit_frame_pointer_adjust(
        out, RESULT_ROW, plan->row_stride);
    fprintf(out,
            "\tdec (ix%d)\n\tjp nz, L%d\n"
            "\tld sp,ix\n\tpop ix\n\tpop iy\n\tret\n",
            ROW_COUNT, row_loop);
}

static void mir_emit_fixed_float_zero(
    FILE *out, const struct MirFixedFloatZero *plan)
{
    const char *array_name =
        asm_name_for(sym_asm_name(plan->array));
    int bytes = plan->rows * plan->row_stride;

    mir_emit_symbol_extrn(out, plan->array);
    fprintf(out,
            "\tld hl,%s\n\tld (hl),0\n"
            "\tld de,%s+1\n\tld bc,%d\n\tldir\n\tret\n",
            array_name, array_name, bytes - 1);
}

static void mir_emit_float_sum(
    FILE *out, const struct MirFloatSum *plan)
{
    const char *array_name =
        asm_name_for(sym_asm_name(plan->array));
    const char *accumulator_name =
        asm_name_for(sym_asm_name(plan->accumulator));
    int loop = new_label();

    mir_emit_symbol_extrn(out, plan->array);
    mir_emit_symbol_extrn(out, plan->accumulator);
    fprintf(out,
            "\tld hl,%s\n\tpush hl\n\tpop iy\n"
            "\tld hl,%d\n\tld (ix-2),l\n\tld (ix-1),h\n"
            "L%d:\n"
            "\tld hl,(%s)\n\tld de,(%s+2)\n"
            "\tpush de\n\tpush hl\n"
            "\tld l,(iy+0)\n\tld h,(iy+1)\n"
            "\tld e,(iy+2)\n\tld d,(iy+3)\n",
            array_name, plan->count, loop,
            accumulator_name, accumulator_name);
    mir_emit_runtime_call(out, "__faf");
    fprintf(out,
            "\tpop bc\n\tpop bc\n"
            "\tld (%s),hl\n\tld (%s+2),de\n"
            "\tinc iy\n\tinc iy\n\tinc iy\n\tinc iy\n"
            "\tld l,(ix-2)\n\tld h,(ix-1)\n\tdec hl\n"
            "\tld (ix-2),l\n\tld (ix-1),h\n"
            "\tld a,h\n\tor l\n\tjp nz, L%d\n"
            "\tld sp,ix\n\tpop ix\n\tpop iy\n\tret\n",
            accumulator_name, accumulator_name, loop);
}

static void mir_emit_basic_global_to_frame(
    FILE *out, struct Sym *symbol, int frame_offset)
{
    const char *name = asm_name_for(sym_asm_name(symbol));

    mir_emit_symbol_extrn(out, symbol);
    fprintf(out,
            "\tld hl,(%s)\n\tld (ix%d),l\n\tld (ix%d),h\n",
            name, frame_offset, frame_offset + 1);
}

static void mir_emit_basic_frame_to_global(
    FILE *out, struct Sym *symbol, int frame_offset)
{
    const char *name = asm_name_for(sym_asm_name(symbol));

    mir_emit_symbol_extrn(out, symbol);
    fprintf(out,
            "\tld l,(ix%d)\n\tld h,(ix%d)\n\tld (%s),hl\n",
            frame_offset, frame_offset + 1, name);
}

static void mir_emit_basic_scaled_address(
    FILE *out, int base_offset, int scale)
{
    mir_emit_mul_hl_const(out, (unsigned long)scale);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, base_offset);
    fputs("\tadd hl,de\n", out);
}

static void mir_emit_basic_instruction_word(FILE *out, int offset)
{
    fprintf(out,
            "\tld l,(iy%+d)\n\tld h,(iy%+d)\n",
            offset, offset + 1);
}

static void mir_emit_basic_die(
    FILE *out, const struct MirBasicRun *plan, int string_id)
{
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", string_id);
    mir_emit_symbol_call(out, plan->die_function);
}

static void mir_emit_basic_push_hl(FILE *out)
{
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FORTH_SP);
    fputs("\tpop de\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n\tinc hl\n", out);
    mir_emit_forth_frame_store(out, MIR_FORTH_SP);
}

static void mir_emit_basic_pop_hl(FILE *out)
{
    mir_emit_forth_frame_load(out, MIR_FORTH_SP);
    fputs("\tdec hl\n\tdec hl\n", out);
    mir_emit_forth_frame_store(out, MIR_FORTH_SP);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n", out);
}

#define mir_emit_forth_push_hl mir_emit_basic_push_hl
#define mir_emit_forth_pop_hl mir_emit_basic_pop_hl
static void mir_emit_basic_run(
    FILE *out, const struct MirBasicRun *plan)
{
    enum {
        BASIC_CODE = MIR_FORTH_CODE,
        BASIC_MEMORY = MIR_FORTH_MEMORY,
        BASIC_STACK = MIR_FORTH_STACK,
        BASIC_GOSUB_STACK = MIR_FORTH_CALL_STACK,
        BASIC_FOR_STACK = MIR_FORTH_LOOP_INDEX,
        BASIC_SYMBOLS = MIR_FORTH_LOOP_LIMIT,
        BASIC_STRINGS = MIR_FORTH_LOOP_PREVIOUS,
        BASIC_SP = MIR_FORTH_SP,
        BASIC_GSP = MIR_FORTH_CRP,
        BASIC_FSP = MIR_FORTH_LRP,
        BASIC_TEMP_A = MIR_FORTH_TEMP_A,
        BASIC_TEMP_B = MIR_FORTH_TEMP_B,
        BASIC_TEMP_C = MIR_FORTH_TEMP_C,
        BASIC_TEMP_N = MIR_FORTH_TEMP_N
    };
    int cases[30];
    int dispatch = new_label();
    int table = new_label();
    int next = new_label();
    int set_pc = new_label();
    int exit_label = new_label();
    int bad_opcode = new_label();
    int gosub_full = new_label();
    int gosub_empty = new_label();
    int for_full = new_label();
    int next_empty = new_label();
    int item;

    for (item = 0; item < plan->opcode_count; ++item)
        cases[item] = new_label();
    mir_emit_basic_global_to_frame(out, plan->code, BASIC_CODE);
    mir_emit_basic_global_to_frame(out, plan->memory, BASIC_MEMORY);
    mir_emit_basic_global_to_frame(out, plan->stack, BASIC_STACK);
    mir_emit_basic_global_to_frame(
        out, plan->gosub_stack, BASIC_GOSUB_STACK);
    mir_emit_basic_global_to_frame(out, plan->for_stack, BASIC_FOR_STACK);
    mir_emit_basic_global_to_frame(out, plan->symbols, BASIC_SYMBOLS);
    mir_emit_basic_global_to_frame(out, plan->strings, BASIC_STRINGS);
    mir_emit_basic_global_to_frame(out, plan->stack_pointer, BASIC_SP);
    mir_emit_forth_frame_load(out, BASIC_SP);
    fputs("\tadd hl,hl\n\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, BASIC_STACK);
    fputs("\tadd hl,de\n", out);
    mir_emit_forth_frame_store(out, BASIC_SP);
    mir_emit_basic_global_to_frame(out, plan->gosub_pointer, BASIC_GSP);
    mir_emit_basic_global_to_frame(out, plan->for_pointer, BASIC_FSP);
    mir_emit_forth_frame_load(out, BASIC_CODE);
    fprintf(out,
            "\tpush hl\n\tpop iy\n"
            "L%d:\n\tld a,(iy%+d)\n\tcp %d\n\tjp nc, L%d\n"
            "\tld l,a\n\tld h,0\n\tadd hl,hl\n"
            "\tld de,L%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n\tjp (hl)\n"
            "L%d:\n",
            dispatch, plan->instruction_op_offset,
            plan->opcode_count, bad_opcode,
            table, table);
    for (item = 0; item < plan->opcode_count; ++item)
        fprintf(out, "\tdw L%d\n", cases[item]);

    fprintf(out, "L%d:\n\tjp L%d\n", cases[0], exit_label);

    fprintf(out, "L%d:\n", cases[1]);
    mir_emit_basic_instruction_word(out, plan->instruction_a_offset);
    mir_emit_forth_push_hl(out);
    fprintf(out, "\tjp L%d\n", next);

    /* Scalar load/store. */
    fprintf(out, "L%d:\n", cases[2]);
    mir_emit_basic_instruction_word(out, plan->instruction_a_offset);
    mir_emit_basic_scaled_address(out, BASIC_SYMBOLS, plan->symbol_stride);
    fprintf(out, "\tld de,%d\n\tadd hl,de\n"
                 "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n",
            plan->symbol_scalar_offset);
    mir_emit_basic_scaled_address(out, BASIC_MEMORY, 2);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n", out);
    mir_emit_forth_push_hl(out);
    fprintf(out, "\tjp L%d\n", next);

    fprintf(out, "L%d:\n", cases[3]);
    mir_emit_basic_instruction_word(out, plan->instruction_a_offset);
    mir_emit_basic_scaled_address(out, BASIC_SYMBOLS, plan->symbol_stride);
    fprintf(out, "\tld de,%d\n\tadd hl,de\n"
                 "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n",
            plan->symbol_scalar_offset);
    mir_emit_basic_scaled_address(out, BASIC_MEMORY, 2);
    fputs("\tpush hl\n", out);
    mir_emit_forth_pop_hl(out);
    fputs("\tex de,hl\n\tpop hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
          out);
    fprintf(out, "\tjp L%d\n", next);

    /* Array load/store. */
    {
        int load_invalid = new_label();
        int load_ready = new_label();

        fprintf(out, "L%d:\n", cases[4]);
        mir_emit_basic_instruction_word(out, plan->instruction_a_offset);
        mir_emit_basic_scaled_address(
            out, BASIC_SYMBOLS, plan->symbol_stride);
        mir_emit_forth_frame_store(out, BASIC_TEMP_C);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, BASIC_TEMP_A);
        mir_emit_forth_frame_load(out, BASIC_TEMP_C);
        fprintf(out, "\tld de,%d\n\tadd hl,de\n"
                     "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n"
                     "\tbit 7,h\n\tjp nz, L%d\n",
                plan->symbol_base_offset, load_invalid);
        mir_emit_forth_frame_store(out, BASIC_TEMP_N);
        mir_emit_forth_frame_load(out, BASIC_TEMP_A);
        fprintf(out, "\tbit 7,h\n\tjp nz, L%d\n\tpush hl\n",
                load_invalid);
        mir_emit_forth_frame_load(out, BASIC_TEMP_C);
        fprintf(out, "\tld de,%d\n\tadd hl,de\n"
                     "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n",
                plan->symbol_size_offset);
        fputs("\tpop hl\n\tor a\n\tsbc hl,de\n", out);
        fprintf(out, "\tjp nc, L%d\n", load_invalid);
        mir_emit_forth_frame_load(out, BASIC_TEMP_N);
        fputs("\tpush hl\n", out);
        mir_emit_forth_frame_load(out, BASIC_TEMP_A);
        fputs("\tex de,hl\n\tpop hl\n\tadd hl,de\n", out);
        mir_emit_basic_scaled_address(out, BASIC_MEMORY, 2);
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n"
              "\tjp L", out);
        fprintf(out, "%d\nL%d:\n\tld hl,0\nL%d:\n",
                load_ready, load_invalid, load_ready);
        mir_emit_forth_push_hl(out);
        fprintf(out, "\tjp L%d\n", next);
    }

    {
        int store_done = new_label();

        fprintf(out, "L%d:\n", cases[5]);
        mir_emit_basic_instruction_word(out, plan->instruction_a_offset);
        mir_emit_basic_scaled_address(
            out, BASIC_SYMBOLS, plan->symbol_stride);
        mir_emit_forth_frame_store(out, BASIC_TEMP_C);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, BASIC_TEMP_B);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, BASIC_TEMP_A);
        mir_emit_forth_frame_load(out, BASIC_TEMP_C);
        fprintf(out, "\tld de,%d\n\tadd hl,de\n"
                     "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n"
                     "\tbit 7,h\n\tjp nz, L%d\n",
                plan->symbol_base_offset, store_done);
        mir_emit_forth_frame_store(out, BASIC_TEMP_N);
        mir_emit_forth_frame_load(out, BASIC_TEMP_A);
        fprintf(out, "\tbit 7,h\n\tjp nz, L%d\n\tpush hl\n",
                store_done);
        mir_emit_forth_frame_load(out, BASIC_TEMP_C);
        fprintf(out, "\tld de,%d\n\tadd hl,de\n"
                     "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n",
                plan->symbol_size_offset);
        fputs("\tpop hl\n\tor a\n\tsbc hl,de\n", out);
        fprintf(out, "\tjp nc, L%d\n", store_done);
        mir_emit_forth_frame_load(out, BASIC_TEMP_N);
        fputs("\tpush hl\n", out);
        mir_emit_forth_frame_load(out, BASIC_TEMP_A);
        fputs("\tex de,hl\n\tpop hl\n\tadd hl,de\n", out);
        mir_emit_basic_scaled_address(out, BASIC_MEMORY, 2);
        fputs("\tpush hl\n", out);
        mir_emit_forth_frame_load(out, BASIC_TEMP_B);
        fputs("\tex de,hl\n\tpop hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
              out);
        fprintf(out, "L%d:\n\tjp L%d\n", store_done, next);
    }

    /* Arithmetic. */
    for (item = 6; item <= 10; ++item) {
        int nonzero = new_label();
        int arithmetic_done = new_label();

        fprintf(out, "L%d:\n", cases[item]);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, BASIC_TEMP_B);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, BASIC_TEMP_A);
        if (item == 9 || item == 10) {
            mir_emit_forth_frame_load(out, BASIC_TEMP_B);
            fprintf(out,
                    "\tld a,h\n\tor l\n\tjp nz, L%d\n"
                    "\tld hl,0\n\tjp L%d\nL%d:\n\tex de,hl\n",
                    nonzero, arithmetic_done, nonzero);
            mir_emit_forth_frame_load(out, BASIC_TEMP_A);
            mir_emit_runtime_call(
                out, item == 9 ? "__divs" : "__mods");
            fprintf(out, "L%d:\n", arithmetic_done);
        } else {
            mir_emit_forth_frame_load(out, BASIC_TEMP_B);
            fputs("\tex de,hl\n", out);
            mir_emit_forth_frame_load(out, BASIC_TEMP_A);
            if (item == 6)
                fputs("\tadd hl,de\n", out);
            else if (item == 7)
                fputs("\tor a\n\tsbc hl,de\n", out);
            else
                mir_emit_runtime_call(out, "__mulu");
        }
        mir_emit_forth_push_hl(out);
        fprintf(out, "\tjp L%d\n", next);
    }

    fprintf(out, "L%d:\n", cases[11]);
    mir_emit_forth_pop_hl(out);
    fputs("\txor a\n\tsub l\n\tld l,a\n\tld a,0\n\tsbc a,h\n\tld h,a\n",
          out);
    mir_emit_forth_push_hl(out);
    fprintf(out, "\tjp L%d\n", next);

    /* Comparisons. */
    for (item = 12; item <= 17; ++item) {
        int true_label = new_label();
        int false_label = new_label();
        int compare_done = new_label();

        fprintf(out, "L%d:\n", cases[item]);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, BASIC_TEMP_B);
        mir_emit_forth_pop_hl(out);
        mir_emit_forth_frame_store(out, BASIC_TEMP_A);
        if (item == 12 || item == 13) {
            mir_emit_forth_frame_load(out, BASIC_TEMP_B);
            fputs("\tex de,hl\n", out);
            mir_emit_forth_frame_load(out, BASIC_TEMP_A);
            fputs("\tor a\n\tsbc hl,de\n", out);
            fprintf(out, "\tjp %s, L%d\n\tjp L%d\n",
                    item == 12 ? "z" : "nz",
                    true_label, false_label);
        } else {
            if (item == 14 || item == 17) {
                mir_emit_forth_frame_load(out, BASIC_TEMP_B);
                fputs("\tex de,hl\n", out);
                mir_emit_forth_frame_load(out, BASIC_TEMP_A);
            } else {
                mir_emit_forth_frame_load(out, BASIC_TEMP_A);
                fputs("\tex de,hl\n", out);
                mir_emit_forth_frame_load(out, BASIC_TEMP_B);
            }
            if (item == 14 || item == 16) {
                mir_emit_forth_signed_less_branch(
                    out, true_label, false_label);
            } else {
                mir_emit_forth_signed_less_branch(
                    out, false_label, true_label);
            }
        }
        fprintf(out,
                "L%d:\n\tld hl,1\n\tjp L%d\n"
                "L%d:\n\tld hl,0\n"
                "L%d:\n",
                true_label, compare_done,
                false_label, compare_done);
        mir_emit_forth_push_hl(out);
        fprintf(out, "\tjp L%d\n", next);
    }

    fprintf(out, "L%d:\n", cases[18]);
    mir_emit_forth_pop_hl(out);
    mir_emit_forth_frame_store(out, BASIC_TEMP_B);
    mir_emit_forth_pop_hl(out);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, BASIC_TEMP_B);
    fputs("\tex de,hl\n\tpop hl\n"
          "\tld a,l\n\tand e\n\tld l,a\n"
          "\tld a,h\n\tand d\n\tld h,a\n", out);
    mir_emit_forth_push_hl(out);
    fprintf(out, "\tjp L%d\n", next);

    /* Jumps and gosub stack. */
    fprintf(out, "L%d:\n", cases[19]);
    mir_emit_basic_instruction_word(out, plan->instruction_a_offset);
    fprintf(out, "\tjp L%d\n", set_pc);

    fprintf(out, "L%d:\n", cases[20]);
    mir_emit_forth_pop_hl(out);
    fprintf(out,
            "\tld a,h\n\tor l\n\tjp nz, L%d\n",
            next);
    mir_emit_basic_instruction_word(out, plan->instruction_a_offset);
    fprintf(out, "\tjp L%d\n", set_pc);

    fprintf(out, "L%d:\n", cases[21]);
    mir_emit_forth_frame_load(out, BASIC_GSP);
    fprintf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n\tjp nc, L%d\n"
            "\tpush iy\n\tpop hl\n\tld de,%d\n\tadd hl,de\n\tpush hl\n",
            plan->gosub_limit, gosub_full, plan->instruction_size);
    mir_emit_forth_local_array_address(
        out, BASIC_GOSUB_STACK, BASIC_GSP, 0);
    fputs("\tpop de\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
    mir_emit_forth_frame_load(out, BASIC_GSP);
    fputs("\tinc hl\n", out);
    mir_emit_forth_frame_store(out, BASIC_GSP);
    mir_emit_basic_instruction_word(out, plan->instruction_a_offset);
    fprintf(out, "\tjp L%d\n", set_pc);

    fprintf(out, "L%d:\n", cases[22]);
    mir_emit_forth_frame_load(out, BASIC_GSP);
    fprintf(out,
            "\tld a,h\n\tor a\n\tjp m, L%d\n"
            "\tor l\n\tjp z, L%d\n\tdec hl\n",
            gosub_empty, gosub_empty);
    mir_emit_forth_frame_store(out, BASIC_GSP);
    mir_emit_forth_local_array_address(
        out, BASIC_GOSUB_STACK, BASIC_GSP, 0);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tpush de\n\tpop iy\n", out);
    fprintf(out, "\tjp L%d\n", dispatch);

    /* FOR / NEXT. */
    fprintf(out, "L%d:\n", cases[23]);
    mir_emit_forth_frame_load(out, BASIC_FSP);
    fprintf(out,
            "\tld de,%d\n\tor a\n\tsbc hl,de\n\tjp nc, L%d\n",
            plan->for_limit, for_full);
    mir_emit_forth_frame_load(out, BASIC_FSP);
    mir_emit_basic_scaled_address(out, BASIC_FOR_STACK, plan->for_stride);
    mir_emit_forth_frame_store(out, BASIC_TEMP_C);
    fputs("\tpush hl\n", out);
    mir_emit_basic_instruction_word(out, plan->instruction_a_offset);
    fputs("\tex de,hl\n\tpop hl\n", out);
    if (plan->for_var_offset != 0)
        fprintf(out, "\tld bc,%d\n\tadd hl,bc\n",
                plan->for_var_offset);
    fputs("\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
    mir_emit_forth_pop_hl(out);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, BASIC_TEMP_C);
    if (plan->for_limit_offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                plan->for_limit_offset);
    fputs("\tpop de\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
    mir_emit_forth_frame_load(out, BASIC_TEMP_C);
    if (plan->for_step_offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                plan->for_step_offset);
    fputs("\tpush hl\n", out);
    mir_emit_basic_instruction_word(out, plan->instruction_b_offset);
    fputs("\tex de,hl\n\tpop hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
          out);
    mir_emit_forth_frame_load(out, BASIC_TEMP_C);
    if (plan->for_pc_offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                plan->for_pc_offset);
    fputs("\tpush hl\n\tpush iy\n\tpop hl\n", out);
    fprintf(out, "\tld de,%d\n\tadd hl,de\n\tex de,hl\n\tpop hl\n"
                 "\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
            plan->instruction_size);
    mir_emit_forth_frame_load(out, BASIC_FSP);
    fputs("\tinc hl\n", out);
    mir_emit_forth_frame_store(out, BASIC_FSP);
    fprintf(out, "\tjp L%d\n", next);

    {
        int continue_loop = new_label();
        int finish_loop = new_label();

        fprintf(out, "L%d:\n", cases[24]);
        mir_emit_forth_frame_load(out, BASIC_FSP);
        fprintf(out,
                "\tld a,h\n\tor a\n\tjp m, L%d\n"
                "\tor l\n\tjp z, L%d\n\tdec hl\n",
                next_empty, next_empty);
        mir_emit_basic_scaled_address(out, BASIC_FOR_STACK, plan->for_stride);
        mir_emit_forth_frame_store(out, BASIC_TEMP_C);
        if (plan->for_var_offset != 0)
            fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                    plan->for_var_offset);
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n", out);
        mir_emit_basic_scaled_address(out, BASIC_SYMBOLS, plan->symbol_stride);
        fprintf(out, "\tld de,%d\n\tadd hl,de\n"
                     "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n",
                plan->symbol_scalar_offset);
        mir_emit_basic_scaled_address(out, BASIC_MEMORY, 2);
        fputs("\tpush hl\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
              "\tex de,hl\n", out);
        mir_emit_forth_frame_store(out, BASIC_TEMP_A);
        mir_emit_forth_frame_load(out, BASIC_TEMP_C);
        if (plan->for_step_offset != 0)
            fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                    plan->for_step_offset);
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n", out);
        mir_emit_forth_frame_load(out, BASIC_TEMP_A);
        fputs("\tpop bc\n\tadd hl,de\n\tex de,hl\n"
              "\tld h,b\n\tld l,c\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n"
              "\tex de,hl\n", out);
        mir_emit_forth_frame_store(out, BASIC_TEMP_A);
        mir_emit_forth_frame_load(out, BASIC_TEMP_C);
        if (plan->for_limit_offset != 0)
            fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                    plan->for_limit_offset);
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n", out);
        mir_emit_forth_frame_load(out, BASIC_TEMP_A);
        /* Continue unless limit < new value. */
        fputs("\tex de,hl\n", out);
        mir_emit_forth_signed_less_branch(
            out, finish_loop, continue_loop);
        fprintf(out, "L%d:\n", continue_loop);
        mir_emit_forth_frame_load(out, BASIC_TEMP_C);
        if (plan->for_pc_offset != 0)
            fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                    plan->for_pc_offset);
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
              "\tpush de\n\tpop iy\n", out);
        fprintf(out, "\tjp L%d\nL%d:\n",
                dispatch, finish_loop);
        mir_emit_forth_frame_load(out, BASIC_FSP);
        fputs("\tdec hl\n", out);
        mir_emit_forth_frame_store(out, BASIC_FSP);
        fprintf(out, "\tjp L%d\n", next);
    }

    /* Printing and no-op clear. */
    fprintf(out, "L%d:\n", cases[25]);
    mir_emit_forth_pop_hl(out);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->number_format_string);
    mir_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n\tpop bc\n", out);
    fprintf(out, "\tjp L%d\n", next);

    fprintf(out, "L%d:\n", cases[26]);
    mir_emit_forth_frame_load(out, BASIC_STRINGS);
    fputs("\tpush hl\n", out);
    mir_emit_basic_instruction_word(out, plan->instruction_a_offset);
    fputs("\tadd hl,hl\n\tex de,hl\n\tpop hl\n\tadd hl,de\n"
          "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tpush de\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->string_format_string);
    mir_emit_symbol_call(out, plan->print_function);
    fputs("\tpop bc\n\tpop bc\n", out);
    fprintf(out, "\tjp L%d\n", next);

    for (item = 27; item <= 28; ++item) {
        int string_id =
            item == 27 ? plan->space_string : plan->newline_string;
        fprintf(out, "L%d:\n\tld hl,S%d\n\tpush hl\n",
                cases[item], string_id);
        mir_emit_symbol_call(out, plan->print_function);
        fputs("\tpop bc\n", out);
        fprintf(out, "\tjp L%d\n", next);
    }
    fprintf(out, "L%d:\n\tjp L%d\n", cases[29], next);

    fprintf(out, "L%d:\n", next);
    for (item = 0; item < plan->instruction_size; ++item)
        fputs("\tinc iy\n", out);
    fprintf(out,
            "\tjp L%d\n"
            "L%d:\n"
            "\tpush hl\n\tadd hl,hl\n\tadd hl,hl\n\tpop de\n\tadd hl,de\n"
            "\tex de,hl\n",
            dispatch, set_pc);
    mir_emit_forth_frame_load(out, BASIC_CODE);
    fprintf(out,
            "\tadd hl,de\n\tpush hl\n\tpop iy\n\tjp L%d\n"
            "L%d:\n",
            dispatch, exit_label);
    mir_emit_forth_frame_load(out, BASIC_SP);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, BASIC_STACK);
    fputs("\tex de,hl\n\tor a\n\tsbc hl,de\n"
          "\tsrl h\n\trr l\n", out);
    {
        const char *stack_pointer_name =
            asm_name_for(sym_asm_name(plan->stack_pointer));
        mir_emit_symbol_extrn(out, plan->stack_pointer);
        fprintf(out, "\tld (%s),hl\n", stack_pointer_name);
    }
    mir_emit_basic_frame_to_global(out, plan->gosub_pointer, BASIC_GSP);
    mir_emit_basic_frame_to_global(out, plan->for_pointer, BASIC_FSP);
    fputs("\tld sp,ix\n\tpop ix\n\tpop iy\n\tret\n", out);

    fprintf(out, "L%d:\n", gosub_full);
    mir_emit_basic_die(out, plan, plan->gosub_full_string);
    fprintf(out, "\tjp L%d\nL%d:\n", exit_label, gosub_empty);
    mir_emit_basic_die(out, plan, plan->gosub_empty_string);
    fprintf(out, "\tjp L%d\nL%d:\n", exit_label, for_full);
    mir_emit_basic_die(out, plan, plan->for_full_string);
    fprintf(out, "\tjp L%d\nL%d:\n", exit_label, next_empty);
    mir_emit_basic_die(out, plan, plan->next_empty_string);
    fprintf(out, "\tjp L%d\nL%d:\n", exit_label, bad_opcode);
    mir_emit_basic_die(out, plan, plan->bad_opcode_string);
    fprintf(out, "\tjp L%d\n", exit_label);
}
#undef mir_emit_forth_push_hl
#undef mir_emit_forth_pop_hl

enum MirFortranEvalFrameOffset {
    MIR_FOREVAL_END = -2,
    MIR_FOREVAL_SYMBOLS = -4,
    MIR_FOREVAL_MEMORY = -6,
    MIR_FOREVAL_MEMORY_CAPACITY = -8,
    MIR_FOREVAL_SYMBOL_INDEX = -10,
    MIR_FOREVAL_ARRAY_INDEX = -12,
    MIR_FOREVAL_SYMBOL_POINTER = -14,
    MIR_FOREVAL_STACK_POINTER = -16
};

static void mir_emit_fortran_symbol_load(
    FILE *out, const struct MirFortranEval *plan)
{
    int array_index = new_label();
    int index_ready = new_label();
    int word_value = new_label();
    int word_array_index = new_label();
    int word_index_ready = new_label();
    int bounds_error = new_label();
    int done = new_label();

    mir_emit_forth_frame_load(out, MIR_FOREVAL_SYMBOL_INDEX);
    mir_emit_mul_hl_const(out, (unsigned long)plan->symbol_stride);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FOREVAL_SYMBOLS);
    fputs("\tadd hl,de\n", out);
    mir_emit_forth_frame_store(out, MIR_FOREVAL_SYMBOL_POINTER);
    fprintf(out,
            "\tld de,%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tld hl,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp nz, L%d\n",
            plan->symbol_type_offset,
            plan->byte_type, word_value);
    mir_emit_forth_frame_load(out, MIR_FOREVAL_SYMBOL_POINTER);
    fprintf(out,
            "\tld de,%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tld hl,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp nz, L%d\n\tld hl,0\n\tjp L%d\n"
            "L%d:\n",
            plan->symbol_kind_offset,
            plan->scalar_kind, array_index, index_ready,
            array_index);
    mir_emit_forth_frame_load(out, MIR_FOREVAL_ARRAY_INDEX);
    fprintf(out, "L%d:\n\tex de,hl\n", index_ready);
    mir_emit_forth_frame_load(out, MIR_FOREVAL_SYMBOL_POINTER);
    fprintf(out,
            "\tld bc,%d\n\tadd hl,bc\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
            "\tld h,b\n\tld l,c\n\tadd hl,de\n\tex de,hl\n",
            plan->symbol_base_offset);
    mir_emit_forth_frame_load(out, MIR_FOREVAL_MEMORY);
    fputs("\tadd hl,de\n\tld l,(hl)\n"
          "\tld a,l\n\trlca\n\tsbc a,a\n\tld h,a\n"
          "\tjp L", out);
    fprintf(out, "%d\nL%d:\n", done, word_value);

    mir_emit_forth_frame_load(out, MIR_FOREVAL_SYMBOL_POINTER);
    fprintf(out,
            "\tld de,%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tld hl,%d\n\tor a\n\tsbc hl,de\n"
            "\tjp nz, L%d\n\tld hl,0\n\tjp L%d\n"
            "L%d:\n",
            plan->symbol_kind_offset,
            plan->scalar_kind, word_array_index, word_index_ready,
            word_array_index);
    mir_emit_forth_frame_load(out, MIR_FOREVAL_ARRAY_INDEX);
    fprintf(out, "L%d:\n\tadd hl,hl\n\tex de,hl\n",
            word_index_ready);
    mir_emit_forth_frame_load(out, MIR_FOREVAL_SYMBOL_POINTER);
    fprintf(out,
            "\tld bc,%d\n\tadd hl,bc\n"
            "\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
            "\tld h,b\n\tld l,c\n\tadd hl,de\n"
            "\tld (ix%d),l\n\tld (ix%d),h\n"
            "\tbit 7,h\n\tjp nz, L%d\n"
            "\tinc hl\n\tex de,hl\n",
            plan->symbol_base_offset,
            MIR_FOREVAL_ARRAY_INDEX, MIR_FOREVAL_ARRAY_INDEX + 1,
            bounds_error);
    mir_emit_forth_frame_load(out, MIR_FOREVAL_MEMORY_CAPACITY);
    fputs("\tor a\n\tsbc hl,de\n", out);
    fprintf(out,
            "\tjp c, L%d\n\tjp z, L%d\n",
            bounds_error, bounds_error);
    mir_emit_forth_frame_load(out, MIR_FOREVAL_ARRAY_INDEX);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_FOREVAL_MEMORY);
    fputs("\tadd hl,de\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tex de,hl\n", out);
    fprintf(out, "\tjp L%d\nL%d:\n", done, bounds_error);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", plan->bounds_string);
    mir_emit_symbol_call(out, plan->die_function);
    fprintf(out, "\tld hl,0\nL%d:\n", done);
}

static void mir_emit_fortran_eval(
    FILE *out, const struct MirFortranEval *plan)
{
    const char *stack_name =
        asm_name_for(sym_asm_name(plan->evaluation_stack));
    const char *tokens_name =
        asm_name_for(sym_asm_name(plan->tokens));
    const char *expressions_name =
        asm_name_for(sym_asm_name(plan->expressions));
    int cases[17];
    int dispatch = new_label();
    int table = new_label();
    int next = new_label();
    int done = new_label();
    int empty = new_label();
    int exit_label = new_label();
    int pop_two = new_label();
    int push_result = new_label();
    int item;

    for (item = 0; item < plan->opcode_count; ++item)
        cases[item] = new_label();
    mir_emit_symbol_extrn(out, plan->evaluation_stack);
    mir_emit_symbol_extrn(out, plan->tokens);
    mir_emit_symbol_extrn(out, plan->expressions);
    mir_emit_basic_global_to_frame(
        out, plan->symbols, MIR_FOREVAL_SYMBOLS);
    mir_emit_basic_global_to_frame(
        out, plan->memory, MIR_FOREVAL_MEMORY);
    mir_emit_basic_global_to_frame(
        out, plan->memory_capacity, MIR_FOREVAL_MEMORY_CAPACITY);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tbit 7,h\n\tjp nz, L%d\n"
            "\tpush hl\n\tld hl,(%s)\n\tex de,hl\n\tpop hl\n",
            plan->expression_index_offset + 2,
            plan->expression_index_offset + 3,
            empty, expressions_name);
    mir_emit_mul_hl_const(out, (unsigned long)plan->expression_stride);
    fputs("\tadd hl,de\n\tpush hl\n", out);
    if (plan->expression_start_offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                plan->expression_start_offset);
    fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n", out);
    fprintf(out, "\tld hl,(%s)\n\tadd hl,bc\n\tadd hl,bc\n"
                 "\tadd hl,bc\n\tadd hl,bc\n"
                 "\tpush hl\n\tpop iy\n\tpop hl\n",
            tokens_name);
    if (plan->expression_length_offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                plan->expression_length_offset);
    fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
          "\tld h,b\n\tld l,c\n", out);
    mir_emit_mul_hl_const(out, (unsigned long)plan->token_stride);
    fputs("\tpush iy\n\tpop de\n\tadd hl,de\n", out);
    mir_emit_forth_frame_store(out, MIR_FOREVAL_END);
    fprintf(out, "\tld hl,%s\n", stack_name);
    mir_emit_forth_frame_store(out, MIR_FOREVAL_STACK_POINTER);
    fprintf(out,
            "L%d:\n\tpush iy\n\tpop hl\n\tpush hl\n",
            dispatch);
    mir_emit_forth_frame_load(out, MIR_FOREVAL_END);
    fputs("\tex de,hl\n\tpop hl\n\tor a\n\tsbc hl,de\n", out);
    fprintf(out,
            "\tjp nc, L%d\n"
            "\tld a,(iy%+d)\n\tor a\n\tjp nz, L%d\n"
            "\tld a,(iy%+d)\n\tdec a\n\tcp %d\n\tjp nc, L%d\n"
            "\tld l,a\n\tld h,0\n\tadd hl,hl\n"
            "\tld de,L%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n\tjp (hl)\n"
            "L%d:\n",
            done,
            plan->token_op_offset + 1, next,
            plan->token_op_offset, plan->opcode_count, next,
            table, table);
    for (item = 0; item < plan->opcode_count; ++item)
        fprintf(out, "\tdw L%d\n", cases[item]);

    fprintf(out, "L%d:\n", cases[0]);
    mir_emit_basic_instruction_word(out, plan->token_argument_offset);
    fprintf(out, "\tjp L%d\n", push_result);

    for (item = 1; item <= 2; ++item) {
        fprintf(out, "L%d:\n", cases[item]);
        if (item == 2) {
            mir_emit_basic_pop_hl(out);
            mir_emit_forth_frame_store(out, MIR_FOREVAL_ARRAY_INDEX);
        } else {
            fputs("\tld hl,0\n", out);
            mir_emit_forth_frame_store(out, MIR_FOREVAL_ARRAY_INDEX);
        }
        mir_emit_basic_instruction_word(out, plan->token_argument_offset);
        mir_emit_forth_frame_store(out, MIR_FOREVAL_SYMBOL_INDEX);
        mir_emit_fortran_symbol_load(out, plan);
        fprintf(out, "\tjp L%d\n", push_result);
    }

    fprintf(out, "L%d:\n", cases[8]);
    mir_emit_basic_pop_hl(out);
    fputs("\txor a\n\tsub l\n\tld l,a\n\tld a,0\n\tsbc a,h\n\tld h,a\n",
          out);
    fprintf(out, "\tjp L%d\n", push_result);

    for (item = 3; item < plan->opcode_count; ++item) {
        int true_label = new_label();
        int false_label = new_label();
        int result_label = new_label();

        if (item == 8)
            continue;
        fprintf(out, "L%d:\n", cases[item]);
        fprintf(out,
                "\tcall L%d\n"
                "\tld (ix%d),c\n\tld (ix%d),b\n",
                pop_two,
                MIR_FOREVAL_STACK_POINTER,
                MIR_FOREVAL_STACK_POINTER + 1);
        if (item == 6 || item == 7) {
            int nonzero = new_label();
            fprintf(out,
                    "\tld a,d\n\tor e\n\tjp nz, L%d\n"
                    "\tld hl,0\n\tjp L%d\nL%d:\n",
                    nonzero, result_label, nonzero);
            mir_emit_runtime_call(
                out, item == 6 ? "__divs" : "__mods");
            fprintf(out, "L%d:\n", result_label);
        } else if (item >= 9 && item <= 14) {
            if (item == 9 || item == 10) {
                fputs("\tor a\n\tsbc hl,de\n", out);
                fprintf(out, "\tjp %s, L%d\n\tjp L%d\n",
                        item == 9 ? "z" : "nz",
                        true_label, false_label);
            } else {
                if (item == 12 || item == 13)
                    fputs("\tex de,hl\n", out);
                if (item == 11 || item == 13)
                    mir_emit_forth_signed_less_branch(
                        out, true_label, false_label);
                else
                    mir_emit_forth_signed_less_branch(
                        out, false_label, true_label);
            }
            fprintf(out,
                    "L%d:\n\tld hl,1\n\tjp L%d\n"
                    "L%d:\n\tld hl,0\nL%d:\n",
                    true_label, result_label,
                    false_label, result_label);
        } else if (item == 15 || item == 16) {
            int short_circuit = new_label();
            fputs("\tld a,h\n\tor l\n", out);
            if (item == 15)
                fprintf(out, "\tjp z, L%d\n", short_circuit);
            else
                fprintf(out, "\tjp nz, L%d\n", true_label);
            fputs("\tld a,d\n\tor e\n", out);
            if (item == 15)
                fprintf(out, "\tjp z, L%d\n", short_circuit);
            else
                fprintf(out, "\tjp nz, L%d\n", true_label);
            if (item == 15) {
                fputs("\tld hl,1\n", out);
                fprintf(out, "\tjp L%d\nL%d:\n\tld hl,0\n",
                        result_label, short_circuit);
            } else {
                fputs("\tld hl,0\n", out);
                fprintf(out,
                        "\tjp L%d\nL%d:\n\tld hl,1\n",
                        result_label, true_label);
            }
            fprintf(out, "L%d:\n", result_label);
        } else {
            if (item == 3)
                fputs("\tadd hl,de\n", out);
            else if (item == 4)
                fputs("\tor a\n\tsbc hl,de\n", out);
            else
                mir_emit_runtime_call(out, "__mulu");
        }
        fprintf(out, "\tjp L%d\n", push_result);
    }
    fprintf(out, "L%d:\n", pop_two);
    fprintf(out,
            "\tld c,(ix%d)\n\tld b,(ix%d)\n"
            "\tdec bc\n\tdec bc\n"
            "\tld l,c\n\tld h,b\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tpush de\n"
            "\tdec bc\n\tdec bc\n"
            "\tld l,c\n\tld h,b\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n\tpop de\n\tret\n",
            MIR_FOREVAL_STACK_POINTER,
            MIR_FOREVAL_STACK_POINTER + 1);
    fprintf(out, "L%d:\n", push_result);
    mir_emit_basic_push_hl(out);
    fprintf(out, "\tjp L%d\n", next);
    fprintf(out, "L%d:\n", next);
    for (item = 0; item < plan->token_stride; ++item)
        fputs("\tinc iy\n", out);
    fprintf(out, "\tjp L%d\nL%d:\n", dispatch, done);
    mir_emit_forth_frame_load(out, MIR_FOREVAL_STACK_POINTER);
    fprintf(out,
            "\tld de,%s\n\tor a\n\tsbc hl,de\n"
            "\tjp z, L%d\n",
            stack_name, empty);
    mir_emit_basic_pop_hl(out);
    fprintf(out, "\tjp L%d\nL%d:\n\tld hl,0\nL%d:\n"
                 "\tld sp,ix\n\tpop ix\n\tpop iy\n\tret\n",
            exit_label, empty, exit_label);
}

enum MirCRunFrameOffset {
    MIR_CRUN_CODE = -2,
    MIR_CRUN_GLOBAL_MEMORY = -4,
    MIR_CRUN_FRAME_MEMORY = -6,
    MIR_CRUN_FUNCTIONS = -8,
    MIR_CRUN_RETURN_STACK = -10,
    MIR_CRUN_FRAME_STORAGE = -12,
    MIR_CRUN_STRINGS = -14,
    MIR_CRUN_STACK_POINTER = -16,
    MIR_CRUN_FRAME_SIZE = -18,
    MIR_CRUN_FRAME_POINTER = -20,
    MIR_CRUN_PC = -22,
    MIR_CRUN_TEMP_A = -24,
    MIR_CRUN_TEMP_B = -26,
    MIR_CRUN_TEMP_V = -28,
    MIR_CRUN_TEMP_FI = -30,
    MIR_CRUN_VALUES = -46
};

static void mir_emit_c_state_load(
    FILE *out, const char *state_name, int offset)
{
    fprintf(out, "\tld hl,(%s+%d)\n", state_name, offset);
}

static void mir_emit_c_state_store(
    FILE *out, const char *state_name, int offset)
{
    fprintf(out, "\tld (%s+%d),hl\n", state_name, offset);
}

static void mir_emit_c_function_address(
    FILE *out, const struct MirCRun *plan)
{
    mir_emit_mul_hl_const(out, (unsigned long)plan->function_stride);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_CRUN_FUNCTIONS);
    fputs("\tadd hl,de\n", out);
}

static void mir_emit_c_sync_state(
    FILE *out, const struct MirCRun *plan, const char *state_name)
{
    mir_emit_forth_frame_load(out, MIR_CRUN_STACK_POINTER);
    mir_emit_c_state_store(out, state_name, plan->state_stp_offset);
    mir_emit_forth_frame_load(out, MIR_CRUN_FRAME_MEMORY);
    mir_emit_c_state_store(out, state_name, plan->state_flp_offset);
    mir_emit_forth_frame_load(out, MIR_CRUN_FRAME_POINTER);
    mir_emit_c_state_store(out, state_name, plan->state_fp_offset);
}

static void mir_emit_c_reload_state(
    FILE *out, const struct MirCRun *plan, const char *state_name)
{
    mir_emit_c_state_load(out, state_name, plan->state_stp_offset);
    mir_emit_forth_frame_store(out, MIR_CRUN_STACK_POINTER);
    mir_emit_c_state_load(out, state_name, plan->state_flp_offset);
    mir_emit_forth_frame_store(out, MIR_CRUN_FRAME_MEMORY);
    mir_emit_c_state_load(out, state_name, plan->state_fp_offset);
    mir_emit_forth_frame_store(out, MIR_CRUN_FRAME_POINTER);
}

static void mir_emit_c_instruction_word(FILE *out, int offset)
{
    fprintf(out,
            "\tld l,(iy%+d)\n\tld h,(iy%+d)\n",
            offset, offset + 1);
}

static void mir_emit_c_memory_address(
    FILE *out, int memory_frame_offset,
    int indexed, int element_size)
{
    if (indexed) {
        if (element_size == 2)
            fputs("\tadd hl,hl\n", out);
        fputs("\tpush hl\n", out);
        mir_emit_c_instruction_word(out, 1);
        fputs("\tex de,hl\n\tpop hl\n\tadd hl,de\n", out);
    } else {
        mir_emit_c_instruction_word(out, 1);
    }
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, memory_frame_offset);
    fputs("\tadd hl,de\n", out);
}

static void mir_emit_c_run(FILE *out, const struct MirCRun *plan)
{
    const char *state_name =
        asm_name_for(sym_asm_name(plan->state));
    const char *saved_main_name =
        asm_name_for(sym_asm_name(plan->saved_main));
    int cases[42];
    int dispatch = new_label();
    int table = new_label();
    int next = new_label();
    int set_pc = new_label();
    int exit_label = new_label();
    int bad_opcode = new_label();
    int no_main = new_label();
    int pop_two = new_label();
    int push_result = new_label();
    int item;

    for (item = 0; item < plan->opcode_count; ++item)
        cases[item] = new_label();
    mir_emit_symbol_extrn(out, plan->state);
    mir_emit_symbol_extrn(out, plan->saved_main);

    mir_emit_c_state_load(out, state_name, plan->state_code_offset);
    mir_emit_forth_frame_store(out, MIR_CRUN_CODE);
    mir_emit_c_state_load(out, state_name, plan->state_global_memory_offset);
    mir_emit_forth_frame_store(out, MIR_CRUN_GLOBAL_MEMORY);
    mir_emit_c_state_load(out, state_name, plan->state_st_offset);
    mir_emit_forth_frame_store(out, MIR_CRUN_STACK_POINTER);
    mir_emit_c_state_store(out, state_name, plan->state_stp_offset);
    fputs("\tld hl,0\n", out);
    mir_emit_forth_frame_store(out, MIR_CRUN_FRAME_POINTER);
    mir_emit_c_state_store(out, state_name, plan->state_fp_offset);
    mir_emit_c_state_load(out, state_name, plan->state_floc_offset);
    mir_emit_forth_frame_store(out, MIR_CRUN_FRAME_STORAGE);
    mir_emit_forth_frame_store(out, MIR_CRUN_FRAME_MEMORY);
    mir_emit_c_state_store(out, state_name, plan->state_flp_offset);
    mir_emit_c_state_load(out, state_name, plan->state_functions_offset);
    mir_emit_forth_frame_store(out, MIR_CRUN_FUNCTIONS);
    mir_emit_c_state_load(out, state_name, plan->state_return_stack_offset);
    mir_emit_forth_frame_store(out, MIR_CRUN_RETURN_STACK);
    mir_emit_c_state_load(out, state_name, plan->state_strings_offset);
    mir_emit_forth_frame_store(out, MIR_CRUN_STRINGS);
    mir_emit_c_state_load(out, state_name, plan->state_frame_size_offset);
    mir_emit_forth_frame_store(out, MIR_CRUN_FRAME_SIZE);

    mir_emit_forth_frame_load(out, MIR_CRUN_FRAME_STORAGE);
    fputs("\tpush hl\n\tld e,0\n", out);
    mir_emit_forth_frame_load(out, MIR_CRUN_FRAME_SIZE);
    mir_emit_mul_hl_const(out, (unsigned long)plan->frame_limit);
    fputs("\tld b,h\n\tld c,l\n\tpop hl\n", out);
    mir_emit_runtime_call(out, "__msf");

    fprintf(out, "\tld hl,(%s)\n\tbit 7,h\n\tjp nz, L%d\n",
            saved_main_name, no_main);
    mir_emit_c_state_store(out, state_name, plan->state_main_function_offset);
    mir_emit_forth_frame_store(out, MIR_CRUN_TEMP_FI);
    mir_emit_c_function_address(out, plan);
    if (plan->function_parameter_count_offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                plan->function_parameter_count_offset);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tex de,hl\n\tld de,2\n\tor a\n\tsbc hl,de\n", out);
    {
        int no_args = new_label();
        int args_ready = new_label();
        fprintf(out, "\tjp c, L%d\n", no_args);
        fputs("\tld hl,1\n", out);
        mir_emit_basic_push_hl(out);
        fputs("\tld hl,0\n", out);
        mir_emit_basic_push_hl(out);
        fputs("\tld hl,2\n", out);
        fprintf(out, "\tjp L%d\nL%d:\n\tld hl,0\nL%d:\n",
                args_ready, no_args, args_ready);
    }
    mir_emit_forth_frame_store(out, MIR_CRUN_TEMP_A);
    mir_emit_c_sync_state(out, plan, state_name);
    mir_emit_forth_frame_load(out, MIR_CRUN_TEMP_A);
    fputs("\tpush hl\n\tld hl,65535\n\tpush hl\n", out);
    mir_emit_forth_frame_load(out, MIR_CRUN_TEMP_FI);
    fputs("\tpush hl\n", out);
    mir_emit_symbol_call(out, plan->call_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);
    mir_emit_c_reload_state(out, plan, state_name);
    mir_emit_forth_frame_load(out, MIR_CRUN_TEMP_FI);
    mir_emit_c_function_address(out, plan);
    if (plan->function_entry_offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                plan->function_entry_offset);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n", out);
    fprintf(out, "\tjp L%d\n", set_pc);

    fprintf(out,
            "L%d:\n",
            dispatch);
    mir_emit_forth_frame_load(out, MIR_CRUN_PC);
    fputs("\tinc hl\n", out);
    mir_emit_forth_frame_store(out, MIR_CRUN_PC);
    fprintf(out,
            "\tld a,(iy%+d)\n\tcp %d\n\tjp nc, L%d\n"
            "\tld l,a\n\tld h,0\n\tadd hl,hl\n"
            "\tld de,L%d\n\tadd hl,de\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n\tjp (hl)\n"
            "L%d:\n",
            plan->instruction_op_offset,
            plan->opcode_count, bad_opcode,
            table, table);
    for (item = 0; item < plan->opcode_count; ++item)
        fprintf(out, "\tdw L%d\n", cases[item]);

    fprintf(out, "L%d:\n\tjp L%d\n", cases[0], exit_label);
    fprintf(out, "L%d:\n", cases[1]);
    mir_emit_c_instruction_word(out, plan->instruction_a_offset);
    fprintf(out, "\tjp L%d\n", push_result);

    for (item = 2; item <= 17; ++item) {
        int is_store = (item & 1) != 0;
        int indexed =
            (item >= 6 && item <= 9) ||
            item == 12 || item == 13 ||
            item == 16 || item == 17;
        int is_byte = item >= 10;
        int global_memory =
            item == 2 || item == 3 || item == 6 || item == 7 ||
            item == 10 || item == 11 || item == 12 || item == 13;
        int memory_frame =
            global_memory ? MIR_CRUN_GLOBAL_MEMORY :
                            MIR_CRUN_FRAME_MEMORY;

        fprintf(out, "L%d:\n", cases[item]);
        if (is_store && indexed) {
            fprintf(out,
                    "\tcall L%d\n"
                    "\tld (ix%d),c\n\tld (ix%d),b\n",
                    pop_two,
                    MIR_CRUN_STACK_POINTER,
                    MIR_CRUN_STACK_POINTER + 1);
            mir_emit_forth_frame_store(out, MIR_CRUN_TEMP_A);
            fputs("\tex de,hl\n", out);
            mir_emit_forth_frame_store(out, MIR_CRUN_TEMP_V);
            mir_emit_forth_frame_load(out, MIR_CRUN_TEMP_A);
        } else if (indexed) {
            mir_emit_basic_pop_hl(out);
        } else if (is_store) {
            mir_emit_basic_pop_hl(out);
            mir_emit_forth_frame_store(out, MIR_CRUN_TEMP_V);
        }
        mir_emit_c_memory_address(
            out, memory_frame, indexed, is_byte ? 1 : 2);
        if (is_store) {
            fputs("\tpush hl\n", out);
            mir_emit_forth_frame_load(out, MIR_CRUN_TEMP_V);
            fputs("\tex de,hl\n\tpop hl\n\tld (hl),e\n", out);
            if (!is_byte)
                fputs("\tinc hl\n\tld (hl),d\n", out);
            fprintf(out, "\tjp L%d\n", next);
        } else {
            if (is_byte) {
                fputs("\tld l,(hl)\n", out);
                fputs("\tld h,0\n", out);
            } else {
                fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
                      "\tex de,hl\n", out);
            }
            fprintf(out, "\tjp L%d\n", push_result);
        }
    }

    /* Arithmetic and comparisons. */
    for (item = 18; item <= 22; ++item) {
        int nonzero = new_label();
        int arithmetic_done = new_label();

        fprintf(out,
                "L%d:\n\tcall L%d\n"
                "\tld (ix%d),c\n\tld (ix%d),b\n",
                cases[item], pop_two,
                MIR_CRUN_STACK_POINTER, MIR_CRUN_STACK_POINTER + 1);
        if (item == 21 || item == 22) {
            fprintf(out,
                    "\tld a,d\n\tor e\n\tjp nz, L%d\n"
                    "\tld hl,0\n\tjp L%d\nL%d:\n",
                    nonzero, arithmetic_done, nonzero);
            mir_emit_runtime_call(
                out, item == 21 ? "__divs" : "__mods");
            fprintf(out, "L%d:\n", arithmetic_done);
        } else if (item == 18) {
            fputs("\tadd hl,de\n", out);
        } else if (item == 19) {
            fputs("\tor a\n\tsbc hl,de\n", out);
        } else {
            mir_emit_runtime_call(out, "__mulu");
        }
        fprintf(out, "\tjp L%d\n", push_result);
    }

    for (item = 23; item <= 24; ++item) {
        int zero = new_label();
        int unary_done = new_label();

        fprintf(out, "L%d:\n", cases[item]);
        mir_emit_basic_pop_hl(out);
        if (item == 23) {
            fputs("\txor a\n\tsub l\n\tld l,a\n"
                  "\tld a,0\n\tsbc a,h\n\tld h,a\n", out);
        } else {
            fprintf(out,
                    "\tld a,h\n\tor l\n\tjp z, L%d\n"
                    "\tld hl,0\n\tjp L%d\n"
                    "L%d:\n\tld hl,1\nL%d:\n",
                    zero, unary_done, zero, unary_done);
        }
        fprintf(out, "\tjp L%d\n", push_result);
    }

    for (item = 25; item <= 30; ++item) {
        int true_label = new_label();
        int false_label = new_label();
        int compare_done = new_label();

        fprintf(out,
                "L%d:\n\tcall L%d\n"
                "\tld (ix%d),c\n\tld (ix%d),b\n",
                cases[item], pop_two,
                MIR_CRUN_STACK_POINTER, MIR_CRUN_STACK_POINTER + 1);
        if (item == 25 || item == 26) {
            fputs("\tor a\n\tsbc hl,de\n", out);
            fprintf(out, "\tjp %s, L%d\n\tjp L%d\n",
                    item == 25 ? "z" : "nz",
                    true_label, false_label);
        } else {
            if (item == 28 || item == 29)
                fputs("\tex de,hl\n", out);
            if (item == 27 || item == 29)
                mir_emit_forth_signed_less_branch(
                    out, true_label, false_label);
            else
                mir_emit_forth_signed_less_branch(
                    out, false_label, true_label);
        }
        fprintf(out,
                "L%d:\n\tld hl,1\n\tjp L%d\n"
                "L%d:\n\tld hl,0\nL%d:\n\tjp L%d\n",
                true_label, compare_done,
                false_label, compare_done, push_result);
    }

    for (item = 31; item <= 33; ++item) {
        int true_label = new_label();
        int false_label = new_label();
        int logical_done = new_label();

        fprintf(out,
                "L%d:\n\tcall L%d\n"
                "\tld (ix%d),c\n\tld (ix%d),b\n",
                cases[item], pop_two,
                MIR_CRUN_STACK_POINTER, MIR_CRUN_STACK_POINTER + 1);
        if (item == 33) {
            fputs("\tld a,l\n\tand e\n\tld l,a\n"
                  "\tld a,h\n\tand d\n\tld h,a\n", out);
        } else {
            fputs("\tld a,h\n\tor l\n", out);
            if (item == 31)
                fprintf(out, "\tjp z, L%d\n", false_label);
            else
                fprintf(out, "\tjp nz, L%d\n", true_label);
            fputs("\tld a,d\n\tor e\n", out);
            if (item == 31)
                fprintf(out, "\tjp z, L%d\n", false_label);
            else
                fprintf(out, "\tjp nz, L%d\n", true_label);
            if (item == 31) {
                fputs("\tld hl,1\n", out);
                fprintf(out, "\tjp L%d\nL%d:\n\tld hl,0\n",
                        logical_done, false_label);
            } else {
                fputs("\tld hl,0\n", out);
                fprintf(out, "\tjp L%d\nL%d:\n\tld hl,1\n",
                        logical_done, true_label);
            }
            fprintf(out, "L%d:\n", logical_done);
        }
        fprintf(out, "\tjp L%d\n", push_result);
    }

    /* Branches. */
    fprintf(out, "L%d:\n", cases[34]);
    mir_emit_c_instruction_word(out, plan->instruction_a_offset);
    fprintf(out, "\tjp L%d\n", set_pc);
    for (item = 35; item <= 36; ++item) {
        fprintf(out, "L%d:\n", cases[item]);
        mir_emit_basic_pop_hl(out);
        fputs("\tld a,h\n\tor l\n", out);
        if (item == 35)
            fprintf(out, "\tjp nz, L%d\n", next);
        else
            fprintf(out, "\tjp z, L%d\n", next);
        mir_emit_c_instruction_word(out, plan->instruction_a_offset);
        fprintf(out, "\tjp L%d\n", set_pc);
    }

    /* Direct and indirect calls. */
    for (item = 37; item <= 38; ++item) {
        fprintf(out, "L%d:\n", cases[item]);
        if (item == 37) {
            mir_emit_c_instruction_word(out, plan->instruction_a_offset);
            mir_emit_forth_frame_store(out, MIR_CRUN_TEMP_FI);
            mir_emit_c_instruction_word(out, plan->instruction_b_offset);
            mir_emit_forth_frame_store(out, MIR_CRUN_TEMP_B);
        } else {
            mir_emit_basic_pop_hl(out);
            mir_emit_forth_frame_store(out, MIR_CRUN_TEMP_FI);
            fputs("\tld hl,0\n", out);
            mir_emit_forth_frame_store(out, MIR_CRUN_TEMP_B);
        }
        mir_emit_c_sync_state(out, plan, state_name);
        mir_emit_forth_frame_load(out, MIR_CRUN_TEMP_B);
        fputs("\tpush hl\n", out);
        mir_emit_forth_frame_load(out, MIR_CRUN_PC);
        fputs("\tpush hl\n", out);
        mir_emit_forth_frame_load(out, MIR_CRUN_TEMP_FI);
        fputs("\tpush hl\n", out);
        mir_emit_symbol_call(out, plan->call_function);
        fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);
        mir_emit_c_reload_state(out, plan, state_name);
        mir_emit_forth_frame_load(out, MIR_CRUN_TEMP_FI);
        mir_emit_c_function_address(out, plan);
        if (plan->function_entry_offset != 0)
            fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                    plan->function_entry_offset);
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n", out);
        fprintf(out, "\tjp L%d\n", set_pc);
    }

    /* Return. */
    fprintf(out, "L%d:\n", cases[39]);
    mir_emit_basic_pop_hl(out);
    mir_emit_forth_frame_store(out, MIR_CRUN_TEMP_V);
    mir_emit_forth_frame_load(out, MIR_CRUN_FRAME_POINTER);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, MIR_CRUN_RETURN_STACK);
    fputs("\tpop de\n\tadd hl,de\n\tadd hl,de\n"
          "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n", out);
    mir_emit_forth_frame_store(out, MIR_CRUN_PC);
    mir_emit_forth_frame_load(out, MIR_CRUN_FRAME_POINTER);
    fputs("\tdec hl\n", out);
    mir_emit_forth_frame_store(out, MIR_CRUN_FRAME_POINTER);
    mir_emit_forth_frame_load(out, MIR_CRUN_PC);
    fprintf(out, "\tbit 7,h\n\tjp nz, L%d\n", exit_label);
    mir_emit_forth_frame_load(out, MIR_CRUN_FRAME_POINTER);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, MIR_CRUN_FRAME_SIZE);
    fputs("\tex de,hl\n\tpop hl\n", out);
    mir_emit_runtime_call(out, "__mulu");
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_CRUN_FRAME_STORAGE);
    fputs("\tadd hl,de\n", out);
    mir_emit_forth_frame_store(out, MIR_CRUN_FRAME_MEMORY);
    mir_emit_forth_frame_load(out, MIR_CRUN_PC);
    fputs("\tdec hl\n", out);
    mir_emit_mul_hl_const(out, (unsigned long)plan->instruction_stride);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_CRUN_CODE);
    fputs("\tadd hl,de\n\tpush hl\n\tpop iy\n", out);
    mir_emit_forth_frame_load(out, MIR_CRUN_TEMP_V);
    fprintf(out, "\tjp L%d\n", push_result);

    fprintf(out, "L%d:\n", cases[40]);
    mir_emit_basic_pop_hl(out);
    fprintf(out, "\tjp L%d\n", next);

    /* printf bytecode. */
    {
        int collect = new_label();
        int collected = new_label();

        fprintf(out, "L%d:\n", cases[41]);
        mir_emit_c_instruction_word(out, plan->instruction_b_offset);
        mir_emit_forth_frame_store(out, MIR_CRUN_TEMP_A);
        fprintf(out, "L%d:\n", collect);
        mir_emit_forth_frame_load(out, MIR_CRUN_TEMP_A);
        fputs("\tld a,h\n\tor l\n", out);
        fprintf(out, "\tjp z, L%d\n\tdec hl\n", collected);
        mir_emit_forth_frame_store(out, MIR_CRUN_TEMP_A);
        fputs("\tadd hl,hl\n\tpush hl\n\tpush ix\n\tpop hl\n"
              "\tld de,-46\n\tadd hl,de\n\tpop de\n\tadd hl,de\n"
              "\tpush hl\n", out);
        mir_emit_basic_pop_hl(out);
        fputs("\tex de,hl\n\tpop hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
              out);
        fprintf(out, "\tjp L%d\nL%d:\n", collect, collected);
        fputs("\tpush ix\n\tpop hl\n\tld de,-46\n\tadd hl,de\n\tpush hl\n",
              out);
        mir_emit_c_instruction_word(out, plan->instruction_b_offset);
        fputs("\tpush hl\n", out);
        mir_emit_forth_frame_load(out, MIR_CRUN_STRINGS);
        fputs("\tpush hl\n", out);
        mir_emit_c_instruction_word(out, plan->instruction_a_offset);
        fputs("\tadd hl,hl\n\tex de,hl\n\tpop hl\n\tadd hl,de\n"
              "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tpush de\n", out);
        mir_emit_symbol_call(out, plan->print_function);
        fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);
        fputs("\tld hl,0\n", out);
        fprintf(out, "\tjp L%d\n", push_result);
    }

    /* Shared stack helpers. */
    fprintf(out, "L%d:\n", pop_two);
    fprintf(out,
            "\tld c,(ix%d)\n\tld b,(ix%d)\n"
            "\tdec bc\n\tdec bc\n"
            "\tld l,c\n\tld h,b\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tpush de\n"
            "\tdec bc\n\tdec bc\n"
            "\tld l,c\n\tld h,b\n"
            "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
            "\tex de,hl\n\tpop de\n\tret\n",
            MIR_CRUN_STACK_POINTER, MIR_CRUN_STACK_POINTER + 1);
    fprintf(out, "L%d:\n", push_result);
    mir_emit_basic_push_hl(out);
    fprintf(out, "\tjp L%d\n", next);

    fprintf(out, "L%d:\n", next);
    fprintf(out, "\tld de,%d\n\tadd iy,de\n",
            plan->instruction_stride);
    fprintf(out, "\tjp L%d\nL%d:\n", dispatch, set_pc);
    mir_emit_forth_frame_store(out, MIR_CRUN_PC);
    mir_emit_mul_hl_const(out, (unsigned long)plan->instruction_stride);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, MIR_CRUN_CODE);
    fputs("\tadd hl,de\n\tpush hl\n\tpop iy\n", out);
    fprintf(out, "\tjp L%d\nL%d:\n", dispatch, exit_label);
    mir_emit_c_sync_state(out, plan, state_name);
    fputs("\tld sp,ix\n\tpop ix\n\tpop iy\n\tret\n", out);

    fprintf(out, "L%d:\n", no_main);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", plan->no_main_string);
    mir_emit_symbol_call(out, plan->die_function);
    fprintf(out, "\tjp L%d\nL%d:\n", exit_label, bad_opcode);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", plan->bad_opcode_string);
    mir_emit_symbol_call(out, plan->die_function);
    fprintf(out, "\tjp L%d\n", exit_label);
}

static void mir_emit_nqueens_board_load(
    FILE *out, const struct MirNQueensSafe *plan)
{
    const char *board_name =
        asm_name_for(sym_asm_name(plan->board));

    fputs("\tpush de\n\tpush bc\n"
          "\tld h,d\n\tld l,e\n", out);
    mir_emit_mul_hl_const(out, (unsigned long)plan->row_stride);
    fputs("\tadd hl,bc\n", out);
    fprintf(out, "\tld de,%s\n\tadd hl,de\n\tld a,(hl)\n",
            board_name);
    fputs("\tpop bc\n\tpop de\n", out);
}

static void mir_emit_nqueens_safe(
    FILE *out, const struct MirNQueensSafe *plan)
{
    int horizontal = new_label();
    int up_init = new_label();
    int up_loop = new_label();
    int down_init = new_label();
    int down_loop = new_label();
    int down_in_range = new_label();
    int down_done = new_label();
    int unsafe = new_label();
    int safe = new_label();
    int exit_label = new_label();

    mir_emit_symbol_extrn(out, plan->board);
    fprintf(out,
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "\tld c,(ix%+d)\n\tld b,(ix%+d)\n\tdec bc\n"
            "L%d:\n\tbit 7,b\n\tjp nz, L%d\n",
            plan->row_offset, plan->row_offset + 1,
            plan->column_offset, plan->column_offset + 1,
            horizontal, up_init);
    mir_emit_nqueens_board_load(out, plan);
    fprintf(out,
            "\tor a\n\tjp nz, L%d\n\tdec bc\n\tjp L%d\n"
            "L%d:\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n\tdec de\n"
            "\tld c,(ix%+d)\n\tld b,(ix%+d)\n\tdec bc\n"
            "L%d:\n\tbit 7,d\n\tjp nz, L%d\n"
            "\tbit 7,b\n\tjp nz, L%d\n",
            unsafe, horizontal,
            up_init,
            plan->row_offset, plan->row_offset + 1,
            plan->column_offset, plan->column_offset + 1,
            up_loop, down_init, down_init);
    mir_emit_nqueens_board_load(out, plan);
    fprintf(out,
            "\tor a\n\tjp nz, L%d\n"
            "\tdec de\n\tdec bc\n\tjp L%d\n"
            "L%d:\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n\tinc de\n"
            "\tld c,(ix%+d)\n\tld b,(ix%+d)\n\tdec bc\n"
            "L%d:\n\tpush de\n\tpush bc\n"
            "\tbit 7,b\n\tjp nz, L%d\n"
            "\tld h,d\n\tld l,e\n"
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
            unsafe, up_loop,
            down_init,
            plan->row_offset, plan->row_offset + 1,
            plan->column_offset, plan->column_offset + 1,
            down_loop, down_done,
            plan->size_offset, plan->size_offset + 1);
    mir_emit_forth_signed_less_branch(
        out, down_in_range, down_done);
    fprintf(out, "L%d:\n\tpop bc\n\tpop de\n", down_in_range);
    mir_emit_nqueens_board_load(out, plan);
    fprintf(out,
            "\tor a\n\tjp nz, L%d\n"
            "\tinc de\n\tdec bc\n\tjp L%d\n"
            "L%d:\n\tpop bc\n\tpop de\n\tjp L%d\n"
            "L%d:\n\tld hl,0\n\tjp L%d\n"
            "L%d:\n\tld hl,1\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            unsafe, down_loop,
            down_done, safe,
            unsafe, exit_label,
            safe,
            exit_label);
}

static void mir_emit_word_insertion_sort(
    FILE *out, const struct MirWordInsertionSort *plan)
{
    enum {
        SORT_BASE = -2,
        SORT_CURRENT = -4,
        SORT_END = -6,
        SORT_KEY = -8,
        SORT_SCAN = -10
    };
    int outer = new_label();
    int inner = new_label();
    int move = new_label();
    int insert = new_label();
    int done = new_label();

    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tbit 7,h\n\tjp nz, L%d\n"
            "\tdec hl\n\tld a,h\n\tor l\n\tjp z, L%d\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
            plan->count_offset, plan->count_offset + 1,
            done, done,
            plan->array_offset, plan->array_offset + 1);
    mir_emit_forth_frame_store(out, SORT_BASE);
    fputs("\tinc hl\n\tinc hl\n", out);
    mir_emit_forth_frame_store(out, SORT_CURRENT);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tadd hl,hl\n\tex de,hl\n",
            plan->count_offset, plan->count_offset + 1);
    mir_emit_forth_frame_load(out, SORT_BASE);
    fputs("\tadd hl,de\n", out);
    mir_emit_forth_frame_store(out, SORT_END);
    fprintf(out, "L%d:\n", outer);
    mir_emit_forth_frame_load(out, SORT_CURRENT);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, SORT_END);
    fputs("\tex de,hl\n\tpop hl\n\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp nc, L%d\n", done);
    mir_emit_forth_frame_load(out, SORT_CURRENT);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n", out);
    mir_emit_forth_frame_store(out, SORT_KEY);
    mir_emit_forth_frame_load(out, SORT_CURRENT);
    fputs("\tdec hl\n\tdec hl\n", out);
    mir_emit_forth_frame_store(out, SORT_SCAN);
    fprintf(out, "L%d:\n", inner);
    mir_emit_forth_frame_load(out, SORT_SCAN);
    fputs("\tpush hl\n", out);
    mir_emit_forth_frame_load(out, SORT_BASE);
    fputs("\tex de,hl\n\tpop hl\n\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp c, L%d\n", insert);
    mir_emit_forth_frame_load(out, SORT_SCAN);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n", out);
    mir_emit_forth_frame_load(out, SORT_KEY);
    mir_emit_forth_signed_less_branch(out, move, insert);
    fprintf(out, "L%d:\n", move);
    mir_emit_forth_frame_load(out, SORT_SCAN);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tinc hl\n"
          "\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
    mir_emit_forth_frame_load(out, SORT_SCAN);
    fputs("\tdec hl\n\tdec hl\n", out);
    mir_emit_forth_frame_store(out, SORT_SCAN);
    fprintf(out, "\tjp L%d\nL%d:\n", inner, insert);
    mir_emit_forth_frame_load(out, SORT_SCAN);
    fputs("\tinc hl\n\tinc hl\n\tpush hl\n", out);
    mir_emit_forth_frame_load(out, SORT_KEY);
    fputs("\tex de,hl\n\tpop hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
          out);
    mir_emit_forth_frame_load(out, SORT_CURRENT);
    fputs("\tinc hl\n\tinc hl\n", out);
    mir_emit_forth_frame_store(out, SORT_CURRENT);
    fprintf(out,
            "\tjp L%d\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            outer, done);
}

static void mir_emit_visit_count(
    FILE *out, const struct MirVisitCount *plan)
{
    int no_adjust = new_label();
    int done = new_label();

    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
            plan->count_offset, plan->count_offset + 1);
    mir_emit_mul_hl_const(out, (unsigned long)plan->scale);
    fputs("\tld c,l\n\tld b,h\n", out);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tld a,h\n\tand 1\n\tld h,a\n"
            "\tpush hl\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tld a,h\n\tand 1\n\tld h,a\n"
            "\tpop de\n\tadd hl,de\n"
            "\tld de,512\n\tor a\n\tsbc hl,de\n"
            "\tjp c, L%d\n\tjp z, L%d\n"
            "\tld h,b\n\tld l,c\n\tld de,32\n\tor a\n\tsbc hl,de\n"
            "\tjp L%d\n"
            "L%d:\n\tld h,b\n\tld l,c\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            plan->offset_offset, plan->offset_offset + 1,
            plan->count_offset, plan->count_offset + 1,
            no_adjust, no_adjust, done,
            no_adjust, done);
}

static void mir_emit_exact_vla_allocate(
    FILE *out, int count_offset, int saved_sp_offset)
{
    fputs("\tld hl,0\n\tadd hl,sp\n", out);
    mir_emit_forth_frame_store(out, saved_sp_offset);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tadd hl,hl\n"
            "\tex de,hl\n\tld hl,0\n\tadd hl,sp\n"
            "\tor a\n\tsbc hl,de\n\tld sp,hl\n",
            count_offset, count_offset + 1);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
}

static void mir_emit_exact_vla_restore(
    FILE *out, int saved_sp_offset)
{
    mir_emit_forth_frame_load(out, saved_sp_offset);
    fputs("\tld sp,hl\n", out);
}

static void mir_emit_vla_stable(
    FILE *out, const struct MirVlaStable *plan)
{
    enum {
        FIRST = -2,
        STABLE = -4,
        INDEX = -6,
        SAVED_SP = -8
    };
    int loop = new_label();
    int body = new_label();
    int first = new_label();
    int compare = new_label();
    int restore = new_label();
    int done = new_label();

    fputs("\tld hl,0\n", out);
    mir_emit_forth_frame_store(out, FIRST);
    fputs("\tld hl,1\n", out);
    mir_emit_forth_frame_store(out, STABLE);
    fputs("\tld hl,0\n", out);
    mir_emit_forth_frame_store(out, INDEX);
    fprintf(out, "L%d:\n", loop);
    mir_emit_forth_frame_load(out, INDEX);
    fprintf(out,
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
            plan->iter_offset, plan->iter_offset + 1);
    mir_emit_forth_signed_less_branch(out, body, done);
    fprintf(out, "L%d:\n", body);
    mir_emit_exact_vla_allocate(out, plan->count_offset, SAVED_SP);
    mir_emit_forth_frame_load(out, INDEX);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z, L%d\n\tjp L%d\n", first, compare);
    fprintf(out, "L%d:\n\tld hl,0\n\tadd hl,sp\n", first);
    mir_emit_forth_frame_store(out, FIRST);
    fprintf(out, "\tjp L%d\nL%d:\n", restore, compare);
    fputs("\tld hl,0\n\tadd hl,sp\n\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, FIRST);
    fputs("\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp z, L%d\n\tld hl,0\n", restore);
    mir_emit_forth_frame_store(out, STABLE);
    fprintf(out, "L%d:\n", restore);
    mir_emit_exact_vla_restore(out, SAVED_SP);
    mir_emit_forth_frame_load(out, INDEX);
    fputs("\tinc hl\n", out);
    mir_emit_forth_frame_store(out, INDEX);
    fprintf(out, "\tjp L%d\nL%d:\n", loop, done);
    mir_emit_forth_frame_load(out, STABLE);
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_nested_vla_stable(
    FILE *out, const struct MirNestedVlaStable *plan)
{
    enum {
        OUTER_FIRST = -2,
        INNER_FIRST = -4,
        OUTER_STABLE = -6,
        INNER_STABLE = -8,
        OUTER_INDEX = -10,
        INNER_INDEX = -12,
        OUTER_SP = -14,
        INNER_SP = -16
    };
    int outer_loop = new_label();
    int outer_body = new_label();
    int outer_first = new_label();
    int outer_compare = new_label();
    int outer_ready = new_label();
    int inner_loop = new_label();
    int inner_body = new_label();
    int inner_first = new_label();
    int inner_compare = new_label();
    int inner_ready = new_label();
    int inner_done = new_label();
    int outer_done = new_label();
    int return_false = new_label();
    int exit_label = new_label();

    fputs("\tld hl,0\n", out);
    mir_emit_forth_frame_store(out, OUTER_FIRST);
    mir_emit_forth_frame_store(out, INNER_FIRST);
    fputs("\tld hl,1\n", out);
    mir_emit_forth_frame_store(out, OUTER_STABLE);
    mir_emit_forth_frame_store(out, INNER_STABLE);
    fputs("\tld hl,0\n", out);
    mir_emit_forth_frame_store(out, OUTER_INDEX);
    fprintf(out, "L%d:\n", outer_loop);
    mir_emit_forth_frame_load(out, OUTER_INDEX);
    fprintf(out,
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
            plan->outer_offset, plan->outer_offset + 1);
    mir_emit_forth_signed_less_branch(out, outer_body, outer_done);
    fprintf(out, "L%d:\n", outer_body);
    mir_emit_exact_vla_allocate(out, plan->count_offset, OUTER_SP);
    mir_emit_forth_frame_load(out, OUTER_INDEX);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z, L%d\n\tjp L%d\n", outer_first, outer_compare);
    fprintf(out, "L%d:\n\tld hl,0\n\tadd hl,sp\n", outer_first);
    mir_emit_forth_frame_store(out, OUTER_FIRST);
    fprintf(out, "\tjp L%d\nL%d:\n", outer_ready, outer_compare);
    fputs("\tld hl,0\n\tadd hl,sp\n\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, OUTER_FIRST);
    fputs("\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp z, L%d\n\tld hl,0\n", outer_ready);
    mir_emit_forth_frame_store(out, OUTER_STABLE);
    fprintf(out, "L%d:\n\tld hl,0\n", outer_ready);
    mir_emit_forth_frame_store(out, INNER_INDEX);

    fprintf(out, "L%d:\n", inner_loop);
    mir_emit_forth_frame_load(out, INNER_INDEX);
    fprintf(out,
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
            plan->inner_offset, plan->inner_offset + 1);
    mir_emit_forth_signed_less_branch(out, inner_body, inner_done);
    fprintf(out, "L%d:\n", inner_body);
    mir_emit_exact_vla_allocate(out, plan->count_offset, INNER_SP);
    mir_emit_forth_frame_load(out, OUTER_INDEX);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp nz, L%d\n", inner_compare);
    mir_emit_forth_frame_load(out, INNER_INDEX);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z, L%d\n", inner_first);
    fprintf(out, "L%d:\n", inner_compare);
    fputs("\tld hl,0\n\tadd hl,sp\n\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, INNER_FIRST);
    fputs("\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp z, L%d\n\tld hl,0\n", inner_ready);
    mir_emit_forth_frame_store(out, INNER_STABLE);
    fprintf(out, "\tjp L%d\n", inner_ready);
    fprintf(out, "L%d:\n\tld hl,0\n\tadd hl,sp\n", inner_first);
    mir_emit_forth_frame_store(out, INNER_FIRST);
    fprintf(out, "L%d:\n", inner_ready);
    mir_emit_exact_vla_restore(out, INNER_SP);
    mir_emit_forth_frame_load(out, INNER_INDEX);
    fputs("\tinc hl\n", out);
    mir_emit_forth_frame_store(out, INNER_INDEX);
    fprintf(out, "\tjp L%d\nL%d:\n", inner_loop, inner_done);
    mir_emit_exact_vla_restore(out, OUTER_SP);
    mir_emit_forth_frame_load(out, OUTER_INDEX);
    fputs("\tinc hl\n", out);
    mir_emit_forth_frame_store(out, OUTER_INDEX);
    fprintf(out, "\tjp L%d\nL%d:\n", outer_loop, outer_done);
    mir_emit_forth_frame_load(out, OUTER_STABLE);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z, L%d\n", return_false);
    mir_emit_forth_frame_load(out, INNER_STABLE);
    fprintf(out,
            "\tjp L%d\n"
            "L%d:\n\tld hl,0\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            exit_label, return_false, exit_label);
}

static void mir_emit_vla_loop_result(
    FILE *out, const struct MirVlaLoopResult *plan)
{
    enum {
        INDEX = -2,
        LAST = -4,
        SAVED_SP = -6
    };
    int loop = new_label();
    int body = new_label();
    int restore = new_label();
    int done = new_label();

    fputs("\tld hl,0\n", out);
    mir_emit_forth_frame_store(out, INDEX);
    mir_emit_forth_frame_store(out, LAST);
    fprintf(out, "L%d:\n", loop);
    mir_emit_forth_frame_load(out, INDEX);
    fprintf(out,
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
            plan->iter_offset, plan->iter_offset + 1);
    mir_emit_forth_signed_less_branch(out, body, done);
    fprintf(out, "L%d:\n", body);
    mir_emit_exact_vla_allocate(out, plan->count_offset, SAVED_SP);
    mir_emit_forth_frame_load(out, INDEX);
    fprintf(out,
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "\tadd hl,de\n\tdec hl\n\tld a,l\n\tand 15\n"
            "\tld l,a\n\tld h,0\n",
            plan->count_offset, plan->count_offset + 1);
    mir_emit_forth_frame_store(out, LAST);
    mir_emit_forth_frame_load(out, INDEX);
    fputs("\tbit 0,l\n", out);
    fprintf(out, "\tjp z, L%d\n\tld a,l\n\tand 15\n\tld e,a\n\tld d,0\n",
            restore);
    mir_emit_forth_frame_load(out, LAST);
    fputs("\tadd hl,de\n", out);
    mir_emit_forth_frame_store(out, LAST);
    fprintf(out, "L%d:\n", restore);
    mir_emit_exact_vla_restore(out, SAVED_SP);
    mir_emit_forth_frame_load(out, INDEX);
    fputs("\tinc hl\n", out);
    mir_emit_forth_frame_store(out, INDEX);
    fprintf(out, "\tjp L%d\nL%d:\n", loop, done);
    mir_emit_forth_frame_load(out, LAST);
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_file_seek_start(
    FILE *out, const struct MirFileLength *plan)
{
    fputs("\tld hl,0\n\tpush hl\n\tld de,0\n\tpush de\n\tpush hl\n", out);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tpush hl\n",
            plan->file_offset, plan->file_offset + 1);
    mir_emit_symbol_call(out, plan->seek_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n\tpop bc\n", out);
}

static void mir_emit_file_length(
    FILE *out, const struct MirFileLength *plan)
{
    const char *buffer_name =
        asm_name_for(sym_asm_name(plan->buffer));
    int loop = new_label();
    int scanned = new_label();
    int add_count = new_label();
    int no_carry = new_label();
    int done = new_label();

    mir_emit_symbol_extrn(out, plan->buffer);
    fputs("\tld hl,0\n\tld de,0\n", out);
    mir_emit_frame_long_store(out, -4);
    mir_emit_file_seek_start(out, plan);
    fprintf(out, "L%d:\n", loop);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tpush hl\n",
            plan->file_offset, plan->file_offset + 1);
    mir_emit_symbol_call(out, plan->eof_function);
    fputs("\tpop bc\n\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp nz, L%d\n", done);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tpush hl\n"
            "\tld hl,%d\n\tpush hl\n"
            "\tld hl,1\n\tpush hl\n"
            "\tld hl,%s\n\tpush hl\n",
            plan->file_offset, plan->file_offset + 1,
            plan->block_size, buffer_name);
    mir_emit_symbol_call(out, plan->read_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n\tpop bc\n"
          "\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z, L%d\n", done);
    fprintf(out,
            "\tld hl,%s\n\tld bc,%d\n\tld a,%d\n\tcpir\n"
            "\tjp z, L%d\n\tld hl,%d\n\tjp L%d\n"
            "L%d:\n\tld hl,%d\n\tor a\n\tsbc hl,bc\n"
            "L%d:\n\tld c,l\n\tld b,h\n",
            buffer_name, plan->block_size, plan->marker,
            scanned, plan->block_size, add_count,
            scanned, plan->block_size - 1,
            add_count);
    mir_emit_frame_long_load(out, -4);
    fprintf(out,
            "\tadd hl,bc\n\tjp nc, L%d\n\tinc de\nL%d:\n",
            no_carry, no_carry);
    mir_emit_frame_long_store(out, -4);
    fprintf(out, "\tjp L%d\nL%d:\n", loop, done);
    mir_emit_file_seek_start(out, plan);
    mir_emit_frame_long_load(out, -4);
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_wide_gcd(
    FILE *out, const struct MirWideGcd *plan)
{
    enum {
        LEFT = -4,
        RIGHT = -8,
        OLD_RIGHT = -12
    };
    int swap = new_label();
    int ordered = new_label();
    int loop = new_label();
    int done = new_label();

    mir_emit_frame_long_load(out, plan->left_offset);
    mir_emit_frame_long_store(out, LEFT);
    mir_emit_frame_long_load(out, plan->right_offset);
    mir_emit_frame_long_store(out, RIGHT);
    mir_emit_forth_frame_load(out, LEFT + 2);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, RIGHT + 2);
    fputs("\tex de,hl\n\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp c, L%d\n\tjp nz, L%d\n", swap, ordered);
    mir_emit_forth_frame_load(out, LEFT);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, RIGHT);
    fputs("\tex de,hl\n\tor a\n\tsbc hl,de\n", out);
    fprintf(out, "\tjp nc, L%d\nL%d:\n", ordered, swap);
    mir_emit_frame_long_load(out, LEFT);
    mir_emit_frame_long_store(out, OLD_RIGHT);
    mir_emit_frame_long_load(out, RIGHT);
    mir_emit_frame_long_store(out, LEFT);
    mir_emit_frame_long_load(out, OLD_RIGHT);
    mir_emit_frame_long_store(out, RIGHT);
    fprintf(out, "L%d:\n", ordered);
    fprintf(out, "L%d:\n", loop);
    mir_emit_frame_long_load(out, RIGHT);
    fputs("\tld a,l\n\tor h\n\tor e\n\tor d\n", out);
    fprintf(out, "\tjp z, L%d\n", done);
    mir_emit_frame_long_store(out, OLD_RIGHT);
    mir_emit_frame_long_load(out, LEFT);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_frame_long_load(out, RIGHT);
    mir_emit_runtime_call(out, "__lmu");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_frame_long_store(out, RIGHT);
    mir_emit_frame_long_load(out, OLD_RIGHT);
    mir_emit_frame_long_store(out, LEFT);
    fprintf(out, "\tjp L%d\nL%d:\n", loop, done);
    mir_emit_frame_long_load(out, LEFT);
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_add_frame_longs(
    FILE *out, int left_offset, int right_offset)
{
    mir_emit_frame_long_load(out, left_offset);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_frame_long_load(out, right_offset);
    fputs("\tpop bc\n\tadd hl,bc\n\tex de,hl\n"
          "\tpop bc\n\tadc hl,bc\n\tex de,hl\n", out);
}

static void mir_emit_fixed_long_add(
    FILE *out, const struct MirFixedLongAdd *plan)
{
    enum {
        DESTINATION = -2,
        SOURCE = -4,
        COUNT = -5,
        CARRY = -6
    };
    int loop = new_label();
    int no_input_carry = new_label();
    int negative = new_label();
    int reduce = new_label();
    int reduced = new_label();
    int store = new_label();
    int done = new_label();
    int last_offset = (plan->count - 1) * 4;

    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tld de,%d\n\tadd hl,de\n",
            plan->destination_offset, plan->destination_offset + 1,
            last_offset);
    mir_emit_forth_frame_store(out, DESTINATION);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tld de,%d\n\tadd hl,de\n",
            plan->source_offset, plan->source_offset + 1,
            last_offset);
    mir_emit_forth_frame_store(out, SOURCE);
    fprintf(out, "\tld (ix%d),%d\n\tld (ix%d),0\n",
            COUNT, plan->count, CARRY);
    fprintf(out, "L%d:\n", loop);
    mir_emit_pointer_long_load(out, DESTINATION);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_pointer_long_load(out, SOURCE);
    fputs("\tpop bc\n\tadd hl,bc\n\tex de,hl\n"
          "\tpop bc\n\tadc hl,bc\n\tex de,hl\n"
          "\tld a,(ix-6)\n\tor a\n", out);
    fprintf(out,
            "\tjp z, L%d\n\tinc hl\n\tjp nz, L%d\n\tinc de\n"
            "L%d:\n\tbit 7,d\n\tjp nz, L%d\n"
            "\tld a,d\n\tor e\n\tjp nz, L%d\n"
            "\tld bc,%ld\n\tor a\n\tsbc hl,bc\n"
            "\tjp nc, L%d\n\tadd hl,bc\n\tjp L%d\n"
            "L%d:\n\tld bc,%ld\n\tor a\n\tsbc hl,bc\n"
            "\tjp nc, L%d\n\tdec de\n"
            "L%d:\n\tld (ix%d),1\n\tjp L%d\n"
            "L%d:\n\tld (ix%d),0\n",
            no_input_carry, no_input_carry,
            no_input_carry, negative,
            reduce,
            plan->base, reduced, negative,
            reduce, plan->base, reduced,
            reduced, CARRY, store,
            negative, CARRY);
    fprintf(out, "L%d:\n", store);
    mir_emit_pointer_long_store(out, DESTINATION);
    mir_emit_frame_pointer_adjust(out, DESTINATION, -4);
    mir_emit_frame_pointer_adjust(out, SOURCE, -4);
    fprintf(out,
            "\tdec (ix%d)\n\tjp nz, L%d\n\tjp L%d\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            COUNT, loop, done, done);
}

static void mir_emit_fixed_long_zero(
    FILE *out, const struct MirFixedLongZero *plan)
{
    int loop = new_label();
    int nonzero = new_label();
    int done = new_label();

    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tld b,%d\n"
            "L%d:\n\tld a,(hl)\n\tinc hl\n\tor (hl)\n\tinc hl\n"
            "\tor (hl)\n\tinc hl\n\tor (hl)\n\tinc hl\n"
            "\tjp nz, L%d\n\tdjnz L%d\n"
            "\tld hl,1\n\tjp L%d\n"
            "L%d:\n\tld hl,0\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            plan->array_offset, plan->array_offset + 1,
            plan->count, loop, nonzero, loop,
            done, nonzero, done);
}

static void mir_emit_fixed_long_mul_div(
    FILE *out, const struct MirFixedLongMulDiv *plan)
{
    enum {
        POINTER = -2,
        COUNT = -3,
        CARRY = -8,
        REMAINDER = -12,
        VALUE = -16
    };
    int multiply_loop = new_label();
    int divide_loop = new_label();
    int done = new_label();
    int last_offset = (plan->count - 1) * 4;

    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n\tld de,%d\n\tadd hl,de\n",
            plan->array_offset, plan->array_offset + 1, last_offset);
    mir_emit_forth_frame_store(out, POINTER);
    fprintf(out, "\tld (ix%d),%d\n\tld hl,0\n\tld de,0\n",
            COUNT, plan->count);
    mir_emit_frame_long_store(out, CARRY);
    fprintf(out, "L%d:\n", multiply_loop);
    mir_emit_pointer_long_load(out, POINTER);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_frame_long_load(out, plan->multiplier_offset);
    mir_emit_runtime_call(out, "__lmul");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_frame_long_store(out, VALUE);
    mir_emit_add_frame_longs(out, VALUE, CARRY);
    mir_emit_frame_long_store(out, VALUE);

    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,%ld\n\tld de,0\n", plan->base);
    mir_emit_runtime_call(out, "__lms");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_pointer_long_store(out, POINTER);

    mir_emit_frame_long_load(out, VALUE);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,%ld\n\tld de,0\n", plan->base);
    mir_emit_runtime_call(out, "__lds");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_frame_long_store(out, CARRY);
    mir_emit_frame_pointer_adjust(out, POINTER, -4);
    fprintf(out, "\tdec (ix%d)\n\tjp nz, L%d\n",
            COUNT, multiply_loop);

    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
            plan->array_offset, plan->array_offset + 1);
    mir_emit_forth_frame_store(out, POINTER);
    fprintf(out, "\tld (ix%d),%d\n\tld hl,0\n\tld de,0\n",
            COUNT, plan->count);
    mir_emit_frame_long_store(out, REMAINDER);
    fprintf(out, "L%d:\n", divide_loop);
    mir_emit_frame_long_load(out, REMAINDER);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,%ld\n\tld de,0\n", plan->base);
    mir_emit_runtime_call(out, "__lmul");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_frame_long_store(out, VALUE);
    mir_emit_pointer_long_load(out, POINTER);
    mir_emit_frame_long_store(out, CARRY);
    mir_emit_add_frame_longs(out, VALUE, CARRY);
    mir_emit_frame_long_store(out, VALUE);

    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_frame_long_load(out, plan->divisor_offset);
    mir_emit_runtime_call(out, "__lds");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_pointer_long_store(out, POINTER);

    mir_emit_frame_long_load(out, VALUE);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_frame_long_load(out, plan->divisor_offset);
    mir_emit_runtime_call(out, "__lms");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_frame_long_store(out, REMAINDER);
    mir_emit_frame_pointer_adjust(out, POINTER, 4);
    fprintf(out,
            "\tdec (ix%d)\n\tjp nz, L%d\n\tjp L%d\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            COUNT, divide_loop, done, done);
}

static void mir_emit_long_spigot(
    FILE *out, const struct MirLongSpigot *plan)
{
    enum {
        OUTER = -2,
        INDEX = -4,
        ACCUMULATOR = -8,
        CARRY = -12,
        DIVISOR = -14,
        POINTER = -16,
        VALUE = -20
    };
    const char *array_name =
        asm_name_for(sym_asm_name(plan->array));
    int outer_loop = new_label();
    int inner_loop = new_label();
    int inner_done = new_label();
    int done = new_label();

    mir_emit_symbol_extrn(out, plan->array);
    fprintf(out,
            "\tld hl,%s\n\tld (hl),%ld\n\tinc hl\n"
            "\tld (hl),%ld\n\tinc hl\n\tld (hl),0\n\tinc hl\n\tld (hl),0\n"
            "\tld hl,%s\n\tld de,%s+4\n\tld bc,%d\n\tldir\n"
            "\tld hl,%d\n",
            array_name, plan->initial_value & 0xffL,
            (plan->initial_value >> 8) & 0xffL,
            array_name, array_name,
            (plan->array_count - 1) * 4,
            plan->outer_start);
    mir_emit_forth_frame_store(out, OUTER);
    fputs("\tld hl,0\n\tld de,0\n", out);
    mir_emit_frame_long_store(out, CARRY);

    fprintf(out, "L%d:\n", outer_loop);
    mir_emit_forth_frame_load(out, OUTER);
    fputs("\tbit 7,h\n", out);
    fprintf(out, "\tjp nz, L%d\n\tld a,h\n\tor l\n\tjp z, L%d\n",
            done, done);
    fputs("\tld hl,0\n\tld de,0\n", out);
    mir_emit_frame_long_store(out, ACCUMULATOR);
    mir_emit_forth_frame_load(out, OUTER);
    mir_emit_forth_frame_store(out, INDEX);

    fprintf(out, "L%d:\n", inner_loop);
    mir_emit_forth_frame_load(out, INDEX);
    fputs("\tadd hl,hl\n\tadd hl,hl\n", out);
    fprintf(out, "\tld de,%s\n\tadd hl,de\n", array_name);
    mir_emit_forth_frame_store(out, POINTER);
    mir_emit_pointer_long_load(out, POINTER);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,%ld\n\tld de,0\n", plan->radix);
    mir_emit_runtime_call(out, "__lmul");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_frame_long_store(out, VALUE);
    mir_emit_add_frame_longs(out, VALUE, ACCUMULATOR);
    mir_emit_frame_long_store(out, ACCUMULATOR);

    mir_emit_forth_frame_load(out, INDEX);
    fputs("\tadd hl,hl\n\tdec hl\n", out);
    mir_emit_forth_frame_store(out, DIVISOR);
    mir_emit_frame_long_load(out, ACCUMULATOR);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_forth_frame_load(out, DIVISOR);
    fputs("\tld de,0\n", out);
    mir_emit_runtime_call(out, "__lms");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_pointer_long_store(out, POINTER);

    mir_emit_frame_long_load(out, ACCUMULATOR);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_forth_frame_load(out, DIVISOR);
    fputs("\tld de,0\n", out);
    mir_emit_runtime_call(out, "__lds");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_frame_long_store(out, ACCUMULATOR);
    mir_emit_forth_frame_load(out, INDEX);
    fputs("\tdec hl\n", out);
    mir_emit_forth_frame_store(out, INDEX);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z, L%d\n", inner_done);
    mir_emit_frame_long_load(out, ACCUMULATOR);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_forth_frame_load(out, INDEX);
    fputs("\tld de,0\n", out);
    mir_emit_runtime_call(out, "__lmul");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_frame_long_store(out, ACCUMULATOR);
    fprintf(out, "\tjp L%d\n", inner_loop);

    fprintf(out, "L%d:\n", inner_done);
    mir_emit_frame_long_load(out, ACCUMULATOR);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,%ld\n\tld de,0\n", plan->radix);
    mir_emit_runtime_call(out, "__lds");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_frame_long_store(out, VALUE);
    mir_emit_add_frame_longs(out, CARRY, VALUE);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->digit_format_string);
    mir_emit_resolved_symbol_call(
        out, plan->print_function, plan->digit_print_name);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n\tld hl,1\n\tpush hl\n", out);
    mir_emit_symbol_call(out, plan->flush_function);
    fputs("\tpop bc\n", out);

    mir_emit_frame_long_load(out, ACCUMULATOR);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,%ld\n\tld de,0\n", plan->radix);
    mir_emit_runtime_call(out, "__lms");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_frame_long_store(out, CARRY);
    mir_emit_forth_frame_load(out, OUTER);
    fprintf(out, "\tld de,%d\n\tor a\n\tsbc hl,de\n",
            plan->outer_step);
    mir_emit_forth_frame_store(out, OUTER);
    fprintf(out, "\tjp L%d\nL%d:\n\tld hl,S%d\n\tpush hl\n",
            outer_loop, done, plan->done_string);
    mir_emit_resolved_symbol_call(
        out, plan->print_function, plan->done_print_name);
    fputs("\tpop bc\n\tld hl,0\n\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_parameter_as_long(
    FILE *out, int offset, int size, int is_unsigned)
{
    if (size == 4) {
        mir_emit_frame_long_load(out, offset);
        return;
    }
    fprintf(out, "\tld l,(ix%+d)\n", offset);
    if (size == 1) {
        if (is_unsigned)
            fputs("\tld h,0\n", out);
        else
            fputs("\tld a,l\n\trlca\n\tsbc a,a\n\tld h,a\n", out);
    } else {
        fprintf(out, "\tld h,(ix%+d)\n", offset + 1);
    }
    if (is_unsigned)
        fputs("\tld de,0\n", out);
    else
        fputs("\tld a,h\n\trlca\n\tsbc a,a\n\tld e,a\n\tld d,a\n", out);
}

static void mir_emit_wide_frame_less_branch(
    FILE *out, int left_offset, int right_offset, int is_unsigned,
    int true_label, int false_label)
{
    int high_top_equal = new_label();
    int high_equal = new_label();
    int low_top_equal = new_label();

    mir_emit_forth_frame_load(out, left_offset + 2);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, right_offset + 2);
    fputs("\tex de,hl\n", out);
    if (is_unsigned) {
        fprintf(out,
                "\tld a,h\n\tcp d\n\tjp z, L%d\n"
                "\tjp c, L%d\n\tjp L%d\n",
                high_top_equal, true_label, false_label);
    } else {
        fprintf(out,
                "\tld a,h\n\txor 128\n\tld b,a\n"
                "\tld a,d\n\txor 128\n\tcp b\n\tjp z, L%d\n"
                "\tjp c, L%d\n\tjp L%d\n",
                high_top_equal, false_label, true_label);
    }
    fprintf(out,
            "L%d:\n\tld a,l\n\tcp e\n\tjp z, L%d\n"
            "\tjp c, L%d\n\tjp L%d\n",
            high_top_equal, high_equal, true_label, false_label);
    fprintf(out, "L%d:\n", high_equal);
    mir_emit_forth_frame_load(out, left_offset);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, right_offset);
    fputs("\tex de,hl\n", out);
    fprintf(out,
            "\tld a,h\n\tcp d\n\tjp z, L%d\n"
            "\tjp c, L%d\n\tjp L%d\n"
            "L%d:\n\tld a,l\n\tcp e\n"
            "\tjp c, L%d\n\tjp L%d\n",
            low_top_equal, true_label, false_label,
            low_top_equal, true_label, false_label);
}

static void mir_emit_typed_array_pointer(
    FILE *out, int index_offset, int delta, int element_size,
    int base_offset)
{
    int nonnegative = new_label();

    mir_emit_forth_frame_load(out, index_offset);
    fprintf(out, "\tld de,%d\n\tadd hl,de\n\tbit 7,h\n\tjp z, L%d\n",
            delta, nonnegative);
    mir_emit_forth_frame_load(out, index_offset);
    fputs("\txor a\n\tsub l\n\tld l,a\n\tsbc a,a\n\tsub h\n\tld h,a\n",
          out);
    fprintf(out, "\tld de,%d\n\tadd hl,de\n", delta);
    fprintf(out, "L%d:\n", nonnegative);
    if (element_size >= 2)
        fputs("\tadd hl,hl\n", out);
    if (element_size == 4)
        fputs("\tadd hl,hl\n", out);
    fputs("\tex de,hl\n", out);
    mir_emit_forth_frame_load(out, base_offset);
    fputs("\tadd hl,de\n", out);
}

static void mir_emit_typed_array_load(
    FILE *out, int index_offset, int delta,
    const struct MirTypedArrayConditions *plan, int base_offset)
{
    mir_emit_typed_array_pointer(
        out, index_offset, delta, plan->element_size, base_offset);
    if (plan->element_size == 1) {
        fputs("\tld l,(hl)\n", out);
        if (plan->is_unsigned)
            fputs("\tld h,0\n", out);
        else
            fputs("\tld a,l\n\trlca\n\tsbc a,a\n\tld h,a\n", out);
    } else {
        fputs("\tld a,(hl)\n\tinc hl\n\tld h,(hl)\n\tld l,a\n", out);
    }
}

static void mir_emit_typed_array_update(
    FILE *out, int index_offset, int amount,
    const struct MirTypedArrayConditions *plan, int base_offset)
{
    mir_emit_typed_array_pointer(
        out, index_offset, 14, plan->element_size, base_offset);
    fputs("\tpush hl\n", out);
    if (plan->element_size == 1) {
        fputs("\tld l,(hl)\n\tld h,0\n", out);
    } else {
        fputs("\tld a,(hl)\n\tinc hl\n\tld h,(hl)\n\tld l,a\n", out);
    }
    fprintf(out, "\tld de,%d\n\tadd hl,de\n\tex de,hl\n\tpop hl\n"
                 "\tld (hl),e\n",
            amount);
    if (plan->element_size >= 2)
        fputs("\tinc hl\n\tld (hl),d\n", out);
    if (plan->element_size == 4)
        fputs("\tinc hl\n\tld (hl),0\n\tinc hl\n\tld (hl),0\n", out);
}

static void mir_emit_typed_array_condition(
    FILE *out, const struct MirTypedArrayConditions *plan,
    int index_offset, int base_offset, int relation, int amount)
{
    int true_label = new_label();
    int false_label = new_label();

    mir_emit_typed_array_load(out, index_offset, 12, plan, base_offset);
    mir_emit_forth_frame_store(out, -12);
    mir_emit_typed_array_load(out, index_offset, 13, plan, base_offset);
    mir_emit_forth_frame_store(out, -14);
    if (relation == '=') {
        mir_emit_forth_frame_load(out, -12);
        fputs("\tex de,hl\n", out);
        mir_emit_forth_frame_load(out, -14);
        fputs("\tor a\n\tsbc hl,de\n", out);
        fprintf(out, "\tjp z, L%d\n\tjp L%d\n", true_label, false_label);
    } else {
        int left_offset = relation == '>' || relation == 'l' ? -14 : -12;
        int right_offset = relation == '>' || relation == 'l' ? -12 : -14;
        int less_true = relation == '>' || relation == '<';

        mir_emit_forth_frame_load(out, left_offset);
        fputs("\tex de,hl\n", out);
        mir_emit_forth_frame_load(out, right_offset);
        fputs("\tex de,hl\n", out);
        if (plan->is_unsigned) {
            fputs("\tor a\n\tsbc hl,de\n", out);
            fprintf(out, less_true
                    ? "\tjp c, L%d\n\tjp L%d\n"
                    : "\tjp c, L%d\n\tjp L%d\n",
                    less_true ? true_label : false_label,
                    less_true ? false_label : true_label);
        } else {
            mir_emit_forth_signed_less_branch(
                out,
                less_true ? true_label : false_label,
                less_true ? false_label : true_label);
        }
    }
    fprintf(out, "L%d:\n", true_label);
    mir_emit_typed_array_update(
        out, index_offset, amount, plan, base_offset);
    fprintf(out, "L%d:\n", false_label);
}

static void mir_emit_typed_array_conditions(
    FILE *out, const struct MirTypedArrayConditions *plan)
{
    enum {
        INDEX = -4,
        MAXIMUM = -8,
        ARRAY_BASE = -10,
        LEFT = -12,
        RIGHT = -14
    };
    int frame_bytes = 14 + plan->count * plan->element_size;
    int init_loop = new_label();
    int loop = new_label();
    int body = new_label();
    int done = new_label();

    fputs("\tpush ix\n\tpop hl\n", out);
    fprintf(out, "\tld de,-%d\n\tadd hl,de\n", frame_bytes);
    mir_emit_forth_frame_store(out, ARRAY_BASE);
    fputs("\tld b,50\n\txor a\n", out);
    mir_emit_forth_frame_load(out, ARRAY_BASE);
    fprintf(out, "L%d:\n\tld (hl),a\n\tinc hl\n", init_loop);
    if (plan->element_size >= 2)
        fputs("\tld (hl),0\n\tinc hl\n", out);
    if (plan->element_size == 4)
        fputs("\tld (hl),0\n\tinc hl\n\tld (hl),0\n\tinc hl\n", out);
    fprintf(out, "\tinc a\n\tdjnz L%d\n", init_loop);
    mir_emit_parameter_as_long(
        out, plan->minimum_offset, plan->element_size, plan->is_unsigned);
    mir_emit_frame_long_store(out, INDEX);
    mir_emit_parameter_as_long(
        out, plan->maximum_offset, plan->element_size, plan->is_unsigned);
    mir_emit_frame_long_store(out, MAXIMUM);
    fprintf(out, "L%d:\n", loop);
    mir_emit_wide_frame_less_branch(
        out, INDEX, MAXIMUM,
        plan->element_size == 4 && plan->is_unsigned,
        body, done);
    fprintf(out, "L%d:\n", body);
    mir_emit_typed_array_condition(out, plan, INDEX, ARRAY_BASE, '>', 3);
    mir_emit_typed_array_condition(out, plan, INDEX, ARRAY_BASE, '<', 7);
    mir_emit_typed_array_condition(out, plan, INDEX, ARRAY_BASE, 'g', 3);
    mir_emit_typed_array_condition(out, plan, INDEX, ARRAY_BASE, 'l', 7);
    mir_emit_typed_array_condition(out, plan, INDEX, ARRAY_BASE, '=', 9);
    mir_emit_frame_long_load(out, INDEX);
    fputs("\tinc hl\n\tld a,h\n\tor l\n", out);
    {
        int no_carry = new_label();
        fprintf(out, "\tjp nz, L%d\n\tinc de\nL%d:\n",
                no_carry, no_carry);
    }
    mir_emit_frame_long_store(out, INDEX);
    fprintf(out, "\tjp L%d\nL%d:\n", loop, done);
    mir_emit_forth_frame_load(out, ARRAY_BASE);
    fprintf(out, "\tld de,%d\n\tadd hl,de\n",
            10 * plan->element_size);
    if (plan->element_size == 1) {
        fputs("\tld l,(hl)\n", out);
        if (plan->is_unsigned)
            fputs("\tld h,0\n", out);
        else
            fputs("\tld a,l\n\trlca\n\tsbc a,a\n\tld h,a\n", out);
    } else if (plan->element_size == 2) {
        fputs("\tld a,(hl)\n\tinc hl\n\tld h,(hl)\n\tld l,a\n", out);
    } else {
        fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n\tinc hl\n"
              "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
              "\tld l,c\n\tld h,b\n", out);
    }
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_float_binary_frames(
    FILE *out, int left_offset, int right_offset, const char *helper)
{
    mir_emit_frame_long_load(out, left_offset);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_frame_long_load(out, right_offset);
    mir_emit_runtime_call(out, helper);
    fputs("\tpop bc\n\tpop bc\n", out);
}

static void mir_emit_float_binary_constant(
    FILE *out, int left_offset, unsigned long right_bits,
    const char *helper)
{
    mir_emit_frame_long_load(out, left_offset);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_float_bits(out, right_bits);
    mir_emit_runtime_call(out, helper);
    fputs("\tpop bc\n\tpop bc\n", out);
}

static void mir_emit_float_compare_constant(
    FILE *out, int left_offset, unsigned long right_bits,
    const char *helper, int true_label, int false_label)
{
    mir_emit_float_binary_constant(out, left_offset, right_bits, helper);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp nz, L%d\n\tjp L%d\n", true_label, false_label);
}

static void mir_emit_wide_factorial(
    FILE *out, const struct MirWideFactorial *plan)
{
    enum {
        VALUE = -4,
        RESULT = -8
    };
    int loop = new_label();
    int done = new_label();

    mir_emit_frame_long_load(out, plan->parameter_offset);
    mir_emit_frame_long_store(out, VALUE);
    fputs("\tld hl,1\n\tld de,0\n", out);
    mir_emit_frame_long_store(out, RESULT);
    fprintf(out, "L%d:\n", loop);
    mir_emit_frame_long_load(out, VALUE);
    fputs("\tld a,l\n\tor h\n\tor e\n\tor d\n", out);
    fprintf(out, "\tjp z, L%d\n", done);
    mir_emit_frame_long_load(out, RESULT);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_frame_long_load(out, VALUE);
    mir_emit_runtime_call(out, "__lmul");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_frame_long_store(out, RESULT);
    mir_emit_frame_long_load(out, VALUE);
    fputs("\tdec hl\n\tld a,h\n\tand l\n\tinc a\n", out);
    {
        int no_borrow = new_label();
        fprintf(out, "\tjp nz, L%d\n\tdec de\nL%d:\n",
                no_borrow, no_borrow);
    }
    mir_emit_frame_long_store(out, VALUE);
    fprintf(out, "\tjp L%d\nL%d:\n", loop, done);
    mir_emit_frame_long_load(out, RESULT);
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_float_exp(
    FILE *out, const struct MirFloatExp *plan)
{
    enum {
        INPUT = -4,
        N = -6,
        R = -10,
        SUM = -14,
        TERM = -18,
        I = -20,
        TEMP = -24
    };
    int return_maximum = new_label();
    int check_lower = new_label();
    int return_zero = new_label();
    int calculate = new_label();
    int check_rounding = new_label();
    int after_rounding = new_label();
    int series_loop = new_label();
    int series_done = new_label();
    int scale_down = new_label();
    int scale_up_loop = new_label();
    int scale_down_loop = new_label();
    int return_sum = new_label();
    int exit_label = new_label();

    mir_emit_frame_long_load(out, plan->parameter_offset);
    mir_emit_frame_long_store(out, INPUT);
    mir_emit_float_compare_constant(
        out, INPUT, plan->upper_bits, "__fltf",
        return_maximum, check_lower);
    fprintf(out, "L%d:\n", check_lower);
    mir_emit_float_compare_constant(
        out, INPUT, plan->upper_bits ^ 0x80000000UL,
        "__fgtf", return_zero, calculate);
    fprintf(out, "L%d:\n", calculate);
    mir_emit_float_binary_constant(out, INPUT, plan->ln2_bits, "__fdf");
    mir_emit_runtime_call(out, "__ffi");
    mir_emit_forth_frame_store(out, N);
    mir_emit_float_compare_constant(
        out, INPUT, 0, "__fgtf", check_rounding, after_rounding);
    fprintf(out, "L%d:\n", check_rounding);
    mir_emit_float_binary_constant(out, INPUT, plan->ln2_bits, "__fdf");
    mir_emit_frame_long_store(out, TEMP);
    mir_emit_forth_frame_load(out, N);
    mir_emit_runtime_call(out, "__fif");
    mir_emit_frame_long_store(out, R);
    mir_emit_float_binary_frames(out, TEMP, R, "__fnef");
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z, L%d\n\tld a,(ix%d)\n\tdec (ix%d)\n"
                 "\tor a\n\tjp nz, L%d\n\tdec (ix%d)\n",
            after_rounding, N, N, after_rounding, N + 1);
    fprintf(out, "L%d:\n", after_rounding);
    mir_emit_forth_frame_load(out, N);
    mir_emit_runtime_call(out, "__fif");
    mir_emit_frame_long_store(out, TEMP);
    mir_emit_float_binary_constant(out, TEMP, plan->ln2_bits, "__fmf");
    mir_emit_frame_long_store(out, TEMP);
    mir_emit_float_binary_frames(out, INPUT, TEMP, "__fsf");
    mir_emit_frame_long_store(out, R);
    mir_emit_float_bits(out, plan->one_bits);
    mir_emit_frame_long_store(out, SUM);
    mir_emit_frame_long_store(out, TERM);
    fputs("\tld hl,1\n", out);
    mir_emit_forth_frame_store(out, I);
    fprintf(out, "L%d:\n", series_loop);
    mir_emit_forth_frame_load(out, I);
    fprintf(out, "\tld de,%d\n\tor a\n\tsbc hl,de\n",
            plan->term_limit + 1);
    fprintf(out, "\tjp nc, L%d\n", series_done);
    mir_emit_float_binary_frames(out, TERM, R, "__fmf");
    mir_emit_frame_long_store(out, TEMP);
    mir_emit_forth_frame_load(out, I);
    mir_emit_runtime_call(out, "__fif");
    mir_emit_frame_long_store(out, TERM);
    mir_emit_float_binary_frames(out, TEMP, TERM, "__fdf");
    mir_emit_frame_long_store(out, TERM);
    mir_emit_float_binary_frames(out, SUM, TERM, "__faf");
    mir_emit_frame_long_store(out, SUM);
    mir_emit_forth_frame_load(out, I);
    fputs("\tinc hl\n", out);
    mir_emit_forth_frame_store(out, I);
    fprintf(out, "\tjp L%d\nL%d:\n", series_loop, series_done);
    mir_emit_forth_frame_load(out, N);
    fputs("\tbit 7,h\n", out);
    fprintf(out, "\tjp nz, L%d\nL%d:\n",
            scale_down, scale_up_loop);
    mir_emit_forth_frame_load(out, N);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z, L%d\n", return_sum);
    mir_emit_float_binary_constant(out, SUM, plan->two_bits, "__fmf");
    mir_emit_frame_long_store(out, SUM);
    fputs("\tld a,(ix-6)\n\tdec (ix-6)\n\tor a\n", out);
    fprintf(out, "\tjp nz, L%d\n\tdec (ix-5)\n\tjp L%d\n",
            scale_up_loop, scale_up_loop);
    fprintf(out, "L%d:\n", scale_down);
    fprintf(out, "L%d:\n", scale_down_loop);
    mir_emit_forth_frame_load(out, N);
    fputs("\tbit 7,h\n", out);
    fprintf(out, "\tjp z, L%d\n", return_sum);
    mir_emit_float_binary_constant(out, SUM, plan->two_bits, "__fdf");
    mir_emit_frame_long_store(out, SUM);
    fputs("\tinc (ix-6)\n", out);
    fprintf(out, "\tjp nz, L%d\n\tinc (ix-5)\n\tjp L%d\n",
            scale_down_loop, scale_down_loop);
    fprintf(out, "L%d:\n", return_sum);
    mir_emit_frame_long_load(out, SUM);
    fprintf(out, "\tjp L%d\n", exit_label);
    fprintf(out, "L%d:\n", return_maximum);
    mir_emit_float_bits(out, plan->maximum_bits);
    fprintf(out, "\tjp L%d\n", exit_label);
    fprintf(out,
            "L%d:\n\tld hl,0\n\tld de,0\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            return_zero, exit_label);
}

static void mir_emit_float_log(
    FILE *out, const struct MirFloatLog *plan)
{
    enum {
        INPUT = -4,
        M = -8,
        N = -10,
        Y = -14,
        Y2 = -18,
        SUM = -22,
        TERM = -26,
        I = -28,
        TEMP = -32
    };
    int domain_ok = new_label();
    int reduce_down = new_label();
    int reduce_up_loop = new_label();
    int reduce_down_loop = new_label();
    int reduced = new_label();
    int series = new_label();
    int series_done = new_label();

    mir_emit_frame_long_load(out, plan->parameter_offset);
    mir_emit_frame_long_store(out, INPUT);
    mir_emit_float_compare_constant(
        out, INPUT, 0, "__fgef", reduce_down, domain_ok);
    fprintf(out, "L%d:\n", reduce_down);
    mir_emit_float_bits(out, plan->maximum_bits ^ 0x80000000UL);
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
    fprintf(out, "L%d:\n\tld hl,0\n", domain_ok);
    mir_emit_forth_frame_store(out, N);
    mir_emit_frame_long_load(out, INPUT);
    mir_emit_frame_long_store(out, M);
    mir_emit_float_compare_constant(
        out, M, plan->one_bits, "__flef",
        reduce_up_loop, reduce_down_loop);

    fprintf(out, "L%d:\n", reduce_up_loop);
    mir_emit_float_compare_constant(
        out, M, plan->two_bits, "__flef", series, reduced);
    fprintf(out, "L%d:\n", series);
    mir_emit_float_binary_constant(out, M, plan->two_bits, "__fdf");
    mir_emit_frame_long_store(out, M);
    fputs("\tinc (ix-10)\n", out);
    {
        int no_carry = new_label();
        fprintf(out, "\tjp nz, L%d\n\tinc (ix-9)\nL%d:\n",
                no_carry, no_carry);
    }
    fprintf(out, "\tjp L%d\n", reduce_up_loop);

    fprintf(out, "L%d:\n", reduce_down_loop);
    mir_emit_float_compare_constant(
        out, M, plan->one_bits, "__fgtf", series_done, reduced);
    fprintf(out, "L%d:\n", series_done);
    mir_emit_float_binary_constant(out, M, plan->two_bits, "__fmf");
    mir_emit_frame_long_store(out, M);
    fputs("\tld a,(ix-10)\n\tdec (ix-10)\n\tor a\n", out);
    {
        int no_borrow = new_label();
        fprintf(out, "\tjp nz, L%d\n\tdec (ix-9)\nL%d:\n",
                no_borrow, no_borrow);
    }
    fprintf(out, "\tjp L%d\n", reduce_down_loop);

    fprintf(out, "L%d:\n", reduced);
    mir_emit_float_binary_constant(out, M, plan->one_bits, "__fsf");
    mir_emit_frame_long_store(out, Y);
    mir_emit_float_binary_constant(out, M, plan->one_bits, "__faf");
    mir_emit_frame_long_store(out, TEMP);
    mir_emit_float_binary_frames(out, Y, TEMP, "__fdf");
    mir_emit_frame_long_store(out, Y);
    mir_emit_float_binary_frames(out, Y, Y, "__fmf");
    mir_emit_frame_long_store(out, Y2);
    mir_emit_float_bits(out, 0);
    mir_emit_frame_long_store(out, SUM);
    mir_emit_frame_long_load(out, Y);
    mir_emit_frame_long_store(out, TERM);
    fputs("\tld hl,1\n", out);
    mir_emit_forth_frame_store(out, I);
    {
        int term_loop = new_label();
        int term_done = new_label();
        fprintf(out, "L%d:\n", term_loop);
        mir_emit_forth_frame_load(out, I);
        fprintf(out, "\tld de,%d\n\tor a\n\tsbc hl,de\n",
                plan->term_limit + 1);
        fprintf(out, "\tjp nc, L%d\n", term_done);
        mir_emit_forth_frame_load(out, I);
        mir_emit_runtime_call(out, "__fif");
        mir_emit_frame_long_store(out, TEMP);
        mir_emit_float_binary_frames(out, TERM, TEMP, "__fdf");
        mir_emit_frame_long_store(out, TEMP);
        mir_emit_float_binary_frames(out, SUM, TEMP, "__faf");
        mir_emit_frame_long_store(out, SUM);
        mir_emit_float_binary_frames(out, TERM, Y2, "__fmf");
        mir_emit_frame_long_store(out, TERM);
        mir_emit_forth_frame_load(out, I);
        fprintf(out, "\tld de,%d\n\tadd hl,de\n", plan->term_step);
        mir_emit_forth_frame_store(out, I);
        fprintf(out, "\tjp L%d\nL%d:\n", term_loop, term_done);
    }
    mir_emit_float_binary_constant(out, SUM, plan->two_bits, "__fmf");
    mir_emit_frame_long_store(out, SUM);
    mir_emit_forth_frame_load(out, N);
    mir_emit_runtime_call(out, "__fif");
    mir_emit_frame_long_store(out, TEMP);
    mir_emit_float_binary_constant(out, TEMP, plan->ln2_bits, "__fmf");
    mir_emit_frame_long_store(out, TEMP);
    mir_emit_float_binary_frames(out, SUM, TEMP, "__faf");
    fputs("\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static void mir_emit_fixed_long_copy(
    FILE *out, const struct MirFixedLongCopy *plan)
{
    fprintf(out,
            "\tld e,(ix%+d)\n\tld d,(ix%+d)\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld bc,%d\n\tldir\n"
            "\tld sp,ix\n\tpop ix\n\tret\n",
            plan->destination_offset, plan->destination_offset + 1,
            plan->source_offset, plan->source_offset + 1,
            plan->count * plan->stride);
}

static void mir_emit_long_div_small(
    FILE *out, const struct MirLongDivSmall *plan)
{
    int loop = new_label();
    int exit = new_label();

    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld (ix-2),l\n\tld (ix-1),h\n"
            "\tld (ix-3),%d\n"
            "\tld hl,0\n\tld de,0\n",
            plan->array_offset, plan->array_offset + 1,
            plan->count);
    mir_emit_frame_long_store(out, -7);
    fprintf(out,
            "L%d:\n\tld a,(ix-3)\n\tor a\n\tjp z, L%d\n",
            loop, exit);
    mir_emit_frame_long_load(out, -7);
    fputs("\tpush de\n\tpush hl\n", out);
    fprintf(out, "\tld hl,%ld\n\tld de,0\n", plan->base & 0xffffL);
    mir_emit_runtime_call(out, "__lmul");
    fputs("\tpop bc\n\tpop bc\n\tpush de\n\tpush hl\n", out);
    mir_emit_pointer_long_load(out, -2);
    fputs("\tpop bc\n\tadd hl,bc\n\tex de,hl\n"
          "\tpop bc\n\tadc hl,bc\n\tex de,hl\n", out);
    mir_emit_frame_long_store(out, -11);

    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_frame_long_load(out, plan->divisor_offset);
    mir_emit_runtime_call(out, "__lds");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_pointer_long_store(out, -2);

    mir_emit_frame_long_load(out, -11);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_frame_long_load(out, plan->divisor_offset);
    mir_emit_runtime_call(out, "__lms");
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_emit_frame_long_store(out, -7);
    mir_emit_frame_pointer_adjust(out, -2, 4);
    fprintf(out,
            "\tdec (ix-3)\n\tjp L%d\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            loop, exit);
}

static void mir_emit_long_add_signed(
    FILE *out, const struct MirLongAddSigned *plan)
{
    int subtract = new_label();
    int add_loop = new_label();
    int add_no_carry = new_label();
    int add_reduce = new_label();
    int add_no_borrow = new_label();
    int add_reduced = new_label();
    int add_no_reduce = new_label();
    int add_store = new_label();
    int sub_loop = new_label();
    int sub_no_carry = new_label();
    int sub_nonzero_low = new_label();
    int sub_nonnegative = new_label();
    int sub_no_overflow = new_label();
    int sub_store = new_label();
    int finish = new_label();
    int last_offset = (plan->count - 1) * 4;

    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld de,%d\n\tadd hl,de\n"
            "\tld (ix-2),l\n\tld (ix-1),h\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tld de,%d\n\tadd hl,de\n"
            "\tld (ix-4),l\n\tld (ix-3),h\n"
            "\tld (ix-5),%d\n\tld (ix-6),0\n"
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tbit 7,h\n\tjp nz, L%d\n"
            "\tld a,h\n\tor l\n\tjp z, L%d\n",
            plan->destination_offset, plan->destination_offset + 1,
            last_offset,
            plan->source_offset, plan->source_offset + 1,
            last_offset,
            plan->count,
            plan->sign_offset, plan->sign_offset + 1,
            subtract, subtract);

    fprintf(out, "L%d:\n", add_loop);
    mir_emit_pointer_long_load(out, -2);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_pointer_long_load(out, -4);
    fputs("\tpop bc\n\tadd hl,bc\n\tex de,hl\n"
          "\tpop bc\n\tadc hl,bc\n\tex de,hl\n"
          "\tld a,(ix-6)\n\tor a\n\tjp z, L", out);
    fprintf(out, "%d\n\tinc hl\n\tjp nz, L%d\n\tinc de\nL%d:\n",
            add_no_carry, add_no_carry, add_no_carry);
    fprintf(out,
            "\tbit 7,d\n\tjp nz, L%d\n"
            "\tld a,d\n\tor e\n\tjp nz, L%d\n"
            "\tld bc,%ld\n\tor a\n\tsbc hl,bc\n"
            "\tjp nc, L%d\n\tadd hl,bc\n\tjp L%d\n"
            "L%d:\n"
            "\tld bc,%ld\n\tor a\n\tsbc hl,bc\n"
            "\tjp nc, L%d\n\tdec de\n"
            "L%d:\nL%d:\n\tld (ix-6),1\n\tjp L%d\n"
            "L%d:\n\tld (ix-6),0\n"
            "L%d:\n",
            add_no_reduce, add_reduce, plan->base & 0xffffL,
            add_reduced, add_no_reduce, add_reduce,
            plan->base & 0xffffL, add_no_borrow,
            add_no_borrow, add_reduced, add_store,
            add_no_reduce, add_store);
    mir_emit_pointer_long_store(out, -2);
    mir_emit_frame_pointer_adjust(out, -2, -4);
    mir_emit_frame_pointer_adjust(out, -4, -4);
    fprintf(out,
            "\tdec (ix-5)\n\tjp nz, L%d\n\tjp L%d\n",
            add_loop, finish);

    fprintf(out, "L%d:\nL%d:\n", subtract, sub_loop);
    mir_emit_pointer_long_load(out, -4);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_pointer_long_load(out, -2);
    fputs("\tpop bc\n\tor a\n\tsbc hl,bc\n\tex de,hl\n"
          "\tpop bc\n\tsbc hl,bc\n\tex de,hl\n"
          "\tld a,(ix-6)\n\tor a\n", out);
    fprintf(out,
            "\tjp z, L%d\n\tld a,h\n\tor l\n"
            "\tjp nz, L%d\n\tdec hl\n\tdec de\n\tjp L%d\n"
            "L%d:\n\tdec hl\n"
            "L%d:\n"
            "\tbit 7,d\n\tjp z, L%d\n"
            "\tld bc,%ld\n\tadd hl,bc\n\tjp nc, L%d\n\tinc de\n"
            "L%d:\n\tld (ix-6),1\n\tjp L%d\n"
            "L%d:\n\tld (ix-6),0\n"
            "L%d:\n",
            sub_no_carry, sub_nonzero_low, sub_no_carry,
            sub_nonzero_low, sub_no_carry,
            sub_nonnegative,
            plan->base & 0xffffL, sub_no_overflow,
            sub_no_overflow, sub_store,
            sub_nonnegative, sub_store);
    mir_emit_pointer_long_store(out, -2);
    mir_emit_frame_pointer_adjust(out, -2, -4);
    mir_emit_frame_pointer_adjust(out, -4, -4);
    fprintf(out,
            "\tdec (ix-5)\n\tjp nz, L%d\n"
            "L%d:\n\tld sp,ix\n\tpop ix\n\tret\n",
            sub_loop, finish);
}

static void mir_emit_byte_sieve(
    FILE *out, const struct MirByteSieve *plan)
{
    const char *flags_name =
        asm_name_for(sym_asm_name(plan->flags));
    const char *print_name =
        asm_name_for(sym_asm_name(plan->print_function));
    int outer = new_label();
    int scan = new_label();
    int scan_tail = new_label();
    int mark = new_label();
    int mark_in_range = new_label();
    int mark_done = new_label();
    int scan_done = new_label();

    if ((plan->flags->storage == SC_EXTERN ||
         plan->flags->needs_extrn) &&
        mir_extrn_should_emit(plan->flags))
        fprintf(out, "\textrn %s\n", flags_name);
    if ((plan->print_function->storage == SC_EXTERN ||
         plan->print_function->needs_extrn) &&
        mir_extrn_should_emit(plan->print_function))
        fprintf(out, "\textrn %s\n", print_name);
    fputs("\tld (ix-3),1\n", out);
    fprintf(out,
            "L%d:\n"
            "\tld hl,0\n\tld (ix-2),l\n\tld (ix-1),h\n"
            "\tld hl,%s\n\tld (hl),%d\n"
            "\tld de,%s+1\n\tld bc,%d\n\tldir\n"
            "\tld bc,0\n\tld hl,%s\n",
            outer,
            flags_name, plan->true_value & 0xff,
            flags_name, plan->maximum_index,
            flags_name);
    fprintf(out,
            "L%d:\n\tld a,(hl)\n\tor a\n\tjp z, L%d\n"
            "\tpush bc\n\tpush hl\n",
            scan, scan_tail);
    fputs("\tld h,b\n\tld l,c\n\tadd hl,hl\n"
          "\tinc hl\n\tinc hl\n\tinc hl\n"
          "\tld b,h\n\tld c,l\n\tpop hl\n\tadd hl,bc\n", out);
    fprintf(out,
            "\tjp c, L%d\n\tld de,%s+%d\n"
            "L%d:\n"
            "\tld a,h\n\tcp d\n\tjp c, L%d\n\tjp nz, L%d\n"
            "\tld a,l\n\tcp e\n\tjp nc, L%d\n"
            "L%d:\n\tld (hl),0\n\tadd hl,bc\n"
            "\tjp c, L%d\n\tjp L%d\n"
            "L%d:\n\tpop bc\n\tld hl,%s\n\tadd hl,bc\n",
            mark_done, flags_name, plan->maximum_index + 1,
            mark,
            mark_in_range, mark_done,
            mark_done,
            mark_in_range,
            mark_done, mark,
            mark_done, flags_name);
    fprintf(out,
            "\tinc (ix-2)\n\tjp nz, L%d\n\tinc (ix-1)\n"
            "L%d:\n\tinc hl\n\tinc bc\n"
            "\tld a,b\n\tcp %d\n\tjp c, L%d\n\tjp nz, L%d\n"
            "\tld a,c\n\tcp %d\n\tjp c, L%d\n"
            "L%d:\n\tinc (ix-3)\n\tld a,(ix-3)\n"
            "\tcp %d\n\tjp c, L%d\n",
            scan_tail,
            scan_tail,
            ((plan->maximum_index + 1) >> 8) & 0xff,
            scan, scan_done,
            (plan->maximum_index + 1) & 0xff,
            scan,
            scan_done,
            plan->pass_count + 1, outer);
    fprintf(out,
            "\tld l,(ix-2)\n\tld h,(ix-1)\n\tpush hl\n"
            "\tld hl,S%d\n\tpush hl\n\tcall %s\n"
            "\tpop bc\n\tpop bc\n"
            "\tld hl,0\n\tld sp,ix\n\tpop ix\n\tret\n",
            plan->format_string, print_name);
}

static void mir_emit_wide_byte_store(
    FILE *out, const struct MirWideByteStore *store)
{
    int offset;

    if (getenv("DCC_MIR_LOW_BYTE_INDEX_LOOP_REPORT") != NULL)
        fprintf(stderr,
                "; MIR wide-byte-store function=%s byte-offset=%d\n",
                mir.name, store->byte_offset);
    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
            store->base_offset, store->base_offset + 1);
    for (offset = 0; offset < store->byte_offset; ++offset)
        fputs("\tinc hl\n", out);
    fprintf(out, "\tld a,(ix%+d)\n\tld (hl),a\n",
            store->source_offset);
}

static void mir_emit_wide_byte_pack_return(
    FILE *out, const struct MirWideBytePackReturn *pack)
{
    if (getenv("DCC_MIR_LOW_BYTE_INDEX_LOOP_REPORT") != NULL)
        fprintf(stderr,
                "; MIR wide-byte-pack-return function=%s\n",
                mir.name);
    fprintf(out,
            "\tld c,(ix%+d)\n\tld b,(ix%+d)\n"
            "\tld a,(bc)\n\tld d,a\n\tinc bc\n"
            "\tld a,(bc)\n\tld e,a\n\tinc bc\n"
            "\tld a,(bc)\n\tld h,a\n\tinc bc\n"
            "\tld a,(bc)\n\tld l,a\n",
            pack->base_offset, pack->base_offset + 1);
    mir_emit_virtual_iy_epilogue(out);
}

static void mir_emit_restore_virtual_iy(FILE *out)
{
    if (!mir_virtual_iy_base)
        return;
    fputs("\tpush ix\n\tpop iy\n", out);
    if (mir_effective_local_bytes() + mir.aggregate_temp_bytes != 0)
        fprintf(out, "\tld bc,-%d\n\tadd iy,bc\n",
                mir_effective_local_bytes() + mir.aggregate_temp_bytes);
}

static int mir_frame_word_uses_short_ix(int offset)
{
    return offset >= -128 && offset + 1 <= 127;
}

static void mir_emit_frame_word_store(FILE *out, int offset)
{
    if (mir_frame_word_uses_short_ix(offset)) {
        fprintf(out, "\tld (ix%+d),l\n\tld (ix%+d),h\n",
                offset, offset + 1);
    } else {
        fputs("\tex de,hl\n\tpush ix\n\tpop hl\n", out);
        fprintf(out, "\tld bc,%d\n\tadd hl,bc\n"
                     "\tld (hl),e\n\tinc hl\n\tld (hl),d\n\tex de,hl\n",
                offset);
    }
}

static void mir_emit_frame_word_load(FILE *out, int offset)
{
    if (mir_frame_word_uses_short_ix(offset)) {
        fprintf(out, "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
                offset, offset + 1);
    } else {
        fputs("\tpush ix\n\tpop hl\n", out);
        fprintf(out, "\tld de,%d\n\tadd hl,de\n"
                     "\tld a,(hl)\n\tinc hl\n\tld h,(hl)\n\tld l,a\n",
                offset);
    }
}

static int mir_emit_scalar_operation(FILE *out, const struct MirInsn *insn)
{
    switch ((int)insn->immediate) {
    case '+': fputs("\tadd hl,de\n", out); return 1;
    case '-': fputs("\tor a\n\tsbc hl,de\n", out); return 1;
    case '&':
        fputs("\tld a,h\n\tand d\n\tld h,a\n\tld a,l\n\tand e\n\tld l,a\n", out);
        return 1;
    case '|':
        fputs("\tld a,h\n\tor d\n\tld h,a\n\tld a,l\n\tor e\n\tld l,a\n", out);
        return 1;
    case '^':
        fputs("\tld a,h\n\txor d\n\tld h,a\n\tld a,l\n\txor e\n\tld l,a\n", out);
        return 1;
    case '*': mir_emit_runtime_call(out, "__mulu"); return 1;
    case '/':
        mir_emit_runtime_call(
            out, (insn->type & TYPE_UNSIGNED) != 0 ? "__divu" : "__divs");
        return 1;
    case '%':
        mir_emit_runtime_call(
            out, (insn->type & TYPE_UNSIGNED) != 0 ? "__modu" : "__mods");
        return 1;
    case TOK_EQ: case TOK_NE: case '<': case '>': case TOK_LE: case TOK_GE:
        {
            const struct MirInsn *left = mir_definition(insn->src1);
            const struct MirInsn *right = mir_definition(insn->src2);
            int is_unsigned =
                (left != NULL &&
                 mir_type_uses_unsigned_comparison(left->type)) ||
                (right != NULL &&
                 mir_type_uses_unsigned_comparison(right->type));
            mir_emit_scalar_compare(out, (int)insn->immediate, is_unsigned);
        }
        return 1;
    case TOK_SHL: case TOK_SHR:
        {
            const struct MirInsn *left = mir_definition(insn->src1);
            mir_emit_scalar_shift(out, (int)insn->immediate,
                                  left != NULL &&
                                  (left->type & TYPE_UNSIGNED) != 0,
                                  insn->src2);
        }
        return 1;
    default:
        return 0;
    }
}

static int mir_emit_spilled_phi_copies(FILE *out, int predecessor,
                                       int successor);
static int mir_phi_copies_are_empty(int predecessor, int successor);
static int mir_phi_copy_is_slot_identity(int source, int destination);

static const char *mir_invert_z80_condition(const char *condition)
{
    if (strcmp(condition, "z") == 0) return "nz";
    if (strcmp(condition, "nz") == 0) return "z";
    if (strcmp(condition, "c") == 0) return "nc";
    if (strcmp(condition, "nc") == 0) return "c";
    return NULL;
}

/* Item T32 (mir-text-size-plan.md): every fused comparison branch below
 * previously always emitted the three-instruction "branch over a jump"
 * shape - `jp <true_condition>,Lfallthrough` / (phi copies) /
 * `jp Ltarget` / `Lfallthrough:` - even when there were no phi copies to
 * run on the false edge. dccpeep's own pass_branch_over_jump
 * (peep_pass_control_flow.c) already collapses exactly this shape into a
 * single `jp <inverse>,Ltarget` whenever the two instructions between the
 * conditional jump and its target label are just an unconditional jump, so
 * the peeped .COM was never actually paying for the extra jump - only the
 * pre-peephole selector-acceptance byte count was. Emitting the already-
 * collapsed form directly here means the census-visible generated_bytes
 * (which decide MIR text-size acceptance) match what dccpeep would have
 * produced anyway, unlocking acceptance for functions that were only over
 * budget by this redundant jump, with zero change to the final peeped
 * binary. The three-instruction shape is still required, unchanged, when
 * there are phi copies pending on the false edge (they must run
 * conditionally, so they cannot be replaced by a single unconditional
 * branch to `target`). */
static int mir_emit_conditional_branch_with_phi_copies(
    FILE *out, const int *labels, const char *true_condition,
    int predecessor, int target, int branch_label)
{
    int fallthrough_label;
    int fallthrough = predecessor + 1;
    int false_copies_empty =
        mir_phi_copies_are_empty(predecessor, target);
    int true_copies_empty =
        fallthrough >= mir.count ||
        mir_phi_copies_are_empty(predecessor, fallthrough);
    const char *inverse;

    if (false_copies_empty) {
        inverse = mir_invert_z80_condition(true_condition);
        if (inverse != NULL) {
            fprintf(out, "\tjp %s, L%d\n", inverse, labels[branch_label]);
            if (!true_copies_empty &&
                !mir_emit_spilled_phi_copies(
                    out, predecessor, fallthrough))
                return 0;
            return 1;
        }
    }
    fallthrough_label = new_label();
    fprintf(out, "\tjp %s, L%d\n", true_condition, fallthrough_label);
    if (!mir_emit_spilled_phi_copies(out, predecessor, target))
        return 0;
    fprintf(out, "\tjp L%d\nL%d:\n", labels[branch_label], fallthrough_label);
    if (!true_copies_empty &&
        !mir_emit_spilled_phi_copies(out, predecessor, fallthrough))
        return 0;
    return 1;
}

static int mir_emit_wide_mask_zero_branch(
    FILE *out, const int *labels,
    const struct MirWideMaskZeroBranch *plan)
{
    static const char registers[4] = { 'l', 'h', 'e', 'd' };
    const struct MirInsn *branch =
        &mir.insns[plan->branch_instruction];
    const char *true_condition =
        plan->comparison == TOK_EQ ? "z" : "nz";
    int target = mir_find_label(branch->label);
    int first = 1;
    int flags_set = 0;
    int byte;

    if (target < 0)
        return 0;
    if (plan->source_is_direct)
        fprintf(out,
                "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
                "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
                plan->source_offset, plan->source_offset + 1,
                plan->source_offset + 2, plan->source_offset + 3);
    else
        mir_emit_virtual_load_wide(out, plan->source_value);
    for (byte = 0; byte < 4; ++byte) {
        unsigned int mask =
            (unsigned int)((plan->mask >> (8 * byte)) & 0xffUL);

        if (mask == 0)
            continue;
        if (!first)
            fputs("\tld c,a\n", out);
        fprintf(out, "\tld a,%c\n", registers[byte]);
        if (mask != 255)
            fprintf(out, "\tand %u\n", mask);
        if (mask != 255)
            flags_set = 1;
        if (!first) {
            fputs("\tor c\n", out);
            flags_set = 1;
        }
        first = 0;
    }
    if (!flags_set)
        fputs("\tor a\n", out);
    if (getenv("DCC_MIR_LOW_BYTE_INDEX_LOOP_REPORT") != NULL)
        fprintf(stderr,
                "; MIR wide-mask-zero-branch function=%s mask=%lu\n",
                mir.name, plan->mask);
    return mir_emit_conditional_branch_with_phi_copies(
        out, labels, true_condition, plan->branch_instruction,
        target, branch->label);
}

/* Item 1 (mir-migration-plan-100): when a scalar comparison feeds nothing
 * but the MIR_BRANCH_FALSE that immediately follows it, mir_emit_scalar_compare
 * would otherwise materialize an explicit 0/1 boolean into HL, spill it to a
 * backend slot, and reload it just so the branch can re-test it with
 * `ld a,h / or l`. Test the flags directly instead and jump straight to the
 * branch's targets, eliding the materialize/spill/reload entirely.
 *
 * Item 4 extends this through a single intervening logical-not: `!(a OP b)`
 * feeding a branch is exactly the branch on the complementary operator, so
 * `mir_binary_is_fusable_comparison` returns 2 (skip compare, not, branch)
 * instead of 1 (skip compare, branch) and the caller negates the operator. */
static int mir_negate_comparison_operator(int operation)
{
    switch (operation) {
    case TOK_EQ: return TOK_NE;
    case TOK_NE: return TOK_EQ;
    case '<': return TOK_GE;
    case TOK_GE: return '<';
    case '>': return TOK_LE;
    default: return '>'; /* TOK_LE */
    }
}

static int mir_binary_is_fusable_comparison(int i)
{
    const struct MirInsn *insn = &mir.insns[i];
    const struct MirInsn *next;

    if (insn->opcode != MIR_BINARY)
        return 0;
    switch ((int)insn->immediate) {
    case TOK_EQ: case TOK_NE: case '<': case '>': case TOK_LE: case TOK_GE:
        break;
    default:
        return 0;
    }
    if (mir_value_use_count(insn->dst) != 1 || i + 1 >= mir.count)
        return 0;
    next = &mir.insns[i + 1];
    if (next->opcode == MIR_BRANCH_FALSE && next->src1 == insn->dst)
        return 1;
    if (next->opcode == MIR_UNARY && next->immediate == '!' &&
        next->src1 == insn->dst && !mir_value_is_wide(next->src1) &&
        mir_value_use_count(next->dst) == 1 && i + 2 < mir.count &&
        mir.insns[i + 2].opcode == MIR_BRANCH_FALSE &&
        mir.insns[i + 2].src1 == next->dst)
        return 2;
    return 0;
}

static int mir_truth_parameter_comparison(const struct MirInsn *compare,
                                          int *parameter_value)
{
    const struct MirInsn *left;
    const struct MirInsn *right;

    if (compare == NULL || compare->opcode != MIR_BINARY ||
        compare->immediate != TOK_NE ||
        type_size(compare->secondary_offset) > 2 ||
        mir_value_use_count(compare->dst) != 1)
        return 0;
    left = mir_definition(compare->src1);
    right = mir_definition(compare->src2);
    if (left == NULL || left->opcode != MIR_PARAM ||
        type_size(left->type) > 2 ||
        right == NULL || right->opcode != MIR_CONST ||
        (right->immediate & 0xffffL) != 0)
        return 0;
    *parameter_value = compare->src1;
    return 1;
}

static int mir_nested_truth_comparison(int instruction,
                                       int *left_parameter,
                                       int *right_parameter)
{
    const struct MirInsn *outer;
    const struct MirInsn *left;
    const struct MirInsn *right;

    if (instruction < 0 || instruction >= mir.count ||
        mir_has_phi_instruction())
        return 0;
    outer = &mir.insns[instruction];
    if (outer->opcode != MIR_BINARY || outer->immediate != TOK_NE ||
        type_size(outer->secondary_offset) > 2 ||
        mir_binary_is_fusable_comparison(instruction) != 1)
        return 0;
    left = mir_definition(outer->src1);
    right = mir_definition(outer->src2);
    return mir_truth_parameter_comparison(left, left_parameter) &&
           mir_truth_parameter_comparison(right, right_parameter);
}

/* A pair of one-use `param != 0` booleans consumed by `(left != right)` and
 * an immediate branch can compare the original parameter truth values
 * directly.  Do not allocate backend slots or materialize either inner
 * boolean; mir_emit_nested_truth_comparison_branch emits the complete branch
 * at the outer comparison. */
static int mir_value_is_nested_truth_comparison_input(int value)
{
    int instruction;

    for (instruction = 0; instruction < mir.count; ++instruction) {
        int left_parameter;
        int right_parameter;
        const struct MirInsn *outer = &mir.insns[instruction];

        if ((outer->src1 == value || outer->src2 == value) &&
            mir_nested_truth_comparison(instruction, &left_parameter,
                                        &right_parameter))
            return 1;
    }
    return 0;
}

static int mir_float_madd_match(int add_index, int *multiply_index,
                                int *addend_value)
{
    const struct MirInsn *add;
    const struct MirInsn *multiply;
    int candidate;
    int addend;

    if (add_index <= 0 || add_index >= mir.count)
        return 0;
    add = &mir.insns[add_index];
    if (add->opcode != MIR_BINARY || add->immediate != '+' ||
        !type_is_float(add->type) ||
        !type_is_float(add->secondary_offset) ||
        type_size(add->secondary_offset) != 4)
        return 0;
    candidate = add_index - 1;
    multiply = &mir.insns[candidate];
    addend = add->src1;
    if (multiply->opcode != MIR_BINARY || multiply->immediate != '*' ||
        !type_is_float(multiply->type) ||
        !type_is_float(multiply->secondary_offset) ||
        type_size(multiply->secondary_offset) != 4 ||
        mir_value_use_count(multiply->dst) != 1 ||
        add->src2 != multiply->dst)
        return 0;
    if (multiply_index != NULL)
        *multiply_index = candidate;
    if (addend_value != NULL)
        *addend_value = addend;
    return 1;
}

static int mir_float_multiply_is_fused(int multiply_index)
{
    int matched_multiply;

    return multiply_index + 1 < mir.count &&
           mir_float_madd_match(multiply_index + 1, &matched_multiply, NULL) &&
           matched_multiply == multiply_index;
}

static int mir_narrow_multiply_has_named_word_home(
    const struct MirInsn *source)
{
    int memory_type;
    int memory_storage;
    int memory_offset;

    if (source == NULL ||
        (source->opcode != MIR_LOAD && source->opcode != MIR_PARAM) ||
        !mir_scalar_memory_location(
            source, &memory_type, &memory_storage, &memory_offset) ||
        type_size(memory_type) != 2)
        return 0;
    if (memory_storage == SC_GLOBAL || memory_storage == SC_EXTERN)
        return 1;
    return (memory_storage == SC_LOCAL ||
            memory_storage == SC_PARAM) &&
           memory_offset >= -128 && memory_offset + 1 <= 127;
}

static int mir_plain_u16_widen_source(int value, int *source_value)
{
    const struct MirInsn *widen = mir_definition(value);
    const struct MirInsn *source;

    if (widen == NULL || widen->opcode != MIR_UNARY ||
        widen->immediate != 0 || type_size(widen->type) != 4 ||
        type_is_float(widen->type) ||
        (widen->type & TYPE_UNSIGNED) == 0)
        return 0;
    source = mir_definition(widen->src1);
    if (source == NULL || source->opcode != MIR_PARAM ||
        type_size(source->type) > 2 ||
        type_is_float(source->type) || type_ptr_depth(source->type) > 0 ||
        (source->type & TYPE_UNSIGNED) == 0)
        return 0;
    if (source_value != NULL)
        *source_value = widen->src1;
    return 1;
}

static int mir_narrow_multiply_widen_source(
    int value, int *source_value, int *is_unsigned)
{
    const struct MirInsn *widen = mir_definition(value);
    const struct MirInsn *source;
    int source_unsigned;
    int target_unsigned;

    if (widen == NULL || widen->opcode != MIR_UNARY ||
        widen->immediate != 0 || type_size(widen->type) != 4 ||
        type_is_float(widen->type) ||
        mir_value_use_count(widen->dst) != 1)
        return 0;
    source = mir_definition(widen->src1);
    if (source == NULL || type_size(source->type) > 2 ||
        type_is_float(source->type) || type_ptr_depth(source->type) > 0)
        return 0;
    if (!mir_narrow_multiply_has_named_word_home(source) &&
        mir_value_use_count(source->dst) <= 1)
        return 0;
    source_unsigned = (source->type & TYPE_UNSIGNED) != 0;
    target_unsigned = (widen->type & TYPE_UNSIGNED) != 0;
    if (source_unsigned != target_unsigned &&
        !(type_size(source->type) == 1 &&
          source_unsigned && !target_unsigned))
        return 0;
    if (source_value != NULL)
        *source_value = widen->src1;
    if (is_unsigned != NULL)
        *is_unsigned = target_unsigned;
    return 1;
}

static int mir_wide_narrow_multiply_match(
    const struct MirInsn *multiply, int *left_source,
    int *right_source, int *is_unsigned)
{
    int left_unsigned;
    int right_unsigned;

    if (multiply == NULL || multiply->opcode != MIR_BINARY ||
        multiply->immediate != '*' ||
        type_size(multiply->secondary_offset) != 4 ||
        type_is_float(multiply->secondary_offset) ||
        !mir_narrow_multiply_widen_source(
            multiply->src1, left_source, &left_unsigned) ||
        !mir_narrow_multiply_widen_source(
            multiply->src2, right_source, &right_unsigned) ||
        left_unsigned != right_unsigned)
        return 0;
    if (is_unsigned != NULL)
        *is_unsigned = left_unsigned;
    return 1;
}

static int mir_value_is_wide_narrow_multiply_widen(int value)
{
    int instruction;

    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *multiply = &mir.insns[instruction];

        if (mir_wide_narrow_multiply_match(
                multiply, NULL, NULL, NULL) &&
            (multiply->src1 == value || multiply->src2 == value))
            return 1;
    }
    return 0;
}

static int mir_wide_mulmod_match(int modulo_index, int *multiply_index,
                                 int *left_value, int *right_value,
                                 int *modulus_value)
{
    const struct MirInsn *modulo;
    const struct MirInsn *multiply;

    if (modulo_index < 0 || modulo_index >= mir.count)
        return 0;
    modulo = &mir.insns[modulo_index];
    multiply = mir_definition(modulo->src1);
    if (modulo->opcode != MIR_BINARY || modulo->immediate != '%' ||
        type_size(modulo->secondary_offset) != 4 ||
        type_is_float(modulo->secondary_offset) ||
        (modulo->secondary_offset & TYPE_UNSIGNED) == 0 ||
        multiply == NULL || multiply->opcode != MIR_BINARY ||
        multiply->immediate != '*' ||
        type_size(multiply->secondary_offset) != 4 ||
        type_is_float(multiply->secondary_offset) ||
        (multiply->secondary_offset & TYPE_UNSIGNED) == 0 ||
        mir_value_use_count(multiply->dst) != 1 ||
        !mir_plain_u16_widen_source(multiply->src1, left_value) ||
        !mir_plain_u16_widen_source(multiply->src2, right_value) ||
        !mir_plain_u16_widen_source(modulo->src2, modulus_value))
        return 0;
    if (multiply_index != NULL)
        *multiply_index = (int)(multiply - mir.insns);
    return 1;
}

static int mir_wide_multiply_is_fused_mulmod(int multiply_index)
{
    int instruction;

    for (instruction = multiply_index + 1;
         instruction < mir.count; ++instruction) {
        int matched_multiply;
        if (mir_wide_mulmod_match(instruction, &matched_multiply,
                                  NULL, NULL, NULL) &&
            matched_multiply == multiply_index)
            return 1;
    }
    return 0;
}

int mir_spilled_cfg_has_wide_mulmod_fusion(void)
{
    int instruction;

    for (instruction = 0; instruction < mir.count; ++instruction)
        if (mir_wide_mulmod_match(instruction, NULL, NULL, NULL, NULL))
            return 1;
    return 0;
}

static int mir_unary_is_fusable_not_branch(int i)
{
    const struct MirInsn *candidate;
    const struct MirInsn *candidate_source;
    const struct MirInsn *insn;
    const struct MirInsn *next;
    int instruction;

    if (i < 0 || i + 1 >= mir.count)
        return 0;
    for (instruction = 0; instruction + 1 < mir.count; ++instruction) {
        candidate = &mir.insns[instruction];
        if (candidate->opcode != MIR_UNARY ||
            candidate->immediate != '!' ||
            mir.insns[instruction + 1].opcode != MIR_BRANCH_FALSE ||
            mir.insns[instruction + 1].src1 != candidate->dst)
            continue;
        candidate_source = mir_definition(candidate->src1);
        if (candidate_source != NULL &&
            candidate_source->opcode == MIR_CALL &&
            (candidate_source->memory_flags & MIR_CALL_FLAG_VARIADIC) != 0)
            return 0;
    }
    insn = &mir.insns[i];
    next = &mir.insns[i + 1];
    return insn->opcode == MIR_UNARY && insn->immediate == '!' &&
           !mir_value_is_wide(insn->src1) &&
           (mir_definition(insn->src1) == NULL ||
            mir_definition(insn->src1)->opcode != MIR_UNARY) &&
           mir_value_use_count(insn->dst) == 1 &&
           next->opcode == MIR_BRANCH_FALSE && next->src1 == insn->dst;
}

/* Item 25 (mir-migration-plan-100): an `==`/`!=` comparison against the
 * constant 0 needs neither operand materialized into DE nor a 16-bit
 * `sbc hl,de` - HL already holds the left operand (loaded unconditionally
 * before every MIR_BINARY), and `ld a,h / or l` sets Z/NZ from it directly.
 * This only applies to the right operand being the zero constant (the
 * overwhelmingly common `x == 0` / `x != 0` source shape); a zero constant
 * on the left (`0 == x`) still loads HL with the constant first, so no
 * benefit is available without reordering operand evaluation, which this
 * item does not attempt. */
static int mir_fused_compare_is_const_zero_rhs(int compare_index)
{
    const struct MirInsn *compare = &mir.insns[compare_index];
    const struct MirInsn *right;

    if (compare->immediate != TOK_EQ && compare->immediate != TOK_NE)
        return 0;
    right = mir_definition(compare->src2);
    return right != NULL && right->opcode == MIR_CONST &&
           (right->immediate & 0xffffL) == 0;
}

static int mir_fused_compare_is_const_zero_lhs(int compare_index)
{
    const struct MirInsn *compare = &mir.insns[compare_index];
    const struct MirInsn *left;

    if (compare->immediate != TOK_EQ && compare->immediate != TOK_NE)
        return 0;
    left = mir_definition(compare->src1);
    return left != NULL && left->opcode == MIR_CONST &&
           (left->immediate & 0xffffL) == 0;
}

/* Item 26 (mir-migration-plan-100): an 8-bit-range `cp`-based fast path for
 * "small constant" comparisons was investigated and deferred. MIR reaches
 * MIR_BINARY only after C's usual arithmetic conversions have already
 * promoted narrower operands to a full 16-bit int - there is no tracking of
 * an operand's pre-promotion original type (or a proven small value range)
 * surviving to this point, so proving either operand is guaranteed to fit in
 * a single byte would require new semantic/range-tracking infrastructure,
 * not a small selector tweak. Deferred until such tracking exists (same
 * "defer, don't guess" rationale as Item 6/Item 14). */

/* Item 27 (mir-migration-plan-100): a signed `<`/`>=` comparison against the
 * constant 0 needs only the sign bit of the left operand - `bit 7,h` sets Z
 * from bit 7 of H directly, with no DE materialization or 16-bit `sbc
 * hl,de` (and no xor-128 sign-flip dance, which exists only to make an
 * unsigned `sbc` behave like a signed compare against a non-zero DE). This
 * only applies when the comparison is provably signed: if either operand is
 * unsigned, "x < 0" is always false and "x >= 0" is always true, which is a
 * different (constant-fold) opportunity this item does not attempt. */
static int mir_fused_compare_is_signed_zero_sign_test(int compare_index)
{
    const struct MirInsn *compare = &mir.insns[compare_index];
    const struct MirInsn *left;
    const struct MirInsn *right;

    if (compare->immediate != '<' && compare->immediate != TOK_GE)
        return 0;
    left = mir_definition(compare->src1);
    right = mir_definition(compare->src2);
    if ((left != NULL && mir_type_uses_unsigned_comparison(left->type)) ||
        (right != NULL && mir_type_uses_unsigned_comparison(right->type)))
        return 0;
    if (right == NULL || right->opcode != MIR_CONST ||
        (right->immediate & 0xffffL) != 0)
        return 0;
    return 1;
}

static int mir_emit_fused_comparison_branch(FILE *out, const int *labels,
                                             int compare_index, int negate,
                                             int de_holds_biased_constant)
{
    const struct MirInsn *compare = &mir.insns[compare_index];
    const struct MirInsn *branch = &mir.insns[compare_index + 1 + negate];
    const struct MirInsn *left = mir_definition(compare->src1);
    const struct MirInsn *right = mir_definition(compare->src2);
    int is_unsigned =
        (left != NULL && mir_type_uses_unsigned_comparison(left->type)) ||
        (right != NULL && mir_type_uses_unsigned_comparison(right->type));
    int operation = negate ? mir_negate_comparison_operator(
                                 (int)compare->immediate)
                           : (int)compare->immediate;
    int target;
    const char *true_condition;

    if (branch->label < 0 || branch->label >= mir.next_label)
        return 0;
    target = mir_find_label(branch->label);
    if (target < 0)
        return 0;
    if ((operation == TOK_EQ || operation == TOK_NE) &&
        (mir_fused_compare_is_const_zero_rhs(compare_index) ||
         mir_fused_compare_is_const_zero_lhs(compare_index))) {
        /* Item 25: DE was never loaded for this case (the caller skips it
         * on this same const-zero-rhs test), so test HL directly. */
        fputs("\tld a,h\n\tor l\n", out);
    } else if ((operation == '<' || operation == TOK_GE) &&
               mir_fused_compare_is_signed_zero_sign_test(compare_index)) {
        /* Item 27: DE was never loaded for this case either (the caller
         * skips it on this same signed-zero-sign-test), so the sign bit of
         * HL is tested directly instead of a 16-bit sbc. `bit 7,h` sets Z
         * when the sign bit is clear (value >= 0) and NZ when it is set
         * (value < 0) - the opposite sense of the c/nc pair the sbc path
         * produces, so this case picks its own true_condition below rather
         * than falling into the shared switch. */
        fputs("\tbit 7,h\n", out);
        true_condition = operation == '<' ? "nz" : "z";
        return mir_emit_conditional_branch_with_phi_copies(
            out, labels, true_condition, compare_index + 1 + negate, target,
            branch->label);
    } else if (de_holds_biased_constant &&
               (operation == '<' || operation == TOK_GE)) {
        /* Item T50 (mir-text-size-plan.md): the caller already loaded DE
         * with the compile-time-biased constant (constant ^ 0x8000)
         * instead of the raw value, mirroring
         * mir_emit_homed_binary_instruction's biased_right_constant
         * optimization - only HL's sign bit needs the runtime xor-128
         * flip, not both HL and DE, and the xor's own side effect clears
         * carry so the usual leading `or a` is also unneeded. negate
         * cannot change this eligibility: mir_negate_comparison_operator
         * only ever swaps '<' with TOK_GE (never introduces '>' or
         * TOK_LE from one of these two), so the bias computed for the
         * un-negated compare->immediate remains valid after negation. */
        fputs("\tld a,h\n\txor 128\n\tld h,a\n\tsbc hl,de\n", out);
    } else {
        if (operation == '>' || operation == TOK_LE) {
            fputs("\tex de,hl\n", out);
            operation = operation == '>' ? '<' : TOK_GE;
        }
        if (!is_unsigned && operation != TOK_EQ && operation != TOK_NE)
            fputs("\tld a,h\n\txor 128\n\tld h,a\n"
                  "\tld a,d\n\txor 128\n\tld d,a\n", out);
        fputs("\tor a\n\tsbc hl,de\n", out);
    }
    switch (operation) {
    case TOK_EQ: true_condition = "z"; break;
    case TOK_NE: true_condition = "nz"; break;
    case '<': true_condition = "c"; break;
    default: true_condition = "nc"; break; /* TOK_GE */
    }
    return mir_emit_conditional_branch_with_phi_copies(
        out, labels, true_condition, compare_index + 1 + negate, target,
        branch->label);
}

/* Item T2 (mir-text-size-plan): the 32-bit ("wide") comparison operators
 * previously took the same "materialize 0/1 boolean into HL, spill it to a
 * backend slot, reload it, retest with ld a,h/or l" round trip as the 16-bit
 * path did before Item 1 - mir_binary_is_fusable_comparison only recognized
 * 16-bit operands. Every wide comparison shape (inline xor-compare for ==/!=,
 * and the __ltu/__lts/__leu/__les/__lgu/__lgs/__lku/__lks runtime helpers for
 * relational, and the float helpers) already leaves the boolean result as a
 * concrete 0/1 in HL by construction - there is no flag-based short cut
 * available (unlike the 16-bit path's `sbc hl,de`), but skipping the
 * store/reload/retest is still a direct win, and is a strict superset of
 * what the 16-bit fusion already exploits: HL is always tested with
 * `ld a,h / or l` immediately once it is known to be 0 or 1, whether the
 * branch consumes the comparison directly or through a single intervening
 * logical-not (mir_binary_is_fusable_comparison's existing negate signal).
 *
 * Item T53 (mir-text-size-plan.md): Item T2 initially kept a defensive
 * `type_is_float` exclusion in mir_binary_is_fusable_comparison pending
 * independent verification of the float comparison helpers' HL-return
 * convention. Verified directly against DCCRTL.MAC: __feqf, __fnef, __fltf,
 * __fgtf, __flef, and __fgef all end every code path with an explicit
 * `ld hl,1` or `ld hl,0` immediately before `ret` - exactly the same
 * concrete-0/1-in-HL contract this function already relies on for `long`.
 * This function needed no changes at all; only the gate in
 * mir_binary_is_fusable_comparison did. */
static int mir_emit_fused_wide_comparison_branch(FILE *out, const int *labels,
                                                  int compare_index,
                                                  int negate)
{
    const struct MirInsn *branch = &mir.insns[compare_index + 1 + negate];
    int target;
    const char *true_condition;

    if (branch->label < 0 || branch->label >= mir.next_label)
        return 0;
    target = mir_find_label(branch->label);
    if (target < 0)
        return 0;
    fputs("\tld a,h\n\tor l\n", out);
    true_condition = negate ? "z" : "nz";
    return mir_emit_conditional_branch_with_phi_copies(
        out, labels, true_condition, compare_index + 1 + negate, target,
        branch->label);
}

/* Item T45 (mir-text-size-plan.md): ported directly from
 * emit_shift_const_long (dcc_ops.c, the legacy AST backend) - any wide
 * shift count 1..31 decomposes into a whole-byte register-move (0-3
 * bytes, reusing the same move sequences legacy already validated) plus
 * a 0-7 bit remainder unrolled directly, since the count is already
 * known at compile time and a runtime b-counted loop would only add
 * control overhead for no benefit. A count of exactly 0 emits nothing.
 * The caller guarantees count is in [0,31] - counts >= 32 are handled
 * separately (or left on the runtime-loop path) since they are outside
 * the range this decomposition was validated for. Shared with Item T46's
 * multiply-by-power-of-two-constant fast path below, which is always an
 * `is_left` shift regardless of the multiplicand's signedness. */
void mir_emit_wide_shift_by_constant(FILE *out, int is_left,
                                     int is_unsigned, long count)
{
    int bytes;
    int bits;

    if (count <= 0)
        return;
    bytes = (int)(count / 8);
    bits = (int)(count % 8);

    if (is_left) {
        switch (bytes) {
        case 1: fputs("\tld d,e\n\tld e,h\n\tld h,l\n\tld l,0\n", out); break;
        case 2: fputs("\tld e,l\n\tld d,h\n\tld hl,0\n", out); break;
        case 3: fputs("\tld d,l\n\tld e,0\n\tld hl,0\n", out); break;
        default: break;
        }
        while (bits-- > 0)
            fputs("\tadd hl,hl\n\trl e\n\trl d\n", out);
    } else if (is_unsigned) {
        switch (bytes) {
        case 1: fputs("\tld l,h\n\tld h,e\n\tld e,d\n\tld d,0\n", out); break;
        case 2: fputs("\tld l,e\n\tld h,d\n\tld de,0\n", out); break;
        case 3: fputs("\tld l,d\n\tld h,0\n\tld de,0\n", out); break;
        default: break;
        }
        while (bits-- > 0)
            fputs("\tsrl d\n\trr e\n\trr h\n\trr l\n", out);
    } else {
        if (bytes > 0) {
            fputs("\tld a,d\n\trla\n\tsbc a,a\n", out);
            switch (bytes) {
            case 1: fputs("\tld l,h\n\tld h,e\n\tld e,d\n\tld d,a\n", out); break;
            case 2: fputs("\tld l,e\n\tld h,d\n\tld e,a\n\tld d,a\n", out); break;
            case 3: fputs("\tld l,d\n\tld h,a\n\tld e,a\n\tld d,a\n", out); break;
            default: break;
            }
        }
        while (bits-- > 0)
            fputs("\tsra d\n\trr e\n\trr h\n\trr l\n", out);
    }
}

/* log2 of a power-of-two 32-bit unsigned value; returns -1 if v is 0 or
 * not an exact power of two. Ported from ulong_log2_pow2 (dcc_ops.c). Not
 * static: also used by Item T49's scalar (16-bit) unsigned div/mod-by-
 * power-of-2 fast path, including the call site in
 * dcc_mir_emit_common.c. A 16-bit divisor is simply passed through the
 * same 32-bit-wide check unchanged - the power-of-two test and log2
 * computation are correct for any width. */
int mir_ulong_log2_pow2(unsigned long v)
{
    int n;

    if (v == 0 || (v & (v - 1)) != 0)
        return -1;
    n = 0;
    while (v > 1) {
        v >>= 1;
        ++n;
    }
    return n;
}

/* AND one 16-bit register pair (hi_reg:lo_reg) with a compile-time word
 * mask in place, without a temporary register pair: a byte that is
 * all-ones in the mask is left untouched, a byte that is all-zero
 * collapses to a single immediate load, and anything else gets one
 * immediate `and`. Ported from emit_and_word_const (dcc_ops.c). Not
 * static: also called from dcc_mir_emit_common.c's mir_emit_scalar_value
 * (Item T48) for the trivial-single-return selector's own scalar '&'
 * case, mirroring how mir_emit_scalar_shift is already shared between
 * both files (Item T44). */
void mir_emit_word_and_constant(FILE *out, char hi_reg, char lo_reg,
                                 unsigned int word_mask)
{
    unsigned int hib = (word_mask >> 8) & 0xffU;
    unsigned int lob = word_mask & 0xffU;

    if (word_mask == 0xffffU)
        return;
    if (word_mask == 0) {
        fprintf(out, "\tld %c%c,0\n", hi_reg, lo_reg);
        return;
    }
    if (hib == 0)
        fprintf(out, "\tld %c,0\n", hi_reg);
    else if (hib != 0xffU)
        fprintf(out, "\tld a,%c\n\tand %u\n\tld %c,a\n", hi_reg, hib, hi_reg);
    if (lob == 0)
        fprintf(out, "\tld %c,0\n", lo_reg);
    else if (lob != 0xffU)
        fprintf(out, "\tld a,%c\n\tand %u\n\tld %c,a\n", lo_reg, lob, lo_reg);
}

/* Item T47 (mir-text-size-plan.md): AND the DE:HL long value in place with
 * a compile-time 32-bit mask, byte by byte, instead of the generic
 * push/pop/ex-de-hl AND dance. Ported from emit_and_long_const
 * (dcc_ops.c). */
static void mir_emit_wide_and_constant(FILE *out, unsigned long mask)
{
    mir_emit_word_and_constant(out, 'd', 'e',
                                (unsigned int)((mask >> 16) & 0xffffUL));
    mir_emit_word_and_constant(out, 'h', 'l', (unsigned int)(mask & 0xffffUL));
}

static int mir_emit_nested_truth_comparison_branch(FILE *out,
                                                    const int *labels,
                                                    int instruction)
{
    int left_parameter;
    int right_parameter;
    int left_zero_label;
    int done_label;
    const struct MirInsn *branch;

    if (!mir_nested_truth_comparison(instruction, &left_parameter,
                                     &right_parameter))
        return 0;
    branch = &mir.insns[instruction + 1];
    if (branch->label < 0 || branch->label >= mir.next_label)
        return 0;
    left_zero_label = new_label();
    done_label = new_label();
    mir_emit_virtual_load(out, left_parameter);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\n", left_zero_label);
    mir_emit_virtual_load(out, right_parameter);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp nz,L%d\n\tjp L%d\nL%d:\n",
            labels[branch->label], done_label, left_zero_label);
    mir_emit_virtual_load(out, right_parameter);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\nL%d:\n",
            labels[branch->label], done_label);
    return 1;
}

/* Checks whether insn (a wide '&') has a MIR_CONST operand and, if so,
 * emits the byte-wise mask-AND fast path and returns 1. Checks src2
 * first (the common `x & CONST` shape - DE:HL already holds src2's
 * now-dead value, discarded via pop hl/pop de to restore src1, the real
 * lhs, from the stack, mirroring Items T45/T46's identical restore
 * sequence), then src1 (the `CONST & x` shape MIR does not canonicalize
 * away - DE:HL already holds src2, the real lhs, needing no restore;
 * the dead constant pushed for src1 is simply discarded via pop bc/pop
 * bc). Returns 0 (emits nothing) if neither operand is a compile-time
 * constant, leaving the caller to fall back to the generic AND path. */
static int mir_emit_wide_and_constant_fastpath(FILE *out,
                                                const struct MirInsn *insn)
{
    const struct MirInsn *src2_definition = mir_definition(insn->src2);
    const struct MirInsn *src1_definition = mir_definition(insn->src1);

    if (src2_definition != NULL && src2_definition->opcode == MIR_CONST) {
        fputs("\tpop hl\n\tpop de\n", out);
        mir_emit_wide_and_constant(out, (unsigned long)src2_definition->immediate);
        return 1;
    }

    if (src1_definition != NULL && src1_definition->opcode == MIR_CONST) {
        fputs("\tpop bc\n\tpop bc\n", out);
        mir_emit_wide_and_constant(out, (unsigned long)src1_definition->immediate);
        return 1;
    }
    return 0;
}

static const char *mir_wide_runtime_helper(const struct MirInsn *insn)
{
    int operation = (int)insn->immediate;
    int operand_type = insn->secondary_offset;

    if (type_is_float(operand_type)) {
        if (operation == '+' || operation == '-' || operation == '*' ||
            operation == '/')
            return operation == '+' ? "__faf" : operation == '-' ? "__fsf" :
                   operation == '*' ? "__fmf" : "__fdf";
        if (operation == TOK_EQ || operation == TOK_NE ||
            operation == '<' || operation == '>' ||
            operation == TOK_LE || operation == TOK_GE)
            return operation == TOK_EQ ? "__feqf" :
                   operation == TOK_NE ? "__fnef" :
                   operation == '<' ? "__fgtf" :
                   operation == '>' ? "__fltf" :
                   operation == TOK_LE ? "__fgef" : "__flef";
        return NULL;
    }
    if (operation == '<' || operation == '>' || operation == TOK_LE ||
        operation == TOK_GE) {
        int is_unsigned = (operand_type & TYPE_UNSIGNED) != 0;
        return operation == '<' ? (is_unsigned ? "__ltu" : "__lts") :
               operation == TOK_LE ? (is_unsigned ? "__leu" : "__les") :
               operation == '>' ? (is_unsigned ? "__lgu" : "__lgs") :
               (is_unsigned ? "__lku" : "__lks");
    }
    if (operation == '*') {
        const struct MirInsn *src2_definition =
            mir_definition(insn->src2);
        const struct MirInsn *src1_definition =
            mir_definition(insn->src1);

        if (src2_definition != NULL &&
            src2_definition->opcode == MIR_CONST &&
            mir_ulong_log2_pow2(
                (unsigned long)src2_definition->immediate) > 0)
            return NULL;
        if (src1_definition != NULL &&
            src1_definition->opcode == MIR_CONST &&
            mir_ulong_log2_pow2(
                (unsigned long)src1_definition->immediate) > 0)
            return NULL;
        return "__lmul";
    }
    if (operation == '/')
        return (insn->type & TYPE_UNSIGNED) != 0 ? "__ldu" : "__lds";
    if (operation == '%')
        return (insn->type & TYPE_UNSIGNED) != 0 ? "__lmu" : "__lms";
    return NULL;
}

/* Item T395/follow-on (mir-text-size-plan.md): direct port of the legacy
 * AST backend's emit_signed_long_const_cmp_ast (dcc_ast_gen_expr.c) into
 * the MIR value-materializing wide-comparison path. Legacy never calls
 * __lts/__les/__gts/__ges when the right operand is a signed compile-time
 * long constant - it inlines a sign-flip + 32-bit sbc sequence instead,
 * applying a C+1 bias to reduce '>'/'<=' to '>='/'<' (with a dedicated
 * INT32_MAX early-out, since C+1 would otherwise overflow the bias
 * arithmetic). This function reproduces that sequence exactly, byte for
 * byte, against a literal constant rather than a loaded DE:HL - the
 * caller is responsible for having DE:HL hold the *variable* operand's
 * value (not the constant) before calling this. */
static int mir_emit_wide_signed_const_compare(FILE *out, int op, long c)
{
    unsigned long threshold = (unsigned long)c & 0xffffffffUL;
    unsigned long biased;
    unsigned int lo;
    unsigned int hi;
    int true_label;
    int end_label;
    int true_on_carry;

    if (op == '>' || op == TOK_LE) {
        if (threshold == 0x7fffffffUL) {
            fputs(op == '>' ? "\tld hl,0\n" : "\tld hl,1\n", out);
            return 1;
        }
        threshold = (threshold + 1UL) & 0xffffffffUL;
    }
    biased = (threshold ^ 0x80000000UL) & 0xffffffffUL;
    lo = (unsigned int)(biased & 0xffffUL);
    hi = (unsigned int)((biased >> 16) & 0xffffUL);
    true_on_carry = (op == '<' || op == TOK_LE);
    true_label = new_label();
    end_label = new_label();

    fputs("\tld a,d\n\txor 80h\n\tld d,a\n", out);
    fprintf(out, "\tld bc,%u\n", lo);
    fputs("\tor a\n\tsbc hl,bc\n\tex de,hl\n", out);
    fprintf(out, "\tld bc,%u\n", hi);
    fputs("\tsbc hl,bc\n", out);
    fprintf(out, true_on_carry ? "\tjp c, L%d\n" : "\tjp nc, L%d\n",
            true_label);
    fprintf(out, "\tld hl,0\n\tjp L%d\nL%d:\n\tld hl,1\nL%d:\n",
            end_label, true_label, end_label);
    return 1;
}

/* Item T395/follow-on: identifies whether mir_emit_wide_operation will
 * take the mir_emit_wide_signed_const_compare fast path for this
 * instruction, so the caller (mir_emit_spilled_scalar_cfg's MIR_BINARY
 * dispatch) can skip loading src2 into DE:HL entirely - the fast path
 * only ever needs src2's compile-time literal value, never its loaded
 * runtime form, and skipping that dead load avoids paying for it at
 * every call site (legacy never materializes the constant into
 * registers for this shape either). */
int mir_wide_operation_is_signed_const_relational(const struct MirInsn *insn)
{
    int operation = (int)insn->immediate;
    const struct MirInsn *right;

    if (operation != '<' && operation != '>' && operation != TOK_LE &&
        operation != TOK_GE)
        return 0;
    if (type_is_float(insn->secondary_offset) ||
        (insn->secondary_offset & TYPE_UNSIGNED) != 0)
        return 0;
    right = mir_definition(insn->src2);
    return right != NULL && right->opcode == MIR_CONST;
}

int mir_emit_wide_operation(FILE *out, const struct MirInsn *insn)
{
    const char *helper = NULL;
    int operation = (int)insn->immediate;
    int operand_type = insn->secondary_offset;
    if (type_is_float(operand_type)) {
        helper = mir_wide_runtime_helper(insn);
        if (helper == NULL)
            return 0;
        mir_emit_runtime_call(out, helper);
        fputs("\tpop bc\n\tpop bc\n", out);
        return 1;
    }
    if (operation == TOK_EQ || operation == TOK_NE) {
        int true_label = new_label();
        int end_label = new_label();
        fputs("\tpop bc\n\tld a,c\n\txor l\n\tld l,a\n"
              "\tld a,b\n\txor h\n\tor l\n\tld l,a\n"
              "\tpop bc\n\tld a,c\n\txor e\n\tor l\n\tld l,a\n"
              "\tld a,b\n\txor d\n\tor l\n", out);
        fprintf(out, operation == TOK_EQ ? "\tjp z, L%d\n" : "\tjp nz, L%d\n",
                true_label);
        fprintf(out, "\tld hl,0\n\tjp L%d\nL%d:\n\tld hl,1\nL%d:\n",
                end_label, true_label, end_label);
        return 1;
    }
    if (operation == '<' || operation == '>' || operation == TOK_LE ||
        operation == TOK_GE) {
        const struct MirInsn *left = mir_definition(insn->src1);
        const struct MirInsn *right = mir_definition(insn->src2);
        int compares_constant =
            (left != NULL && left->opcode == MIR_CONST) ||
            (right != NULL && right->opcode == MIR_CONST);

        if (compares_constant) {
            if ((operand_type & TYPE_UNSIGNED) != 0)
                mir_spilled_cfg_used_unsigned_wide_constant_relational = 1;
            else
                mir_spilled_cfg_used_signed_wide_constant_relational = 1;
        }
        /* Item T395/follow-on: legacy's emit_signed_long_const_cmp_ast
         * only ever applies when the constant is the *right* operand
         * (ast_const_scalar_fold(n->b, ...) in dcc_ast_gen_expr.c) - a
         * constant on the left still falls through to the runtime
         * helper in legacy too, so leaving that ordering on the
         * existing call-based path below is exactly call-for-call
         * equivalent to legacy, not a missed optimization. The caller
         * (mir_emit_spilled_scalar_cfg) recognizes this same shape via
         * mir_wide_operation_is_signed_const_relational and skips both
         * the push of src1 and the load of src2 - DE:HL already holds
         * src1's value untouched from its own load, exactly what this
         * path needs. */
        if (mir_wide_operation_is_signed_const_relational(insn))
            return mir_emit_wide_signed_const_compare(
                out, operation, right->immediate);
        helper = mir_wide_runtime_helper(insn);
        fputs("\tpush de\n\tpush hl\n", out);
        mir_emit_runtime_call(out, helper);
        fputs("\tex de,hl\n\tld hl,8\n\tadd hl,sp\n"
              "\tld sp,hl\n\tex de,hl\n", out);
        return 1;
    }
    switch ((int)insn->immediate) {
    case '+':
        fputs("\tpop bc\n\tor a\n\tadd hl,bc\n"
              "\tex de,hl\n\tpop bc\n\tadc hl,bc\n\tex de,hl\n", out);
        return 1;
    case '-':
        fputs("\tld b,h\n\tld c,l\n\tpop hl\n\tor a\n\tsbc hl,bc\n"
              "\tld b,h\n\tld c,l\n\tpop hl\n\tsbc hl,de\n"
              "\tld d,b\n\tld e,c\n\tex de,hl\n", out);
        return 1;
    case '&': case '|': case '^':
        /* Item T47 (mir-text-size-plan.md): `long_expr & <compile-time
         * constant mask>` skips the generic push/pop/ex-de-hl AND dance
         * entirely in favor of a byte-wise mask apply, mirroring
         * legacy's emit_and_long_const. Only '&' is special-cased here,
         * matching legacy exactly - there is no equivalent OR/XOR
         * constant-mask optimization in the legacy backend to port. */
        if (insn->immediate == '&' &&
            mir_emit_wide_and_constant_fastpath(out, insn))
            return 1;
        {
            const char *operation = insn->immediate == '&' ? "and" :
                                    insn->immediate == '|' ? "or" : "xor";
            fprintf(out,
                    "\tpop bc\n\tld a,l\n\t%s c\n\tld l,a\n"
                    "\tld a,h\n\t%s b\n\tld h,a\n"
                    "\tex de,hl\n\tpop bc\n"
                    "\tld a,l\n\t%s c\n\tld l,a\n"
                    "\tld a,h\n\t%s b\n\tld h,a\n\tex de,hl\n",
                    operation, operation, operation, operation);
        }
        return 1;
    case TOK_SHL: case TOK_SHR:
        {
            /* Item T45 (mir-text-size-plan.md): the wide (32-bit)
             * counterpart of Item T44's scalar shift unroll - a
             * compile-time-constant shift count still went through the
             * generic runtime bit-loop unconditionally. When insn->src2
             * resolves to a MIR_CONST in the only meaningful range for
             * a 32-bit value (0-31; wider counts are undefined
             * behavior in C and left on the loop path unchanged),
             * decompose into the same whole-byte-move-plus-bit-remainder
             * sequence legacy's emit_shift_const_long already uses (see
             * mir_emit_wide_shift_by_constant above) instead of a
             * generic per-bit unroll - the count is already known, so
             * the loop's `ld a,l` (extracting the runtime count from
             * src2's low byte) and `ld b,a`/`dec b`/`jp` bookkeeping are
             * unneeded entirely, not just the loop body repetition. A
             * shift count of 0 collapses to just the two pops that
             * restore src1 from the stack, with no shift instructions
             * at all. */
            const struct MirInsn *count_definition =
                mir_definition(insn->src2);
            int is_unsigned = (operand_type & TYPE_UNSIGNED) != 0;

            if (count_definition != NULL &&
                count_definition->opcode == MIR_CONST &&
                count_definition->immediate >= 0 &&
                count_definition->immediate < 32) {
                long count = count_definition->immediate;

                fputs("\tpop hl\n\tpop de\n", out);
                mir_emit_wide_shift_by_constant(out,
                                                 insn->immediate == TOK_SHL,
                                                 is_unsigned, count);
            } else {
                int loop_label = new_label();
                int done_label = new_label();
                fputs("\tld a,l\n\tpop hl\n\tpop de\n\tld b,a\n", out);
                fprintf(out, "L%d:\n\tld a,b\n\tor a\n\tjp z, L%d\n",
                        loop_label, done_label);
                if (insn->immediate == TOK_SHL)
                    fputs("\tadd hl,hl\n\trl e\n\trl d\n", out);
                else if (is_unsigned)
                    fputs("\tsrl d\n\trr e\n\trr h\n\trr l\n", out);
                else
                    fputs("\tsra d\n\trr e\n\trr h\n\trr l\n", out);
                fprintf(out, "\tdec b\n\tjp L%d\nL%d:\n",
                        loop_label, done_label);
            }
        }
        return 1;
    case '*':
        {
            /* Item T46 (mir-text-size-plan.md): ported from
             * emit_mul_pow2_long_const (dcc_ops.c) - `long_expr *
             * <compile-time power-of-two constant>` strength-reduces to
             * a left shift instead of a call to the generic __lmul
             * runtime helper, reusing mir_emit_wide_shift_by_constant
             * (Item T45, above). Unlike legacy's AST-level version
             * (which only ever sees the constant in the syntactic right
             * operand position), MIR's lowering does not canonicalize
             * commutative operands - `x * 4L` lowers with the constant
             * as src2, `4L * x` lowers with the constant as src1 - so
             * both positions are checked. When src2 is the constant,
             * DE:HL (already loaded with src2's now-dead value) is
             * discarded and src1 (the real multiplicand) is restored
             * from the stack, mirroring Item T45's shift-fix exactly.
             * When src1 is the constant, DE:HL already holds src2 (the
             * real multiplicand, loaded most recently) and the dead
             * constant left on the stack from src1's evaluation is
             * simply popped off - no register restore needed at all.
             * Declines (falls through to __lmul) for 0, 1, and any
             * non-power-of-two multiplier, matching legacy's exact
             * scope - 0 and 1 are rare enough as literal long
             * multipliers not to be worth special-casing separately. */
            const struct MirInsn *src2_definition =
                mir_definition(insn->src2);
            const struct MirInsn *src1_definition =
                mir_definition(insn->src1);

            if (src2_definition != NULL &&
                src2_definition->opcode == MIR_CONST) {
                int shift = mir_ulong_log2_pow2(
                    (unsigned long)src2_definition->immediate);
                if (shift > 0) {
                    fputs("\tpop hl\n\tpop de\n", out);
                    mir_emit_wide_shift_by_constant(out, 1, 1, shift);
                    return 1;
                }
            }
            if (src1_definition != NULL &&
                src1_definition->opcode == MIR_CONST) {
                int shift = mir_ulong_log2_pow2(
                    (unsigned long)src1_definition->immediate);
                if (shift > 0) {
                    fputs("\tpop bc\n\tpop bc\n", out);
                    mir_emit_wide_shift_by_constant(out, 1, 1, shift);
                    return 1;
                }
            }
        }
        helper = mir_wide_runtime_helper(insn); break;
    case '/': case '%': helper = mir_wide_runtime_helper(insn); break;
    default: return 0;
    }
    mir_emit_runtime_call(out, helper);
    fputs("\tpop bc\n\tpop bc\n", out);
    return 1;
}

/* Item T32 (mir-text-size-plan.md): mir_emit_fused_comparison_branch and its
 * wide/sign-test siblings need to know, before committing to an emission
 * shape, whether a given CFG edge has any phi copies to run at all - see
 * mir_phi_copies_are_empty below. Both that predicate and
 * mir_emit_spilled_phi_copies itself now share this single collection
 * routine so the "what copies does this edge need" logic can never drift
 * between the two callers. */
static int mir_collect_phi_copies_for_edge(int predecessor, int successor,
                                            int *sources, int *destinations)
{
    int predecessor_label = mir_block_label_before(predecessor);
    int edge_label = -1;
    int instruction = mir_first_phi_or_block_end(successor);
    int copy_count = 0;

    if (predecessor >= 0 && predecessor < mir.count &&
        (mir.insns[predecessor].opcode == MIR_JUMP ||
         mir.insns[predecessor].opcode == MIR_BRANCH_FALSE) &&
        mir_find_label(mir.insns[predecessor].label) == successor)
        edge_label = mir.insns[predecessor].label;

    while (instruction >= 0 && instruction < mir.count &&
           (mir.insns[instruction].opcode == MIR_PHI ||
            mir.insns[instruction].opcode == MIR_NOP)) {
        const struct MirInsn *phi = &mir.insns[instruction];
        int source;
        if (phi->opcode == MIR_NOP) {
            ++instruction;
            continue;
        }
        if (!mir_value_has_use(phi->dst)) {
            ++instruction;
            continue;
        }
        source = mir_phi_source_for_edge(phi, predecessor_label, edge_label,
                                         successor, instruction);
        if (source < 0)
            return -1;
        if ((mir_phi_slot_cleanup_enabled ||
             mir_value_is_wide_phi_increment_result(source) ||
             mir_value_is_narrow_phi_adjust_result(source)) &&
            mir_phi_copy_is_slot_identity(source, phi->dst)) {
            ++instruction;
            continue;
        }
        if (copy_count >= MAX_FLOW)
            return -1;
        sources[copy_count] = source;
        destinations[copy_count] = phi->dst;
        ++copy_count;
        ++instruction;
    }
    return copy_count;
}

/* Item T32: true only when the edge from `predecessor` to `successor`
 * definitely has no phi copies to run (a hard-fail collection is treated as
 * "not provably empty" so the caller falls back to the general path, which
 * will itself surface the same failure mir_emit_spilled_phi_copies always
 * has). Callers use this to decide whether a fused comparison branch can
 * skip straight to a single inverted jump - see
 * mir_emit_conditional_branch_with_phi_copies. */
static int mir_phi_copies_are_empty(int predecessor, int successor)
{
    int sources[MAX_FLOW];
    int destinations[MAX_FLOW];
    return mir_collect_phi_copies_for_edge(predecessor, successor, sources,
                                            destinations) == 0;
}

/* Recover the switch identity lost when MIR lowering expands each case into
 * an equality branch, but only when every edge is phi-copy-free. */
struct MirDenseByteSwitch {
    int condition;
    int condition_size;
    int condition_in_hl;
    int default_label;
    int end_instruction;
    int case_count;
    int minimum_case;
    int maximum_case;
    int targets[256];
};

static int mir_match_dense_byte_switch(
    int start, struct MirDenseByteSwitch *dispatch);

struct MirInlinePostincrementStore {
    struct Sym *callee;
    struct Sym *pointer;
    struct Sym *base;
    struct Sym *index;
    struct Sym *state;
    struct FieldDef *field;
    int kind;
    int member_op;
    int width;
    int enabled;
    int call_count;
    int continuation_label;
};

enum MirInlinePostincrementStoreKind {
    MIR_INLINE_POSTINC_DIRECT_POINTER = 1,
    MIR_INLINE_POSTINC_INDEXED_BASE = 2,
    MIR_INLINE_POSTINC_MEMBER_POINTER = 3
};

struct MirInlineMemoryStore {
    struct Sym *callee;
    int width;
};

struct MirInlineTypedIndexedStore {
    struct Sym *callee;
    struct Sym *array;
    struct Sym *base_state;
    struct FieldDef *base_field;
    struct FieldDef *width_field;
    struct FieldDef *pointer_field;
    int stride;
};

struct MirInlineIndexedStackStore {
    struct Sym *callee;
    struct Sym *base;
    struct Sym *state;
    struct FieldDef *index_field;
    int base_offset;
    int width;
};

static const struct AstNode *mir_inline_single_statement_expr(
    const struct Sym *callee)
{
    const struct AstNode *body;

    if (callee == NULL)
        return NULL;
    body = callee->inline_stmt_expr != NULL
        ? callee->inline_stmt_expr : callee->inline_stmt_body;
    if (body != NULL && body->kind == AST_EXPR_STMT)
        body = body->a;
    if (body != NULL && body->kind == AST_COMPOUND &&
        body->list_len == 1 &&
        body->list[0] != NULL &&
        body->list[0]->kind == AST_EXPR_STMT)
        body = body->list[0]->a;
    return body;
}

static const struct AstNode *mir_inline_unwrap_cast(
    const struct AstNode *node)
{
    while (node != NULL && node->kind == AST_CAST)
        node = node->a;
    return node;
}

static const struct AstNode *mir_inline_unwrap_integer_representation_cast(
    const struct AstNode *node)
{
    while (node != NULL && node->kind == AST_CAST) {
        const struct AstNode *source = node->a;

        if (source == NULL ||
            type_ptr_depth(node->type) != 0 ||
            type_ptr_depth(source->type) != 0 ||
            type_is_float(node->type) ||
            type_is_float(source->type) ||
            type_is_struct_object(node->type) ||
            type_is_struct_object(source->type) ||
            type_size(node->type) != type_size(source->type))
            return NULL;
        node = source;
    }
    return node;
}

static struct Sym *mir_inline_ident_symbol(const struct AstNode *node)
{
    if (node == NULL || node->kind != AST_IDENT)
        return NULL;
    if (node->sym != NULL)
        return node->sym;
    return node->sval != NULL ? find_global(node->sval) : NULL;
}

static int mir_inline_is_parameter(
    const struct AstNode *node, const struct Sym *callee, int parameter)
{
    const char *name;

    node = mir_inline_unwrap_integer_representation_cast(node);
    if (node == NULL || node->kind != AST_IDENT ||
        callee == NULL || parameter < 0 ||
        parameter >= callee->proto_nargs)
        return 0;
    name = node->sval != NULL
        ? node->sval : node->sym != NULL ? node->sym->name : NULL;
    return name != NULL &&
           !strcmp(name, callee->inline_param_names[parameter]);
}

static int mir_inline_is_parameter_low_bytes(
    const struct AstNode *node, const struct Sym *callee,
    int parameter, int width)
{
    const char *name;

    if (width <= 0 || width > 2)
        return 0;
    while (node != NULL && node->kind == AST_CAST) {
        const struct AstNode *source = node->a;

        if (source == NULL ||
            type_ptr_depth(node->type) != 0 ||
            type_ptr_depth(source->type) != 0 ||
            type_is_float(node->type) ||
            type_is_float(source->type) ||
            type_is_struct_object(node->type) ||
            type_is_struct_object(source->type) ||
            type_size(node->type) < width ||
            type_size(source->type) < width)
            return 0;
        node = source;
    }
    if (node == NULL || node->kind != AST_IDENT ||
        callee == NULL || parameter < 0 ||
        parameter >= callee->proto_nargs)
        return 0;
    name = node->sval != NULL
        ? node->sval : node->sym != NULL ? node->sym->name : NULL;
    return name != NULL &&
           !strcmp(name, callee->inline_param_names[parameter]);
}

static int mir_inline_global_member(
    const struct AstNode *node, struct Sym **state_out,
    struct FieldDef **field_out, int *member_op_out)
{
    struct Sym *state;
    struct FieldDef *field;
    int struct_id;

    if (node == NULL || node->kind != AST_MEMBER ||
        (node->op != '.' && node->op != TOK_ARROW))
        return 0;
    state = mir_inline_ident_symbol(node->a);
    if (state == NULL ||
        (state->storage != SC_GLOBAL && state->storage != SC_EXTERN) ||
        state->is_volatile)
        return 0;
    struct_id = base_struct_id_from_type(state->type);
    field = struct_id >= 0 && node->sval != NULL
        ? find_field_def(struct_id, node->sval) : NULL;
    if (field == NULL || field->is_volatile || field->bit_width > 0)
        return 0;
    if (state_out != NULL)
        *state_out = state;
    if (field_out != NULL)
        *field_out = field;
    if (member_op_out != NULL)
        *member_op_out = node->op;
    return 1;
}

static int mir_inline_same_global_member(
    const struct AstNode *node, const struct Sym *state,
    const struct FieldDef *field, int member_op)
{
    struct Sym *candidate_state;
    struct FieldDef *candidate_field;
    int candidate_op;

    return mir_inline_global_member(
               node, &candidate_state, &candidate_field, &candidate_op) &&
           candidate_state == state && candidate_field == field &&
           candidate_op == member_op;
}

static int mir_inline_member_decrement(
    const struct AstNode *update, int required_kind,
    struct Sym **state_out, struct FieldDef **field_out)
{
    const struct AstNode *member;
    struct Sym *state;
    struct FieldDef *field;
    int struct_id;

    if (update == NULL || update->kind != required_kind ||
        update->op != TOK_DEC || update->a == NULL ||
        update->a->kind != AST_MEMBER || update->a->op != '.')
        return 0;
    member = update->a;
    state = mir_inline_ident_symbol(member->a);
    if (state == NULL ||
        (state->storage != SC_GLOBAL && state->storage != SC_EXTERN) ||
        state->is_volatile || type_ptr_depth(state->type) != 0)
        return 0;
    struct_id = base_struct_id_from_type(state->type);
    field = struct_id >= 0 && member->sval != NULL
        ? find_field_def(struct_id, member->sval) : NULL;
    if (field == NULL || field->is_volatile ||
        field->bit_width > 0 || type_size(field->type) != 1)
        return 0;
    if (state_out != NULL)
        *state_out = state;
    if (field_out != NULL)
        *field_out = field;
    return 1;
}

static int mir_inline_same_member_decrement(
    const struct AstNode *update, int required_kind,
    const struct Sym *state, const struct FieldDef *field)
{
    struct Sym *candidate_state;
    struct FieldDef *candidate_field;

    return mir_inline_member_decrement(
               update, required_kind,
               &candidate_state, &candidate_field) &&
           candidate_state == state && candidate_field == field;
}

static int mir_match_inline_indexed_stack_store(
    const struct MirInsn *call,
    struct MirInlineIndexedStackStore *helper)
{
    const struct AstNode *body;
    const struct AstNode *assignment;
    const struct AstNode *dereference;
    const struct AstNode *address;
    const struct AstNode *base_plus_offset;
    const struct AstNode *base_ident;
    const struct AstNode *update;
    const struct AstNode *second_update = NULL;
    const struct AstNode *value;
    struct Sym *callee;
    struct Sym *base;
    struct Sym *state;
    struct FieldDef *index_field;
    int width;

    if (call == NULL || call->opcode != MIR_CALL ||
        (call->memory_flags &
         MIR_CALL_FLAG_INLINE_SUBSTITUTABLE) == 0 ||
        (call->type & 15) != TYPE_VOID)
        return 0;
    callee = find_global(call->name);
    if (callee == NULL || !callee->is_static || !callee->is_inline ||
        callee->proto_nargs != 1 || callee->has_inline_local ||
        callee->inline_param_use_count[0] != 1)
        return 0;
    body = callee->inline_stmt_body != NULL
        ? callee->inline_stmt_body : callee->inline_stmt_expr;
    if (body != NULL && body->kind == AST_ASSIGN)
        assignment = body;
    else if (body != NULL && body->kind == AST_EXPR_STMT)
        assignment = body->a;
    else if (body != NULL && body->kind == AST_COMPOUND &&
             body->list_len == 2 &&
             body->list[0] != NULL &&
             body->list[0]->kind == AST_EXPR_STMT &&
             body->list[1] != NULL &&
             body->list[1]->kind == AST_EXPR_STMT) {
        assignment = body->list[0]->a;
        second_update = body->list[1]->a;
    } else
        return 0;
    if (assignment == NULL || assignment->kind != AST_ASSIGN ||
        assignment->op != '=' || assignment->a == NULL ||
        assignment->a->kind != AST_UNARY ||
        assignment->a->op != '*' || assignment->b == NULL)
        return 0;
    dereference = assignment->a;
    value = assignment->b;
    if (value->kind != AST_IDENT ||
        value->sval == NULL ||
        strcmp(value->sval, callee->inline_param_names[0]) != 0)
        return 0;
    address = mir_inline_unwrap_cast(dereference->a);
    if (address == NULL || address->kind != AST_BINARY ||
        address->op != '+' || address->a == NULL ||
        address->b == NULL)
        return 0;
    base_plus_offset = address->a;
    update = address->b;
    if (base_plus_offset->kind != AST_BINARY ||
        base_plus_offset->op != '+' ||
        base_plus_offset->a == NULL ||
        base_plus_offset->b == NULL ||
        base_plus_offset->b->kind != AST_INT_LIT ||
        base_plus_offset->b->ival < 0 ||
        base_plus_offset->b->ival > 65535)
        return 0;
    base_ident = mir_inline_unwrap_cast(base_plus_offset->a);
    base = mir_inline_ident_symbol(base_ident);
    if (base == NULL ||
        (base->storage != SC_GLOBAL && base->storage != SC_EXTERN) ||
        !base->is_array || base->is_volatile ||
        base->elem_size != 1)
        return 0;
    width = type_size(dereference->type);
    if (width == 1) {
        if (second_update != NULL ||
            !mir_inline_member_decrement(
                update, AST_POSTFIX, &state, &index_field))
            return 0;
    } else if (width == 2) {
        if (!mir_inline_member_decrement(
                update, AST_UNARY, &state, &index_field) ||
            !mir_inline_same_member_decrement(
                second_update, AST_POSTFIX, state, index_field))
            return 0;
    } else
        return 0;
    if (helper != NULL) {
        helper->callee = callee;
        helper->base = base;
        helper->state = state;
        helper->index_field = index_field;
        helper->base_offset = (int)base_plus_offset->b->ival;
        helper->width = width;
    }
    return 1;
}

static int mir_call_uses_inline_indexed_stack_store(
    int call_instruction, int *argument,
    struct MirInlineIndexedStackStore *helper)
{
    return call_instruction >= 0 && call_instruction < mir.count &&
           mir_match_inline_indexed_stack_store(
               &mir.insns[call_instruction], helper) &&
           mir_single_call_argument(call_instruction, argument);
}

static void mir_emit_inline_indexed_stack_store(
    FILE *out, const struct MirInlineIndexedStackStore *helper)
{
    const char *base_name =
        asm_name_for(sym_asm_name(helper->base));
    const char *state_name =
        asm_name_for(sym_asm_name(helper->state));

    if ((helper->base->storage == SC_EXTERN ||
         helper->base->needs_extrn) &&
        mir_extrn_should_emit(helper->base))
        fprintf(out, "\textrn %s\n", base_name);
    if ((helper->state->storage == SC_EXTERN ||
         helper->state->needs_extrn) &&
        mir_extrn_should_emit(helper->state))
        fprintf(out, "\textrn %s\n", state_name);
    fputs("\tex de,hl\n", out);
    fprintf(out, "\tld a,(%s%+d)\n",
            state_name, helper->index_field->offset);
    if (helper->width == 2)
        fputs("\tdec a\n", out);
    fputs("\tld l,a\n\tld h,0\n\tdec a\n", out);
    fprintf(out, "\tld (%s%+d),a\n",
            state_name, helper->index_field->offset);
    fprintf(out, "\tld bc,%s%+d\n\tadd hl,bc\n"
                 "\tld (hl),e\n",
            base_name, helper->base_offset);
    if (helper->width == 2)
        fputs("\tinc hl\n\tld (hl),d\n", out);
}

static int mir_match_inline_postincrement_store(
    const struct MirInsn *call,
    struct MirInlinePostincrementStore *helper)
{
    struct Sym *callee;
    struct Sym *pointer;
    const struct AstNode *assignment;
    const struct AstNode *dereference;
    const struct AstNode *increment;
    const struct AstNode *pointer_ident;
    const struct AstNode *value_ident;
    const char *value_name;
    int width;

    if (call == NULL || call->opcode != MIR_CALL ||
        (call->memory_flags &
         MIR_CALL_FLAG_INLINE_SUBSTITUTABLE) == 0 ||
        (call->type & 15) != TYPE_VOID)
        return 0;
    callee = find_global(call->name);
    if (callee == NULL || !callee->is_static || !callee->is_inline ||
        callee->proto_nargs != 1 || callee->has_inline_local)
        return 0;
    assignment = mir_inline_single_statement_expr(callee);
    if (assignment == NULL || assignment->kind != AST_ASSIGN ||
        assignment->op != '=' ||
        assignment->a == NULL || assignment->b == NULL)
        return 0;
    dereference = assignment->a;
    increment = dereference->a;
    pointer_ident = increment != NULL ? increment->a : NULL;
    value_ident = assignment->b;
    if (dereference->kind != AST_UNARY ||
        dereference->op != '*' ||
        increment == NULL || increment->kind != AST_POSTFIX ||
        increment->op != TOK_INC ||
        pointer_ident == NULL || pointer_ident->kind != AST_IDENT ||
        value_ident->kind != AST_IDENT)
        return 0;
    value_name = value_ident->sval != NULL
        ? value_ident->sval
        : value_ident->sym != NULL ? value_ident->sym->name : NULL;
    if (value_name == NULL ||
        strcmp(value_name, callee->inline_param_names[0]) != 0 ||
        callee->inline_param_use_count[0] != 1)
        return 0;
    pointer = pointer_ident->sym;
    width = type_size(dereference->type);
    if (pointer == NULL ||
        (pointer->storage != SC_GLOBAL &&
         pointer->storage != SC_EXTERN) ||
        pointer->is_volatile || pointer->pointee_is_volatile ||
        type_ptr_depth(pointer->type) == 0 ||
        (width != 1 && width != 2))
        return 0;
    if (helper != NULL) {
        memset(helper, 0, sizeof(*helper));
        helper->callee = callee;
        helper->pointer = pointer;
        helper->kind = MIR_INLINE_POSTINC_DIRECT_POINTER;
        helper->width = width;
    }
    return 1;
}

static int mir_match_inline_indexed_postincrement_store(
    const struct MirInsn *call,
    struct MirInlinePostincrementStore *helper)
{
    const struct AstNode *assignment;
    const struct AstNode *index;
    const struct AstNode *increment;
    struct Sym *callee;
    struct Sym *base;
    struct Sym *counter;
    int width;
    int element_size;

    if (call == NULL || call->opcode != MIR_CALL ||
        (call->memory_flags &
         MIR_CALL_FLAG_INLINE_SUBSTITUTABLE) == 0 ||
        (call->type & 15) != TYPE_VOID)
        return 0;
    callee = find_global(call->name);
    if (callee == NULL || !callee->is_static || !callee->is_inline ||
        callee->proto_nargs != 1 || callee->has_inline_local ||
        callee->inline_param_use_count[0] != 1)
        return 0;
    assignment = mir_inline_single_statement_expr(callee);
    if (assignment == NULL || assignment->kind != AST_ASSIGN ||
        assignment->op != '=' || assignment->a == NULL ||
        assignment->a->kind != AST_INDEX)
        return 0;
    index = assignment->a;
    width = type_size(index->type);
    if ((width != 1 && width != 2) ||
        !mir_inline_is_parameter_low_bytes(
            assignment->b, callee, 0, width))
        return 0;
    increment = index->b;
    base = mir_inline_ident_symbol(index->a);
    counter = increment != NULL && increment->kind == AST_POSTFIX &&
                      increment->op == TOK_INC
        ? mir_inline_ident_symbol(increment->a) : NULL;
    if (base == NULL || counter == NULL ||
        (base->storage != SC_GLOBAL && base->storage != SC_EXTERN) ||
        (counter->storage != SC_GLOBAL && counter->storage != SC_EXTERN) ||
        base->is_volatile || base->pointee_is_volatile ||
        counter->is_volatile || type_ptr_depth(counter->type) != 0 ||
        type_size(counter->type) != 2)
        return 0;
    element_size = base->is_array
        ? base->elem_size : type_index_elem_size(base->type);
    if ((width != 1 && width != 2) || element_size != width)
        return 0;
    if (helper != NULL) {
        memset(helper, 0, sizeof(*helper));
        helper->callee = callee;
        helper->base = base;
        helper->index = counter;
        helper->kind = MIR_INLINE_POSTINC_INDEXED_BASE;
        helper->width = width;
    }
    return 1;
}

static int mir_match_inline_member_postincrement_store(
    const struct MirInsn *call,
    struct MirInlinePostincrementStore *helper)
{
    const struct AstNode *body;
    const struct AstNode *store_statement;
    const struct AstNode *update_statement;
    const struct AstNode *assignment;
    const struct AstNode *dereference;
    const struct AstNode *update;
    const struct AstNode *addition;
    const struct AstNode *one;
    struct Sym *callee;
    struct Sym *state;
    struct FieldDef *field;
    int member_op;
    int width;

    if (call == NULL || call->opcode != MIR_CALL ||
        (call->memory_flags &
         MIR_CALL_FLAG_INLINE_SUBSTITUTABLE) == 0 ||
        (call->type & 15) != TYPE_VOID)
        return 0;
    callee = find_global(call->name);
    if (callee == NULL || !callee->is_static || !callee->is_inline ||
        callee->proto_nargs != 1 || callee->has_inline_local ||
        callee->inline_param_use_count[0] != 1)
        return 0;
    body = callee->inline_stmt_body != NULL
        ? callee->inline_stmt_body : callee->inline_stmt_expr;
    if (body == NULL || body->kind != AST_COMPOUND ||
        body->list_len != 2)
        return 0;
    store_statement = body->list[0];
    update_statement = body->list[1];
    if (store_statement == NULL ||
        store_statement->kind != AST_EXPR_STMT ||
        update_statement == NULL ||
        update_statement->kind != AST_EXPR_STMT)
        return 0;
    assignment = store_statement->a;
    update = update_statement->a;
    if (assignment == NULL || assignment->kind != AST_ASSIGN ||
        assignment->op != '=' || assignment->a == NULL ||
        assignment->a->kind != AST_UNARY ||
        assignment->a->op != '*' ||
        update == NULL || update->kind != AST_ASSIGN ||
        update->op != '=')
        return 0;
    dereference = assignment->a;
    width = type_size(dereference->type);
    if ((width != 1 && width != 2) ||
        !mir_inline_is_parameter_low_bytes(
            assignment->b, callee, 0, width))
        return 0;
    if (!mir_inline_global_member(
            dereference->a, &state, &field, &member_op) ||
        !mir_inline_same_global_member(
            update->a, state, field, member_op))
        return 0;
    addition = update->b;
    if (addition == NULL || addition->kind != AST_BINARY ||
        addition->op != '+' ||
        !mir_inline_same_global_member(
            addition->a, state, field, member_op))
        return 0;
    one = mir_inline_unwrap_cast(addition->b);
    if (one == NULL || one->kind != AST_INT_LIT || one->ival != 1 ||
        type_ptr_depth(field->type) == 0 ||
        type_index_elem_size(field->type) != width ||
        (width != 1 && width != 2))
        return 0;
    if (helper != NULL) {
        memset(helper, 0, sizeof(*helper));
        helper->callee = callee;
        helper->state = state;
        helper->field = field;
        helper->kind = MIR_INLINE_POSTINC_MEMBER_POINTER;
        helper->member_op = member_op;
        helper->width = width;
    }
    return 1;
}

static int mir_match_any_inline_postincrement_store(
    const struct MirInsn *call,
    struct MirInlinePostincrementStore *helper)
{
    return mir_match_inline_postincrement_store(call, helper) ||
           mir_match_inline_indexed_postincrement_store(call, helper) ||
           mir_match_inline_member_postincrement_store(call, helper);
}

static int mir_inline_affine_index(
    const struct AstNode *node, const struct Sym *callee,
    int coefficients[3])
{
    int left[3] = {0, 0, 0};
    int right[3] = {0, 0, 0};
    int component;

    node = mir_inline_unwrap_integer_representation_cast(node);
    if (node == NULL)
        return 0;
    if (mir_inline_is_parameter(node, callee, 0)) {
        coefficients[0] = 1;
        coefficients[1] = 0;
        coefficients[2] = 0;
        return 1;
    }
    if (mir_inline_is_parameter(node, callee, 1)) {
        coefficients[0] = 0;
        coefficients[1] = 1;
        coefficients[2] = 0;
        return 1;
    }
    if (node->kind == AST_INT_LIT &&
        node->ival >= 0 && node->ival <= 4) {
        coefficients[0] = 0;
        coefficients[1] = 0;
        coefficients[2] = (int)node->ival;
        return 1;
    }
    if (node->kind != AST_BINARY ||
        (node->op != '+' && node->op != '*') ||
        !mir_inline_affine_index(node->a, callee, left) ||
        !mir_inline_affine_index(node->b, callee, right))
        return 0;
    if (node->op == '+') {
        for (component = 0; component < 3; ++component) {
            coefficients[component] =
                left[component] + right[component];
            if (coefficients[component] < 0 ||
                coefficients[component] > 4)
                return 0;
        }
        return 1;
    }
    if (left[0] != 0 || left[1] != 0) {
        if (right[0] != 0 || right[1] != 0)
            return 0;
        for (component = 0; component < 3; ++component)
            coefficients[component] =
                left[component] * right[2];
    } else if (right[0] != 0 || right[1] != 0) {
        for (component = 0; component < 3; ++component)
            coefficients[component] =
                right[component] * left[2];
    } else {
        coefficients[0] = 0;
        coefficients[1] = 0;
        coefficients[2] = left[2] * right[2];
    }
    for (component = 0; component < 3; ++component)
        if (coefficients[component] < 0 ||
            coefficients[component] > 4)
            return 0;
    return 1;
}

static int mir_inline_value_byte_lane(
    const struct AstNode *node, const struct Sym *callee, int lane)
{
    const struct AstNode *constant;

    while (node != NULL && node->kind == AST_CAST) {
        const struct AstNode *source = node->a;

        if (source == NULL ||
            type_ptr_depth(node->type) != 0 ||
            type_ptr_depth(source->type) != 0 ||
            type_is_float(node->type) ||
            type_is_float(source->type) ||
            type_is_struct_object(node->type) ||
            type_is_struct_object(source->type) ||
            type_size(node->type) < 1 ||
            type_size(source->type) < 1)
            return 0;
        node = source;
    }
    if (node != NULL && node->kind == AST_BINARY &&
        node->op == '&') {
        constant = mir_inline_unwrap_cast(node->b);
        if (constant != NULL && constant->kind == AST_INT_LIT &&
            constant->ival == 255)
            node = mir_inline_unwrap_cast(node->a);
        else {
            constant = mir_inline_unwrap_cast(node->a);
            if (constant == NULL || constant->kind != AST_INT_LIT ||
                constant->ival != 255)
                return 0;
            node = mir_inline_unwrap_cast(node->b);
        }
    }
    if (lane == 0)
        return mir_inline_is_parameter_low_bytes(
            node, callee, 3, 1);
    if (lane != 1 || node == NULL ||
        node->kind != AST_BINARY || node->op != TOK_SHR ||
        !mir_inline_is_parameter(node->a, callee, 3))
        return 0;
    constant = mir_inline_unwrap_cast(node->b);
    return constant != NULL && constant->kind == AST_INT_LIT &&
           constant->ival == 8;
}

static const struct AstNode *mir_inline_body_expression(
    const struct Sym *callee, int index, int count)
{
    const struct AstNode *body;
    const struct AstNode *statement;

    if (callee == NULL || index < 0 || index >= count)
        return NULL;
    body = callee->inline_stmt_body != NULL
        ? callee->inline_stmt_body : callee->inline_stmt_expr;
    if (body == NULL)
        return NULL;
    if (body->kind == AST_COMPOUND) {
        if (body->list_len != count)
            return NULL;
        statement = body->list[index];
    } else {
        if (count != 1 || index != 0)
            return NULL;
        statement = body;
    }
    if (statement != NULL && statement->kind == AST_EXPR_STMT)
        statement = statement->a;
    return statement;
}

static int mir_match_inline_memory_store(
    const struct MirInsn *call, struct MirInlineMemoryStore *helper)
{
    struct Sym *callee;
    int width;
    int lane;

    if (call == NULL || call->opcode != MIR_CALL)
        return 0;
    callee = find_global(call->name);
    if ((call->memory_flags &
         MIR_CALL_FLAG_INLINE_SUBSTITUTABLE) == 0 ||
        (call->type & 15) != TYPE_VOID)
        return 0;
    if (callee == NULL || !callee->is_static || !callee->is_inline ||
        callee->proto_nargs != 4 || callee->has_inline_local ||
        type_ptr_depth(callee->proto_types[2]) == 0 ||
        type_index_elem_size(callee->proto_types[2]) != 1)
        return 0;
    width = mir_inline_body_expression(callee, 1, 2) != NULL ? 2 : 1;
    for (lane = 0; lane < width; ++lane) {
        const struct AstNode *assignment =
            mir_inline_body_expression(callee, lane, width);
        const struct AstNode *index =
            assignment != NULL && assignment->kind == AST_ASSIGN
                ? assignment->a : NULL;
        int coefficients[3] = {-1, -1, -1};
        int affine = index != NULL && index->kind == AST_INDEX &&
            mir_inline_affine_index(
                index->b, callee, coefficients);
        int base_parameter = index != NULL &&
            index->kind == AST_INDEX &&
            mir_inline_is_parameter(index->a, callee, 2);
        int value_lane = assignment != NULL &&
            mir_inline_value_byte_lane(
                assignment->b, callee, lane);

        if (assignment == NULL || assignment->kind != AST_ASSIGN ||
            assignment->op != '=' || assignment->a == NULL ||
            assignment->a->kind != AST_INDEX)
            return 0;
        index = assignment->a;
        if (!base_parameter || !affine ||
            coefficients[0] != 1 ||
            coefficients[1] != width ||
            coefficients[2] != lane ||
            !value_lane)
            return 0;
    }
    if (helper != NULL) {
        helper->callee = callee;
        helper->width = width;
    }
    return 1;
}

static int mir_collect_call_arguments(
    int call_instruction, int expected, int *arguments)
{
    const struct MirInsn *call;
    int found = 0;
    int instruction;
    int argument;

    if (call_instruction < 0 || call_instruction >= mir.count ||
        expected <= 0 || arguments == NULL)
        return 0;
    call = &mir.insns[call_instruction];
    for (argument = 0; argument < expected; ++argument)
        arguments[argument] = -1;
    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];
        int index;

        if (insn->opcode != MIR_ARG ||
            insn->secondary_offset != call->secondary_offset)
            continue;
        index = (int)insn->immediate;
        if (index < 0 || index >= expected ||
            arguments[index] >= 0 ||
            type_size(insn->type) > 2)
            return 0;
        arguments[index] = insn->src1;
        ++found;
    }
    if (found != expected)
        return 0;
    for (argument = 0; argument < expected; ++argument)
        if (arguments[argument] < 0)
            return 0;
    return 1;
}

static int mir_call_uses_inline_memory_store(
    int call_instruction, struct MirInlineMemoryStore *helper,
    int arguments[4])
{
    if (call_instruction < 0 || call_instruction >= mir.count ||
        !mir_match_inline_memory_store(
            &mir.insns[call_instruction], helper))
        return 0;
    if (arguments == NULL)
        return 1;
    return mir_collect_call_arguments(
        call_instruction, 4, arguments);
}

static void mir_emit_inline_memory_store(
    FILE *out, const struct MirInlineMemoryStore *helper,
    const int arguments[4])
{
    mir_emit_spilled_arg_to_hl(out, arguments[3]);
    fputs("\tpush hl\n", out);
    mir_emit_spilled_arg_to_hl(out, arguments[2]);
    fputs("\tpush hl\n", out);
    mir_emit_spilled_arg_to_hl(out, arguments[1]);
    if (helper->width == 2)
        fputs("\tadd hl,hl\n", out);
    fputs("\tpush hl\n", out);
    mir_emit_spilled_arg_to_hl(out, arguments[0]);
    fputs("\tpop de\n\tadd hl,de\n\tpop de\n\tadd hl,de\n"
          "\tpop de\n\tld (hl),e\n", out);
    if (helper->width == 2)
        fputs("\tinc hl\n\tld (hl),d\n", out);
}

static const struct AstNode *mir_inline_unwrap_statement(
    const struct AstNode *node)
{
    while (node != NULL && node->kind == AST_COMPOUND &&
           node->list_len == 1)
        node = node->list[0];
    if (node != NULL && node->kind == AST_EXPR_STMT)
        node = node->a;
    return node;
}

static int mir_inline_local_member(
    const struct AstNode *node, const struct Sym *callee,
    struct FieldDef **field_out)
{
    const struct AstNode *base;
    const char *name;
    struct FieldDef *field;
    int struct_id;

    node = mir_inline_unwrap_cast(node);
    if (node == NULL || node->kind != AST_MEMBER ||
        node->op != TOK_ARROW || callee == NULL ||
        !callee->has_inline_local || node->a == NULL)
        return 0;
    base = mir_inline_unwrap_cast(node->a);
    if (base == NULL || base->kind != AST_IDENT)
        return 0;
    name = base->sval != NULL
        ? base->sval : base->sym != NULL ? base->sym->name : NULL;
    if (name == NULL || strcmp(name, callee->inline_local_name) != 0)
        return 0;
    struct_id = base_struct_id_from_type(callee->inline_local_type);
    field = struct_id >= 0 && node->sval != NULL
        ? find_field_def(struct_id, node->sval) : NULL;
    if (field == NULL || field->is_volatile || field->bit_width > 0)
        return 0;
    if (field_out != NULL)
        *field_out = field;
    return 1;
}

static int mir_inline_typed_store_assignment(
    const struct AstNode *node, const struct Sym *callee,
    struct FieldDef **pointer_field_out, int *width_out)
{
    const struct AstNode *assignment =
        mir_inline_unwrap_statement(node);
    const struct AstNode *index;
    const struct AstNode *base;
    struct FieldDef *pointer_field;
    int width;

    if (assignment == NULL || assignment->kind != AST_ASSIGN ||
        assignment->op != '=' || assignment->a == NULL ||
        assignment->a->kind != AST_INDEX)
        return 0;
    index = assignment->a;
    if (!mir_inline_is_parameter(index->b, callee, 1))
        return 0;
    base = index->a;
    width = type_index_elem_size(base->type);
    base = mir_inline_unwrap_cast(base);
    if ((width != 1 && width != 2) ||
        !mir_inline_is_parameter_low_bytes(
            assignment->b, callee, 2, width) ||
        !mir_inline_local_member(
            base, callee, &pointer_field) ||
        type_ptr_depth(pointer_field->type) == 0)
        return 0;
    if (pointer_field_out != NULL)
        *pointer_field_out = pointer_field;
    if (width_out != NULL)
        *width_out = width;
    return 1;
}

static int mir_match_inline_typed_indexed_store(
    const struct MirInsn *call,
    struct MirInlineTypedIndexedStore *helper)
{
    struct Sym *callee;
    const struct AstNode *initializer;
    const struct AstNode *address;
    const struct AstNode *body;
    const struct AstNode *condition;
    const struct AstNode *constant;
    const struct AstNode *member;
    struct Sym *array;
    struct Sym *base_state = NULL;
    struct FieldDef *base_field = NULL;
    int base_member_op = 0;
    struct FieldDef *width_field;
    struct FieldDef *then_pointer;
    struct FieldDef *else_pointer;
    int then_width;
    int else_width;

    if (call == NULL || call->opcode != MIR_CALL ||
        (call->memory_flags &
         MIR_CALL_FLAG_INLINE_SUBSTITUTABLE) == 0 ||
        (call->type & 15) != TYPE_VOID)
        return 0;
    callee = find_global(call->name);
    if (callee == NULL || !callee->is_static || !callee->is_inline ||
        callee->proto_nargs != 3 || !callee->has_inline_local ||
        type_ptr_depth(callee->inline_local_type) == 0)
        return 0;
    initializer = mir_inline_unwrap_cast(callee->inline_local_init);
    if (initializer == NULL || initializer->kind != AST_UNARY ||
        initializer->op != '&')
        return 0;
    address = mir_inline_unwrap_cast(initializer->a);
    if (address == NULL || address->kind != AST_INDEX ||
        !mir_inline_is_parameter(address->b, callee, 0))
        return 0;
    array = mir_inline_ident_symbol(address->a);
    if (array != NULL) {
        if (!array->is_array || array->elem_size <= 0 ||
            (array->storage != SC_GLOBAL &&
             array->storage != SC_EXTERN) ||
            array->is_volatile)
            return 0;
    } else {
        if (!mir_inline_global_member(
                mir_inline_unwrap_cast(address->a),
                &base_state, &base_field, &base_member_op) ||
            base_member_op != '.' ||
            type_ptr_depth(base_field->type) == 0 ||
            type_index_elem_size(base_field->type) <= 0)
            return 0;
    }
    body = mir_inline_unwrap_statement(
        callee->inline_stmt_body != NULL
            ? callee->inline_stmt_body : callee->inline_stmt_expr);
    if (body == NULL || body->kind != AST_IF ||
        body->a == NULL || body->b == NULL || body->c == NULL)
        return 0;
    condition = mir_inline_unwrap_cast(body->a);
    if (condition == NULL || condition->kind != AST_BINARY ||
        condition->op != TOK_EQ)
        return 0;
    member = mir_inline_unwrap_cast(condition->a);
    constant = mir_inline_unwrap_cast(condition->b);
    if (constant == NULL || constant->kind != AST_INT_LIT ||
        constant->ival != 1) {
        member = mir_inline_unwrap_cast(condition->b);
        constant = mir_inline_unwrap_cast(condition->a);
    }
    if (constant == NULL || constant->kind != AST_INT_LIT ||
        constant->ival != 1 ||
        !mir_inline_local_member(
            member, callee, &width_field) ||
        type_size(width_field->type) != 1 ||
        !mir_inline_typed_store_assignment(
            body->b, callee, &then_pointer, &then_width) ||
        !mir_inline_typed_store_assignment(
            body->c, callee, &else_pointer, &else_width) ||
        then_pointer != else_pointer ||
        then_width != 1 || else_width != 2)
        return 0;
    if (helper != NULL) {
        helper->callee = callee;
        helper->array = array;
        helper->base_state = base_state;
        helper->base_field = base_field;
        helper->width_field = width_field;
        helper->pointer_field = then_pointer;
        helper->stride = array != NULL
            ? array->elem_size
            : type_index_elem_size(base_field->type);
    }
    return 1;
}

static int mir_call_uses_inline_typed_indexed_store(
    int call_instruction, struct MirInlineTypedIndexedStore *helper,
    int arguments[3])
{
    if (call_instruction < 0 || call_instruction >= mir.count ||
        !mir_match_inline_typed_indexed_store(
            &mir.insns[call_instruction], helper))
        return 0;
    if (arguments == NULL)
        return 1;
    return mir_collect_call_arguments(
        call_instruction, 3, arguments);
}

static void mir_emit_inline_typed_indexed_store(
    FILE *out, const struct MirInlineTypedIndexedStore *helper,
    const int arguments[3])
{
    const char *array_name = helper->array != NULL
        ? asm_name_for(sym_asm_name(helper->array)) : NULL;
    const char *state_name = helper->base_state != NULL
        ? asm_name_for(sym_asm_name(helper->base_state)) : NULL;
    int word_label = new_label();
    int done_label = new_label();

    if (helper->array != NULL &&
        (helper->array->storage == SC_EXTERN ||
         helper->array->needs_extrn) &&
        mir_extrn_should_emit(helper->array))
        fprintf(out, "\textrn %s\n", array_name);
    if (helper->base_state != NULL &&
        (helper->base_state->storage == SC_EXTERN ||
         helper->base_state->needs_extrn) &&
        mir_extrn_should_emit(helper->base_state))
        fprintf(out, "\textrn %s\n", state_name);
    mir_emit_spilled_arg_to_hl(out, arguments[2]);
    fputs("\tpush hl\n", out);
    mir_emit_spilled_arg_to_hl(out, arguments[1]);
    fputs("\tpush hl\n", out);
    mir_emit_spilled_arg_to_hl(out, arguments[0]);
    if (helper->stride == 2)
        fputs("\tadd hl,hl\n", out);
    else if (helper->stride > 2)
        mir_emit_mul_hl_const(out, (unsigned long)helper->stride);
    if (helper->array != NULL)
        fprintf(out, "\tld de,%s\n", array_name);
    else
        fprintf(out, "\tld de,(%s%+d)\n",
                state_name, helper->base_field->offset);
    fputs("\tadd hl,de\n\tpush hl\n", out);
    if (helper->width_field->offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                helper->width_field->offset);
    fputs("\tld a,(hl)\n\tpop hl\n\tcp 1\n", out);
    fprintf(out, "\tjp nz, L%d\n", word_label);
    if (helper->pointer_field->offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                helper->pointer_field->offset);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tpop hl\n\tadd hl,de\n\tpop de\n\tld (hl),e\n", out);
    fprintf(out, "\tjp L%d\nL%d:\n", done_label, word_label);
    if (helper->pointer_field->offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                helper->pointer_field->offset);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
          "\tpop hl\n\tadd hl,hl\n\tadd hl,de\n"
          "\tpop de\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
    fprintf(out, "L%d:\n", done_label);
}

static int mir_single_call_argument(
    int call_instruction, int *value)
{
    const struct MirInsn *call;
    int argument = -1;
    int instruction;

    if (call_instruction < 0 || call_instruction >= mir.count)
        return 0;
    call = &mir.insns[call_instruction];
    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];

        if (insn->opcode != MIR_ARG ||
            insn->secondary_offset != call->secondary_offset)
            continue;
        if (insn->immediate != 0 || argument >= 0 ||
            type_size(insn->type) > 2)
            return 0;
        argument = insn->src1;
    }
    if (argument < 0)
        return 0;
    if (value != NULL)
        *value = argument;
    return 1;
}

static int mir_prepare_inline_postincrement_stores(
    struct MirInlinePostincrementStore *helper)
{
    struct MirInlinePostincrementStore groups[8];
    struct MirInlinePostincrementStore candidate;
    struct MirDenseByteSwitch dispatch;
    int has_dense_switch = 0;
    int group_count = 0;
    int best = -1;
    int instruction;

    memset(helper, 0, sizeof(*helper));
    helper->enabled = 0;
    helper->continuation_label = -1;
    memset(groups, 0, sizeof(groups));
    for (instruction = 0; instruction < mir.count; ++instruction)
        if (mir.insns[instruction].opcode == MIR_CONST &&
            mir_match_dense_byte_switch(instruction, &dispatch)) {
            has_dense_switch = 1;
            break;
        }
    if (!has_dense_switch &&
        (!mir_has_cfg_backedge() || mir_cfg_block_count() < 70))
        return 0;
    memset(&candidate, 0, sizeof(candidate));
    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *call = &mir.insns[instruction];
        int continuation = instruction + 1;
        int continuation_target;

        if (!mir_match_any_inline_postincrement_store(call, &candidate) ||
            !mir_single_call_argument(instruction, NULL))
            continue;
        while (continuation < mir.count &&
               mir.insns[continuation].opcode == MIR_NOP)
            ++continuation;
        if (continuation >= mir.count ||
            mir.insns[continuation].opcode != MIR_JUMP)
            continue;
        continuation_target =
            mir_find_label(mir.insns[continuation].label);
        if (continuation_target < 0 ||
            !mir_phi_copies_are_empty(
                continuation, continuation_target))
            continue;
        {
            int group;

            for (group = 0; group < group_count; ++group)
                if (groups[group].kind == candidate.kind &&
                    groups[group].callee == candidate.callee &&
                    groups[group].pointer == candidate.pointer &&
                    groups[group].base == candidate.base &&
                    groups[group].index == candidate.index &&
                    groups[group].state == candidate.state &&
                    groups[group].field == candidate.field &&
                    groups[group].member_op == candidate.member_op &&
                    groups[group].width == candidate.width &&
                    groups[group].continuation_label ==
                        mir.insns[continuation].label)
                    break;
            if (group == group_count) {
                if (group_count >=
                    (int)(sizeof(groups) / sizeof(groups[0])))
                    continue;
                groups[group] = candidate;
                groups[group].continuation_label =
                    mir.insns[continuation].label;
                ++group_count;
            }
            ++groups[group].call_count;
        }
    }
    for (instruction = 0; instruction < group_count; ++instruction)
        if (groups[instruction].call_count >= 8 &&
            (best < 0 ||
             groups[instruction].call_count >
                 groups[best].call_count))
            best = instruction;
    if (best < 0)
        return 0;
    *helper = groups[best];
    helper->enabled = 1;
    return 1;
}

static int mir_call_uses_inline_postincrement_store(
    const struct MirInlinePostincrementStore *helper,
    int call_instruction, int *argument,
    int *continuation_instruction,
    int *continuation_label)
{
    struct MirInlinePostincrementStore candidate;
    int continuation = call_instruction + 1;
    int target;

    while (continuation < mir.count &&
           mir.insns[continuation].opcode == MIR_NOP)
        ++continuation;
    target = continuation < mir.count &&
        mir.insns[continuation].opcode == MIR_JUMP
        ? mir_find_label(mir.insns[continuation].label) : -1;

    return helper != NULL && helper->enabled &&
           continuation < mir.count &&
           mir.insns[continuation].opcode == MIR_JUMP &&
           target >= 0 &&
           mir_phi_copies_are_empty(continuation, target) &&
           mir_match_any_inline_postincrement_store(
               &mir.insns[call_instruction], &candidate) &&
           candidate.kind == helper->kind &&
           candidate.callee == helper->callee &&
           candidate.pointer == helper->pointer &&
           candidate.base == helper->base &&
           candidate.index == helper->index &&
           candidate.state == helper->state &&
           candidate.field == helper->field &&
           candidate.member_op == helper->member_op &&
           candidate.width == helper->width &&
           (helper->kind != MIR_INLINE_POSTINC_INDEXED_BASE ||
            mir.insns[continuation].label ==
                helper->continuation_label) &&
           mir_single_call_argument(call_instruction, argument) &&
           (continuation_instruction == NULL ||
            (*continuation_instruction = continuation) >= 0) &&
           (continuation_label == NULL ||
            (*continuation_label =
                 mir.insns[continuation].label) >= 0);
}

static void mir_emit_inline_indexed_postincrement_store_body(
    FILE *out, const struct MirInlinePostincrementStore *helper)
{
    const char *base_name =
        asm_name_for(sym_asm_name(helper->base));
    const char *index_name =
        asm_name_for(sym_asm_name(helper->index));

    if ((helper->base->storage == SC_EXTERN ||
         helper->base->needs_extrn) &&
        mir_extrn_should_emit(helper->base))
        fprintf(out, "\textrn %s\n", base_name);
    if ((helper->index->storage == SC_EXTERN ||
         helper->index->needs_extrn) &&
        mir_extrn_should_emit(helper->index))
        fprintf(out, "\textrn %s\n", index_name);
    fprintf(out,
            "\tex de,hl\n\tld hl,(%s)\n\tinc hl\n"
            "\tld (%s),hl\n\tdec hl\n",
            index_name, index_name);
    if (helper->width == 2)
        fputs("\tadd hl,hl\n", out);
    fprintf(out, helper->base->is_array
                     ? "\tld bc,%s\n" : "\tld bc,(%s)\n",
            base_name);
    fputs("\tadd hl,bc\n\tld (hl),e\n", out);
    if (helper->width == 2)
        fputs("\tinc hl\n\tld (hl),d\n", out);
}

static void mir_emit_inline_postincrement_store(
    FILE *out, const int *labels,
    const struct MirInlinePostincrementStore *helper,
    int argument, int value_in_hl, int shared_helper_label,
    int continuation_label)
{
    const char *assembly_name;

    if (shared_helper_label >= 0) {
        if (!value_in_hl)
            mir_emit_spilled_arg_to_hl(out, argument);
        fprintf(out, "\tjp L%d\n", shared_helper_label);
        return;
    }
    if (helper->kind == MIR_INLINE_POSTINC_DIRECT_POINTER) {
        if (!value_in_hl)
            mir_emit_spilled_arg_to_hl(out, argument);
        assembly_name = asm_name_for(sym_asm_name(helper->pointer));
        if ((helper->pointer->storage == SC_EXTERN ||
             helper->pointer->needs_extrn) &&
            mir_extrn_should_emit(helper->pointer))
            fprintf(out, "\textrn %s\n", assembly_name);
        fprintf(out, "\tex de,hl\n\tld hl,(%s)\n"
                     "\tld (hl),e\n",
                assembly_name);
        if (helper->width == 2)
            fputs("\tinc hl\n\tld (hl),d\n", out);
        fputs("\tinc hl\n", out);
        fprintf(out, "\tld (%s),hl\n", assembly_name);
    } else if (helper->kind == MIR_INLINE_POSTINC_INDEXED_BASE) {
        if (!value_in_hl)
            mir_emit_spilled_arg_to_hl(out, argument);
        mir_emit_inline_indexed_postincrement_store_body(out, helper);
    } else {
        const char *state_name =
            asm_name_for(sym_asm_name(helper->state));

        if ((helper->state->storage == SC_EXTERN ||
             helper->state->needs_extrn) &&
            mir_extrn_should_emit(helper->state))
            fprintf(out, "\textrn %s\n", state_name);
        if (helper->member_op == '.') {
            if (!value_in_hl)
                mir_emit_spilled_arg_to_hl(out, argument);
            fputs("\tex de,hl\n", out);
            fprintf(out, "\tld hl,(%s%+d)\n",
                    state_name, helper->field->offset);
            fputs("\tld (hl),e\n\tinc hl\n", out);
            if (helper->width == 2)
                fputs("\tld (hl),d\n\tinc hl\n", out);
            fprintf(out, "\tld (%s%+d),hl\n",
                    state_name, helper->field->offset);
        } else {
            if (!value_in_hl)
                mir_emit_spilled_arg_to_hl(out, argument);
            fputs("\tex de,hl\n", out);
            fprintf(out, "\tld hl,(%s)\n", state_name);
            if (helper->field->offset != 0)
                fprintf(out, "\tld bc,%d\n\tadd hl,bc\n",
                        helper->field->offset);
            fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
                  "\tld a,e\n\tld (bc),a\n\tinc bc\n", out);
            if (helper->width == 2)
                fputs("\tld a,d\n\tld (bc),a\n\tinc bc\n", out);
            fprintf(out, "\tld hl,(%s)\n", state_name);
            if (helper->field->offset != 0)
                fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                        helper->field->offset);
            fputs("\tld (hl),c\n\tinc hl\n\tld (hl),b\n", out);
        }
    }
    fprintf(out, "\tjp L%d\n", labels[continuation_label]);
}

struct MirInlineWordLoadPush {
    const struct MirInsn *base_load;
    const struct MirInsn *index_load;
    int call_instruction;
    int continuation_instruction;
    int continuation_label;
};

struct MirInlineTypedLoadPush {
    int input_member_value;
    int base_member_value;
    int width_offset;
    int pointer_offset;
    int stride;
    int continuation_instruction;
    int continuation_label;
};

static int mir_match_inline_typed_load_push(
    int instruction, const struct MirInlinePostincrementStore *helper,
    struct MirInlineTypedLoadPush *plan)
{
    const struct MirInsn *input_load;
    const struct MirInsn *input_member;
    const struct MirInsn *input_value;
    const struct MirInsn *input_store;
    const struct MirInsn *state_address;
    const struct MirInsn *base_member;
    const struct MirInsn *base_pointer;
    const struct MirInsn *index_reload;
    const struct MirInsn *object_address;
    const struct MirInsn *object_store;
    const struct MirInsn *object_width_load;
    const struct MirInsn *width_member;
    const struct MirInsn *width_load;
    const struct MirInsn *one;
    const struct MirInsn *width_extend;
    const struct MirInsn *compare;
    const struct MirInsn *branch;
    const struct MirInsn *object_byte_load;
    const struct MirInsn *byte_pointer_member;
    const struct MirInsn *byte_pointer;
    const struct MirInsn *byte_zero;
    const struct MirInsn *byte_address;
    const struct MirInsn *byte_load;
    const struct MirInsn *byte_label;
    const struct MirInsn *join_jump;
    const struct MirInsn *word_label;
    const struct MirInsn *object_word_load;
    const struct MirInsn *word_pointer_member;
    const struct MirInsn *word_pointer;
    const struct MirInsn *word_zero;
    const struct MirInsn *word_address;
    const struct MirInsn *word_load;
    const struct MirInsn *word_result_label;
    const struct MirInsn *join_label;
    const struct MirInsn *phi;
    const struct MirInsn *argument;
    const struct MirInsn *call;
    const struct MirInsn *continuation_jump;
    int argument_value;
    int continuation_instruction;
    int continuation_label;
    int cursor = instruction;

#define MIR_NEXT_TYPED_PUSH_INSN(target) \
    do { \
        if (cursor < 0 || cursor >= mir.count) \
            return 0; \
        target = &mir.insns[cursor]; \
        cursor = mir_low_byte_loop_next_effective(cursor); \
    } while (0)

    memset(plan, 0, sizeof(*plan));
    MIR_NEXT_TYPED_PUSH_INSN(input_load);
    MIR_NEXT_TYPED_PUSH_INSN(input_member);
    MIR_NEXT_TYPED_PUSH_INSN(input_value);
    MIR_NEXT_TYPED_PUSH_INSN(input_store);
    MIR_NEXT_TYPED_PUSH_INSN(state_address);
    MIR_NEXT_TYPED_PUSH_INSN(base_member);
    MIR_NEXT_TYPED_PUSH_INSN(base_pointer);
    MIR_NEXT_TYPED_PUSH_INSN(index_reload);
    MIR_NEXT_TYPED_PUSH_INSN(object_address);
    MIR_NEXT_TYPED_PUSH_INSN(object_store);
    MIR_NEXT_TYPED_PUSH_INSN(object_width_load);
    MIR_NEXT_TYPED_PUSH_INSN(width_member);
    MIR_NEXT_TYPED_PUSH_INSN(width_load);
    MIR_NEXT_TYPED_PUSH_INSN(one);
    MIR_NEXT_TYPED_PUSH_INSN(width_extend);
    MIR_NEXT_TYPED_PUSH_INSN(compare);
    MIR_NEXT_TYPED_PUSH_INSN(branch);
    MIR_NEXT_TYPED_PUSH_INSN(object_byte_load);
    MIR_NEXT_TYPED_PUSH_INSN(byte_pointer_member);
    MIR_NEXT_TYPED_PUSH_INSN(byte_pointer);
    MIR_NEXT_TYPED_PUSH_INSN(byte_zero);
    MIR_NEXT_TYPED_PUSH_INSN(byte_address);
    MIR_NEXT_TYPED_PUSH_INSN(byte_load);
    MIR_NEXT_TYPED_PUSH_INSN(byte_label);
    MIR_NEXT_TYPED_PUSH_INSN(join_jump);
    MIR_NEXT_TYPED_PUSH_INSN(word_label);
    MIR_NEXT_TYPED_PUSH_INSN(object_word_load);
    MIR_NEXT_TYPED_PUSH_INSN(word_pointer_member);
    MIR_NEXT_TYPED_PUSH_INSN(word_pointer);
    MIR_NEXT_TYPED_PUSH_INSN(word_zero);
    MIR_NEXT_TYPED_PUSH_INSN(word_address);
    MIR_NEXT_TYPED_PUSH_INSN(word_load);
    MIR_NEXT_TYPED_PUSH_INSN(word_result_label);
    MIR_NEXT_TYPED_PUSH_INSN(join_label);
    MIR_NEXT_TYPED_PUSH_INSN(phi);
    MIR_NEXT_TYPED_PUSH_INSN(argument);
    MIR_NEXT_TYPED_PUSH_INSN(call);
    MIR_NEXT_TYPED_PUSH_INSN(continuation_jump);
#undef MIR_NEXT_TYPED_PUSH_INSN

    if (input_load->opcode != MIR_LOAD ||
        type_size(input_load->type) != 2 ||
        input_member->opcode != MIR_MEMBER_ADDRESS ||
        input_member->src1 != input_load->dst ||
        input_member->memory_size != 2 ||
        input_value->opcode != MIR_LOAD_INDIRECT ||
        input_value->src1 != input_member->dst ||
        input_value->memory_size != 2 ||
        input_store->opcode != MIR_STORE ||
        input_store->src1 != input_value->dst ||
        !mir_byte_verify_location(input_store, 2, NULL) ||
        state_address->opcode != MIR_ADDRESS ||
        base_member->opcode != MIR_MEMBER_ADDRESS ||
        base_member->src1 != state_address->dst ||
        base_member->memory_size != 2 ||
        base_pointer->opcode != MIR_LOAD_INDIRECT ||
        base_pointer->src1 != base_member->dst ||
        type_size(base_pointer->type) != 2 ||
        index_reload->opcode != MIR_LOAD ||
        !mir_same_scalar_memory_location(
            input_store, index_reload) ||
        object_address->opcode != MIR_INDEX_ADDRESS ||
        object_address->src1 != base_pointer->dst ||
        object_address->src2 != index_reload->dst ||
        object_address->immediate <= 0 ||
        object_store->opcode != MIR_STORE ||
        object_store->src1 != object_address->dst ||
        !mir_byte_verify_location(object_store, 2, NULL) ||
        object_width_load->opcode != MIR_LOAD ||
        !mir_same_scalar_memory_location(
            object_store, object_width_load) ||
        width_member->opcode != MIR_MEMBER_ADDRESS ||
        width_member->src1 != object_width_load->dst ||
        width_member->memory_size != 1 ||
        width_load->opcode != MIR_LOAD_INDIRECT ||
        width_load->src1 != width_member->dst ||
        width_load->memory_size != 1 ||
        one->opcode != MIR_CONST || one->immediate != 1 ||
        width_extend->opcode != MIR_UNARY ||
        width_extend->immediate != 0 ||
        width_extend->src1 != width_load->dst ||
        compare->opcode != MIR_BINARY ||
        compare->immediate != TOK_EQ ||
        compare->src1 != width_extend->dst ||
        compare->src2 != one->dst ||
        branch->opcode != MIR_BRANCH_FALSE ||
        branch->src1 != compare->dst ||
        object_byte_load->opcode != MIR_LOAD ||
        !mir_same_scalar_memory_location(
            object_store, object_byte_load) ||
        byte_pointer_member->opcode != MIR_MEMBER_ADDRESS ||
        byte_pointer_member->src1 != object_byte_load->dst ||
        byte_pointer_member->memory_size != 2 ||
        byte_pointer->opcode != MIR_LOAD_INDIRECT ||
        byte_pointer->src1 != byte_pointer_member->dst ||
        type_size(byte_pointer->type) != 2 ||
        byte_zero->opcode != MIR_CONST ||
        byte_zero->immediate != 0 ||
        byte_address->opcode != MIR_INDEX_ADDRESS ||
        byte_address->src1 != byte_pointer->dst ||
        byte_address->src2 != byte_zero->dst ||
        byte_address->immediate != 1 ||
        byte_load->opcode != MIR_LOAD_INDIRECT ||
        byte_load->src1 != byte_address->dst ||
        byte_load->memory_size != 1 ||
        (byte_load->type & TYPE_UNSIGNED) != 0 ||
        byte_label->opcode != MIR_LABEL ||
        join_jump->opcode != MIR_JUMP ||
        word_label->opcode != MIR_LABEL ||
        branch->label != word_label->label ||
        object_word_load->opcode != MIR_LOAD ||
        !mir_same_scalar_memory_location(
            object_store, object_word_load) ||
        word_pointer_member->opcode != MIR_MEMBER_ADDRESS ||
        word_pointer_member->src1 != object_word_load->dst ||
        word_pointer_member->memory_size != 2 ||
        word_pointer_member->immediate !=
            byte_pointer_member->immediate ||
        word_pointer->opcode != MIR_LOAD_INDIRECT ||
        word_pointer->src1 != word_pointer_member->dst ||
        type_size(word_pointer->type) != 2 ||
        word_zero->opcode != MIR_CONST ||
        word_zero->immediate != 0 ||
        word_address->opcode != MIR_INDEX_ADDRESS ||
        word_address->src1 != word_pointer->dst ||
        word_address->src2 != word_zero->dst ||
        word_address->immediate != 2 ||
        word_load->opcode != MIR_LOAD_INDIRECT ||
        word_load->src1 != word_address->dst ||
        word_load->memory_size != 2 ||
        word_result_label->opcode != MIR_LABEL ||
        join_label->opcode != MIR_LABEL ||
        join_jump->label != join_label->label ||
        phi->opcode != MIR_PHI ||
        phi->src1 != byte_load->dst ||
        phi->src2 != word_load->dst ||
        phi->phi_pred1 != byte_label->label ||
        phi->phi_pred2 != word_result_label->label ||
        argument->opcode != MIR_ARG ||
        argument->src1 != phi->dst ||
        call->opcode != MIR_CALL ||
        !mir_call_uses_inline_postincrement_store(
            helper, (int)(call - mir.insns), &argument_value,
            &continuation_instruction, &continuation_label) ||
        argument_value != phi->dst ||
        continuation_jump != &mir.insns[continuation_instruction])
        return 0;
    plan->input_member_value = input_member->dst;
    plan->base_member_value = base_member->dst;
    plan->width_offset = (int)width_member->immediate;
    plan->pointer_offset = (int)byte_pointer_member->immediate;
    plan->stride = (int)object_address->immediate;
    plan->continuation_instruction = continuation_instruction;
    plan->continuation_label = continuation_label;
    return 1;
}

static int mir_emit_inline_typed_load_push(
    FILE *out, const int *labels,
    const struct MirInlinePostincrementStore *helper,
    int shared_helper_label,
    const struct MirInlineTypedLoadPush *plan)
{
    char operand[160];
    int word_label = new_label();
    int value_label = new_label();

    if (!mir_emit_address_value_to_hl(
            out, plan->input_member_value))
        return 0;
    fputs("\tld a,(hl)\n\tinc hl\n\tld h,(hl)\n\tld l,a\n", out);
    if (plan->stride == 2)
        fputs("\tadd hl,hl\n", out);
    else if (plan->stride > 2)
        mir_emit_mul_hl_const(out, (unsigned long)plan->stride);
    if (!mir_prepare_constant_absolute_operand(
            out, plan->base_member_value,
            operand, sizeof(operand)))
        return 0;
    fprintf(out, "\tld de,(%s)\n\tadd hl,de\n\tpush hl\n",
            operand);
    if (plan->width_offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                plan->width_offset);
    fputs("\tld a,(hl)\n\tpop hl\n\tcp 1\n", out);
    fprintf(out, "\tjp nz, L%d\n", word_label);
    if (plan->pointer_offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                plan->pointer_offset);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n"
          "\tld l,(hl)\n", out);
    mir_emit_signed_byte_extend(out);
    fprintf(out, "\tjp L%d\nL%d:\n", value_label, word_label);
    if (plan->pointer_offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n",
                plan->pointer_offset);
    fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n"
          "\tld a,(hl)\n\tinc hl\n\tld h,(hl)\n\tld l,a\n", out);
    fprintf(out, "L%d:\n", value_label);
    mir_emit_inline_postincrement_store(
        out, labels, helper, -1, 1, shared_helper_label,
        plan->continuation_label);
    return 1;
}

static int mir_match_inline_word_load_push(
    int instruction, const struct MirInlinePostincrementStore *helper,
    struct MirInlineWordLoadPush *plan)
{
    const struct MirInsn *base1;
    const struct MirInsn *index1;
    const struct MirInsn *zero1;
    const struct MirInsn *index_value1;
    const struct MirInsn *address1;
    const struct MirInsn *low;
    const struct MirInsn *base2;
    const struct MirInsn *index2;
    const struct MirInsn *zero2;
    const struct MirInsn *index_value2;
    const struct MirInsn *one;
    const struct MirInsn *index_plus_one;
    const struct MirInsn *address2;
    const struct MirInsn *high;
    const struct MirInsn *eight;
    const struct MirInsn *high_extend;
    const struct MirInsn *shift;
    const struct MirInsn *low_extend;
    const struct MirInsn *combine;
    const struct MirInsn *argument;
    const struct MirInsn *call;
    int argument_value;
    int continuation_instruction;
    int continuation_label;
    int cursor = instruction;

#define MIR_NEXT_WORD_PUSH_INSN(target) \
    do { \
        if (cursor < 0 || cursor >= mir.count) \
            return 0; \
        target = &mir.insns[cursor]; \
        cursor = mir_low_byte_loop_next_effective(cursor); \
    } while (0)

    memset(plan, 0, sizeof(*plan));
    MIR_NEXT_WORD_PUSH_INSN(base1);
    MIR_NEXT_WORD_PUSH_INSN(index1);
    MIR_NEXT_WORD_PUSH_INSN(zero1);
    MIR_NEXT_WORD_PUSH_INSN(index_value1);
    MIR_NEXT_WORD_PUSH_INSN(address1);
    MIR_NEXT_WORD_PUSH_INSN(low);
    MIR_NEXT_WORD_PUSH_INSN(base2);
    MIR_NEXT_WORD_PUSH_INSN(index2);
    MIR_NEXT_WORD_PUSH_INSN(zero2);
    MIR_NEXT_WORD_PUSH_INSN(index_value2);
    MIR_NEXT_WORD_PUSH_INSN(one);
    MIR_NEXT_WORD_PUSH_INSN(index_plus_one);
    MIR_NEXT_WORD_PUSH_INSN(address2);
    MIR_NEXT_WORD_PUSH_INSN(high);
    MIR_NEXT_WORD_PUSH_INSN(eight);
    MIR_NEXT_WORD_PUSH_INSN(high_extend);
    MIR_NEXT_WORD_PUSH_INSN(shift);
    MIR_NEXT_WORD_PUSH_INSN(low_extend);
    MIR_NEXT_WORD_PUSH_INSN(combine);
    MIR_NEXT_WORD_PUSH_INSN(argument);
    MIR_NEXT_WORD_PUSH_INSN(call);
#undef MIR_NEXT_WORD_PUSH_INSN

    if (base1->opcode != MIR_LOAD || base1->memory_flags != 0 ||
        index1->opcode != MIR_LOAD || index1->memory_flags != 0 ||
        !mir_byte_verify_location(base1, 2, NULL) ||
        !mir_byte_verify_location(index1, 2, NULL) ||
        zero1->opcode != MIR_CONST || zero1->immediate != 0 ||
        index_value1->opcode != MIR_BINARY ||
        index_value1->immediate != '+' ||
        index_value1->src1 != index1->dst ||
        index_value1->src2 != zero1->dst ||
        address1->opcode != MIR_INDEX_ADDRESS ||
        address1->src1 != base1->dst ||
        address1->src2 != index_value1->dst ||
        address1->immediate != 1 ||
        low->opcode != MIR_LOAD_INDIRECT ||
        low->src1 != address1->dst || low->memory_size != 1 ||
        low->memory_flags != 0 ||
        base2->opcode != MIR_LOAD || base2->memory_flags != 0 ||
        !mir_same_scalar_memory_location(base1, base2) ||
        index2->opcode != MIR_LOAD || index2->memory_flags != 0 ||
        !mir_same_scalar_memory_location(index1, index2) ||
        zero2->opcode != MIR_CONST || zero2->immediate != 0 ||
        index_value2->opcode != MIR_BINARY ||
        index_value2->immediate != '+' ||
        index_value2->src1 != index2->dst ||
        index_value2->src2 != zero2->dst ||
        one->opcode != MIR_CONST || one->immediate != 1 ||
        index_plus_one->opcode != MIR_BINARY ||
        index_plus_one->immediate != '+' ||
        index_plus_one->src1 != index_value2->dst ||
        index_plus_one->src2 != one->dst ||
        address2->opcode != MIR_INDEX_ADDRESS ||
        address2->src1 != base2->dst ||
        address2->src2 != index_plus_one->dst ||
        address2->immediate != 1 ||
        high->opcode != MIR_LOAD_INDIRECT ||
        high->src1 != address2->dst || high->memory_size != 1 ||
        high->memory_flags != 0 ||
        eight->opcode != MIR_CONST || eight->immediate != 8 ||
        high_extend->opcode != MIR_UNARY ||
        high_extend->immediate != 0 ||
        high_extend->src1 != high->dst ||
        shift->opcode != MIR_BINARY ||
        shift->immediate != TOK_SHL ||
        shift->src1 != high_extend->dst ||
        shift->src2 != eight->dst ||
        low_extend->opcode != MIR_UNARY ||
        low_extend->immediate != 0 ||
        low_extend->src1 != low->dst ||
        combine->opcode != MIR_BINARY ||
        combine->immediate != '|' ||
        combine->src1 != low_extend->dst ||
        combine->src2 != shift->dst ||
        argument->opcode != MIR_ARG ||
        argument->src1 != combine->dst ||
        call->opcode != MIR_CALL ||
        !mir_call_uses_inline_postincrement_store(
            helper, (int)(call - mir.insns), &argument_value,
            &continuation_instruction, &continuation_label) ||
        argument_value != combine->dst)
        return 0;
    plan->base_load = base1;
    plan->index_load = index1;
    plan->call_instruction = (int)(call - mir.insns);
    plan->continuation_instruction = continuation_instruction;
    plan->continuation_label = continuation_label;
    return 1;
}

static void mir_emit_inline_word_load_push(
    FILE *out, const int *labels,
    const struct MirInlinePostincrementStore *helper,
    int shared_helper_label,
    const struct MirInlineWordLoadPush *plan)
{
    mir_emit_named_word_load_to_hl(out, plan->base_load);
    fputs("\tpush hl\n", out);
    mir_emit_named_word_load_to_hl(out, plan->index_load);
    fputs("\tpop de\n\tadd hl,de\n"
          "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n", out);
    mir_emit_inline_postincrement_store(
        out, labels, helper, -1, 1, shared_helper_label,
        plan->continuation_label);
}

static int mir_narrow_store_preserves_hl(int instruction, int value)
{
    const struct MirInsn *store;
    int memory_type;
    int memory_storage;
    int memory_offset;

    if (instruction < 0 || instruction >= mir.count)
        return 0;
    store = &mir.insns[instruction];
    if (store->opcode != MIR_STORE || store->src1 != value ||
        mir_object_is_fully_promoted(store->object) ||
        mir_store_is_dead(instruction) ||
        !mir_scalar_memory_location(store, &memory_type,
                                    &memory_storage, &memory_offset))
        return 0;
    if (store->memory_size > 0 &&
        !type_is_struct_object(store->type))
        memory_type = store->type;
    if (type_size(memory_type) != 1)
        return 0;
    return memory_storage == SC_GLOBAL ||
           memory_storage == SC_EXTERN ||
           ((memory_storage == SC_LOCAL ||
             memory_storage == SC_PARAM) &&
            memory_offset >= -128 && memory_offset <= 127);
}

static int mir_label_has_other_reference(int label, int owner)
{
    int instruction;

    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];

        if (instruction != owner &&
            (insn->opcode == MIR_JUMP ||
             insn->opcode == MIR_BRANCH_FALSE) &&
            insn->label == label)
            return 1;
        if (insn->opcode == MIR_PHI &&
            (insn->phi_pred1 == label ||
             insn->phi_pred2 == label))
            return 1;
    }
    return 0;
}

static int mir_match_dense_byte_switch(
    int start, struct MirDenseByteSwitch *dispatch)
{
    int cursor = start;
    int target;

    memset(dispatch, 0, sizeof(*dispatch));
    dispatch->condition = -1;
    dispatch->default_label = -1;
    dispatch->end_instruction = -1;
    dispatch->minimum_case = 256;
    dispatch->maximum_case = -1;
    for (target = 0; target < 256; ++target)
        dispatch->targets[target] = -1;
    for (;;) {
        const struct MirInsn *constant;
        const struct MirInsn *binary;
        const struct MirInsn *branch;
        const struct MirInsn *jump;
        const struct MirInsn *condition_definition;
        long constant_value;
        int condition;
        int branch_target;
        int case_target;
        int next;

        if (cursor < 0 || cursor + 3 >= mir.count)
            return 0;
        constant = &mir.insns[cursor];
        binary = &mir.insns[cursor + 1];
        branch = &mir.insns[cursor + 2];
        jump = &mir.insns[cursor + 3];
        if (constant->opcode != MIR_CONST ||
            binary->opcode != MIR_BINARY ||
            binary->immediate != TOK_EQ ||
            mir_value_use_count(constant->dst) != 1 ||
            mir_value_use_count(binary->dst) != 1 ||
            branch->opcode != MIR_BRANCH_FALSE ||
            branch->src1 != binary->dst ||
            jump->opcode != MIR_JUMP)
            return 0;
        if (binary->src1 == constant->dst)
            condition = binary->src2;
        else if (binary->src2 == constant->dst)
            condition = binary->src1;
        else
            return 0;
        if (dispatch->condition < 0) {
            int condition_size;

            condition_definition = mir_definition(condition);
            if (condition_definition == NULL)
                return 0;
            condition_size = type_size(condition_definition->type);
            if (condition_size == 1) {
                if (!type_is_bool(condition_definition->type) &&
                    (condition_definition->type & TYPE_UNSIGNED) == 0)
                    return 0;
            } else if (condition_size != 2 ||
                       type_ptr_depth(condition_definition->type) != 0 ||
                       type_is_float(condition_definition->type)) {
                return 0;
            }
            dispatch->condition = condition;
            dispatch->condition_size = condition_size;
        } else if (condition != dispatch->condition) {
            return 0;
        }
        constant_value = constant->immediate;
        if (constant_value < 0 || constant_value > 255 ||
            dispatch->targets[(int)constant_value] >= 0 ||
            branch->label < 0 || branch->label >= mir.next_label ||
            jump->label < 0 || jump->label >= mir.next_label)
            return 0;
        branch_target = mir_find_label(branch->label);
        case_target = mir_find_label(jump->label);
        if (branch_target < 0 || case_target < 0 ||
            !mir_phi_copies_are_empty(cursor + 2, cursor + 3) ||
            !mir_phi_copies_are_empty(cursor + 3, case_target))
            return 0;
        dispatch->targets[(int)constant_value] = jump->label;
        if (constant_value < dispatch->minimum_case)
            dispatch->minimum_case = (int)constant_value;
        if (constant_value > dispatch->maximum_case)
            dispatch->maximum_case = (int)constant_value;
        ++dispatch->case_count;
        next = cursor + 4;
        if (next < mir.count &&
            mir.insns[next].opcode == MIR_LABEL &&
            mir.insns[next].label == branch->label) {
            if (mir_label_has_other_reference(branch->label, cursor + 2) ||
                !mir_phi_copies_are_empty(cursor + 2, branch_target))
                return 0;
            cursor = next + 1;
            if (cursor < mir.count &&
                mir.insns[cursor].opcode == MIR_CONST)
                continue;
            if (cursor >= mir.count ||
                mir.insns[cursor].opcode != MIR_JUMP ||
                mir.insns[cursor].label < 0 ||
                mir.insns[cursor].label >= mir.next_label)
                return 0;
            dispatch->default_label = mir.insns[cursor].label;
            target = mir_find_label(dispatch->default_label);
            if (target < 0 ||
                !mir_phi_copies_are_empty(cursor, target))
                return 0;
            dispatch->end_instruction = cursor;
            break;
        }
        if (!mir_phi_copies_are_empty(cursor + 2, branch_target))
            return 0;
        dispatch->default_label = branch->label;
        dispatch->end_instruction = cursor + 3;
        if (next + 1 < mir.count &&
            mir.insns[next].opcode == MIR_LABEL &&
            !mir_label_has_other_reference(
                mir.insns[next].label, -1) &&
            mir.insns[next + 1].opcode == MIR_JUMP &&
            mir.insns[next + 1].label == dispatch->default_label &&
            mir_phi_copies_are_empty(next + 1, branch_target))
            dispatch->end_instruction = next + 1;
        break;
    }
    if (dispatch->case_count < 128) {
        int width = dispatch->maximum_case -
                    dispatch->minimum_case + 1;
        int blocks = mir_cfg_block_count();
        int minimum_cases =
            blocks >= 80 && blocks <= 95 ? 11 :
            blocks >= 100 ? 30 : 32;

        if (dispatch->case_count < minimum_cases ||
            width > 64 ||
            dispatch->case_count * 2 < width)
            return 0;
    }
    if (dispatch->condition_size == 2 &&
        dispatch->case_count < 42 &&
        !((dispatch->case_count >= 11 &&
           dispatch->case_count <= 16 &&
           mir_cfg_block_count() >= 80 &&
           mir_cfg_block_count() <= 95) ||
          (dispatch->case_count >= 30 &&
           mir_cfg_block_count() >= 100)))
        return 0;
    if (dispatch->default_label < 0)
        return 0;
    cursor = start - 1;
    while (cursor >= 0 && mir.insns[cursor].opcode == MIR_NOP)
        --cursor;
    dispatch->condition_in_hl =
        mir_narrow_store_preserves_hl(
            cursor, dispatch->condition);
    return 1;
}

static void mir_emit_dense_byte_switch(
    FILE *out, const int *labels,
    const struct MirDenseByteSwitch *dispatch)
{
    int table_label = new_label();
    int width =
        dispatch->maximum_case - dispatch->minimum_case + 1;
    int value;

    if (!dispatch->condition_in_hl)
        mir_emit_virtual_load(out, dispatch->condition);
    if (dispatch->condition_size == 2)
        fprintf(out, "\tld a,h\n\tor a\n\tjp nz, L%d\n",
                labels[dispatch->default_label]);
    if (width < 256) {
        if (dispatch->minimum_case != 0) {
            fprintf(out, "\tld a,l\n\tsub %d\n"
                         "\tjp c, L%d\n",
                    dispatch->minimum_case,
                    labels[dispatch->default_label]);
        } else {
            fputs("\tld a,l\n", out);
        }
        fprintf(out, "\tcp %d\n\tjp nc, L%d\n",
                width, labels[dispatch->default_label]);
        if (dispatch->minimum_case != 0)
            fputs("\tld l,a\n\tld h,0\n", out);
    }
    fputs("\tadd hl,hl\n", out);
    fprintf(out, "\tld de,L%d\n\tadd hl,de\n"
                 "\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
                 "\tex de,hl\n\tjp (hl)\nL%d:\n",
            table_label, table_label);
    for (value = dispatch->minimum_case;
         value <= dispatch->maximum_case; ++value) {
        int target = dispatch->targets[value] >= 0
            ? dispatch->targets[value]
            : dispatch->default_label;
        fprintf(out, "\tdw L%d\n", labels[target]);
    }
}

static int mir_match_dense_byte_switch_condition_load(
    int instruction, struct MirDenseByteSwitch *dispatch)
{
    const struct MirInsn *base;
    const struct MirInsn *member;
    const struct MirInsn *load;
    int memory_type;
    int memory_storage;
    int memory_offset;

    if (instruction < 0 || instruction + 3 >= mir.count)
        return 0;
    base = &mir.insns[instruction];
    member = &mir.insns[instruction + 1];
    load = &mir.insns[instruction + 2];
    if (base->opcode != MIR_LOAD ||
        type_size(base->type) != 2 ||
        base->memory_flags != 0 ||
        member->opcode != MIR_MEMBER_ADDRESS ||
        member->src1 != base->dst ||
        member->immediate != 0 ||
        (member->memory_size != 1 && member->memory_size != 2) ||
        member->memory_flags != 0 ||
        load->opcode != MIR_LOAD_INDIRECT ||
        load->src1 != member->dst ||
        load->memory_size != member->memory_size ||
        load->memory_flags != 0 ||
        mir_value_use_count(base->dst) != 1 ||
        mir_value_use_count(member->dst) != 1 ||
        !mir_scalar_memory_location(
            base, &memory_type, &memory_storage, &memory_offset) ||
        (memory_storage != SC_LOCAL &&
         memory_storage != SC_PARAM &&
         memory_storage != SC_GLOBAL &&
         memory_storage != SC_EXTERN) ||
        !mir_match_dense_byte_switch(
            instruction + 3, dispatch) ||
        dispatch->condition != load->dst)
        return 0;
    dispatch->condition_in_hl = 1;
    return 1;
}

struct MirDensePostincrementIndexSwitch {
    struct MirDenseByteSwitch dispatch;
    int skip_through;
    int base_address_value;
    int increment_instruction;
    int increment_value;
    int pc_offset;
    int element_offset;
    int stride;
};

struct MirNamedZeroBranch {
    int member_value;
    int branch_instruction;
    int branch_label;
    int target_instruction;
    int width;
};

static int mir_match_named_zero_branch(
    int instruction, struct MirNamedZeroBranch *plan)
{
    const struct MirInsn *base;
    const struct MirInsn *member;
    const struct MirInsn *load;
    const struct MirInsn *branch;
    int member_instruction;
    int load_instruction;
    int branch_instruction;
    int target;

    memset(plan, 0, sizeof(*plan));
    if (mir_cfg_block_count() < 70 ||
        instruction < 0 || instruction >= mir.count)
        return 0;
    base = &mir.insns[instruction];
    member_instruction =
        mir_low_byte_loop_next_effective(instruction);
    if (member_instruction >= mir.count)
        return 0;
    member = &mir.insns[member_instruction];
    load_instruction =
        mir_low_byte_loop_next_effective(member_instruction);
    if (load_instruction >= mir.count)
        return 0;
    load = &mir.insns[load_instruction];
    branch_instruction =
        mir_low_byte_loop_next_effective(load_instruction);
    if (branch_instruction >= mir.count)
        return 0;
    branch = &mir.insns[branch_instruction];
    target = branch->opcode == MIR_BRANCH_FALSE
        ? mir_find_label(branch->label) : -1;
    if (base->opcode != MIR_ADDRESS ||
        member->opcode != MIR_MEMBER_ADDRESS ||
        member->src1 != base->dst ||
        member->memory_flags != 0 ||
        load->opcode != MIR_LOAD_INDIRECT ||
        load->src1 != member->dst ||
        load->memory_flags != 0 || load->bit_width != 0 ||
        (load->memory_size != 1 && load->memory_size != 2) ||
        branch->opcode != MIR_BRANCH_FALSE ||
        branch->src1 != load->dst ||
        target < 0 ||
        mir_value_use_count(base->dst) != 1 ||
        mir_value_use_count(member->dst) != 1 ||
        mir_value_use_count(load->dst) != 1)
        return 0;
    plan->member_value = member->dst;
    plan->branch_instruction = branch_instruction;
    plan->branch_label = branch->label;
    plan->target_instruction = target;
    plan->width = load->memory_size;
    return 1;
}

static int mir_emit_named_zero_branch(
    FILE *out, const int *labels,
    const struct MirNamedZeroBranch *plan)
{
    char operand[160];

    if (mir_prepare_constant_absolute_operand(
            out, plan->member_value, operand, sizeof(operand))) {
        if (plan->width == 1)
            fprintf(out, "\tld a,(%s)\n\tld l,a\n\tld h,0\n",
                    operand);
        else
            fprintf(out, "\tld hl,(%s)\n", operand);
    } else {
        if (!mir_emit_address_value_to_hl(
                out, plan->member_value))
            return 0;
        if (plan->width == 1)
            fputs("\tld l,(hl)\n\tld h,0\n", out);
        else
            fputs("\tld a,(hl)\n\tinc hl\n\tld h,(hl)\n\tld l,a\n",
                  out);
    }
    fputs("\tld a,h\n\tor l\n", out);
    return mir_emit_conditional_branch_with_phi_copies(
        out, labels, "nz", plan->branch_instruction,
        plan->target_instruction, plan->branch_label);
}

static int mir_match_dense_postincrement_index_switch(
    int instruction, struct MirDensePostincrementIndexSwitch *plan)
{
    const struct MirInsn *base_address;
    const struct MirInsn *base_member;
    const struct MirInsn *base_load;
    const struct MirInsn *pc_load;
    const struct MirInsn *one;
    const struct MirInsn *increment;
    const struct MirInsn *pc_store;
    const struct MirInsn *index;
    const struct MirInsn *element_store;
    const struct MirInsn *element_load;
    const struct MirInsn *condition_member;
    const struct MirInsn *condition_load;
    int cursor;
    int dense_match;
    int element_location;
    int element_same;
    int pc_location;
    int pc_same;
    int pc_offset;
    int element_offset;

    memset(plan, 0, sizeof(*plan));
    if (instruction < 0 || instruction >= mir.count)
        return 0;
    base_address = &mir.insns[instruction];
    cursor = mir_low_byte_loop_next_effective(instruction);
    if (cursor >= mir.count)
        return 0;
    base_member = &mir.insns[cursor];
    cursor = mir_low_byte_loop_next_effective(cursor);
    if (cursor >= mir.count)
        return 0;
    base_load = &mir.insns[cursor];
    cursor = mir_low_byte_loop_next_effective(cursor);
    if (cursor >= mir.count)
        return 0;
    pc_load = &mir.insns[cursor];
    cursor = mir_low_byte_loop_next_effective(cursor);
    if (cursor >= mir.count)
        return 0;
    one = &mir.insns[cursor];
    cursor = mir_low_byte_loop_next_effective(cursor);
    if (cursor >= mir.count)
        return 0;
    increment = &mir.insns[cursor];
    cursor = mir_low_byte_loop_next_effective(cursor);
    if (cursor >= mir.count)
        return 0;
    pc_store = &mir.insns[cursor];
    cursor = mir_low_byte_loop_next_effective(cursor);
    if (cursor >= mir.count)
        return 0;
    index = &mir.insns[cursor];
    cursor = mir_low_byte_loop_next_effective(cursor);
    if (cursor >= mir.count)
        return 0;
    element_store = &mir.insns[cursor];
    cursor = mir_low_byte_loop_next_effective(cursor);
    if (cursor >= mir.count)
        return 0;
    element_load = &mir.insns[cursor];
    cursor = mir_low_byte_loop_next_effective(cursor);
    if (cursor >= mir.count)
        return 0;
    condition_member = &mir.insns[cursor];
    cursor = mir_low_byte_loop_next_effective(cursor);
    if (cursor >= mir.count)
        return 0;
    condition_load = &mir.insns[cursor];
    pc_location = mir_byte_verify_location(
        pc_load, 2, &pc_offset);
    pc_same = mir_same_scalar_memory_location(
        pc_load, pc_store);
    element_location = mir_byte_verify_location(
        element_store, 2, &element_offset);
    element_same = mir_same_scalar_memory_location(
        element_store, element_load);
    dense_match = mir_match_dense_byte_switch(
        cursor + 1, &plan->dispatch);
    if (base_address->opcode != MIR_ADDRESS ||
        base_member->opcode != MIR_MEMBER_ADDRESS ||
        base_member->src1 != base_address->dst ||
        base_member->memory_size != 2 ||
        base_load->opcode != MIR_LOAD_INDIRECT ||
        base_load->src1 != base_member->dst ||
        type_size(base_load->type) != 2 ||
        pc_load->opcode != MIR_LOAD ||
        !pc_location ||
        one->opcode != MIR_CONST || one->immediate != 1 ||
        increment->opcode != MIR_BINARY ||
        increment->immediate != '+' ||
        increment->src1 != pc_load->dst ||
        increment->src2 != one->dst ||
        pc_store->opcode != MIR_STORE ||
        pc_store->src1 != increment->dst ||
        !pc_same ||
        index->opcode != MIR_INDEX_ADDRESS ||
        index->src1 != base_load->dst ||
        index->src2 != pc_load->dst ||
        index->immediate <= 0 ||
        element_store->opcode != MIR_STORE ||
        element_store->src1 != index->dst ||
        !element_location ||
        element_load->opcode != MIR_LOAD ||
        !element_same ||
        condition_member->opcode != MIR_MEMBER_ADDRESS ||
        condition_member->src1 != element_load->dst ||
        condition_member->immediate != 0 ||
        condition_member->memory_size != 1 ||
        condition_load->opcode != MIR_LOAD_INDIRECT ||
        condition_load->src1 != condition_member->dst ||
        condition_load->memory_size != 1 ||
        !dense_match ||
        plan->dispatch.condition != condition_load->dst ||
        mir_value_use_count(base_address->dst) != 1 ||
        mir_value_use_count(base_member->dst) != 1 ||
        mir_value_use_count(base_load->dst) != 1 ||
        mir_value_use_count(pc_load->dst) != 2 ||
        mir_value_use_count(one->dst) != 1 ||
        mir_value_use_count(index->dst) != 1 ||
        mir_value_use_count(element_load->dst) != 1 ||
        mir_value_use_count(condition_member->dst) != 1 ||
        mir_value_use_count(condition_load->dst) !=
            plan->dispatch.case_count)
        return 0;
    plan->dispatch.condition_in_hl = 1;
    plan->skip_through = plan->dispatch.end_instruction;
    plan->base_address_value = base_member->dst;
    plan->increment_instruction = (int)(increment - mir.insns);
    plan->increment_value = increment->dst;
    plan->pc_offset = pc_offset;
    plan->element_offset = element_offset;
    plan->stride = (int)index->immediate;
    return 1;
}

static int mir_emit_dense_postincrement_index_switch(
    FILE *out, const int *labels,
    const struct MirDensePostincrementIndexSwitch *plan)
{
    char operand[160];
    int saved_instruction;

    fprintf(out,
            "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
            "\tpush hl\n\tinc hl\n",
            plan->pc_offset, plan->pc_offset + 1);
    mir_emit_frame_word_store(out, plan->pc_offset);
    saved_instruction = mir_emit_instruction_index;
    mir_emit_instruction_index = plan->increment_instruction;
    mir_emit_virtual_store(out, plan->increment_value);
    mir_emit_instruction_index = saved_instruction;
    fputs("\tpop hl\n", out);
    if (plan->stride == 2)
        fputs("\tadd hl,hl\n", out);
    else if (plan->stride > 2)
        mir_emit_mul_hl_const(out, (unsigned long)plan->stride);
    if (!mir_prepare_constant_absolute_operand(
            out, plan->base_address_value,
            operand, sizeof(operand)))
        return 0;
    fprintf(out, "\tld de,(%s)\n\tadd hl,de\n"
                 "\tld (ix%+d),l\n\tld (ix%+d),h\n"
                 "\tld l,(hl)\n\tld h,0\n",
            operand, plan->element_offset, plan->element_offset + 1);
    mir_emit_dense_byte_switch(out, labels, &plan->dispatch);
    return 1;
}

static int mir_emit_named_word_load_to_hl(
    FILE *out, const struct MirInsn *load)
{
    int memory_type;
    int memory_storage;
    int memory_offset;

    if (!mir_scalar_memory_location(
            load, &memory_type, &memory_storage, &memory_offset) ||
        type_size(memory_type) != 2)
        return 0;
    if (memory_storage == SC_GLOBAL ||
        memory_storage == SC_EXTERN) {
        struct Sym *global = find_global(load->name);
        const char *assembly_name = asm_name_for(
            global != NULL ? sym_asm_name(global)
                           : mir_declared_link_name(load->name));

        if (memory_storage == SC_EXTERN &&
            mir_extrn_should_emit(global))
            fprintf(out, "\textrn %s\n", assembly_name);
        fprintf(out, "\tld hl,(%s)\n", assembly_name);
        return 1;
    }
    if (memory_storage != SC_LOCAL &&
        memory_storage != SC_PARAM)
        return 0;
    if (memory_offset >= -128 && memory_offset + 1 <= 127) {
        fprintf(out, "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
                memory_offset, memory_offset + 1);
        return 1;
    }
    fputs("\tpush ix\n\tpop hl\n", out);
    mir_emit_hl_offset_from_ix(out, memory_offset);
    fputs("\tld a,(hl)\n\tinc hl\n\tld h,(hl)\n\tld l,a\n", out);
    return 1;
}

static int mir_emit_dense_byte_switch_condition_load(
    FILE *out, const int *labels, int instruction,
    struct MirDenseByteSwitch *dispatch)
{
    if (!mir_match_dense_byte_switch_condition_load(
            instruction, dispatch) ||
        !mir_emit_named_word_load_to_hl(
            out, &mir.insns[instruction]))
        return 0;
    if (dispatch->condition_size == 1)
        fputs("\tld l,(hl)\n\tld h,0\n", out);
    else
        fputs("\tld a,(hl)\n\tinc hl\n\tld h,(hl)\n\tld l,a\n", out);
    mir_emit_dense_byte_switch(out, labels, dispatch);
    return 1;
}

static int mir_store_feeds_dense_byte_switch(
    int instruction, int value)
{
    const struct MirInsn *definition = mir_definition(value);
    struct MirDenseByteSwitch dispatch;
    int definition_index;
    int offset;
    int iy_offset;
    int next;

    if (!mir_narrow_store_preserves_hl(instruction, value) ||
        definition == NULL)
        return 0;
    if (mir.backend_slots != NULL &&
        mir.backend_slots[value] >= 0) {
        offset = mir_virtual_offset(value);
        iy_offset = mir_virtual_iy_offset(value);
        if (!((offset >= -128 && offset + 1 <= 127) ||
              (mir_virtual_iy_base &&
               iy_offset >= -128 && iy_offset + 1 <= 127)))
            return 0;
    }
    definition_index = (int)(definition - mir.insns);
    for (next = definition_index + 1;
         next < instruction; ++next)
        if (mir.insns[next].opcode != MIR_NOP)
            return 0;
    next = instruction + 1;
    while (next < mir.count &&
           mir.insns[next].opcode == MIR_NOP)
        ++next;
    return next < mir.count &&
           mir_match_dense_byte_switch(next, &dispatch) &&
           dispatch.condition == value &&
           dispatch.condition_in_hl;
}

static int mir_value_is_dense_byte_switch_condition(int value)
{
    const struct MirInsn *definition = mir_definition(value);
    struct MirDenseByteSwitch dispatch;
    int definition_index;
    int store;
    int next;

    if (definition == NULL ||
        definition->opcode != MIR_LOAD_INDIRECT ||
        type_size(definition->type) != 1)
        return 0;
    definition_index = (int)(definition - mir.insns);
    store = definition_index + 1;
    while (store < mir.count &&
           mir.insns[store].opcode == MIR_NOP)
        ++store;
    if (store >= mir.count ||
        mir.insns[store].opcode != MIR_STORE ||
        mir.insns[store].src1 != value ||
        !mir_narrow_store_preserves_hl(store, value))
        return 0;
    next = store + 1;
    while (next < mir.count &&
           mir.insns[next].opcode == MIR_NOP)
        ++next;
    if (next >= mir.count ||
        !mir_match_dense_byte_switch(next, &dispatch) ||
        dispatch.condition != value ||
        !dispatch.condition_in_hl)
        return 0;
    return mir_value_use_count(value) == dispatch.case_count + 1;
}

/* Fuse the dispatch loop's common `word += byte_table[index]` epilogue so
 * the table base and accumulator do not detour through backend slots. */
static int mir_emit_dense_switch_table_pc_advance(
    FILE *out, int instruction, int *end_instruction)
{
    const struct MirInsn *cpu_address;
    const struct MirInsn *pc_address;
    const struct MirInsn *pc_load;
    const struct MirInsn *table_address;
    const struct MirInsn *index_load;
    const struct MirInsn *index_address;
    const struct MirInsn *length_load;
    const struct MirInsn *length_widen;
    const struct MirInsn *addition;
    const struct MirInsn *pc_store;
    char pc_operand[192];
    char table_operand[192];
    int index_type;
    int index_storage;
    int index_offset;

    if (!mir_spilled_cfg_used_dense_byte_switch ||
        instruction < 0 || instruction + 9 >= mir.count)
        return 0;
    cpu_address = &mir.insns[instruction];
    pc_address = &mir.insns[instruction + 1];
    pc_load = &mir.insns[instruction + 2];
    table_address = &mir.insns[instruction + 3];
    index_load = &mir.insns[instruction + 4];
    index_address = &mir.insns[instruction + 5];
    length_load = &mir.insns[instruction + 6];
    length_widen = &mir.insns[instruction + 7];
    addition = &mir.insns[instruction + 8];
    pc_store = &mir.insns[instruction + 9];
    if (cpu_address->opcode != MIR_ADDRESS ||
        pc_address->opcode != MIR_MEMBER_ADDRESS ||
        pc_address->src1 != cpu_address->dst ||
        pc_load->opcode != MIR_LOAD_INDIRECT ||
        pc_load->src1 != pc_address->dst ||
        pc_load->memory_size != 2 ||
        pc_load->memory_flags != 0 ||
        table_address->opcode != MIR_ADDRESS ||
        !strcmp(cpu_address->name, table_address->name) ||
        index_load->opcode != MIR_LOAD ||
        index_load->memory_flags != 0 ||
        type_size(index_load->type) != 1 ||
        type_is_bool(index_load->type) ||
        (index_load->type & TYPE_UNSIGNED) == 0 ||
        index_address->opcode != MIR_INDEX_ADDRESS ||
        index_address->src1 != table_address->dst ||
        index_address->src2 != index_load->dst ||
        index_address->memory_size != 1 ||
        index_address->memory_flags != 0 ||
        index_address->immediate != 1 ||
        length_load->opcode != MIR_LOAD_INDIRECT ||
        length_load->src1 != index_address->dst ||
        length_load->memory_size != 1 ||
        length_load->memory_flags != 0 ||
        type_is_bool(length_load->type) ||
        (length_load->type & TYPE_UNSIGNED) == 0 ||
        length_widen->opcode != MIR_UNARY ||
        length_widen->src1 != length_load->dst ||
        length_widen->immediate != 0 ||
        type_size(length_widen->type) != 2 ||
        addition->opcode != MIR_BINARY ||
        addition->immediate != '+' ||
        addition->src1 != pc_load->dst ||
        addition->src2 != length_widen->dst ||
        type_size(addition->type) != 2 ||
        pc_store->opcode != MIR_STORE_INDIRECT ||
        pc_store->src1 != pc_address->dst ||
        pc_store->src2 != addition->dst ||
        pc_store->memory_size != 2 ||
        pc_store->memory_flags != 0 ||
        mir_value_use_count(cpu_address->dst) != 1 ||
        mir_value_use_count(pc_address->dst) != 2 ||
        mir_value_use_count(pc_load->dst) != 1 ||
        mir_value_use_count(table_address->dst) != 1 ||
        mir_value_use_count(index_load->dst) != 1 ||
        mir_value_use_count(index_address->dst) != 1 ||
        mir_value_use_count(length_load->dst) != 1 ||
        mir_value_use_count(length_widen->dst) != 1 ||
        mir_value_use_count(addition->dst) != 1 ||
        !mir_constant_absolute_access_supported(pc_load) ||
        !mir_constant_absolute_access_supported(pc_store) ||
        (instruction + 10 < mir.count &&
         !mir_phi_copies_are_empty(
             instruction + 9, instruction + 10)))
        return 0;
    if (!mir_scalar_memory_location(
            index_load, &index_type, &index_storage, &index_offset) ||
        type_size(index_type) != 1 ||
        type_is_bool(index_type) ||
        (index_type & TYPE_UNSIGNED) == 0 ||
        ((index_storage == SC_LOCAL ||
          index_storage == SC_PARAM) &&
         (index_offset < -128 || index_offset > 127)) ||
        (index_storage != SC_LOCAL &&
         index_storage != SC_PARAM &&
         index_storage != SC_GLOBAL &&
         index_storage != SC_EXTERN))
        return 0;
    if (!mir_prepare_constant_absolute_operand(
            out, pc_address->dst,
            pc_operand, sizeof(pc_operand)) ||
        !mir_prepare_constant_absolute_operand(
            out, table_address->dst,
            table_operand, sizeof(table_operand)))
        return -1;
    fprintf(out, "\tld hl,(%s)\n\tpush hl\n", pc_operand);
    if (index_storage == SC_GLOBAL ||
        index_storage == SC_EXTERN) {
        struct Sym *global = find_global(index_load->name);
        const char *assembly_name = asm_name_for(
            global != NULL ? sym_asm_name(global)
                           : mir_declared_link_name(index_load->name));

        if (index_storage == SC_EXTERN &&
            mir_extrn_should_emit(global))
            fprintf(out, "\textrn %s\n", assembly_name);
        fprintf(out, "\tld a,(%s)\n\tld l,a\n", assembly_name);
    } else {
        fprintf(out, "\tld l,(ix%+d)\n", index_offset);
    }
    fputs("\tld h,0\n", out);
    fprintf(out, "\tld de,%s\n\tadd hl,de\n"
                 "\tld l,(hl)\n\tld h,0\n"
                 "\tpop de\n\tadd hl,de\n\tld (%s),hl\n",
            table_operand, pc_operand);
    *end_instruction = instruction + 9;
    return 1;
}

/* T399 (mir-text-size-plan.md): a phi copy's source or destination only
 * has a concrete backend-slot address when it is an ordinary spilled
 * value (mir.backend_slots[value] >= 0); rematerializable constants,
 * addresses, and directly-named-home values have no slot to compare and
 * are conservatively treated as unable to prove disjointness here (the
 * general swap-safe path below already handles them correctly, it is
 * just not eligible for the fast-path skip). */
static int mir_phi_copy_value_slot_range(int value, int *base, int *width)
{
    int slot;
    if (mir.backend_slots == NULL)
        return 0;
    slot = mir.backend_slots[value];
    if (slot < 0)
        return 0;
    *base = slot;
    *width = mir_value_is_wide(value) ? 2 : 1;
    return 1;
}

static int mir_phi_copy_is_slot_identity(int source, int destination)
{
    int source_base, source_width;
    int destination_base, destination_width;

    return mir_phi_copy_value_slot_range(source, &source_base, &source_width) &&
           mir_phi_copy_value_slot_range(destination, &destination_base,
                                         &destination_width) &&
           source_base == destination_base &&
           source_width == destination_width;
}

/* T399: true only when no copy's destination slot overlaps any *other*
 * copy's source slot. The general push-all-sources/pop-all-destinations
 * shape exists specifically to guard against that hazard (a later
 * destination store clobbering a still-unread source of an earlier
 * copy) for a true simultaneous swap; when every destination is
 * provably a fresh slot disjoint from every other copy's source (the
 * common case for a loop header phi introducing new loop-carried
 * homes), a direct load-then-store per copy reaches the identical
 * result in any order, with no stack round-trip. */
static int mir_phi_copy_group_is_disjoint(const int *sources,
                                          const int *destinations,
                                          int copy_count)
{
    int dest_base[MAX_FLOW], dest_width[MAX_FLOW];
    int src_base[MAX_FLOW], src_width[MAX_FLOW];
    int i, j;

    for (j = 0; j < copy_count; ++j) {
        if (!mir_phi_copy_value_slot_range(destinations[j], &dest_base[j],
                                            &dest_width[j]) ||
            !mir_phi_copy_value_slot_range(sources[j], &src_base[j],
                                            &src_width[j]))
            return 0;
    }
    for (j = 0; j < copy_count; ++j)
        for (i = 0; i < copy_count; ++i) {
            if (i == j)
                continue;
            if (dest_base[j] < src_base[i] + src_width[i] &&
                src_base[i] < dest_base[j] + dest_width[j])
                return 0;
        }
    return 1;
}

static int mir_emit_spilled_phi_copies(FILE *out, int predecessor,
                                       int successor)
{
    int sources[MAX_FLOW];
    int destinations[MAX_FLOW];
    int copy_count = mir_collect_phi_copies_for_edge(predecessor, successor,
                                                      sources, destinations);
    int copy;

    if (copy_count < 0)
        return 0;
    for (copy = 0; copy < copy_count; ++copy)
        if (destinations[copy] >= 0 &&
            destinations[copy] < mir.next_value &&
            mir.backend_slots != NULL &&
            mir.backend_slots[destinations[copy]] ==
                MIR_BACKEND_SLOT_PHI_ARGUMENT_STACK) {
            if (copy_count != 1 ||
                mir_value_is_wide(sources[copy]))
                return 0;
            mir_emit_virtual_load(out, sources[copy]);
            fputs("\tpush hl\n", out);
            return 1;
        }
    /* Item T9 (mir-text-size-plan.md): the general push-all-sources-then-
     * pop-all-destinations-in-reverse shape below exists to let several
     * simultaneous phi copies swap through each other safely (a later
     * destination store must not clobber a still-unread source). With
     * exactly one copy pending there is no other copy to clobber or be
     * clobbered by, so the whole push/pop round-trip through the stack is
     * dead weight - a direct load-then-store reaches the identical result. */
    if (copy_count == 1) {
        if (mir_value_is_wide(sources[0])) {
            mir_emit_virtual_load_wide(out, sources[0]);
            mir_emit_virtual_store_wide(out, destinations[0]);
        } else {
            mir_emit_virtual_load(out, sources[0]);
            mir_emit_virtual_store(out, destinations[0]);
        }
        return 1;
    }
    /* T399: extend the same reasoning to two or more copies whose whole
     * group is provably disjoint (see mir_phi_copy_group_is_disjoint) -
     * no push/pop swap machinery is needed when nothing can be
     * clobbered, regardless of copy order. */
    if (mir_phi_copy_group_is_disjoint(sources, destinations, copy_count)) {
        for (copy = 0; copy < copy_count; ++copy) {
            if (mir_value_is_wide(sources[copy])) {
                mir_emit_virtual_load_wide(out, sources[copy]);
                mir_emit_virtual_store_wide(out, destinations[copy]);
            } else {
                mir_emit_virtual_load(out, sources[copy]);
                mir_emit_virtual_store(out, destinations[copy]);
            }
        }
        return 1;
    }
    for (copy = 0; copy < copy_count; ++copy) {
        if (mir_value_is_wide(sources[copy])) {
            mir_emit_virtual_load_wide(out, sources[copy]);
            fputs("\tpush de\n\tpush hl\n", out);
        } else {
            mir_emit_virtual_load(out, sources[copy]);
            fputs("\tpush hl\n", out);
        }
    }
    for (copy = copy_count - 1; copy >= 0; --copy) {
        if (mir_value_is_wide(destinations[copy])) {
            fputs("\tpop hl\n\tpop de\n", out);
            mir_emit_virtual_store_wide(out, destinations[copy]);
        } else {
            fputs("\tpop hl\n", out);
            mir_emit_virtual_store(out, destinations[copy]);
        }
    }
    return 1;
}

int mir_scalar_memory_location(const struct MirInsn *insn, int *type,
                                      int *storage, int *offset)
{
    struct Sym *global;
    int instruction;
    if (insn->object >= 0 && insn->object < mir.object_count) {
        const struct MirObject *object = &mir.objects[insn->object];
        *type = object->type;
        *storage = object->storage;
        *offset = object->offset + (int)insn->immediate;
        return 1;
    }
    if (mir_declared_location(insn->name, type, storage, offset)) {
        *offset += (int)insn->immediate;
        return 1;
    }
    for (instruction = 0; instruction < mir.count; ++instruction)
        if (mir.insns[instruction].opcode == MIR_COMPOUND_ADDRESS &&
            strcmp(mir.insns[instruction].name, insn->name) == 0) {
            *type = insn->type;
            *storage = SC_LOCAL;
            *offset = (int)mir.insns[instruction].immediate +
                      (int)insn->immediate;
            return 1;
        }
    global = find_global(insn->name);
    if (global != NULL) {
        *type = global->type;
        *storage = global->storage;
        *offset = global->offset + (int)insn->immediate;
        return 1;
    }
    return 0;
}

/* T383 (mir-text-size-plan.md): mir_emit_constant_absolute_load/store already
 * collapse a global/extern base plus constant MEMBER_ADDRESS/INDEX_ADDRESS
 * offsets into one absolute operand, but only for the instruction that
 * *dereferences* the resulting address (a scalar load/store). When the same
 * fully-constant chain is instead consumed as plain data - stored as a
 * pointer value, passed as a call argument, or returned - the address is
 * still recomputed at runtime through the whole base-load-and-add sequence.
 * mir_prepare_constant_absolute_operand already proves and formats the exact
 * same operand from insn->dst directly (mir_resolve_constant_absolute_address
 * walks from the instruction defining the value, which is this instruction
 * itself when called against its own dst); reuse it here to materialize the
 * value in one `ld hl,<label>+<offset>` instead. Ordered after each site's
 * existing "only used by a supported load/store" skip so the dereferencing
 * consumer keeps folding the address into its own single instruction rather
 * than this value being materialized and then immediately redereferenced. */
static int mir_emit_constant_absolute_address_value(
    FILE *out, const struct MirInsn *insn)
{
    char operand[160];

    if (!mir_prepare_constant_absolute_operand(
            out, insn->dst, operand, sizeof(operand)))
        return 0;
    mir_spilled_cfg_used_constant_absolute = 1;
    if (mir_constant_absolute_address_has_index(insn->dst))
        mir_spilled_cfg_used_constant_index_absolute = 1;
    fprintf(out, "\tld hl,%s\n", operand);
    mir_emit_virtual_store(out, insn->dst);
    return 1;
}

static int mir_emit_dynamic_absolute_index(
    FILE *out, const struct MirInsn *insn)
{
    const struct MirInsn *base;
    const char *assembly_name;
    struct Sym *global;

    if (!mir_dynamic_absolute_index_base(
            insn, &base, &assembly_name))
        return 0;
    global = find_global(base->name);
    if ((global == NULL || global->needs_extrn) &&
        mir_extrn_should_emit_name(assembly_name))
        fprintf(out, "\textrn %s\n", assembly_name);
    if (getenv("DCC_MIR_PERF_RECOVERY_REPORT") != NULL)
        fprintf(stderr,
                "; MIR perf-recovery function=%s "
                "feature=dynamic-absolute-index\n",
                mir.name);
    mir_emit_virtual_load(out, insn->src2);
    if (insn->immediate == 2)
        fputs("\tadd hl,hl\n", out);
    else if (insn->immediate > 2) {
        unsigned long multiplier =
            (unsigned long)insn->immediate & 0xffffUL;

        if (mir_mul_const_fast_path_eligible(
                multiplier, insn->dst))
            mir_emit_mul_hl_const(out, multiplier);
        else {
            fprintf(out, "\tld de,%ld\n", insn->immediate);
            mir_emit_runtime_call(out, "__mulu");
        }
    }
    fprintf(out, "\tld de,%s\n\tadd hl,de\n", assembly_name);
    mir_emit_virtual_store(out, insn->dst);
    return 1;
}

static int mir_emit_constant_absolute_load(
    FILE *out, const struct MirInsn *insn)
{
    char operand[160];

    if (!mir_constant_absolute_access_supported(insn) ||
        !mir_prepare_constant_absolute_operand(
            out, insn->src1, operand, sizeof(operand)))
        return 0;
    mir_spilled_cfg_used_constant_absolute = 1;
    if (mir_constant_absolute_address_has_index(insn->src1))
        mir_spilled_cfg_used_constant_index_absolute = 1;
    if (insn->memory_size == 1) {
        fprintf(out, "\tld a,(%s)\n\tld l,a\n", operand);
        if (type_is_bool(insn->type)) {
            int end_label = new_label();
            fputs("\tld a,l\n\tor a\n\tld hl,0\n", out);
            fprintf(out, "\tjp z, L%d\n\tinc hl\nL%d:\n",
                    end_label, end_label);
        } else if ((insn->type & TYPE_UNSIGNED) != 0) {
            fputs("\tld h,0\n", out);
        } else {
            mir_emit_signed_byte_extend(out);
        }
    } else {
        fprintf(out, "\tld hl,(%s)\n", operand);
    }
    mir_emit_virtual_store(out, insn->dst);
    return 1;
}

static int mir_emit_constant_absolute_store(
    FILE *out, const struct MirInsn *insn)
{
    char operand[160];

    if (!mir_constant_absolute_access_supported(insn) ||
        !mir_prepare_constant_absolute_operand(
            out, insn->src1, operand, sizeof(operand)))
        return 0;
    mir_spilled_cfg_used_constant_absolute = 1;
    if (mir_constant_absolute_address_has_index(insn->src1))
        mir_spilled_cfg_used_constant_index_absolute = 1;
    mir_emit_virtual_load(out, insn->src2);
    if (insn->memory_size == 1)
        fprintf(out, "\tld a,l\n\tld (%s),a\n", operand);
    else
        fprintf(out, "\tld (%s),hl\n", operand);
    return 1;
}

static int mir_emit_wide_indirect_store(FILE *out,
                                        const struct MirInsn *insn)
{
    if (!mir_constant_absolute_access_supported(insn) &&
        mir_value_currently_uses_stack_handoff(
            insn->src1, mir_emit_instruction_index))
        return 0;
    if (mir_emit_constant_absolute_store(out, insn))
        return 1;
    mir_emit_virtual_load_wide(out, insn->src2);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_emit_virtual_load(out, insn->src1);
    fputs("\tpop bc\n\tpop de\n"
          "\tld (hl),c\n\tinc hl\n\tld (hl),b\n"
          "\tinc hl\n\tld (hl),e\n\tinc hl\n\tld (hl),d\n", out);
    return 1;
}

static void mir_report_constant_absolute_addresses(void)
{
    int instruction;
    int loads = 0;
    int stores = 0;

    if (getenv("DCC_MIR_ABSOLUTE_ADDRESS_REPORT") == NULL)
        return;
    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];

        if (!mir_constant_absolute_access_supported(insn))
            continue;
        if (insn->opcode == MIR_LOAD_INDIRECT)
            ++loads;
        else
            ++stores;
    }
    if (loads != 0 || stores != 0)
        fprintf(stderr,
                "; MIR absolute-address function=%s loads=%d stores=%d\n",
                mir.name, loads, stores);
}

/* Item T85 (mir-text-size-plan.md): storage class + offset alone do not
 * uniquely identify a scalar memory location - two distinct top-level
 * (non-aggregate-field) globals both resolve to storage=SC_GLOBAL,
 * offset=0 (mir_scalar_memory_location's `global->offset` term is only
 * ever nonzero for a struct/array member, not for a whole scalar object),
 * so comparing storage/offset alone can wrongly treat two different
 * globals as "the same location". This wrapper adds the missing identity
 * check: locals/params carry a real per-object index (insn->object >= 0)
 * that already disambiguates them uniquely, so compare that directly;
 * globals/externs (object == -1) fall back to comparing their resolved
 * declared name instead. Callers that key HL-forwarding re-arms on "is
 * this a fresh load of the exact same location a preceding store/fused
 * inc-dec just wrote" must use this instead of a bare storage/offset
 * compare (see the MIR_STORE and MIR_BINARY selfstore-incdec re-arm
 * sites) - found via a synthetic two-global regression test
 * (`ga = 5; return gb;` wrongly forwarding ga's value as gb's). */
static int mir_same_scalar_memory_location(const struct MirInsn *a,
                                            const struct MirInsn *b)
{
    int type_a, storage_a, offset_a;
    int type_b, storage_b, offset_b;
    if (!mir_scalar_memory_location(a, &type_a, &storage_a, &offset_a) ||
        !mir_scalar_memory_location(b, &type_b, &storage_b, &offset_b))
        return 0;
    if (storage_a != storage_b || offset_a != offset_b)
        return 0;
    if (a->object >= 0 || b->object >= 0)
        return a->object == b->object;
    return strcmp(a->name, b->name) == 0;
}

/* Item 31 (mir-migration-plan-100): a bare "x++;"/"x--;" statement on a
 * frame-local scalar lowers (mir_lower_incdec) to load-x / add-or-sub-1 /
 * store-x, going through the general spilled-scalar-cfg load/store path
 * even though the whole operation only ever touches x's own memory. The
 * legacy AST backend already has a dedicated fast path for exactly this
 * shape (emit_incdec_sym_direct, dcc_symbols.c ~line 1322): "inc (ix+n)"
 * (or a carry-checked byte-pair form for 16-bit values) directly against
 * the frame slot, with no register round-trip at all. This mirrors that
 * fast path for the MIR backend, restricted to the same population
 * legacy restricts itself to - non-pointer, frame-local-or-parameter,
 * 16-bit scalars (pointer ++/-- must scale by the pointee size, not a
 * raw +-1, so it is deliberately excluded here exactly as it is in
 * emit_incdec_sym_direct; 8-bit char and 32-bit long operands are also
 * out of scope for this item, left for a future extension since they
 * need their own byte-width-specific carry-chain shape).
 *
 * Item T36 (mir-text-size-plan.md): emit_incdec_sym_direct also has a
 * separate, simpler fast path for a non-pointer 16-bit *global* (or
 * extern) - is_global_word_sym(s) - "ld hl,(name) / inc-or-dec hl /
 * ld (name),hl", since inc/dec hl is an atomic 16-bit operation with no
 * byte-pair carry chain to worry about (unlike the frame-relative form,
 * which must ripple a carry from the low byte into a separate high-byte
 * "inc (ix+n+1)"). Item 31 only ever mirrored the local/parameter half of
 * emit_incdec_sym_direct - this extends the same predicate to recognize
 * the global/extern case too, confirmed via forced-accept-diff on
 * t2darr.c's check() (a `static int failures; ...; failures++;` pattern)
 * that legacy already takes this fast path (3 instructions) while MIR
 * fell back to a full load/push/pop/add/store round trip (7
 * instructions) for the identical global increment.
 *
 * Returns 1 and sets *store_index to the sole store instruction re-writing
 * the result back to the same frame slot iff every one of the following
 * holds: the operator is '+' or '-' against the exact constant 1; the
 * left operand's value is bound to a 16-bit non-pointer local/parameter/
 * global/extern memory location; and the result value (insn->dst) has
 * exactly one use anywhere in the function, which is a plain MIR_STORE
 * writing to that identical memory location.
 *
 * Note on scope: within a single basic block, or across a loop-carrying
 * PHI merge, any later reference to the same source variable reuses this
 * MIR_BINARY's dst value directly (dcc's MIR construction does local value
 * numbering, confirmed while building this item's test coverage), which
 * gives the value a second use and disqualifies it here - that is by
 * design, since the fused instruction only replaces a genuine store-then-
 * never-read-again sequence, not a live loop induction variable (those
 * stay in registers or flow through PHI nodes, and any store back to a
 * frame slot for them is a spill the register allocator itself decided
 * was necessary, not a redundant round-trip this fusion should remove).
 * This makes the fusion's real-world hit population the population of
 * dead-after-increment locals (e.g. "x++;" as the last touch of x before
 * an unrelated return), confirmed narrow by census (see Execution Log). */
static int mir_binary_is_selfstore_wide_increment(
    int index, int *store_index, int *memory_offset)
{
    const struct MirInsn *insn = &mir.insns[index];
    const struct MirInsn *left_definition;
    const struct MirInsn *right_definition;
    int memory_type, memory_storage, offset;
    int found_store = -1;
    int last_use = index;
    int instruction;

    if (insn->opcode != MIR_BINARY || insn->immediate != '+' ||
        type_size(insn->secondary_offset) != 4)
        return 0;
    right_definition = mir_definition(insn->src2);
    left_definition = mir_definition(insn->src1);
    if (right_definition == NULL ||
        right_definition->opcode != MIR_CONST ||
        right_definition->immediate != 1 ||
        left_definition == NULL ||
        left_definition->opcode != MIR_LOAD ||
        left_definition->memory_flags != 0 ||
        mir_value_use_count(left_definition->dst) != 1 ||
        !mir_scalar_memory_location(
            left_definition, &memory_type,
            &memory_storage, &offset) ||
        type_size(memory_type) != 4 ||
        (memory_storage != SC_LOCAL &&
         memory_storage != SC_PARAM) ||
        offset < -128 || offset + 3 > 127 ||
        (left_definition->object >= 0 &&
         mir_object_address_taken(left_definition->object)))
        return 0;
    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *use = &mir.insns[instruction];

        if (use->src1 != insn->dst && use->src2 != insn->dst &&
            !mir_call_uses_value(use, insn->dst))
            continue;
        if (instruction > last_use)
            last_use = instruction;
        if (use->opcode == MIR_STORE &&
            use->src1 == insn->dst &&
            mir_same_scalar_memory_location(left_definition, use)) {
            if (found_store >= 0)
                return 0;
            found_store = instruction;
        }
    }
    if (found_store <= index)
        return 0;
    for (instruction = index + 1;
         instruction < found_store; ++instruction)
        if (mir.insns[instruction].opcode != MIR_NOP)
            return 0;
    for (instruction = found_store + 1;
         instruction <= last_use; ++instruction) {
        const struct MirInsn *candidate = &mir.insns[instruction];

        if (candidate->opcode == MIR_STORE &&
            mir_same_scalar_memory_location(
                left_definition, candidate))
            return 0;
    }
    if (store_index != NULL)
        *store_index = found_store;
    if (memory_offset != NULL)
        *memory_offset = offset;
    return 1;
}

static int mir_value_is_selfstore_wide_increment_result(int value)
{
    const struct MirInsn *definition = mir_definition(value);
    int offset;
    int store_index;

    return definition != NULL &&
           definition->opcode == MIR_BINARY &&
           mir_binary_is_selfstore_wide_increment(
               (int)(definition - mir.insns),
               &store_index, &offset);
}

/* The original 16-bit self-store matcher described by Item 31 above. */
static int mir_binary_is_selfstore_incdec(int index, int *store_index)
{
    const struct MirInsn *insn = &mir.insns[index];
    const struct MirInsn *left_definition;
    const struct MirInsn *right_definition;
    int memory_type, memory_storage, memory_offset;
    int store_type, store_storage, store_offset;
    int uses = 0;
    int found_store = -1;
    int scan;

    if (insn->opcode != MIR_BINARY ||
        (insn->immediate != '+' && insn->immediate != '-'))
        return 0;
    if (type_ptr_depth(insn->secondary_offset) > 0 ||
        type_size(insn->secondary_offset) != 2)
        return 0;
    right_definition = mir_definition(insn->src2);
    if (right_definition == NULL || right_definition->opcode != MIR_CONST ||
        right_definition->immediate != 1)
        return 0;
    left_definition = mir_definition(insn->src1);
    if (left_definition == NULL ||
        !mir_scalar_memory_location(left_definition, &memory_type,
                                    &memory_storage, &memory_offset) ||
        (memory_storage != SC_LOCAL && memory_storage != SC_PARAM &&
         memory_storage != SC_GLOBAL && memory_storage != SC_EXTERN) ||
        type_ptr_depth(memory_type) > 0 || type_size(memory_type) != 2)
        return 0;
    for (scan = 0; scan < mir.count; ++scan) {
        const struct MirInsn *use = &mir.insns[scan];
        if (use->src1 != insn->dst && use->src2 != insn->dst)
            continue;
        if (use->opcode != MIR_STORE || use->src1 != insn->dst ||
            !mir_scalar_memory_location(use, &store_type, &store_storage,
                                        &store_offset) ||
            store_storage != memory_storage || store_offset != memory_offset)
            return 0;
        found_store = scan;
        ++uses;
    }
    if (uses != 1)
        return 0;
    *store_index = found_store;
    return 1;
}

static int mir_integer_constant_expression(
    int value, long *result, int depth)
{
    const struct MirInsn *definition = mir_definition(value);
    long left;
    long right;

    if (definition == NULL || result == NULL || depth > 8)
        return 0;
    if (definition->opcode == MIR_CONST) {
        *result = definition->immediate;
        return 1;
    }
    if (definition->opcode != MIR_BINARY ||
        type_size(definition->secondary_offset) > 2 ||
        !mir_integer_constant_expression(
            definition->src1, &left, depth + 1) ||
        !mir_integer_constant_expression(
            definition->src2, &right, depth + 1))
        return 0;
    return mir_fold_constant_binary(
        definition->immediate, left, right,
        definition->secondary_offset, result);
}

static int mir_binary_is_selfstore_small_adjust(
    int index, int *store_index, int *amount)
{
    const struct MirInsn *insn = &mir.insns[index];
    const struct MirInsn *left_definition;
    const struct MirInsn *right_definition;
    long constant_amount;
    int memory_type, memory_storage, memory_offset;
    int uses = 0;
    int found_store = -1;
    int scan;

    if (insn->opcode != MIR_BINARY ||
        (insn->immediate != '+' && insn->immediate != '-') ||
        type_size(insn->secondary_offset) != 2)
        return 0;
    right_definition = mir_definition(insn->src2);
    if (right_definition == NULL ||
        right_definition->opcode != MIR_CONST ||
        right_definition->immediate < 2 ||
        right_definition->immediate > 255)
        return 0;
    constant_amount = right_definition->immediate;
    left_definition = mir_definition(insn->src1);
    if (left_definition == NULL ||
        left_definition->memory_flags != 0 ||
        !mir_scalar_memory_location(
            left_definition, &memory_type,
            &memory_storage, &memory_offset) ||
        (memory_storage != SC_LOCAL &&
         memory_storage != SC_PARAM &&
         memory_storage != SC_GLOBAL &&
         memory_storage != SC_EXTERN) ||
        type_size(memory_type) != 2)
        return 0;
    for (scan = 0; scan < mir.count; ++scan) {
        const struct MirInsn *use = &mir.insns[scan];

        if (use->src1 != insn->dst && use->src2 != insn->dst)
            continue;
        if (use->opcode != MIR_STORE ||
            use->src1 != insn->dst ||
            use->memory_flags != 0 ||
            !mir_same_scalar_memory_location(
                left_definition, use))
            return 0;
        found_store = scan;
        ++uses;
    }
    if (uses != 1)
        return 0;
    if (store_index != NULL)
        *store_index = found_store;
    if (amount != NULL)
        *amount = insn->immediate == '-'
            ? -(int)constant_amount
            : (int)constant_amount;
    return 1;
}

static int mir_binary_is_selfstore_global_predecrement_load(
    int index, int *store_index, int *load_index, int *amount)
{
    const struct MirInsn *insn = &mir.insns[index];
    const struct MirInsn *left_definition;
    const struct MirInsn *load = NULL;
    long constant_amount;
    int memory_type, memory_storage, memory_offset;
    int found_store = -1;
    int found_load = -1;
    int instruction;

    if (insn->opcode != MIR_BINARY || insn->immediate != '-' ||
        type_size(insn->secondary_offset) != 2 ||
        !mir_integer_constant_expression(
            insn->src2, &constant_amount, 0) ||
        constant_amount < 1 || constant_amount > 8)
        return 0;
    left_definition = mir_definition(insn->src1);
    if (left_definition == NULL ||
        left_definition->memory_flags != 0 ||
        !mir_scalar_memory_location(
            left_definition, &memory_type,
            &memory_storage, &memory_offset) ||
        (memory_storage != SC_GLOBAL &&
         memory_storage != SC_EXTERN) ||
        type_ptr_depth(memory_type) == 0 ||
        type_size(memory_type) != 2)
        return 0;
    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *use = &mir.insns[instruction];

        if (use->src1 != insn->dst && use->src2 != insn->dst &&
            !mir_call_uses_value(use, insn->dst))
            continue;
        if (use->opcode == MIR_STORE &&
            use->src1 == insn->dst &&
            use->memory_flags == 0 &&
            mir_same_scalar_memory_location(left_definition, use)) {
            if (found_store >= 0)
                return 0;
            found_store = instruction;
            continue;
        }
        if (use->opcode == MIR_LOAD_INDIRECT &&
            use->src1 == insn->dst &&
            use->memory_flags == 0 &&
            use->bit_width == 0 &&
            type_size(use->type) == 2) {
            if (found_load >= 0)
                return 0;
            found_load = instruction;
            load = use;
            continue;
        }
        return 0;
    }
    if (found_store <= index || found_load <= found_store ||
        load == NULL ||
        constant_amount != type_size(load->type))
        return 0;
    for (instruction = index + 1;
         instruction < found_load; ++instruction)
        if (instruction != found_store &&
            mir.insns[instruction].opcode != MIR_NOP)
            return 0;
    if (store_index != NULL)
        *store_index = found_store;
    if (load_index != NULL)
        *load_index = found_load;
    if (amount != NULL)
        *amount = (int)constant_amount;
    return 1;
}

static int mir_value_only_used_by_selfstore_adjust_amount(int value)
{
    int instruction;
    int uses = 0;
    int sole_user = -1;
    int amount;
    int memory_offset;
    int narrow_phi_value;
    int phi_value;
    int store_index;
    int load_index;

    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];

        if (insn->src1 != value && insn->src2 != value &&
            !mir_call_uses_value(insn, value))
            continue;
        if (insn->opcode != MIR_BINARY || insn->src2 != value)
            return 0;
        sole_user = instruction;
        ++uses;
    }
    return uses == 1 &&
           (mir_binary_is_selfstore_wide_increment(
                sole_user, &store_index, &memory_offset) ||
            mir_binary_is_narrow_phi_adjust(
                sole_user, &narrow_phi_value, &store_index) ||
            mir_binary_is_wide_phi_increment(
                sole_user, &phi_value, &store_index) ||
            mir_binary_is_selfstore_small_adjust(
                sole_user, &store_index, &amount) ||
            mir_binary_is_selfstore_global_predecrement_load(
                sole_user, &store_index, &load_index, &amount));
}

/* Value-indexed wrapper around mir_binary_is_selfstore_incdec for slot-
 * assignment callers that only have a value, not its defining instruction
 * index (mirroring how mir_call_only_constant/mir_binary_only_constant are
 * both value-indexed too). */
int mir_value_is_selfstore_incdec(int value)
{
    const struct MirInsn *definition = mir_definition(value);
    int amount;
    int load_index;
    int memory_offset;
    int store_index;

    if (definition == NULL || definition->opcode != MIR_BINARY)
        return 0;
    return mir_binary_is_selfstore_incdec((int)(definition - mir.insns),
                                          &store_index) ||
           mir_binary_is_selfstore_wide_increment(
               (int)(definition - mir.insns),
               &store_index, &memory_offset) ||
           mir_binary_is_selfstore_small_adjust(
               (int)(definition - mir.insns),
               &store_index, &amount) ||
           mir_binary_is_selfstore_global_predecrement_load(
               (int)(definition - mir.insns),
               &store_index, &load_index, &amount);
}

/* Item T36 (mir-text-size-plan.md): true iff `value`'s sole use anywhere
 * in the function is as the left (src1) operand of a MIR_BINARY that
 * itself qualifies as a fused selfstore increment/decrement
 * (mir_binary_is_selfstore_incdec) - in that case the fused emission
 * re-reads the operand's memory location directly (see
 * mir_emit_selfstore_incdec/_global), making `value`'s own defining
 * MIR_LOAD/MIR_PARAM entirely redundant: without this check, that load
 * still ran its normal emission (materializing the value into hl and
 * often staging it via a stack push anticipating the *ordinary* binary
 * form the fusion now bypasses entirely), a load-then-discard exactly
 * like the dead-unary case mir_value_only_used_by_dead_unary already
 * covers for a different consumer shape. Found via a forced-accept
 * diff on t2darr.c's check() after the global selfstore-incdec fusion
 * above was added: `failures++` correctly fused into 3 instructions,
 * but the preceding `ld hl,(_Z0001)` / `push hl` (the now-superseded
 * ordinary load-and-forward for the same read) still ran undisturbed
 * ahead of it. Mirrors the same one-and-only-one-use requirement
 * mir_binary_is_selfstore_incdec already applies to the *result*
 * side. */
static int mir_value_is_selfstore_incdec_source(int value)
{
    int instruction;
    int uses = 0;
    int sole_user = -1;

    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];
        if (insn->src1 == value || insn->src2 == value ||
            mir_call_uses_value(insn, value)) {
            if (insn->opcode != MIR_BINARY || insn->src1 != value)
                return 0;
            sole_user = instruction;
            ++uses;
        }
    }
    if (uses != 1)
        return 0;
    {
        int amount;
        int load_index;
        int memory_offset;
        int store_index;
        return mir_binary_is_selfstore_incdec(
                   sole_user, &store_index) ||
               mir_binary_is_selfstore_wide_increment(
                   sole_user, &store_index, &memory_offset) ||
               mir_binary_is_selfstore_small_adjust(
                   sole_user, &store_index, &amount) ||
               mir_binary_is_selfstore_global_predecrement_load(
                   sole_user, &store_index, &load_index, &amount);
    }
}

/* Emits the Item 31 carry-checked byte-pair increment/decrement directly
 * against a frame slot, mirroring emit_incdec_sym_direct's 2-byte form
 * exactly: "inc (ix+n)" cannot ripple a carry into the high byte on its
 * own, so an explicit "jp nz" skips the high-byte adjustment on the
 * common case where the low byte doesn't wrap. */
static void mir_emit_selfstore_incdec(FILE *out, int offset, int is_inc)
{
    int done = new_label();

    if (!mir_frame_word_uses_short_ix(offset)) {
        mir_emit_frame_word_load(out, offset);
        fputs(is_inc ? "\tinc hl\n" : "\tdec hl\n", out);
        mir_emit_frame_word_store(out, offset);
        return;
    }

    if (is_inc) {
        fprintf(out, "\tinc (ix%+d)\n", offset);
        fprintf(out, "\tjp nz, L%d\n", done);
        fprintf(out, "\tinc (ix%+d)\n", offset + 1);
    } else {
        fprintf(out, "\tld a,(ix%+d)\n", offset);
        fprintf(out, "\tdec (ix%+d)\n", offset);
        fputs("\tor a\n", out);
        fprintf(out, "\tjp nz, L%d\n", done);
        fprintf(out, "\tdec (ix%+d)\n", offset + 1);
    }
    fprintf(out, "L%d:\n", done);
}

static int mir_emit_wide_phi_increment(FILE *out, int phi_value)
{
    int offset = mir_virtual_offset(phi_value);
    int iy_offset = mir_virtual_iy_offset(phi_value);
    const char *base = "ix";
    int low = offset;
    int high_low = offset - 2;
    int done;

    if (mir_virtual_iy_base && iy_offset - 2 >= -128 &&
        iy_offset + 1 <= 127) {
        base = "iy";
        low = iy_offset;
        high_low = iy_offset - 2;
    } else if (offset - 2 < -128 || offset + 1 > 127) {
        return 0;
    }
    done = new_label();
    if (getenv("DCC_MIR_PERF_RECOVERY_REPORT") != NULL)
        fprintf(stderr,
                "; MIR perf-recovery function=%s feature=wide-phi-inc\n",
                mir.name);
    fprintf(out,
            "\tinc (%s%+d)\n\tjp nz, L%d\n"
            "\tinc (%s%+d)\n\tjp nz, L%d\n"
            "\tinc (%s%+d)\n\tjp nz, L%d\n"
            "\tinc (%s%+d)\nL%d:\n",
            base, low, done,
            base, low + 1, done,
            base, high_low, done,
            base, high_low + 1, done);
    return 1;
}

static int mir_emit_narrow_phi_adjust(
    FILE *out, int phi_value, int is_increment)
{
    int offset = mir_virtual_offset(phi_value);
    int iy_offset = mir_virtual_iy_offset(phi_value);
    const char *base = "ix";
    int low = offset;
    int done;

    if (mir_virtual_iy_base && iy_offset >= -128 &&
        iy_offset + 1 <= 127) {
        base = "iy";
        low = iy_offset;
    } else if (offset < -128 || offset + 1 > 127) {
        return 0;
    }
    done = new_label();
    if (getenv("DCC_MIR_PERF_RECOVERY_REPORT") != NULL)
        fprintf(stderr,
                "; MIR perf-recovery function=%s "
                "feature=narrow-phi-adjust op=%c\n",
                mir.name, is_increment ? '+' : '-');
    if (is_increment) {
        fprintf(out,
                "\tinc (%s%+d)\n\tjp nz, L%d\n"
                "\tinc (%s%+d)\nL%d:\n",
                base, low, done,
                base, low + 1, done);
    } else {
        fprintf(out,
                "\tld a,(%s%+d)\n\tdec (%s%+d)\n"
                "\tor a\n\tjp nz, L%d\n"
                "\tdec (%s%+d)\nL%d:\n",
                base, low, base, low,
                done, base, low + 1, done);
    }
    return 1;
}

static void mir_emit_wide_named_increment(FILE *out, int offset)
{
    int done = new_label();

    if (getenv("DCC_MIR_PERF_RECOVERY_REPORT") != NULL)
        fprintf(stderr,
                "; MIR perf-recovery function=%s feature=wide-named-inc\n",
                mir.name);
    fprintf(out,
            "\tinc (ix%+d)\n\tjp nz, L%d\n"
            "\tinc (ix%+d)\n\tjp nz, L%d\n"
            "\tinc (ix%+d)\n\tjp nz, L%d\n"
            "\tinc (ix%+d)\nL%d:\n",
            offset, done,
            offset + 1, done,
            offset + 2, done,
            offset + 3, done);
}

/* Item T36 (mir-text-size-plan.md): the global/extern counterpart of
 * mir_emit_selfstore_incdec, mirroring emit_incdec_sym_direct's own
 * is_global_word_sym fast path (dcc_symbols.c) exactly - "ld hl,(name) /
 * inc-or-dec hl / ld (name),hl". A 16-bit inc/dec is a single atomic
 * instruction with no byte-pair carry chain to manage (unlike the frame-
 * relative form above, which must ripple a carry from the low byte into
 * a separate high-byte increment), so this is simpler than the local/
 * parameter form rather than needing its own carry-checked label. */
static void mir_emit_selfstore_incdec_global(FILE *out,
                                              const struct MirInsn *definition,
                                              int storage, int is_inc)
{
    struct Sym *global = find_global(definition->name);
    const char *assembly_name = asm_name_for(
        global != NULL ? sym_asm_name(global)
                       : mir_declared_link_name(definition->name));

    if (storage == SC_EXTERN)
        fprintf(out, "\textrn %s\n", assembly_name);
    fprintf(out, "\tld hl,(%s)\n", assembly_name);
    fputs(is_inc ? "\tinc hl\n" : "\tdec hl\n", out);
    fprintf(out, "\tld (%s),hl\n", assembly_name);
}

static void mir_emit_selfstore_small_adjust(
    FILE *out, const struct MirInsn *definition,
    int storage, int offset, int amount)
{
    int magnitude = amount < 0 ? -amount : amount;
    int done = new_label();

    if (storage == SC_GLOBAL || storage == SC_EXTERN) {
        struct Sym *global = find_global(definition->name);
        const char *assembly_name = asm_name_for(
            global != NULL ? sym_asm_name(global)
                           : mir_declared_link_name(definition->name));

        if (storage == SC_EXTERN &&
            mir_extrn_should_emit(global))
            fprintf(out, "\textrn %s\n", assembly_name);
        if (amount > 0)
            fprintf(out,
                    "\tld a,(%s)\n\tadd a,%d\n\tld (%s),a\n"
                    "\tjp nc, L%d\n\tld a,(%s+1)\n\tinc a\n"
                    "\tld (%s+1),a\nL%d:\n",
                    assembly_name, magnitude, assembly_name,
                    done, assembly_name, assembly_name, done);
        else
            fprintf(out,
                    "\tld a,(%s)\n\tsub %d\n\tld (%s),a\n"
                    "\tjp nc, L%d\n\tld a,(%s+1)\n\tdec a\n"
                    "\tld (%s+1),a\nL%d:\n",
                    assembly_name, magnitude, assembly_name,
                    done, assembly_name, assembly_name, done);
        return;
    }
    if (!mir_frame_word_uses_short_ix(offset)) {
        mir_emit_frame_word_load(out, offset);
        fprintf(out, "\tld de,%d\n\tadd hl,de\n", amount);
        mir_emit_frame_word_store(out, offset);
        return;
    }
    if (amount > 0)
        fprintf(out,
                "\tld a,(ix%+d)\n\tadd a,%d\n\tld (ix%+d),a\n"
                "\tjp nc, L%d\n\tinc (ix%+d)\nL%d:\n",
                offset, magnitude, offset, done, offset + 1, done);
    else
        fprintf(out,
                "\tld a,(ix%+d)\n\tsub %d\n\tld (ix%+d),a\n"
                "\tjp nc, L%d\n\tdec (ix%+d)\nL%d:\n",
                offset, magnitude, offset, done, offset + 1, done);
}

static void mir_emit_selfstore_global_predecrement_load(
    FILE *out, const struct MirInsn *definition,
    int storage, int amount, int load_instruction)
{
    struct Sym *global = find_global(definition->name);
    const char *assembly_name = asm_name_for(
        global != NULL ? sym_asm_name(global)
                       : mir_declared_link_name(definition->name));
    int saved_instruction = mir_emit_instruction_index;
    int step;

    if (storage == SC_EXTERN &&
        mir_extrn_should_emit(global))
        fprintf(out, "\textrn %s\n", assembly_name);
    fprintf(out, "\tld hl,(%s)\n", assembly_name);
    for (step = 0; step < amount; ++step)
        fputs("\tdec hl\n", out);
    fprintf(out, "\tld (%s),hl\n"
                 "\tld a,(hl)\n\tinc hl\n"
                 "\tld h,(hl)\n\tld l,a\n",
            assembly_name);
    mir_emit_instruction_index = load_instruction;
    mir_emit_virtual_store(out, mir.insns[load_instruction].dst);
    mir_emit_instruction_index = saved_instruction;
}

static int mir_scalar_cfg_preflight_reject(const char *reason, int instruction)
{
    if (getenv("DCC_MIR_SELECT_REPORT") != NULL)
        fprintf(stderr,
                "; MIR scalar-cfg preflight function=%s reason=%s insn=%d\n",
                mir.name, reason, instruction);
    return 0;
}

/* Item 86: single shared frame-size accounting predicate. Calls
 * mir_prepare_backend_slots() (which has the side effect of assigning
 * backend slots), so call it exactly once per candidate emitter, same as
 * both call sites below did individually before this consolidation.
 * aggregate_temp_bytes is always 0 for callers that structurally exclude
 * MIR_CALL (e.g. mir_try_emit_general_rollout's opcode whitelist), so
 * including it here is always safe and never changes behavior for them.
 */
int mir_current_frame_bytes(void)
{
    return mir_effective_local_bytes() + mir.aggregate_temp_bytes +
           2 * mir_prepare_backend_slots();
}

